INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('theeabrarrr/LPG-Connect/system-reality-auditor', 'community', 'theeabrarrr', 'LPG-Connect', 'theeabrarrr/LPG-Connect', 'system-reality-auditor', 0, 0, 35, '2026-02-24T18:00:05Z', '2026-03-07T03:58:19.792Z', '91e74302f036faa3f9f35513fe877685a6dfc31388f3f93791f1508c61f98ea8', '{"id":"theeabrarrr/LPG-Connect/system-reality-auditor","name":"system-reality-auditor","description":{"en":"The system-reality-auditor skill provides instructions for a comprehensive audit to ensure master project documents reflect reality, benefiting developers and project managers. It features multi-tenancy, fleet tracking, and financial ledgers built with Next.js and Supabase.","zh":"系统现实审计器是一个企业级的 LPG 管理系统，具有多租户、车队跟踪和财务台账功能，使用 Next.js 和 Supabase 构建","ja":"システムリアリティオーディターは、Next.js と Supabase を使用して構築された、多租憶、車隊追跡、財務台帳機能を備えたエンタープライズグレードの LPG 管理システムです","ko":"시스템 리얼리티 오디터는 Next.js 및 Supabase를 사용하여 구축된 다중 테넌트, 차량 추적 및 재무 원장 기능을 갖춘 엔터프라이즈급 LPG 관리 시스템입니다","es":"System-reality-auditor es una herramienta de auditoría de código y base de datos que utiliza tecnologías como Next.js y Supabase","fr":"System-reality-auditor est un outil d''audit de code et de base de données qui utilise des technologies comme Next.js et Supabase","de":"System-reality-auditor ist ein Tool zur Überprüfung von Code und Datenbank, das Technologien wie Next.js und Supabase nutzt","pt":"O System Reality Auditor é uma ferramenta de auditoria de código e banco de dados que utiliza Next.js e Supabase para garantir a precisão dos documentos de projeto","ru":"System Reality Auditor - это инструмент для аудита кода и базы данных, использующий Next.js и Supabase для обеспечения точности проектной документации","ar":"نظام مدقق الواقع هو أداة لتدقيق الرمز البرمجي وقاعدة البيانات التي تستخدم Next.js و Supabase لضمان دقة وثائق المشروع"},"seo":{"title":{"en":"system-reality-auditor: Comprehensive Audit Setup Guide |...","zh":"系统现实审计器 Setup Guide - 使用 Next.js 和 Supabase","ja":"システムリアリティオーディター Setup Guide - Next.js と Supabase を使用","ko":"시스템 리얼리티 오디터 Setup Guide - Next.js 및 Supabase 사용","es":"Guía de configuración de system-reality-auditor para audi...","fr":"Guide de mise en place de system-reality-auditor pour aud...","de":"Einrichtungsleitfaden für system-reality-auditor zur Durc...","pt":"Guia de Configuração do System Reality Auditor para Desen...","ru":"Настройка System Reality Auditor: ИИ Агенты для Разработч...","ar":"دليل إعداد نظام مدقق الواقع للاستخدام مع أدوات الذكاء الا..."},"description":{"en":"Discover how to perform triple-point audits with system-reality-auditor. Learn to map features, verify UI components, and inspect database schemas with Supab...","zh":"学习如何使用系统现实审计器 AI 工具进行代码审计和数据库审计，确保项目文档准确反映现实","ja":"システムリアリティオーディター AI エージェントを使用してコード監査とデータベース監査を行い、プロジェクト文書が現実を正確に反映していることを確認する方法について学びます","ko":"시스템 리얼리티 오디터 AI 툴을 사용하여 코드 감사와 데이터베이스 감사를 수행하여 프로젝트 문서가 현실을 정확하게 반영하도록 하는 방법에 대해 알아보세요","es":"Aprende a utilizar system-reality-auditor para auditar tu código y base de datos con herramientas como find_by_name y Supabase MCP","fr":"Découvrez comment utiliser system-reality-auditor pour auditer votre code et base de données avec des outils comme find_by_name et Supabase MCP","de":"Erfahren Sie, wie Sie system-reality-auditor verwenden können, um Ihren Code und Ihre Datenbank mit Tools wie find_by_name und Supabase MCP zu auditen","pt":"Aprenda a realizar auditorias de código e banco de dados com o System Reality Auditor, utilizando Next.js e Supabase para melhorar a gestão de projetos","ru":"Проведение комплексной аудитории кода и базы данных с помощью System Reality Auditor, используя Next.js и Supabase для улучшения управления проектами","ar":"تعرف على كيفية إجراء عمليات تدقيق للرمز البرمجي وقاعدة البيانات باستخدام نظام مدقق الواقع، مع استخدام Next.js و Supabase لتحسين إدارة المشاريع"},"definition":{"en":"system-reality-auditor is a skill that provides instructions on how to perform a comprehensive triple-point audit to ensure all master project documents accurately reflect reality.","zh":"系统现实审计器是用于进行全面三点审计的 AI 工具，确保所有主项目文档准确反映现实","ja":"システムリアリティオーディターは、すべてのマスタープロジェクト文書が現実を正確に反映していることを確認するための包括的な三点監査を実行する AI エージェントです","ko":"시스템 리얼리티 오디터는 모든 마스터 프로젝트 문서가 현실을 정확하게 반영하는지 확인하기 위한 포괄적인 3점 감사를 수행하는 AI 에이전트입니다","es":"System-reality-auditor es una herramienta de auditoría que verifica la exactitud de la realidad en los documentos de proyecto","fr":"System-reality-auditor est un outil d''audit qui vérifie l''exactitude de la réalité dans les documents de projet","de":"System-reality-auditor ist ein Überprüfungstool, das die Genauigkeit der Realität in den Projektdokumenten überprüft","pt":"O que é System Reality Auditor? É uma ferramenta de auditoria de código e banco de dados para garantir a precisão dos documentos de projeto","ru":"Что такое System Reality Auditor? Это инструмент для аудита кода и базы данных для обеспечения точности проектной документации","ar":"ما هو نظام مدقق الواقع؟ هو أداة لتدقيق الرمز البرمجي وقاعدة البيانات لضمان دقة وثائق المشروع"},"features":{"en":["Performs code audits using tools like find_by_name and list_dir","Conducts DB audits using the Supabase MCP to fetch the latest database schema","Verifies the actual presence of UI components, server actions, helpers, and API routes","Maps all implemented features in the codebase using recursive file reading","Inspects database tables and columns for accuracy","Supports multi-tenancy, fleet tracking, and financial ledgers"],"zh":["代码审计：使用 find_by_name、list_dir 或递归文件读取来映射所有实现的功能","数据库审计：使用 Supabase MCP 来获取最新的数据库架构","多租户支持","车队跟踪功能","财务台账功能","使用 Next.js 和 Supabase 构建"],"ja":["コード監査：find_by_name、list_dir、または再帰ファイル読み込みを使用してすべての実装された機能をマッピングします","データベース監査：Supabase MCP を使用して最新のデータベーススキーマを取得します","多租憶サポート","車隊追跡機能","財務台帳機能","Next.js と Supabase を使用して構築されています"],"ko":["코드 감사: find_by_name, list_dir 또는 재귀 파일 읽기를 사용하여 모든 구현된 기능을 매핑합니다","데이터베이스 감사: Supabase MCP를 사용하여 최신 데이터베이스 스키마를 가져옵니다","다중 테넌트 지원","차량 추적 기능","재무 원장 기능","Next.js 및 Supabase를 사용하여 구축되었습니다"],"es":["Auditoría de código con herramientas como find_by_name y list_dir","Análisis de base de datos con Supabase MCP","Verificación de la presencia de componentes de interfaz de usuario y rutas de API","Soporte para tecnologías como Next.js y Supabase","Capacidad de realizar auditorías de triple punto"],"fr":["Audit de code avec des outils comme find_by_name et list_dir","Analyse de base de données avec Supabase MCP","Vérification de la présence de composants d''interface utilisateur et de routes d''API","Prise en charge des technologies comme Next.js et Supabase","Capacité à effectuer des audits de triple point"],"de":["Code-Audit mit Tools wie find_by_name und list_dir","Datenbankanalyse mit Supabase MCP","Überprüfung der Anwesenheit von Benutzeroberflächenkomponenten und API-Routen","Unterstützung für Technologien wie Next.js und Supabase","Fähigkeit, Triple-Point-Audits durchzuführen"],"pt":["Auditoria de código com find_by_name, list_dir e leitura recursiva de arquivos","Auditoria de banco de dados com Supabase MCP","Verificação de UI components, server actions, helpers e API routes","Suporte a multi-tenancy e rastreamento de frota","Integração com Next.js e Supabase"],"ru":["Аудит кода с помощью find_by_name, list_dir и рекурсивного чтения файлов","Аудит базы данных с помощью Supabase MCP","Проверка UI компонентов, серверных действий, хелперов и маршрутов API","Поддержка мультиарендности и отслеживания флота","Интеграция с Next.js и Supabase"],"ar":["عمليات تدقيق للرمز البرمجي باستخدام find_by_name, list_dir و قراءة الملفات بشكل متكرر","عمليات تدقيق لقاعدة البيانات باستخدام Supabase MCP","تحقق من مكونات الواجهة المستخدمة، إجراءات الخادم، مساعدين و مسارات API","دعم متعدد الإيجار و تتبع الأسطول","التكامل مع Next.js و Supabase"]},"keywords":{"en":["how to use system-reality-auditor","what is system-reality-auditor","system-reality-auditor alternative","system-reality-auditor vs Next.js","system-reality-auditor install","system-reality-auditor setup guide","Supabase MCP tutorial","triple-point audit best practices"],"zh":["系统现实审计器","AI 工具","代码审计","数据库审计","Next.js","Supabase","多租户","车队跟踪","财务台账"],"ja":["システムリアリティオーディター","AI エージェント","コード監査","データベース監査","Next.js","Supabase","多租憶","車隊追跡","財務台帳"],"ko":["시스템 리얼리티 오디터","AI 툴","코드 감사","데이터베이스 감사","Next.js","Supabase","다중 테넌트","차량 추적","재무 원장"],"es":["system-reality-auditor","auditoría de código","auditoría de base de datos","Next.js","Supabase","find_by_name","list_dir","Supabase MCP","triple punto","herramientas de auditoría"],"fr":["system-reality-auditor","audit de code","audit de base de données","Next.js","Supabase","find_by_name","list_dir","Supabase MCP","triple point","outils d''audit"],"de":["system-reality-auditor","Code-Audit","Datenbank-Audit","Next.js","Supabase","find_by_name","list_dir","Supabase MCP","Triple-Point","Überprüfungstools"],"pt":["System Reality Auditor","auditoria de código","auditoria de banco de dados","Next.js","Supabase","multi-tenancy","rastreamento de frota","desenvolvimento de software","ferramentas de auditoria"],"ru":["System Reality Auditor","аудит кода","аудит базы данных","Next.js","Supabase","мультиарендность","отслеживание флота","разработка программного обеспечения","инструменты аудита"],"ar":["نظام مدقق الواقع","عمليات تدقيق للرمز البرمجي","عمليات تدقيق لقاعدة البيانات","Next.js","Supabase","إيجار متعدد","تتبع الأسطول","تطوير البرمجيات","أدوات التدقيق"]}},"owner":"theeabrarrr","repo":"LPG-Connect","repoPath":"theeabrarrr/LPG-Connect","stars":0,"forks":0,"updatedAt":"2026-02-24T18:00:05Z","topics":[],"category":"community","skillMd":{"name":"system-reality-auditor","description":"Performs a triple-point audit to synchronize codebase, database schema, and project documentation states. Use this skill to align the PRD, Gap Analysis, and Execution Plan with the actual system reality.","bodyPreview":"# System Reality Auditor\n\nThis skill provides instructions on how to perform a comprehensive triple-point audit to ensure all master project documents accurately reflect reality.\n\n## 1. Code Audit\nUse tools like `find_by_name`, `list_dir`, or recursive file reading to map all implemented features in the codebase. Verify the actual presence of UI components, server actions, helpers, and API routes.\n\n## 2. DB Audit\nUse the Supabase MCP to fetch the latest database schema. Inspect:\n- Tables\n- Colum","body":"# System Reality Auditor\n\nThis skill provides instructions on how to perform a comprehensive triple-point audit to ensure all master project documents accurately reflect reality.\n\n## 1. Code Audit\nUse tools like `find_by_name`, `list_dir`, or recursive file reading to map all implemented features in the codebase. Verify the actual presence of UI components, server actions, helpers, and API routes.\n\n## 2. DB Audit\nUse the Supabase MCP to fetch the latest database schema. Inspect:\n- Tables\n- Columns\n- RPCs (Remote Procedure Calls)\n\n## 3. Alignment Logic\nCompare the Code and DB findings against the master project documents (e.g., `PRD.md`, `EXECUTION_PLAN.md`, `GAP_ANALYSIS.md`, `DATABASE_SCHEMA.md`).\n- If a task is marked `[ ]` (pending) in the plan but actually exists in the code or database, mark it as `[x]`.\n- If a task is marked `[x]` (completed) or done in the plan but the feature does not exist in the code or database, uncheck it to `[ ]` and note the gap.\n\n## 4. Update Authority\nYou have full update authority over the project documents. Rewrite the ''Status'' and ''Gaps'' sections of all documents to match the current ground truth. Ensure all documents are strictly synchronized with the codebase and database realities after the audit.\n"},"lastSynced":"2026-03-07T03:58:19.792Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive project audits and codebase verification.","zh":"非常适合需要对项目进行全面审计和代码库验证的开发代理。","ja":"開発エージェントが包括的なプロジェクト監査とコードベースの検証を行う必要がある場合に最適です。","ko":"개발 에이전트가 포괄적인 프로젝트 감사 및 코드베이스 확인이 필요한 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan auditorías de proyectos y verificación de código integral.","fr":"Parfait pour les agents de développement ayant besoin d''audits de projet et de vérification de code intégrale.","de":"Perfekt für Entwicklungsmittel, die umfassende Projekt-Audits und Code-Verifizierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de auditorias de projeto abrangentes e verificação de codebase.","ru":"Идеально подходит для агентов разработки, которым необходимы комплексные аудиты проектов и проверка кодовой базы.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تدقيق شامل للمشروع وتأكيد قاعدة الشفرة."},"recommendation":{"en":"Empowers agents to perform triple-point audits, ensuring master project documents reflect reality, utilizing tools like `find_by_name` and Supabase MCP for database schema inspection, and supporting multi-tenancy and fleet tracking.","zh":"赋予代理商执行三点审计的能力，确保主项目文档反映现实，利用诸如 `find_by_name` 和 Supabase MCP 的工具进行数据库架构检查，并支持多租户和车队跟踪。","ja":"エージェントが三重点監査を実行できるようにし、主プロジェクト文書が現実を反映することを保証するために、`find_by_name` や Supabase MCP などのツールを使用してデータベーススキーマを検査し、マルチテナンシーとフリート追跡をサポートします。","ko":"에이전트가 3중점 감사를 수행할 수 있도록 해줌으로써 마스터 프로젝트 문서가 현실을 반영하도록 보장하며, `find_by_name` 및 Supabase MCP와 같은 도구를 사용하여 데이터베이스 스키마를 검사하고, 멀티 테넌시 및 플릿 추적을 지원합니다.","es":"Habilita a los agentes a realizar auditorías de triple punto, garantizando que los documentos de proyecto maestros reflejen la realidad, utilizando herramientas como `find_by_name` y Supabase MCP para la inspección del esquema de base de datos, y admitiendo multi-tenencia y seguimiento de flotas.","fr":"Permet aux agents d''effectuer des audits à trois points, en garantissant que les documents de projet maîtres reflètent la réalité, en utilisant des outils tels que `find_by_name` et Supabase MCP pour l''inspection du schéma de base de données, et en prenant en charge la multi-locataires et le suivi de flotte.","de":"Ermächtigt Agenten, Dreipunkt-Audits durchzuführen, um sicherzustellen, dass die Masterprojektdokumente der Realität entsprechen, unter Verwendung von Tools wie `find_by_name` und Supabase MCP für die Inspektion des Datenbankschemas und Unterstützung von Multi-Mandanten und Flottenverfolgung.","pt":"Habilita os agentes a realizar auditorias de três pontos, garantindo que os documentos do projeto master reflitam a realidade, utilizando ferramentas como `find_by_name` e Supabase MCP para inspeção do esquema de banco de dados, e suportando multi-tenancy e rastreamento de frota.","ru":"Наделяет агентов возможностью проводить аудиты в трех точках, гарантируя, что мастер-документы проекта отражают реальность, используя инструменты, такие как `find_by_name` и Supabase MCP для инспекции схемы базы данных, и поддерживая многоарендаторность и отслеживание флота.","ar":"تمكين الوكيل من إجراء تدقيق ثلاثي النقاط، لضمان أن تعكس مستندات المشروع الرئيسية الواقع، باستخدام أدوات مثل `find_by_name` و Supabase MCP لتدقيق مخطط قاعدة البيانات، ودعم التenant المتعدد وتعقب الأسطول."},"useCases":{"en":["Auditing codebases for implemented features","Inspecting database schema for tables and columns","Verifying UI components, server actions, helpers, and API routes"],"zh":["用于审计代码库中实现的功能","用于检查数据库架构中的表和列","用于验证 UI 组件、服务器操作、助手和 API 路由"],"ja":["実装された機能のコードベースを監査するために使用","テーブルと列のデータベーススキーマを検査するために使用","UIコンポーネント、サーバーアクション、ヘルパー、APIルートを検証するために使用"],"ko":["구현된 기능의 코드베이스를 감사하는 데 사용","테이블 및 열의 데이터베이스 스키마를 검사하는 데 사용","UI 컴포넌트, 서버 작업, 도우미 및 API 경로를 확인하는 데 사용"],"es":["Auditoría de código para características implementadas","Inspección del esquema de base de datos para tablas y columnas","Verificación de componentes de interfaz de usuario, acciones de servidor, ayudantes y rutas de API"],"fr":["Audit de code pour les fonctionnalités implémentées","Inspection du schéma de base de données pour les tables et les colonnes","Vérification des composants d''interface utilisateur, des actions de serveur, des aides et des routes d''API"],"de":["Auditing von Code für implementierte Funktionen","Inspektion des Datenbankschemas für Tabellen und Spalten","Verifizierung von Benutzeroberflächenkomponenten, Serveraktionen, Hilfsprogrammen und API-Routen"],"pt":["Auditoria de codebases para recursos implementados","Inspeção do esquema de banco de dados para tabelas e colunas","Verificação de componentes de UI, ações de servidor, helpers e rotas de API"],"ru":["Аудит кодовой базы для реализованных функций","Осмотр схемы базы данных для таблиц и столбцов","Проверка компонентов UI, действий сервера, хелперов и маршрутов API"],"ar":["تدقيق قواعد البيانات المطبقة للميزات","فحص مخطط قاعدة البيانات للجداول والأعمدة","التأكد من مكونات الواجهة، إجراءات الخادم، مساعدات وطرق API"]},"limitations":{"en":["Requires access to codebase and database schema","Built with Next.js and Supabase, may require additional setup for other frameworks"],"zh":["需要访问代码库和数据库架构","使用 Next.js 和 Supabase 构建，可能需要为其他框架进行额外设置"],"ja":["コードベースとデータベーススキーマへのアクセスが必要","Next.js と Supabase で構築されているため、他のフレームワークでは追加の設定が必要になる場合があります"],"ko":["코드베이스 및 데이터베이스 스키마에 대한 액세스가 필요","Next.js 및 Supabase로 구축되었으므로 다른 프레임워크에서는 추가 설정이 필요할 수 있습니다"],"es":["Requiere acceso al código y esquema de base de datos","Construido con Next.js y Supabase, puede requerir configuración adicional para otros frameworks"],"fr":["Nécessite l''accès au code et au schéma de base de données","Construit avec Next.js et Supabase, peut nécessiter une configuration supplémentaire pour d''autres frameworks"],"de":["Erfordert Zugriff auf Code und Datenbankschema","Mit Next.js und Supabase erstellt, kann zusätzliche Konfiguration für andere Frameworks erforderlich sein"],"pt":["Requer acesso à codebase e ao esquema de banco de dados","Construído com Next.js e Supabase, pode exigir configuração adicional para outros frameworks"],"ru":["Требует доступа к кодовой базе и схеме базы данных","Построен с использованием Next.js и Supabase, может потребовать дополнительной настройки для других фреймворков"],"ar":["يتطلب الوصول إلى قاعدة الشفرة ومخطط قاعدة البيانات","تم بناؤه باستخدام Next.js و Supabase، قد يتطلب إعدادًا إضافيًا لأطر عمل أخرى"]},"version":4},"contentHash":"91e74302f036faa3f9f35513fe877685a6dfc31388f3f93791f1508c61f98ea8","qualityScore":35}');
