INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('theeabrarrr/LPG-Connect/system-reality-auditor', 'system-reality-auditor', 'theeabrarrr', 'LPG-Connect', 'community', 'system-reality-auditor theeabrarrr LPG-Connect community The system-reality-auditor skill provides instructions for a comprehensive audit to ensure master project documents reflect reality, benefiting developers and project managers. It features multi-tenancy, fleet tracking, and financial ledgers built with Next.js and Supabase. 系统现实审计器是一个企业级的 LPG 管理系统，具有多租户、车队跟踪和财务台账功能，使用 Next.js 和 Supabase 构建 システムリアリティオーディターは、Next.js と Supabase を使用して構築された、多租憶、車隊追跡、財務台帳機能を備えたエンタープライズグレードの LPG 管理システムです 시스템 리얼리티 오디터는 Next.js 및 Supabase를 사용하여 구축된 다중 테넌트, 차량 추적 및 재무 원장 기능을 갖춘 엔터프라이즈급 LPG 관리 시스템입니다 System-reality-auditor es una herramienta de auditoría de código y base de datos que utiliza tecnologías como Next.js y Supabase System-reality-auditor est un outil d''audit de code et de base de données qui utilise des technologies comme Next.js et Supabase System-reality-auditor ist ein Tool zur Überprüfung von Code und Datenbank, das Technologien wie Next.js und Supabase nutzt O System Reality Auditor é uma ferramenta de auditoria de código e banco de dados que utiliza Next.js e Supabase para garantir a precisão dos documentos de projeto System Reality Auditor - это инструмент для аудита кода и базы данных, использующий Next.js и Supabase для обеспечения точности проектной документации نظام مدقق الواقع هو أداة لتدقيق الرمز البرمجي وقاعدة البيانات التي تستخدم Next.js و Supabase لضمان دقة وثائق المشروع how to use system-reality-auditor what is system-reality-auditor system-reality-auditor alternative system-reality-auditor vs Next.js system-reality-auditor install system-reality-auditor setup guide Supabase MCP tutorial triple-point audit best practices 系统现实审计器 AI 工具 代码审计 数据库审计 Next.js Supabase 多租户 车队跟踪 财务台账 Performs code audits using tools like find_by_name and list_dir Conducts DB audits using the Supabase MCP to fetch the latest database schema Verifies the actual presence of UI components, server actions, helpers, and API routes Maps all implemented features in the codebase using recursive file reading Inspects database tables and columns for accuracy Supports multi-tenancy, fleet tracking, and financial ledgers system-reality-auditor is a skill that provides instructions on how to perform a comprehensive triple-point audit to ensure all master project documents accurately reflect reality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jusjinuk/internbot/arxiv-search', 'community', 'jusjinuk', 'internbot', 'jusjinuk/internbot', 'arxiv-search', 0, 0, 35, '2026-03-04T10:10:39Z', '2026-03-07T04:12:53.381Z', 'e0fa7be38e48c880985851f0c10ecf8f7fe4df9e75c0fc634c68c724c705175e', '{"id":"jusjinuk/internbot/arxiv-search","name":"arxiv-search","description":{"en":"The arxiv-search skill is a minimal Slack bot agent for research labs, utilizing Claude Agent SDK to search and summarize arXiv papers. It benefits researchers and labs by streamlining paper discovery","zh":"arxiv-search 是一个使用 Claude Agent SDK 构建的研究实验室 Slack 机器人，用于论文搜索和摘要。它支持按标题、作者或主题搜索论文","ja":"arxiv-search は、Claude Agent SDK を使用して構築された研究ラボの Slack ボットで、論文検索とサマライズ機能を提供します。タイトル、著者、またはトピックで論文を検索できます","ko":"arxiv-search는 Claude Agent SDK를 사용하여 구축된 연구실 슬랙봇으로 논문 검색 및 요약 기능을 제공합니다. 제목, 저자 또는 주제로 논문을 검색할 수 있습니다","es":"arxiv-search es un agente de Slack minimalista para laboratorios de investigación que utiliza el SDK de Claude Agent para buscar y resumir artículos de investigación","fr":"arxiv-search est un agent Slack minimaliste pour les laboratoires de recherche qui utilise le SDK de Claude Agent pour rechercher et résumer des articles de recherche","de":"arxiv-search ist ein minimalistischer Slack-Agent für Forschungslabore, der das Claude Agent SDK verwendet, um Forschungsartikel zu suchen und zusammenzufassen","pt":"O arxiv-search é um agente do Slack que permite a busca e resumo de artigos de pesquisa. Desenvolvido com Claude Agent SDK em TypeScript","ru":"arxiv-search - это агент Slack, который позволяет искать и резюмировать статьи исследований. Разработан с помощью Claude Agent SDK на TypeScript","ar":"arxiv-search هو عامل اسلكي يسمح بالبحث وتلخيص الأبحاث. تم تطويره باستخدام Claude Agent SDK بلغة TypeScript"},"seo":{"title":{"en":"arxiv-search: Setup Guide for AI Agents","zh":"arxiv-search Setup Guide: 使用 Claude Agent SDK 构建研究实验室 Sla...","ja":"arxiv-search セットアップガイド: Claude Agent SDK を使用した研究ラボの Slack...","ko":"arxiv-search 설정 가이드: Claude Agent SDK를 사용한 연구실 슬랙봇 구축","es":"Guía de configuración de arxiv-search: Búsqueda de artícu...","fr":"Guide de mise en place d''arxiv-search: Recherche d''articl...","de":"Einrichtungsleitfaden für arxiv-search: Suche nach Forsch...","pt":"Guia de Configuração do arxiv-search: Busca e Resumo de A...","ru":"Настройка arxiv-search: Поиск и Резюме Статей ИИ Агентов","ar":"دليل إعداد arxiv-search: بحث وتلخيص للأبحاث"},"description":{"en":"Unlock efficient research with arxiv-search! Discover how to use this minimal Slack bot agent to search and summarize arXiv papers by title, author, or topic","zh":"使用 arxiv-search 构建研究实验室的 Slack 机器人，实现论文搜索和摘要功能，了解如何使用 Claude Agent SDK","ja":"arxiv-search を使用して研究ラボの Slack ボットを構築し、論文検索とサマライズ機能を実現します。Claude Agent SDK の使い方を学びましょう","ko":"arxiv-search를 사용하여 연구실 슬랙봇을 구축하고 논문 검색 및 요약 기능을 구현하세요. Claude Agent SDK 사용법을 알아보세요","es":"Descubre cómo configurar arxiv-search, un agente de Slack para laboratorios de investigación, y aprovecha al máximo sus funcionalidades de búsqueda y resumen...","fr":"Découvrez comment configurer arxiv-search, un agent Slack pour les laboratoires de recherche, et exploitez au maximum ses fonctionnalités de recherche et de ...","de":"Erfahren Sie, wie Sie arxiv-search, einen Slack-Agent für Forschungslabore, einrichten und seine Such- und Zusammenfassungsfunktionen optimal nutzen","pt":"Descubra como configurar o arxiv-search, um agente minimalista do Slack para laboratórios de pesquisa, e melhore sua experiência de busca de artigos","ru":"Узнайте, как настроить arxiv-search, минимального бота Slack для исследовательских лабораторий, и улучшите опыт поиска статей с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد arxiv-search، وهو.bot بسيط لاسلكي لمعامل البحث، وتحسين تجربة البحث عن الأبحاث"},"definition":{"en":"arxiv-search is a TypeScript-based Slack bot agent that enables efficient searching and summarization of arXiv papers using the Claude Agent SDK","zh":"arxiv-search 是一个基于 Claude Agent SDK 的研究实验室 Slack 机器人，用于论文搜索和摘要","ja":"arxiv-search は、Claude Agent SDK を使用した研究ラボの Slack ボットで、論文検索とサマライズ機能を提供する AI エージェントです","ko":"arxiv-search는 Claude Agent SDK를 사용하여 구축된 연구실 슬랙봇으로 논문 검색 및 요약 기능을 제공하는 AI 도구입니다","es":"arxiv-search es un agente de búsqueda de artículos de investigación que utiliza el SDK de Claude Agent","fr":"arxiv-search est un agent de recherche d''articles de recherche qui utilise le SDK de Claude Agent","de":"arxiv-search ist ein Suchagent für Forschungsartikel, der das Claude Agent SDK verwendet","pt":"O que é arxiv-search? É um agente do Slack que busca e resume artigos de pesquisa","ru":"Что такое arxiv-search? Это агент Slack, который ищет и резюмирует статьи исследований","ar":"ما هو arxiv-search؟ هو عامل اسلكي يبحث ويلخص الأبحاث"},"features":{"en":["Searching by topic using the `mcp__arxiv__search` command","Combining keywords for precise search queries, such as \"transformer attention mechanism efficiency\"","Support for searching by arxiv URL or ID, e.g., 2301.07041","Ability to ask about new papers in a specific field or topic","Handling of multiple search angles for optimal results"],"zh":["使用 mcp__arxiv__search 函数进行论文搜索","支持按标题、作者或主题搜索论文","可以使用特定领域的术语进行搜索","支持搜索多个角度的结果"],"ja":["mcp__arxiv__search 関数を使用して論文を検索する","タイトル、著者、またはトピックで論文を検索する","特定の分野の用語を使用して検索する","複数の角度からの結果を検索する"],"ko":["mcp__arxiv__search 함수를 사용하여 논문을 검색합니다","제목, 저자 또는 주제로 논문을 검색할 수 있습니다","특정 분야의 용어를 사용하여 검색할 수 있습니다","다중 각도에서 결과를 검색할 수 있습니다"],"es":["Búsqueda de artículos por título, autor o tema","Compatibilidad con URLs y IDs de arXiv","Capacidad para resumir artículos de investigación","Uso de términos específicos de campo para la búsqueda","Posibilidad de buscar desde múltiples ángulos"],"fr":["Recherche d''articles par titre, auteur ou sujet","Compatibilité avec les URLs et les IDs d''arXiv","Capacité à résumer des articles de recherche","Utilisation de termes spécifiques de domaine pour la recherche","Possibilité de rechercher sous plusieurs angles"],"de":["Suche nach Artikeln nach Titel, Autor oder Thema","Kompatibilität mit arXiv-URLs und -IDs","Fähigkeit, Forschungsartikel zusammenzufassen","Verwendung von fachspezifischen Begriffen für die Suche","Möglichkeit, aus mehreren Perspektiven zu suchen"],"pt":["Busca por tópico com queries personalizadas","Suporte a busca por título, autor ou URL do arXiv","Resumo de artigos de pesquisa","Desenvolvido com Claude Agent SDK em TypeScript","Integração com o Slack"],"ru":["Поиск по теме с помощью индивидуальных запросов","Поддержка поиска по названию, автору или URL arXiv","Резюме статей исследований","Разработан с помощью Claude Agent SDK на TypeScript","Интеграция с Slack"],"ar":["بحث حسب الموضوع باستخدام استفسارات مخصصة","دعم البحث حسب العنوان أو المؤلف أو الرابط arXiv","تلخيص الأبحاث","تم تطويره باستخدام Claude Agent SDK بلغة TypeScript","التكامل مع التطبيق الاسلكي"]},"keywords":{"en":["how to use arxiv-search","arxiv-search setup guide","arxiv-search alternative","what is arxiv-search","arxiv-search vs other research tools","installing arxiv-search","arxiv-search for research labs","Claude Agent SDK integration","arxiv paper search and summarize"],"zh":["arxiv-search","Claude Agent SDK","Slack 机器人","论文搜索","论文摘要","AI 机器人","研究实验室","mcp__arxiv__search"],"ja":["arxiv-search","Claude Agent SDK","Slack ボット","論文検索","論文サマライズ","AI エージェント","研究ラボ","mcp__arxiv__search"],"ko":["arxiv-search","Claude Agent SDK","슬랙봇","논문 검색","논문 요약","AI 도구","연구실","mcp__arxiv__search"],"es":["arxiv-search","agente de Slack","búsqueda de artículos de investigación","resumen de artículos","SDK de Claude Agent","herramientas de investigación","agente de búsqueda de artículos","arXiv","investigación científica"],"fr":["arxiv-search","agent Slack","recherche d''articles de recherche","résumé d''articles","SDK de Claude Agent","outils de recherche","agent de recherche d''articles","arXiv","recherche scientifique"],"de":["arxiv-search","Slack-Agent","Suche nach Forschungsartikeln","Zusammenfassung von Artikeln","Claude Agent SDK","Forschungstools","Suchagent für Forschungsartikel","arXiv","wissenschaftliche Forschung"],"pt":["arxiv-search","busca de artigos","resumo de pesquisas","agente do Slack","Claude Agent SDK","TypeScript","laboratórios de pesquisa","ferramentas de pesquisa"],"ru":["arxiv-search","поиск статей","резюме исследований","агент Slack","Claude Agent SDK","TypeScript","исследовательские лаборатории","инструменты поиска"],"ar":["arxiv-search","بحث الأبحاث","تلخيص الأبحاث","عامل الاسلكي","Claude Agent SDK","TypeScript","معامل البحث","أدوات البحث"]}},"owner":"jusjinuk","repo":"internbot","repoPath":"jusjinuk/internbot","stars":0,"forks":0,"updatedAt":"2026-03-04T10:10:39Z","topics":[],"category":"community","skillMd":{"name":"arxiv-search","description":"Search and summarize arxiv papers. Use when asked about papers, research topics, or specific arxiv IDs.","bodyPreview":"# ArXiv Paper Search & Summarize\n\n## When to use\n\n- User asks about a paper by title, author, or topic\n- User shares an arxiv URL or ID (e.g., 2301.07041)\n- User asks \"what''s new in [field]?\" or \"find papers on [topic]\"\n\n## Workflow\n\n### Searching by topic\n1. Use `mcp__arxiv__search` with a well-crafted query\n   - Combine keywords: \"transformer attention mechanism efficiency\"\n   - Use field-specific terms, not casual language\n   - Search multiple angles if the first query returns weak results\n2.","body":"# ArXiv Paper Search & Summarize\n\n## When to use\n\n- User asks about a paper by title, author, or topic\n- User shares an arxiv URL or ID (e.g., 2301.07041)\n- User asks \"what''s new in [field]?\" or \"find papers on [topic]\"\n\n## Workflow\n\n### Searching by topic\n1. Use `mcp__arxiv__search` with a well-crafted query\n   - Combine keywords: \"transformer attention mechanism efficiency\"\n   - Use field-specific terms, not casual language\n   - Search multiple angles if the first query returns weak results\n2. Filter results by relevance — skip papers that only tangentially match\n\n### Fetching a specific paper\n1. Extract the arxiv ID from URL or text (e.g., `2301.07041` from `https://arxiv.org/abs/2301.07041`)\n2. Use `mcp__arxiv__get_paper` to fetch full metadata\n\n### Summarizing\nFor each paper, provide:\n- **Title** and authors (first author et al. if many)\n- **Core problem**: what gap or question does this address?\n- **Method**: the key technical approach in 1-2 sentences\n- **Results**: quantitative results where available (e.g., \"achieves 94.2% on ImageNet, +2.1% over baseline\")\n- **Limitations**: what the paper doesn''t address or where it falls short\n- **Why it matters**: one sentence on significance for the user''s question\n\n### Formatting for Slack\n- Use plain text, no markdown headers (Slack doesn''t render them)\n- Separate papers with blank lines\n- Include arxiv links: `https://arxiv.org/abs/{id}`\n- Keep each summary to 4-6 lines — users can ask for deeper dives on specific papers\n- If returning multiple papers, number them and put the most relevant first\n"},"lastSynced":"2026-03-07T04:12:53.381Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents utilizing Claude Agent SDK to streamline academic paper discovery and summarization.","zh":"适用于使用 Claude Agent SDK 的研究代理，以简化学术论文的发现和总结。","ja":"Claude Agent SDK を使用する研究エージェントに適しています。学術論文の発見と要約をストリームライン化するために。","ko":"Claude Agent SDK를 사용하는 연구 에이전트에 적합합니다. 학술 논문의 발견과 요약을 간소화하기 위해","es":"Ideal para agentes de investigación que utilizan Claude Agent SDK para agilizar el descubrimiento y la resumen de artículos académicos.","fr":"Idéal pour les agents de recherche utilisant Claude Agent SDK pour rationaliser la découverte et la synthèse d''articles universitaires.","de":"Ideal für Forschungsagenten, die Claude Agent SDK verwenden, um die Entdeckung und Zusammenfassung wissenschaftlicher Artikel zu rationalisieren.","pt":"Ideal para Agentes de Pesquisa que utilizam o Claude Agent SDK para otimizar a descoberta e resumo de artigos acadêmicos.","ru":"Идеально для исследовательских агентов, использующих Claude Agent SDK для оптимизации открытия и суммирования академических статей.","ar":"مثالي للوكلاء البحثيين الذين يستخدمون Claude Agent SDK لتسريع اكتشاف وتلخيص الأوراق الأكاديمية."},"recommendation":{"en":"Empowers agents to efficiently search and summarize arXiv papers using well-crafted queries, combining keywords and field-specific terms, and providing results for topics, authors, or titles, leveraging the mcp__arxiv__search functionality.","zh":"赋予代理高效地搜索和总结 arXiv 论文的能力，使用精心设计的查询，结合关键词和特定领域的术语，并提供主题、作者或标题的结果，利用 mcp__arxiv__search 功能。","ja":"エージェントに、arXiv 論文を効率的に検索して要約する能力を与えます。キーワードや分野特有の用語を組み合わせた精心設計されたクエリを使用し、トピック、著者、またはタイトルの結果を提供します。mcp__arxiv__search 機能を利用します。","ko":"에이전트가 효율적으로 arXiv 논문을 검색하고 요약할 수 있는 기능을 제공합니다. 키워드와 특정 분야의 용어를 결합한 잘設計된 쿼리를 사용하여 주제, 저자 또는 제목의 결과를 제공하며, mcp__arxiv__search 기능을 활용합니다.","es":"Habilita a los agentes a buscar y resumir de manera eficiente artículos de arXiv utilizando consultas bien elaboradas, combinando palabras clave y términos específicos de campo, y proporcionando resultados para temas, autores o títulos, aprovechando la funcionalidad de mcp__arxiv__search.","fr":"Permet aux agents de recherche et de synthèse efficaces d''articles arXiv en utilisant des requêtes bien conçues, combinant des mots-clés et des termes spécifiques au domaine, et fournissant des résultats pour les sujets, les auteurs ou les titres, en exploitant la fonctionnalité de mcp__arxiv__search.","de":"Ermöglicht es Agenten, arXiv-Artikel effizient zu suchen und zusammenzufassen, indem sie gut gestaltete Abfragen verwenden, die Schlüsselwörter und feldspezifische Terme kombinieren, und Ergebnisse für Themen, Autoren oder Titel bereitstellen, indem sie die mcp__arxiv__search-Funktionalität nutzen.","pt":"Habilita os agentes a eficientemente pesquisar e resumir artigos arXiv usando consultas bem elaboradas, combinando palavras-chave e termos específicos de campo, e fornecendo resultados para tópicos, autores ou títulos, utilizando a funcionalidade mcp__arxiv__search.","ru":"Наделяет агентов возможностью эффективно искать и суммировать статьи arXiv с помощью хорошо составленных запросов, объединяя ключевые слова и термины, специфичные для области, и предоставляя результаты для тем, авторов или названий, используя функциональность mcp__arxiv__search.","ar":"يمنح الوكلاء القدرة على البحث بكفاءة وتلخيص أوراق arXiv باستخدام استعلامات محكمة الصياغة، ودمج الكلمات الرئيسية والألفاظ الخاصة بالمجال، وتقديم نتائج لمواضيع، ومؤلفين، أو عناوين، وتستخدم وظيفة mcp__arxiv__search."},"useCases":{"en":["Searching arXiv papers by title, author, or topic","Summarizing papers shared via arxiv URL or ID","Discovering new papers in a specific field or topic"],"zh":["通过标题、作者或主题搜索 arXiv 论文","通过 arxiv URL 或 ID 共享的论文进行总结","在特定领域或主题中发现新论文"],"ja":["タイトル、著者、またはトピックで arXiv 論文を検索する","arxiv URL または ID で共有された論文を要約する","特定の分野またはトピックで新しい論文を発見する"],"ko":["제목, 저자 또는 주제로 arXiv 논문을 검색","arxiv URL 또는 ID로 공유된 논문을 요약","특정 분야 또는 주제에서 새로운 논문을 발견"],"es":["Buscar artículos de arXiv por título, autor o tema","Resumir artículos compartidos a través de la URL o ID de arxiv","Descubrir nuevos artículos en un campo o tema específico"],"fr":["Rechercher des articles arXiv par titre, auteur ou sujet","Résumer des articles partagés via l''URL ou l''ID arxiv","Découvrir de nouveaux articles dans un domaine ou un sujet spécifique"],"de":["Suchen von arXiv-Artikeln nach Titel, Autor oder Thema","Zusammenfassen von Artikeln, die über die arxiv-URL oder -ID geteilt werden","Entdecken neuer Artikel in einem bestimmten Bereich oder Thema"],"pt":["Pesquisando artigos arXiv por título, autor ou tópico","Resumindo artigos compartilhados via URL ou ID arxiv","Descobrindo novos artigos em um campo ou tópico específico"],"ru":["Поиск статей arXiv по названию, автору или теме","Суммирование статей,共享 через URL или ID arxiv","Обнаружение новых статей в конкретной области или теме"],"ar":["البحث عن أوراق arXiv حسب العنوان، أو المؤلف، أو الموضوع","تلخيص الأوراق المشتركة عبر الرابط أو معرف arxiv","اكتشاف أوراق جديدة في مجال أو موضوع معين"]},"limitations":{"en":["Requires Claude Agent SDK integration","Limited to arXiv paper search and summarization"],"zh":["需要 Claude Agent SDK 集成","仅限 arXiv 论文搜索和总结"],"ja":["Claude Agent SDK の統合が必要","arXiv 論文の検索と要約のみ"],"ko":["Claude Agent SDK 통합이 필요","arXiv 논문 검색 및 요약만 가능"],"es":["Requiere integración con Claude Agent SDK","Limitado a la búsqueda y resumen de artículos de arXiv"],"fr":["Nécessite une intégration avec Claude Agent SDK","Limité à la recherche et à la synthèse d''articles arXiv"],"de":["Erfordert Integration mit Claude Agent SDK","Begrenzt auf die Suche und Zusammenfassung von arXiv-Artikeln"],"pt":["Requer integração com o Claude Agent SDK","Limitado à pesquisa e resumo de artigos arXiv"],"ru":["Требует интеграции с Claude Agent SDK","Ограничен поиском и суммированием статей arXiv"],"ar":["يتطلب تكاملًا مع Claude Agent SDK","محدود بالبحث و تلخيص أوراق arXiv"]},"version":4},"contentHash":"e0fa7be38e48c880985851f0c10ecf8f7fe4df9e75c0fc634c68c724c705175e","qualityScore":35}');
