INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jusjinuk/internbot/arxiv-search', 'arxiv-search', 'jusjinuk', 'internbot', 'community', 'arxiv-search jusjinuk internbot community The arxiv-search skill is a minimal Slack bot agent for research labs, utilizing Claude Agent SDK to search and summarize arXiv papers. It benefits researchers and labs by streamlining paper discovery arxiv-search 是一个使用 Claude Agent SDK 构建的研究实验室 Slack 机器人，用于论文搜索和摘要。它支持按标题、作者或主题搜索论文 arxiv-search は、Claude Agent SDK を使用して構築された研究ラボの Slack ボットで、論文検索とサマライズ機能を提供します。タイトル、著者、またはトピックで論文を検索できます arxiv-search는 Claude Agent SDK를 사용하여 구축된 연구실 슬랙봇으로 논문 검색 및 요약 기능을 제공합니다. 제목, 저자 또는 주제로 논문을 검색할 수 있습니다 arxiv-search es un agente de Slack minimalista para laboratorios de investigación que utiliza el SDK de Claude Agent para buscar y resumir artículos de investigación arxiv-search est un agent Slack minimaliste pour les laboratoires de recherche qui utilise le SDK de Claude Agent pour rechercher et résumer des articles de recherche arxiv-search ist ein minimalistischer Slack-Agent für Forschungslabore, der das Claude Agent SDK verwendet, um Forschungsartikel zu suchen und zusammenzufassen O arxiv-search é um agente do Slack que permite a busca e resumo de artigos de pesquisa. Desenvolvido com Claude Agent SDK em TypeScript arxiv-search - это агент Slack, который позволяет искать и резюмировать статьи исследований. Разработан с помощью Claude Agent SDK на TypeScript arxiv-search هو عامل اسلكي يسمح بالبحث وتلخيص الأبحاث. تم تطويره باستخدام Claude Agent SDK بلغة TypeScript how to use arxiv-search arxiv-search setup guide arxiv-search alternative what is arxiv-search arxiv-search vs other research tools installing arxiv-search arxiv-search for research labs Claude Agent SDK integration arxiv paper search and summarize arxiv-search Claude Agent SDK Slack 机器人 论文搜索 论文摘要 AI 机器人 研究实验室 mcp__arxiv__search Searching by topic using the `mcp__arxiv__search` command Combining keywords for precise search queries, such as "transformer attention mechanism efficiency" Support for searching by arxiv URL or ID, e.g., 2301.07041 Ability to ask about new papers in a specific field or topic Handling of multiple search angles for optimal results arxiv-search is a TypeScript-based Slack bot agent that enables efficient searching and summarization of arXiv papers using the Claude Agent SDK');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('curiousanthony/supabase-sveltekit/mentore-manager-notion', 'community', 'curiousanthony', 'supabase-sveltekit', 'curiousanthony/supabase-sveltekit', 'mentore-manager-notion', 0, 0, 35, '2026-02-27T16:54:35Z', '2026-03-07T04:14:25.916Z', '703521e22bf237f38d0fcdfe07ff590b562f835511324c847ccd73b82b83b4ad', '{"id":"curiousanthony/supabase-sveltekit/mentore-manager-notion","name":"mentore-manager-notion","description":{"en":"The mentore-manager-notion skill helps Learning Centers comply with Qualiopi conformity using a Notion-based SaaS app. It supports administrative management tasks within the Prototype Mentore Manager Notion space.","zh":"Mentore Manager Notion 是一个基于 Notion 的学习中心管理 SaaS 应用，使用 Notion MCP 可以轻松地管理学习中心","ja":"Mentore Manager Notion は Notion ベースの学習センター管理 SaaS アプリで、Notion MCP を使用して学習センターを簡単に管理できます","ko":"Mentore Manager Notion은 Notion 기반의 학습 센터 관리 SaaS 애플리케이션으로, Notion MCP를 사용하여 학습 센터를 쉽게 관리할 수 있습니다.","es":"Mentore-manager-notion es una herramienta de gestión SaaS para centros de aprendizaje que ayuda a cumplir con Qualiopi de manera sencilla","fr":"Mentore-manager-notion est un outil de gestion SaaS pour les centres d''apprentissage qui aide à se conformer à Qualiopi de manière simple","de":"Mentore-manager-notion ist ein SaaS-Management-Tool für Lernzentren, das dabei hilft, Qualiopi einfach zu erfüllen","pt":"O Mentore Manager Notion é uma ferramenta de IA que ajuda os Centros de Aprendizado a se conformar com a Qualiopi de forma fácil e eficaz","ru":"ИИ Агент Mentore Manager Notion - это инструмент, который помогает Центрам Обучения легче соответствовать требованиям Qualiopi","ar":"أداة Mentore Manager Notion الذكية هي أداة تساعد مراكز التعلم على الامتثال للوائح Qualiopi بسهولة وفعالية"},"seo":{"title":{"en":"mentore-manager-notion: Notion MCP Setup Guide | AI Agent...","zh":"Mentore Manager Notion Setup Guide - AIエージェント","ja":"Mentore Manager Notion ベストプラクティス - AIエージェント","ko":"Mentore Manager Notion 구축 가이드 - AI 도구","es":"Guía de configuración de mentore-manager-notion para Qual...","fr":"Guide d''installation de mentore-manager-notion pour Qualiopi","de":"Einrichtungsleitfaden für mentore-manager-notion mit Qual...","pt":"Guia de Configuração do Mentore Manager Notion - Ferramen...","ru":"Настройка ИИ Агента Mentore Manager Notion - Руководство","ar":"دليل إعداد أداة Mentore Manager Notion الذكية - إدارة التعلم"},"description":{"en":"Unlock efficient Qualiopi conformity with mentore-manager-notion. Discover how to set up and utilize the Notion MCP for streamlined administrative management.","zh":"了解 Mentore Manager Notion 的技术细节和设置方法，优化您的学习中心管理","ja":"Mentore Manager Notion の技術的側面と設定方法を学び、学習センター管理を最適化する","ko":"Mentore Manager Notion의 기술 세부 사항과 설정 방법을 알아보세요. 학습 센터 관리를 최적화하는 데 도움이 됩니다.","es":"Descubre cómo utilizar mentore-manager-notion para cumplir con Qualiopi de manera sencilla con nuestra herramienta de gestión SaaS","fr":"Découvrez comment utiliser mentore-manager-notion pour se conformer à Qualiopi de manière simple avec notre outil de gestion SaaS","de":"Erfahren Sie, wie Sie mentore-manager-notion verwenden können, um Qualiopi einfach zu erfüllen, mit unserer SaaS-Management-Plattform","pt":"Aprenda a configurar o Mentore Manager Notion, uma ferramenta de IA para facilitar a conformidade com a Qualiopi nos Centros de Aprendizado","ru":"Узнайте, как настроить ИИ Агент Mentore Manager Notion для легкой конформности с Qualiopi в Центрах Обучения","ar":"تعرف على كيفية إعداد أداة Mentore Manager Notion الذكية لتسهيل الامتثال مع Qualiopi في مراكز التعلم"},"definition":{"en":"mentore-manager-notion is a skill that utilizes the Notion MCP to facilitate administrative management for Learning Centers, ensuring Qualiopi conformity.","zh":"Mentore Manager Notion 是一个使用 Notion MCP 的学习中心管理工具","ja":"Mentore Manager Notion は Notion MCP を使用した学習センター管理ツールです","ko":"Mentore Manager Notion은 Notion MCP를 사용하는 학습 센터 관리 도구입니다.","es":"Mentore-manager-notion es un agente de inteligencia artificial que ayuda a los centros de aprendizaje a gestionar su conformidad con Qualiopi","fr":"Mentore-manager-notion est un agent d''intelligence artificielle qui aide les centres d''apprentissage à gérer leur conformité à Qualiopi","de":"Mentore-manager-notion ist ein künstliches Intelligenz-Tool, das Lernzentren bei der Verwaltung ihrer Qualiopi-Konformität unterstützt","pt":"O que é Mentore Manager Notion? É uma ferramenta de IA que facilita a gestão administrativa nos Centros de Aprendizado","ru":"Что такое ИИ Агент Mentore Manager Notion? Это инструмент, который упрощает административное управление в Центрах Обучения","ar":"ما هي أداة Mentore Manager Notion الذكية؟ هي أداة تسهل الإدارة الإدارية في مراكز التعلم"},"features":{"en":["Utilizes the Notion MCP for scoped actions within the Prototype Mentore Manager space","Supports Notion databases with specific title conventions","Enforces strict scope adherence to the Prototype Mentore Manager page hierarchy","Requires clarification via chat for ambiguous user requests","Operates exclusively within the defined Notion space for administrative management"],"zh":["使用 Notion MCP","基于 Notion 的学习中心管理","支持 Qualiopi 符合性","具有 Prototype Mentore Manager Notion 空间","支持 Notion 数据库管理"],"ja":["Notion MCP を使用","Notion ベースの学習センター管理","Qualiopi 符合性をサポート","Prototype Mentore Manager Notion 空間を提供","Notion データベース管理をサポート"],"ko":["Notion MCP 사용","Notion 기반의 학습 센터 관리","Qualiopi 준수를 지원","Prototype Mentore Manager Notion 공간 제공","Notion 데이터베이스 관리 지원"],"es":["Integración con Notion MCP","Gestión de bases de datos de Notion","Compatibilidad con Qualiopi","Acceso a la página de prototipo de Mentore Manager","Soporte para la jerarquía de páginas de Notion"],"fr":["Intégration avec Notion MCP","Gestion des bases de données Notion","Compatibilité avec Qualiopi","Accès à la page de prototype de Mentore Manager","Prise en charge de la hiérarchie des pages Notion"],"de":["Integration mit Notion MCP","Verwaltung von Notion-Datenbanken","Kompatibilität mit Qualiopi","Zugriff auf die Prototyp-Seite von Mentore Manager","Unterstützung für die Notion-Seiten-Hierarchie"],"pt":["Utiliza o Notion MCP para gerenciar conteúdo","Trabalha com o espaço de protótipo Mentore Manager","Suporta apenas conteúdo sob a página ''Prototype Mentore Manager''","Permite a clarificação de ações antes de prosseguir","Integração com bases de dados do Notion"],"ru":["Использует Notion MCP для управления контентом","Работает с прототипом пространства Mentore Manager","Поддерживает только контент под страницей ''Prototype Mentore Manager''","Позволяет уточнять действия перед продолжением","Интеграция с базами данных Notion"],"ar":["يستخدم Notion MCP لإدارة المحتوى","يعمل مع مساحة نموذج Mentore Manager","يدعم فقط المحتوى تحت صفحة ''Prototype Mentore Manager''","يسمح بتوضيح الإجراءات قبل المتابعة","دمج مع قواعد بيانات Notion"]},"keywords":{"en":["how to use mentore-manager-notion","mentore-manager-notion setup guide","Notion MCP for administrative management","Qualiopi conformity solutions","mentore-manager-notion alternative","mentore-manager-notion vs other SaaS apps","install mentore-manager-notion","mentore-manager-notion tutorial","Notion-based SaaS apps for Learning Centers"],"zh":["Mentore Manager Notion","Notion MCP","学习中心管理","Qualiopi 符合性","Notion 数据库管理","AIエージェント","SaaS 应用"],"ja":["Mentore Manager Notion","Notion MCP","学習センター管理","Qualiopi 符合性","Notion データベース管理","AIエージェント","SaaS アプリ"],"ko":["Mentore Manager Notion","Notion MCP","학습 센터 관리","Qualiopi 준수","Notion 데이터베이스 관리","AI 도구","SaaS 애플리케이션"],"es":["mentore manager notion","qualiopi","saas para centros de aprendizaje","herramientas de gestión para centros de aprendizaje","agentes de inteligencia artificial para educación","notion mcp","gestión de bases de datos de notion"],"fr":["mentore manager notion","qualiopi","saas pour les centres d''apprentissage","outils de gestion pour les centres d''apprentissage","agents d''intelligence artificielle pour l''éducation","notion mcp","gestion des bases de données notion"],"de":["mentore manager notion","qualiopi","saas für lernzentren","management-tools für lernzentren","künstliche intelligenz-tools für bildung","notion mcp","verwaltung von notion-datenbanken"],"pt":["ferramentas de ia para centros de aprendizado","configuração do mentore manager notion","qualiopi conformidade","notion mcp","gestão administrativa","desenvolvimento de saas"],"ru":["инструменты ии для центров обучения","настройка ии агента mentore manager notion","конформность qualiopi","notion mcp","административное управление","разработка saas"],"ar":["أدوات ذكية لمراكز التعلم","إعداد أداة mentore manager notion","الامتثال للوائح qualiopi","notion mcp","الإدارة الإدارية","تطوير تطبيقات سحابية"]}},"owner":"curiousanthony","repo":"supabase-sveltekit","repoPath":"curiousanthony/supabase-sveltekit","stars":0,"forks":0,"updatedAt":"2026-02-27T16:54:35Z","topics":[],"category":"community","skillMd":{"name":"mentore-manager-notion","description":"Uses the Notion MCP to work with the Prototype Mentore Manager Notion workspace. Infers database schema from Notion DB props, reviews/analyzes the prototype for MVP readiness, and suggests or adds missing database properties. Use when the user says infer db schema, infer schema, review notion, analyze notion, add props, what props would you add?, or references the Prototype Mentore Manager or Notion databases for the Mentore Manager app.","bodyPreview":"# Mentore Manager – Notion Prototype\n\nWork with the **Prototype Mentore Manager** Notion space using the Notion MCP. All actions are scoped to that prototype; other Notion content is out of scope.\n\n**When clarification is needed** (e.g., which database, which page, ambiguous name), ask the user in chat before proceeding. Do not guess.\n\n---\n\n## Scope (strict)\n\n- **In scope**: Only content under the **\"Prototype Mentore Manager\"** page (by parent hierarchy). Only Notion **databases** whose title e","body":"# Mentore Manager – Notion Prototype\n\nWork with the **Prototype Mentore Manager** Notion space using the Notion MCP. All actions are scoped to that prototype; other Notion content is out of scope.\n\n**When clarification is needed** (e.g., which database, which page, ambiguous name), ask the user in chat before proceeding. Do not guess.\n\n---\n\n## Scope (strict)\n\n- **In scope**: Only content under the **\"Prototype Mentore Manager\"** page (by parent hierarchy). Only Notion **databases** whose title ends with:\n  - **`(mm)`** – core Mentore Manager\n  - **`(mm biblio)`** – Library feature (avoids name clashes)\n- **Out of scope**: Any page or database that is not under \"Prototype Mentore Manager\", or any database that does not end with `(mm)` or `(mm biblio)`. Ignore those.\n\nUse **Notion MCP** tools: `notion-search`, `notion-fetch`, `notion-update-data-source`, `notion-create-pages`, `notion-update-page`, etc., as needed for each workflow.\n\n---\n\n## 1. Infer database schema\n\n**When**: User says \"infer db schema\", \"infer schema\", or similar, and provides or identifies a Notion database.\n\n**Steps**:\n\n1. **Resolve the database**\n   - If the user gave a name/URL, search with `notion-search` (query type `internal`) scoped to the Prototype Mentore Manager context, or fetch by URL/ID.\n   - Confirm the database title ends with `(mm)` or `(mm biblio)`. If not, tell the user it is out of scope.\n2. **Fetch the database**\n   - Use `notion-fetch` with the database URL or ID to get the full schema: property names, types, and options (e.g. select/multi_select options, relation targets).\n3. **Infer schema for code**\n   - Map Notion property types to your app’s schema (e.g. Supabase/Postgres or app types):\n     - title → typically primary display / label\n     - rich_text → text/varchar\n     - number → integer/numeric\n     - select, multi_select → enum or lookup tables\n     - date → date/timestamptz\n     - relation → foreign keys / relations\n     - checkbox → boolean\n     - url, email, phone_number → appropriate column types\n   - Output a clear schema summary (tables, columns, types, relations) that can be used for migrations or type definitions. Note any ambiguities and ask the user if needed.\n\n---\n\n## 2. Review / analyze Notion (MVP readiness)\n\n**When**: User says \"review notion\", \"analyze notion\", or wants a review of the prototype for the app.\n\n**Steps**:\n\n1. **Find the prototype root**\n   - Search for \"Prototype Mentore Manager\" and fetch that page to confirm hierarchy and child pages/databases.\n2. **List in-scope databases**\n   - Identify all databases under that hierarchy whose titles end with `(mm)` or `(mm biblio)`. Fetch each to get structure.\n3. **Analyze and recommend**\n   - **Props**: Missing or inconsistent properties (e.g. status, dates, assignees, relations).\n   - **Page names / structure**: Naming consistency, clarity, alignment with app screens/features.\n   - **Databases (data sources)**: Gaps (e.g. missing entity types), redundant or duplicate concepts.\n   - **Relations**: Missing relations between databases, or relation direction/meaning that should be clarified for the app.\n4. **Output**\n   - Short executive summary.\n   - Bulleted recommendations per area (props, page names, databases, relations).\n   - Goal: MVP UX is ready in Notion and the codebase stays in sync on core concepts, schema, and relations.\n\n---\n\n## 3. Add or suggest props for a database\n\n**When**: User says \"add props\", \"what props would you add?\", or similar, and refers to a specific database (by name or context).\n\n**Steps**:\n\n1. **Resolve and fetch the database**\n   - Identify the database (must end with `(mm)` or `(mm biblio)` and be under Prototype Mentore Manager). Fetch it with `notion-fetch` to get current properties and types.\n2. **Analyze context**\n   - Consider the database’s role in the app (e.g. courses, members, library items), what the system needs (e.g. status, dates, ownership), and what the user should see in the finished app.\n3. **Suggest missing props**\n   - List current props, then suggest new ones with:\n     - Property name\n     - Notion type (select, date, relation, etc.)\n     - Brief reason (system need vs user need).\n   - If the user asked to **add** props, use `notion-update-data-source` to add properties; confirm with the user before applying changes. If the user asked what you **would** add, output recommendations only and offer to apply after validation.\n4. **Validate with the user**\n   - Summarize changes or suggestions and ask for confirmation before creating or updating properties in Notion.\n\n---\n\n## 4. Implémenter un ticket (du Suivi de projet)\n\n**When**: L''agent s''apprête à coder une fonctionnalité issue d''un ticket Notion (typiquement après avoir utilisé le skill `suivi-de-projet` pour identifier le ticket).\n\n**Règle fondamentale** : avant d''écrire la moindre ligne de code, chercher et lire la page prototype correspondante dans **Prototype Mentore Manager**. Le prototype est la spécification vivante de l''UI, du schéma DB et des relations.\n\n**Steps**:\n\n1. **Lire le ticket**\n   - Fetch le ticket depuis Notion (via le skill `suivi-de-projet`) : titre, description, type, projet associé.\n   - Identifier le nom de la fonctionnalité / entité cible (ex. \"CRM\", \"Clients\", \"Formations\").\n\n2. **Chercher la page prototype**\n   - `notion-search` dans le scope Prototype Mentore Manager avec le nom de la fonctionnalité.\n   - Confirmer que la page trouvée est bien sous \"Prototype Mentore Manager\" (vérifier `ancestor-path`).\n   - Si aucune page prototype n''est trouvée : **demander à l''utilisateur** plutôt que de supposer. Ne pas inventer de specs.\n\n3. **Lire les specs du prototype**\n   - `notion-fetch` sur la page prototype → lire le contenu : UI, flux, propriétés, bases de données liées (`(mm)` ou `(mm biblio)`).\n   - Pour les bases de données liées : fetch leur schéma (propriétés, types, relations) — c''est la source de vérité pour le schéma Drizzle/Supabase.\n\n4. **Implémenter**\n   - Coder la fonctionnalité en suivant le prototype (UI avec svelte5-stack, DB avec supabase-database-migration).\n   - Reproduire fidèlement les propriétés et relations telles qu''elles apparaissent dans le prototype.\n\n5. **Mettre à jour le ticket**\n   - Après implémentation validée : utiliser le skill `suivi-de-projet` (Workflow 4) pour passer le ticket à `⏳ En cours` au début, puis `✅ Fait` une fois terminé et testé.\n\n6. **Ajouter un récap sur le ticket**\n   - Si l''utilisateur demande d''ajouter un récap (en français) sur la page Notion du ticket : ne jamais l''ajouter au contenu de la page. Toujours utiliser le skill `suivi-de-projet`, **Workflow 7** : ajouter un **commentaire** sur la page du ticket, avec un préfixe indiquant clairement que c''est l''agent qui laisse le récap, et en mentionnant Anthony.\n\n---\n\n## Additional resources\n\n- Trigger phrases, scope summary, and Notion→app type mapping: [reference.md](reference.md)\n"},"lastSynced":"2026-03-07T04:14:25.916Z","agentAnalysis":{"suitability":{"en":"Perfect for Administrative Agents needing Notion-based SaaS app management for Qualiopi conformity","zh":"非常适合需要基于Notion的SaaS应用管理以符合Qualiopi标准的行政代理","ja":"Qualiopi準拠のNotionベースのSaaSアプリ管理を必要とする管理エージェントに最適","ko":"Qualiopi 규정 준수를 위한 Notion 기반 SaaS 앱 관리가 필요한 행정 에이전트에게 적합","es":"Perfecto para Agentes Administrativos que necesitan administración de aplicaciones SaaS basadas en Notion para la conformidad Qualiopi","fr":"Parfait pour les agents administratifs ayant besoin d''une gestion d''applications SaaS basées sur Notion pour la conformité Qualiopi","de":"Perfekt für Administrative Agenten, die eine Notion-basierte SaaS-App-Verwaltung für die Qualiopi-Konformität benötigen","pt":"Perfeito para Agentes Administrativos que precisam de gerenciamento de aplicativos SaaS baseados no Notion para conformidade com o Qualiopi","ru":"Идеально подходит для административных агентов, которым необходимо управление приложениями SaaS на основе Notion для соответствия требованиям Qualiopi","ar":"مثالي للوكلاء الإداريين الذين يحتاجون إلى إدارة تطبيقات SaaS المستندة إلى Notion للامتثال لمعيار Qualiopi"},"recommendation":{"en":"Empowers agents to manage administrative tasks within the Prototype Mentore Manager Notion space using the Notion MCP, supporting databases and pages with precise scoping and clarification protocols","zh":"赋予代理在Prototype Mentore Manager Notion空间内管理行政任务的能力，使用Notion MCP，支持具有精确范围和澄清协议的数据库和页面","ja":"Prototype Mentore Manager Notionスペース内で行政タスクを管理するエージェントをEmpowerできる。Notion MCPを使用して、正確な範囲と明確化プロトコルを持つデータベースとページをサポート","ko":"프로토タイプ 멘토어 매니저 Notion 공간에서 행정 작업을 관리할 수 있는 에이전트를 강화합니다. Notion MCP를 사용하여 정확한 범위 및 명확화 프로토콜을 갖춘 데이터베이스 및 페이지를 지원합니다","es":"Habilita a los agentes a gestionar tareas administrativas dentro del espacio Notion Prototype Mentore Manager utilizando el Notion MCP, que admite bases de datos y páginas con protocolos de alcance y aclaración precisos","fr":"Permet aux agents de gérer des tâches administratives au sein de l''espace Notion Prototype Mentore Manager en utilisant le Notion MCP, qui prend en charge des bases de données et des pages avec des protocoles de portée et de clarification précis","de":"Ermächtigt die Agenten, administrative Aufgaben innerhalb des Notion-Prototype-Mentore-Manager-Raums mit dem Notion MCP zu verwalten, der Datenbanken und Seiten mit präzisen Scoping- und Klärungsprotokollen unterstützt","pt":"Habilita os agentes a gerenciar tarefas administrativas dentro do espaço Notion do Prototype Mentore Manager usando o Notion MCP, com suporte a bancos de dados e páginas com protocolos de escopo e clarificação precisos","ru":"Наделяет агентов возможностью управлять административными задачами внутри пространства Notion Prototype Mentore Manager с использованием Notion MCP, поддерживающего базы данных и страницы с точными протоколами области видимости и разъяснения","ar":"تمكّن الوكلاء من إدارة المهام الإدارية داخل مساحة Notion لبروتوتايب Mentore Manager باستخدام Notion MCP، مع دعم قواعد البيانات والصفحات ببروتوكولات نطاق دقيق وبروتوكولات توضيح"},"useCases":{"en":["Automating tasks within the Prototype Mentore Manager Notion space","Managing Notion databases for Qualiopi conformity","Clarifying ambiguous Notion content using chat protocols"],"zh":["在Prototype Mentore Manager Notion空间内自动执行任务","管理Notion数据库以符合Qualiopi标准","使用聊天协议澄清模糊的Notion内容"],"ja":["Prototype Mentore Manager Notionスペース内でのタスクの自動化","Notionデータベースの Qualiopi 準拠管理","チャットプロトコルを使用した曖昧なNotionコンテンツの明確化"],"ko":["프로토タイプ 멘토어 매니저 Notion 공간 내에서 작업 자동화","Notion 데이터베이스의 Qualiopi 규정 준수 관리","채팅 프로토콜을 사용한 모호한 Notion 콘텐츠 명확화"],"es":["Automatizar tareas dentro del espacio Notion Prototype Mentore Manager","Gestionar bases de datos Notion para la conformidad Qualiopi","Aclarar contenido Notion ambiguo mediante protocolos de chat"],"fr":["Automatiser des tâches au sein de l''espace Notion Prototype Mentore Manager","Gérer des bases de données Notion pour la conformité Qualiopi","Clarifier le contenu Notion ambigu en utilisant des protocoles de chat"],"de":["Automatisierung von Aufgaben innerhalb des Notion-Prototype-Mentore-Manager-Raums","Verwaltung von Notion-Datenbanken für die Qualiopi-Konformität","Klärung von mehrdeutigem Notion-Inhalt unter Verwendung von Chat-Protokollen"],"pt":["Automatizar tarefas dentro do espaço Notion do Prototype Mentore Manager","Gerenciar bancos de dados Notion para conformidade com o Qualiopi","Esclarecer conteúdo ambíguo do Notion usando protocolos de chat"],"ru":["Автоматизировать задачи внутри пространства Notion Prototype Mentore Manager","Управлять базами данных Notion для соответствия требованиям Qualiopi","Разъяснять неоднозначный контент Notion с помощью протоколов чата"],"ar":["أتمتة المهام داخل مساحة Notion لبروتوتايب Mentore Manager","إدارة قواعد بيانات Notion للامتثال لمعيار Qualiopi","توضيح محتوى Notion الغامض باستخدام بروتوكولات الدردشة"]},"limitations":{"en":["Scoped only to the Prototype Mentore Manager Notion space","Requires Notion MCP for interaction","Limited to Notion databases whose title matches the specified criteria"],"zh":["仅限于Prototype Mentore Manager Notion空间","需要Notion MCP进行交互","仅限于标题与指定标准匹配的Notion数据库"],"ja":["Prototype Mentore Manager Notionスペースのみに限定","Notion MCPが必要なインタラクション","指定された基準とタイトルが一致するNotionデータベースのみに限定"],"ko":["프로토タイプ 멘토어 매니저 Notion 공간으로 제한됨","Notion MCP가 필요함","지정된 기준과 제목이 일치하는 Notion 데이터베이스로 제한됨"],"es":["Limitado solo al espacio Notion Prototype Mentore Manager","Requiere Notion MCP para la interacción","Limitado a bases de datos Notion cuyo título coincide con los criterios especificados"],"fr":["Limité uniquement à l''espace Notion Prototype Mentore Manager","Nécessite Notion MCP pour l''interaction","Limité aux bases de données Notion dont le titre correspond aux critères spécifiés"],"de":["Nur auf den Notion-Prototype-Mentore-Manager-Raum beschränkt","Benötigt Notion MCP für die Interaktion","Begrenzt auf Notion-Datenbanken, deren Titel den angegebenen Kriterien entspricht"],"pt":["Limitado apenas ao espaço Notion do Prototype Mentore Manager","Exige Notion MCP para interação","Limitado a bancos de dados Notion cujo título corresponda aos critérios especificados"],"ru":["Ограничен только пространством Notion Prototype Mentore Manager","Требует Notion MCP для взаимодействия","Ограничен базами данных Notion, название которых соответствует указанным критериям"],"ar":["محدود فقط بمساحة Notion لبروتوتايب Mentore Manager","يتطلب Notion MCP للتفاعل","محدود بقواعد بيانات Notion التي تطابق المعايير المحددة"]},"version":4},"contentHash":"703521e22bf237f38d0fcdfe07ff590b562f835511324c847ccd73b82b83b4ad","qualityScore":35}');
