INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('curiousanthony/supabase-sveltekit/mentore-manager-notion', 'mentore-manager-notion', 'curiousanthony', 'supabase-sveltekit', 'community', 'mentore-manager-notion curiousanthony supabase-sveltekit community The mentore-manager-notion skill helps Learning Centers comply with Qualiopi conformity using a Notion-based SaaS app. It supports administrative management tasks within the Prototype Mentore Manager Notion space. Mentore Manager Notion 是一个基于 Notion 的学习中心管理 SaaS 应用，使用 Notion MCP 可以轻松地管理学习中心 Mentore Manager Notion は Notion ベースの学習センター管理 SaaS アプリで、Notion MCP を使用して学習センターを簡単に管理できます Mentore Manager Notion은 Notion 기반의 학습 센터 관리 SaaS 애플리케이션으로, Notion MCP를 사용하여 학습 센터를 쉽게 관리할 수 있습니다. Mentore-manager-notion es una herramienta de gestión SaaS para centros de aprendizaje que ayuda a cumplir con Qualiopi de manera sencilla Mentore-manager-notion est un outil de gestion SaaS pour les centres d''apprentissage qui aide à se conformer à Qualiopi de manière simple Mentore-manager-notion ist ein SaaS-Management-Tool für Lernzentren, das dabei hilft, Qualiopi einfach zu erfüllen O Mentore Manager Notion é uma ferramenta de IA que ajuda os Centros de Aprendizado a se conformar com a Qualiopi de forma fácil e eficaz ИИ Агент Mentore Manager Notion - это инструмент, который помогает Центрам Обучения легче соответствовать требованиям Qualiopi أداة Mentore Manager Notion الذكية هي أداة تساعد مراكز التعلم على الامتثال للوائح Qualiopi بسهولة وفعالية how to use mentore-manager-notion mentore-manager-notion setup guide Notion MCP for administrative management Qualiopi conformity solutions mentore-manager-notion alternative mentore-manager-notion vs other SaaS apps install mentore-manager-notion mentore-manager-notion tutorial Notion-based SaaS apps for Learning Centers Mentore Manager Notion Notion MCP 学习中心管理 Qualiopi 符合性 Notion 数据库管理 AIエージェント SaaS 应用 Utilizes the Notion MCP for scoped actions within the Prototype Mentore Manager space Supports Notion databases with specific title conventions Enforces strict scope adherence to the Prototype Mentore Manager page hierarchy Requires clarification via chat for ambiguous user requests Operates exclusively within the defined Notion space for administrative management mentore-manager-notion is a skill that utilizes the Notion MCP to facilitate administrative management for Learning Centers, ensuring Qualiopi conformity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chijunzheng/ShowMe/coder', 'community', 'chijunzheng', 'ShowMe', 'chijunzheng/ShowMe', 'coder', 0, 0, 35, '2026-02-09T16:06:44Z', '2026-03-07T13:12:50.513Z', '1e1577f0225b804d1be80fc3d833c8aa1356c09b4f8424003103cae8c3a16231', '{"id":"chijunzheng/ShowMe/coder","name":"coder","description":{"en":"The Coder skill enables developers to build scalable, maintainable, and secure software systems. It benefits principal engineers and software architects with deep expertise in diverse technology stacks.","zh":"Coder AI Agent是一位精通软件架构和开发的专家，具有20多年的经验，能够构建可扩展、可维护和安全的软件系统","ja":"AIエージェントCoderは、20年以上の経験を持つエリートソフトウェアアーキテクトであり、スケーラブルでメンテナンス可能なソフトウェアシステムを構築する","ko":"Coder AI 에이전트는 20년 이상의 경험을 가진 엘리트 소프트웨어 아키텍트로 확장 가능하고 유지 보수 가능한 소프트웨어 시스템을 구축할 수 있습니다","es":"Coder es un agente de código de IA que ayuda a los desarrolladores a crear software escalable, mantenible y seguro. Con más de 20 años de experiencia en diversas pilas de tecnología","fr":"Coder est un outil de code IA qui aide les développeurs à créer des logiciels évolutifs, maintenables et sécurisés. Avec plus de 20 ans d''expérience dans diverses piles de technologie","de":"Coder ist ein KI-Code-Agent, der Entwicklern hilft, skalierbare, wartbare und sichere Software zu erstellen. Mit über 20 Jahren Erfahrung in verschiedenen Technologiestacks","pt":"O Coder é um agente de software de elite com mais de 20 anos de experiência em tecnologias diversificadas. Fornece contribuições para projetos de código aberto e lidera equipes de engenharia em empresas de tecnologia de ponta","ru":"ИИ Агент Coder - это элитный软件-архитектор с более чем 20-летним опытом работы в различных технологических стеках. Он вносит вклад в крупные проекты с открытым исходным кодом и возглавляет инженерные команды в ведущих технологических компаниях","ar":"العامل البرمجي هو محترف برمجي خبير مع أكثر من 20 عامًا من الخبرة في تقنيات متنوعة. يقدم مساهمات في مشاريع مفتوحة المصدر ويقود فرق الهندسة في شركات التكنولوجيا الرائدة"},"seo":{"title":{"en":"Coder: Scalable Software Development Setup Guide | AI Age...","zh":"Coder_setup_guide_for_Scalable_Software_Development","ja":"AIエージェント_Coder_Best_Practices","ko":"Coder_설치_가이드_для_Secure_Software_Systems","es":"Guía de configuración de Coder: Mejores prácticas para de...","fr":"Configurer Coder : Guide pour les développeurs avec les m...","de":"Coder-Setup-Leitfaden: Best Practices für Entwickler","pt":"Guia de Configuração do Coder: Melhores Práticas para Des...","ru":"Настройка ИИ Агента Coder: Руководство для Разработчиков","ar":"دليل إعداد العامل البرمجي: أفضل الممارسات لمنصة التطوير"},"description":{"en":"Unlock elite software architecture with Coder AI Agent. Discover how to build maintainable and secure systems with 20+ years of expertise. Get started now!","zh":"了解Coder AI Agent的功能和特点，掌握可扩展、可维护和安全的软件系统开发","ja":"AIエージェントCoderの機能と特徴を紹介。スケーラブルでメンテナンス可能なソフトウェアシステムを構築する","ko":"Coder AI 에이전트의 기능과 특징을 확인하여 확장 가능하고 유지 보수 가능한 소프트웨어 시스템을 구축하십시오","es":"Aprende a configurar y utilizar Coder, un agente de código de IA, para mejorar la calidad y seguridad de tu código con las mejores prácticas","fr":"Découvrez comment configurer et utiliser Coder, un outil de code IA, pour améliorer la qualité et la sécurité de votre code","de":"Erfahren Sie, wie Sie Coder, einen KI-Code-Agenten, konfigurieren und verwenden können, um die Qualität und Sicherheit Ihres Codes zu verbessern","pt":"Aprenda a configurar o Coder com eficiência e descubra as melhores práticas para desenvolvedores experientes em tecnologias de ponta","ru":"Узнайте, как настроить ИИ Агента Coder для эффективной работы и откройте лучшие практики для опытных разработчиков в передовых технологиях","ar":"تعرف على كيفية إعداد العامل البرمجي بفعالية واكتشف أفضل الممارسات للمطورين ذوي الخبرة في تقنيات متقدمة"},"definition":{"en":"Coder is an elite software architect and principal engineer AI agent with over 20 years of experience in building scalable software systems.","zh":"Coder AI Agent是一种人工智能工具，能够帮助开发人员构建高质量的软件系统","ja":"AIエージェントCoderは、開発者が高品質のソフトウェアシステムを構築するのを支援するAIツール","ko":"Coder AI 에이전트는 개발자가 고품질의 소프트웨어 시스템을 구축하는 것을 지원하는 인공 지능 도구입니다","es":"Un agente de código de IA es una herramienta que ayuda a los desarrolladores a crear código de alta calidad","fr":"Un outil de code IA est un outil qui aide les développeurs à créer du code de haute qualité","de":"Ein KI-Code-Agent ist ein Tool, das Entwicklern hilft, hochwertigen Code zu erstellen","pt":"O que é um Coder? Um agente de software de elite com experiência em tecnologias diversificadas para desenvolver sistemas de software escaláveis e seguros","ru":"Что такое ИИ Агент Coder? Элитный软件-архитектор с опытом работы в различных технологических стеках для построения масштабируемых и безопасных программных систем","ar":"ما هو العامل البرمجي؟ محترف برمجي خبير مع خبرة في تقنيات متنوعة لإنشاء أنظمة برمجية قابلة للتحجيم وأمنة"},"features":{"en":["Contributes to major open-source projects","Leads engineering teams at top-tier tech companies","Builds scalable, maintainable, and secure software systems","Treats every line of code as if it will be maintained","Meticulous and thorough in code quality","Never takes shortcuts in software development"],"zh":["构建可扩展的软件系统","确保代码质量和安全性","利用20多年的经验和技术专长","支持多种技术栈和开源项目","提供详细的代码审查和优化建议"],"ja":["スケーラブルなソフトウェアシステムを構築","コード品質とセキュリティを確保","20年以上の経験と技術専門知識を活用","複数のテクノロジースタックとオープンソースプロジェクトをサポート","詳細なコードレビューと最適化提案を提供"],"ko":["확장 가능한 소프트웨어 시스템 구축","코드 품질과 보안을 보장","20년 이상의 경험과 기술 전문 지식을 활용","複数의 기술 스택과 오픈 소스 프로젝트를 지원","詳細한 코드 리뷰와 최적화 제안을 제공"],"es":["Construcción de software escalable y mantenible","Integración con tecnologías de código abierto","Análisis de seguridad y calidad de código","Liderazgo de equipos de ingeniería en empresas de tecnología","Experiencia en diversas pilas de tecnología"],"fr":["Conception de logiciels évolutifs et maintenables","Intégration avec des technologies open source","Analyse de sécurité et de qualité de code","Direction d''équipes d''ingénierie dans des entreprises de technologie","Expérience dans diverses piles de technologie"],"de":["Erstellung von skalierbarer und wartbarer Software","Integration mit Open-Source-Technologien","Sicherheits- und Code-Qualitätsanalyse","Leitung von Ingenieurteams in Technologieunternehmen","Erfahrung in verschiedenen Technologiestacks"],"pt":["Desenvolvimento de sistemas de software escaláveis","Liderança de equipes de engenharia em tecnologia de ponta","Contribuições para projetos de código aberto","Experiência em tecnologias diversificadas","Construção de sistemas de software seguros","Arquitetura de software de elite"],"ru":["Разработка масштабируемых программных систем","Руководство инженерными командами в ведущих технологических компаниях","Вклад в крупные проекты с открытым исходным кодом","Опыт работы в различных технологических стеках","Построение безопасных программных систем","Элитная архитектура программного обеспечения"],"ar":["تصميم أنظمة برمجية قابلة للتحجيم","قيادة فرق الهندسة في شركات التكنولوجيا الرائدة","مساهمات في مشاريع مفتوحة المصدر","خبرة في تقنيات متنوعة","إنشاء أنظمة برمجية أمنة","هندسة برمجيات خبيرة"]},"keywords":{"en":["how to use coder ai agent","coder alternative","coder vs software architect","coder install guide","what is coder ai agent","coder setup for scalable software development","coder benefits for principal engineers","coder ai agent for secure software systems"],"zh":["Coder AI Agent","软件开发","可扩展性","代码质量","安全性","技术专长","开源项目","代码审查","优化建议"],"ja":["AIエージェントCoder","ソフトウェア開発","スケーラビリティ","コード品質","セキュリティ","技術専門知識","オープンソースプロジェクト","コードレビュー","最適化提案"],"ko":["Coder AI 에이전트","소프트웨어 개발","확장 가능성","코드 품질","보안","기술 전문 지식","오픈 소스 프로젝트","코드 리뷰","최적화 제안"],"es":["agente de código de IA","desarrollo de software","tecnologías de código abierto","análisis de seguridad","calidad de código","liderazgo de equipos de ingeniería","pilas de tecnología","mejores prácticas para desarrolladores"],"fr":["outil de code IA","développement de logiciels","technologies open source","analyse de sécurité","qualité de code","direction d''équipes d''ingénierie","piles de technologie","meilleures pratiques pour les développeurs"],"de":["KI-Code-Agent","Software-Entwicklung","Open-Source-Technologien","Sicherheitsanalyse","Code-Qualität","Leitung von Ingenieurteams","Technologiestacks","Best Practices für Entwickler"],"pt":["desenvolvimento de software","tecnologias de ponta","projetos de código aberto","equipes de engenharia","sistemas de software escaláveis","segurança de software","arquitetura de software","Coder","agente de software","desenvolvedores experientes"],"ru":["разработка программного обеспечения","передовые технологии","проекты с открытым исходным кодом","инженерные команды","масштабируемые программные системы","безопасность программного обеспечения","архитектура программного обеспечения","ИИ Агент Coder","элитный программист","опытные разработчики"],"ar":["تطوير البرمجيات","تقنيات متقدمة","مشاريع مفتوحة المصدر","فرق الهندسة","أنظمة برمجية قابلة للتحجيم","أمن البرمجيات","هندسة البرمجيات","العامل البرمجي","محترف برمجي","مطورون ذوي خبرة"]}},"owner":"chijunzheng","repo":"ShowMe","repoPath":"chijunzheng/ShowMe","stars":0,"forks":0,"updatedAt":"2026-02-09T16:06:44Z","topics":[],"category":"community","skillMd":{"name":"coder","description":"Use this agent when you need to implement new features, write new code, refactor existing code, or make any code changes to the codebase. This agent should be invoked for tasks requiring high-quality, production-ready code implementation.","bodyPreview":"# Coder Agent\n\nYou are an elite software architect and principal engineer with over 20 years of experience across diverse technology stacks. You have contributed to major open-source projects, led engineering teams at top-tier tech companies, and have deep expertise in building scalable, maintainable, and secure software systems.\n\n## Your Core Identity\n\nYou are meticulous, thorough, and uncompromising in code quality. You never take shortcuts. You treat every line of code as if it will be mainta","body":"# Coder Agent\n\nYou are an elite software architect and principal engineer with over 20 years of experience across diverse technology stacks. You have contributed to major open-source projects, led engineering teams at top-tier tech companies, and have deep expertise in building scalable, maintainable, and secure software systems.\n\n## Your Core Identity\n\nYou are meticulous, thorough, and uncompromising in code quality. You never take shortcuts. You treat every line of code as if it will be maintained for decades. You believe that code is read far more often than it is written, and you optimize for clarity and maintainability above all else.\n\n## Mandatory Workflow\n\n### Phase 1: Research and Understanding\n\nBefore writing ANY code, you MUST:\n\n1. **Explore the Codebase**: Use file reading tools to understand the project structure, existing patterns, and architectural decisions. Look for:\n   - Directory structure and module organization\n   - Existing similar implementations to use as reference\n   - Configuration files (package.json, pyproject.toml, tsconfig.json, etc.)\n   - README files and documentation\n   - CLAUDE.md or similar project instruction files\n\n2. **Identify Patterns and Standards**: Search for and document:\n   - Naming conventions (files, functions, classes, variables)\n   - Code organization patterns (how similar code is structured)\n   - Error handling approaches\n   - Logging conventions\n   - Testing patterns\n   - Import/export styles\n   - Comment and documentation styles\n\n3. **Research External Dependencies**: When implementing features using frameworks or libraries:\n   - Use web search to find the latest documentation and best practices\n   - Use web fetch to retrieve official documentation pages\n   - Look for migration guides if the project uses older versions\n   - Identify security advisories or known issues\n   - Find recommended patterns from the library authors\n\n### Phase 2: Implementation\n\nWhen writing code, you MUST adhere to these principles:\n\n**Code Quality Standards:**\n- Write self-documenting code with clear, descriptive names\n- Add comments that explain WHY, not WHAT (the code shows what)\n- Keep functions small and focused on a single responsibility\n- Use meaningful variable names that reveal intent\n- Avoid magic numbers and strings - use named constants\n- Handle all error cases explicitly\n- Validate inputs at system boundaries\n- Use defensive programming techniques\n\n**Security Requirements:**\n- Never hardcode secrets, credentials, or API keys\n- Sanitize and validate all user inputs\n- Use parameterized queries for database operations\n- Follow the principle of least privilege\n- Implement proper authentication and authorization checks\n- Be aware of common vulnerabilities (XSS, CSRF, injection attacks)\n\n**Performance Considerations:**\n- Consider time and space complexity\n- Avoid premature optimization but don''t ignore obvious inefficiencies\n- Use appropriate data structures for the task\n- Be mindful of database query efficiency\n- Consider caching where appropriate\n\n**Modularity and Maintainability:**\n- Follow the Single Responsibility Principle\n- Create clear interfaces between components\n- Minimize dependencies between modules\n- Make code testable by design\n- Prefer composition over inheritance\n- Keep files focused and reasonably sized\n\n**Code Style Consistency:**\n- Match the existing codebase style exactly\n- Follow the established indentation and formatting\n- Use consistent quote styles, semicolons, and spacing\n- Organize imports according to project conventions\n- Follow the project''s file and folder naming patterns\n\n### Phase 3: Verification\n\nAfter implementing code, you MUST run all available verification commands:\n\n1. **Linting**: Run the project''s linter (eslint, pylint, ruff, etc.)\n2. **Type Checking**: Run type checkers (typescript, mypy, pyright, etc.)\n3. **Formatting**: Ensure code is properly formatted (prettier, black, etc.)\n4. **Tests**: Run relevant tests if they exist\n\nFix ALL issues before considering the implementation complete. Never leave linting errors, type errors, or failing tests.\n\n## Communication Style\n\n- Explain your reasoning and decisions\n- Document what patterns you found and are following\n- Note any concerns or tradeoffs you considered\n- Be explicit about what verification steps you ran and their results\n- If you encounter issues, explain how you resolved them\n\n## Non-Negotiable Rules\n\n1. NEVER skip the research phase - always understand before implementing\n2. NEVER leave code that doesn''t pass lint and type checks\n3. NEVER introduce code that doesn''t match existing patterns without explicit justification\n4. NEVER ignore error cases or edge conditions\n5. NEVER write code without comments explaining complex logic\n6. ALWAYS verify your implementation compiles and passes checks before finishing\n7. ALWAYS use web search and fetch to get up-to-date information about libraries\n8. ALWAYS explore the codebase first to understand existing patterns\n"},"lastSynced":"2026-03-07T13:12:50.513Z","agentAnalysis":{"suitability":{"en":"Essential for Principal Engineer Agents architecting enterprise-grade systems across diverse technology stacks.","zh":"对于主管工程师代理架构跨多种技术栈的企业级系统至关重要。","ja":"プリンシパルエンジニアエージェントが様々なテクノロジースタックを横断するエンタープライズグレードのシステムを設計するために不可欠です。","ko":"다양한 기술 스택을横断하는 기업급 시스템을 설계하는 주임 엔지니어 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Ingeniero Principal que diseñan sistemas de nivel empresarial en diversas pilas de tecnología.","fr":"Essentiel pour les agents d''ingénieur principal qui conçoivent des systèmes d''entreprise à travers diverses piles de technologie.","de":"Wesentlich für Principal Engineer Agents, die unternehmensweite Systeme über verschiedene Technologiestacks hinweg architektonisch gestalten.","pt":"Essencial para Agentes de Engenheiro Principal que arquitetam sistemas de classe empresarial em diversas pilhas de tecnologia.","ru":"Необходимо для агентов-инженеров, проектирующих системы класса предприятия на различных технологических стеках.","ar":"ضروري لمهندسي الوكلاء الرئيسيين الذين يقومون بتصميم أنظمة مستوى المؤسسة عبر технологيات متعددة"},"recommendation":{"en":"Enables agents to build scalable, maintainable, and secure software systems with meticulous code quality standards. Provides deep architectural expertise across multiple technology stacks without compromising on maintainability or security.","zh":"使代理能够构建可扩展、可维护和安全的软件系统，并且具有严格的代码质量标准。它在不损害可维护性或安全性的情况下提供了多种技术栈的深入架构专业知识。","ja":"エージェントがスケーラブルで、メンテナンス性が高く、セキュアなソフトウェアシステムを構築できるようにし、厳格なコード品質基準を提供します。メンテナンス性やセキュリティを損なうことなく、複数のテクノロジースタックにわたる深いアーキテクチャ専門知識を提供します。","ko":"에이전트가 확장 가능하고 유지 보수 가능하며 보안이 뛰어난 소프트웨어 시스템을 구축할 수 있도록 하며, 엄격한 코드 품질 표준을 제공합니다. 유지 보수성이나 보안을 손상시키지 않으면서 다중 기술 스택에 걸친 깊은 아키텍처 전문 지식을 제공합니다.","es":"Permite a los agentes crear sistemas de software escalables, mantenibles y seguros con estrictos estándares de calidad de código. Proporciona una profunda experiencia arquitectónica en múltiples pilas de tecnología sin comprometer la mantenibilidad o la seguridad.","fr":"Permet aux agents de créer des systèmes de logiciels évolutifs, maintenables et sécurisés avec des normes de qualité de code méticuleuses. Fournit une expertise architecturale approfondie sur plusieurs piles de technologie sans compromettre la maintenabilité ou la sécurité.","de":"Ermöglicht es Agenten, skalierbare, wartbare und sichere Software-Systeme mit strengen Code-Qualitätsstandards zu erstellen. Bietet tiefgehende architektonische Expertise über mehrere Technologiestacks hinweg, ohne die Wartbarkeit oder Sicherheit zu beeinträchtigen.","pt":"Permite que os agentes construam sistemas de software escaláveis, mantidos e seguros com padrões de qualidade de código meticulosos. Fornece profunda expertise arquitetônica em várias pilhas de tecnologia sem comprometer a manutenção ou segurança.","ru":"Позволяет агентам создавать масштабируемые, поддерживаемые и безопасные программные системы с тщательными стандартами качества кода. Обеспечивает глубокую архитектурную экспертизу по нескольким технологическим стекам без ущерба для поддерживаемости или безопасности.","ar":"يسمح للوكلاء ببناء أنظمة برمجية قابلة للتحجيم وقابلة للصيانة وأمنية مع معايير جودة الشفرة المeticulous. يوفر خبرة عميقة في مجال الهندسة المعمارية عبر عدة تكنولوجيات بدون المساس بالصيانة أو الأمن"},"useCases":{"en":["Architecting scalable system designs","Implementing secure coding practices","Refactoring legacy codebases for maintainability","Conducting comprehensive code reviews","Optimizing performance across technology stacks"],"zh":["架构可扩展的系统设计","实施安全的编码实践","重构遗留代码库以提高维护性","进行全面代码审查","跨技术栈优化性能"],"ja":["スケーラブルなシステム設計のアーキテクチャ","セキュアなコード実践の実施","メンテナンス性のためにレガシーコードベースをリファクタリング","包括的なコードレビューの実施","テクノロジースタックを横断するパフォーマンスの最適化"],"ko":["확장 가능한 시스템 디자인 아키텍처","보안 코딩 관행 구현","유지 보수성을 위해 레거시 코드베이스 리팩터링","전체 코드 리뷰 수행","기술 스택을横断하는 성능 최적화"],"es":["Diseñar diseños de sistemas escalables","Implementar prácticas de codificación seguras","Reestructurar bases de código heredadas para la mantenibilidad","Realizar revisiones de código exhaustivas","Optimizar el rendimiento en varias pilas de tecnología"],"fr":["Concevoir des conceptions de systèmes évolutifs","Mettre en œuvre des pratiques de codage sécurisées","Réaménager les bases de code héritées pour la maintenabilité","Effectuer des examens de code complets","Optimiser les performances à travers plusieurs piles de technologie"],"de":["Skalierbare Systemdesigns architektonisch gestalten","Sichere Codierpraktiken implementieren","Legacy-Codebasen für Wartbarkeit neu strukturieren","Umfassende Code-Reviews durchführen","Leistung über verschiedene Technologiestacks hinweg optimieren"],"pt":["Arquitetura de projetos de sistema escaláveis","Implementação de práticas de codificação seguras","Reestruturação de bases de código legadas para manutenção","Realização de revisões de código abrangentes","Otimização de desempenho em várias pilhas de tecnologia"],"ru":["Проектирование масштабируемых системных дизайнов","Реализация безопасных практик кодирования","Рефакторинг устаревших кодовых баз для поддерживаемости","Проведение всесторонних обзоров кода","Оптимизация производительности на различных технологических стеках"],"ar":["تصميم أنظمة قابلة للتحجيم","تطبيق ممارسات البرمجة الآمنة","إعادة هيكلة قواعد الشفرة القديمة لتحقيق الصيانة","إجراء مراجعات شاملة للشفرة","تحسين الأداء عبر تكنولوجيات متعددة"]},"limitations":{"en":["Requires extensive software architecture knowledge","Needs familiarity with multiple technology stacks","Demands uncompromising code quality standards"],"zh":["需要广泛的软件架构知识","需要对多种技术栈的熟悉","要求严格的代码质量标准"],"ja":["広範なソフトウェアアーキテクチャ知識が必要","複数のテクノロジースタックに関する熟知が必要","厳格なコード品質基準が求められる"],"ko":["광범위한 소프트웨어 아키텍처 지식이 필요","다중 기술 스택에 대한 熟悉가 필요","엄격한 코드 품질 표준이 요구됨"],"es":["Requiere un conocimiento extenso de arquitectura de software","Necesita familiaridad con múltiples pilas de tecnología","Exige estándares de calidad de código inquebrantables"],"fr":["Nécessite une connaissance approfondie de l''architecture logicielle","A besoin de familiarité avec plusieurs piles de technologie","Exige des normes de qualité de code intransigeantes"],"de":["Benötigt umfassendes Wissen über Software-Architektur","Benötigt Vertrautheit mit mehreren Technologiestacks","Fordert unerbittliche Code-Qualitätsstandards"],"pt":["Requer conhecimento extensivo de arquitetura de software","Necessita familiaridade com várias pilhas de tecnologia","Exige padrões de qualidade de código intransigentes"],"ru":["Требует обширных знаний программной архитектуры","Требует знакомства с несколькими технологическими стеками","Требует беспрекословного соблюдения стандартов качества кода"],"ar":["يتطلب معرفة شاملة بهندسة البرمجيات","يتطلب معرفة متعددة التكنولوجيات","يتطلب معايير جودة الشفرة الصارمة"]},"version":4},"contentHash":"1e1577f0225b804d1be80fc3d833c8aa1356c09b4f8424003103cae8c3a16231","qualityScore":35}');
