INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chijunzheng/ShowMe/coder', 'coder', 'chijunzheng', 'ShowMe', 'community', 'coder chijunzheng ShowMe community The Coder skill enables developers to build scalable, maintainable, and secure software systems. It benefits principal engineers and software architects with deep expertise in diverse technology stacks. Coder AI Agent是一位精通软件架构和开发的专家，具有20多年的经验，能够构建可扩展、可维护和安全的软件系统 AIエージェントCoderは、20年以上の経験を持つエリートソフトウェアアーキテクトであり、スケーラブルでメンテナンス可能なソフトウェアシステムを構築する Coder AI 에이전트는 20년 이상의 경험을 가진 엘리트 소프트웨어 아키텍트로 확장 가능하고 유지 보수 가능한 소프트웨어 시스템을 구축할 수 있습니다 Coder es un agente de código de IA que ayuda a los desarrolladores a crear software escalable, mantenible y seguro. Con más de 20 años de experiencia en diversas pilas de tecnología Coder est un outil de code IA qui aide les développeurs à créer des logiciels évolutifs, maintenables et sécurisés. Avec plus de 20 ans d''expérience dans diverses piles de technologie Coder ist ein KI-Code-Agent, der Entwicklern hilft, skalierbare, wartbare und sichere Software zu erstellen. Mit über 20 Jahren Erfahrung in verschiedenen Technologiestacks O Coder é um agente de software de elite com mais de 20 anos de experiência em tecnologias diversificadas. Fornece contribuições para projetos de código aberto e lidera equipes de engenharia em empresas de tecnologia de ponta ИИ Агент Coder - это элитный软件-архитектор с более чем 20-летним опытом работы в различных технологических стеках. Он вносит вклад в крупные проекты с открытым исходным кодом и возглавляет инженерные команды в ведущих технологических компаниях العامل البرمجي هو محترف برمجي خبير مع أكثر من 20 عامًا من الخبرة في تقنيات متنوعة. يقدم مساهمات في مشاريع مفتوحة المصدر ويقود فرق الهندسة في شركات التكنولوجيا الرائدة how to use coder ai agent coder alternative coder vs software architect coder install guide what is coder ai agent coder setup for scalable software development coder benefits for principal engineers coder ai agent for secure software systems Coder AI Agent 软件开发 可扩展性 代码质量 安全性 技术专长 开源项目 代码审查 优化建议 Contributes to major open-source projects Leads engineering teams at top-tier tech companies Builds scalable, maintainable, and secure software systems Treats every line of code as if it will be maintained Meticulous and thorough in code quality Never takes shortcuts in software development Coder is an elite software architect and principal engineer AI agent with over 20 years of experience in building scalable software systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wudong/tt-players/react-spectrum-s2', 'community', 'wudong', 'tt-players', 'wudong/tt-players', 'react-spectrum-s2', 0, 0, 35, '2026-03-06T18:47:59Z', '2026-03-07T13:13:54.554Z', '3e3e6694620a15a9e995bd33352749c61cd353869c27bce964da698c4919148a', '{"id":"wudong/tt-players/react-spectrum-s2","name":"react-spectrum-s2","description":{"en":"react-spectrum-s2 provides accessible, adaptive, and high-quality UI components for React applications, benefiting developers and designers. It offers a collection of components with detailed documentation.","zh":"React Spectrum S2 是 Adobe 的 Spectrum 2 设计系统在 React 中的实现，提供可访问性、适应性和高质量的 UI 组件","ja":"React Spectrum S2 は、Adobe の Spectrum 2 デザインシステムを React で実装したもので、アクセシビリティ、適応性、ハイクオリティの UI コンポーネントを提供します","ko":"React Spectrum S2는 Adobe의 Spectrum 2 디자인 시스템을 React에서 구현한 것으로 접근성, 적응성, 고품질의 UI 구성 요소를 제공합니다","es":"react-spectrum-s2 es la implementación de Adobe del sistema de diseño Spectrum 2 en React, que ofrece componentes UI accesibles y personalizables","fr":"react-spectrum-s2 est la mise en œuvre par Adobe du système de conception Spectrum 2 en React, qui propose des composants UI accessibles et personnalisables","de":"react-spectrum-s2 ist Adobes Implementierung des Spectrum-2-Designsystems in React, das zugängliche und anpassbare UI-Komponenten bietet","pt":"O React Spectrum S2 é uma implementação do design system Spectrum 2 em React, fornecendo componentes UI acessíveis e adaptáveis.","ru":"React Spectrum S2 — это реализация дизайн-системы Spectrum 2 в React, обеспечивающая доступные и адаптивные компоненты UI.","ar":"React Spectrum S2 هو تنفيذ لنظام التصميم Spectrum 2 في React، يوفر مكونات UI قابلة للوصول والتحويل."},"seo":{"title":{"en":"react-spectrum-s2: Accessible UI Components Setup Guide |...","zh":"React Spectrum S2 设置指南 - Adobe 的 Spectrum 2 设计系统","ja":"React Spectrum S2 導入ガイド - Adobe の Spectrum 2 デザインシステム","ko":"React Spectrum S2 설정 가이드 - Adobe의 Spectrum 2 디자인 시스템","es":"react-spectrum-s2: Guía de configuración de componentes U...","fr":"react-spectrum-s2: Guide de mise en place des composants ...","de":"react-spectrum-s2: Einrichtungsanleitung für Adobe-UI-Kom...","pt":"Guia de Configuração do React Spectrum S2","ru":"Руководство по настройке React Spectrum S2 (ИИ Агенты)","ar":"دليل إعداد React Spectrum S2 (أدوات ذكاء اصطناعي)"},"description":{"en":"Discover how to leverage react-spectrum-s2 for adaptive UI components. Explore the documentation structure and get started with Guides and Collections today!","zh":"了解 React Spectrum S2 的技术细节和特点，包括可访问性、适应性和高质量的 UI 组件","ja":"React Spectrum S2 の技術的詳細と特徴を学びます。アクセシビリティ、適応性、ハイクオリティの UI コンポーネントなど","ko":"React Spectrum S2의 기술적 세부 정보와 특징을 알아보세요. 접근성, 적응성, 고품질의 UI 구성 요소 등","es":"Aprende a utilizar react-spectrum-s2 para crear interfaces de usuario accesibles y personalizadas con los componentes UI de Adobe","fr":"Découvrez comment utiliser react-spectrum-s2 pour créer des interfaces utilisateur accessibles et personnalisées avec les composants UI d''Adobe","de":"Erfahren Sie, wie Sie react-spectrum-s2 verwenden, um zugängliche und anpassbare Benutzeroberflächen mit Adobes UI-Komponenten zu erstellen","pt":"Aprenda a configurar o React Spectrum S2, uma implementação do design system Spectrum 2 em React, com componentes UI acessíveis e adaptáveis.","ru":"Узнайте, как настроить React Spectrum S2, реализацию дизайн-системы Spectrum 2 в React, с доступными и адаптивными компонентами UI (ИИ Агенты).","ar":"تعرف على كيفية إعداد React Spectrum S2، وهي تنفيذ لنظام التصميم Spectrum 2 في React، مع مكونات UI قابلة للوصول والتحويل (أدوات ذكاء اصطناعي)."},"definition":{"en":"react-spectrum-s2 is Adobe''s implementation of the Spectrum 2 design system in React, providing a set of accessible UI components.","zh":"React Spectrum S2 是一种基于 React 的 UI 组件库，实现了 Adobe 的 Spectrum 2 设计系统","ja":"React Spectrum S2 は、React に基づく UI コンポーネント ライブラリで、Adobe の Spectrum 2 デザイン システムを実装しています","ko":"React Spectrum S2는 React 기반의 UI 구성 요소 라이브러리로 Adobe의 Spectrum 2 디자인 시스템을 구현합니다","es":"react-spectrum-s2 es un conjunto de componentes UI de Adobe para React que proporciona funcionalidades de acceso y personalización","fr":"react-spectrum-s2 est un ensemble de composants UI d''Adobe pour React qui propose des fonctionnalités d''accès et de personnalisation","de":"react-spectrum-s2 ist ein Satz von UI-Komponenten von Adobe für React, der Zugriffs- und Anpassungsfunktionen bietet","pt":"O que é React Spectrum S2? É uma implementação do design system Spectrum 2 em React.","ru":"Что такое React Spectrum S2? Это реализация дизайн-системы Spectrum 2 в React.","ar":"ما هو React Spectrum S2؟ هو تنفيذ لنظام التصميم Spectrum 2 في React."},"features":{"en":["Provides a collection of accessible, adaptive, and high-quality UI components","Includes detailed documentation organized in the references/ directory","Supports keyboard navigation and selection for components displaying collections of items","Offers Guides and Collections documentation, such as collections.md","Follows the Spectrum 2 design system implementation"],"zh":["可访问性和适应性","高质量的 UI 组件","键盘导航和选择功能","集合组件","详细的文档和指南"],"ja":["アクセシビリティと適応性","ハイクオリティの UI コンポーネント","キーボードナビゲーションと選択機能","コレクションコンポーネント","詳細なドキュメントとガイド"],"ko":["접근성과 적응성","고품질의 UI 구성 요소","키보드 탐색과 선택 기능","컬렉션 구성 요소","详细한 문서와 가이드"],"es":["Componentes UI accesibles y personalizables","Funcionalidades de navegación por teclado y selección","Colecciones de componentes para mostrar conjuntos de elementos","Documentación detallada en el directorio references/","Guías para la creación de interfaces de usuario adaptativas","Compatibilidad con el sistema de diseño Spectrum 2 de Adobe"],"fr":["Composants UI accessibles et personnalisables","Fonctionnalités de navigation au clavier et de sélection","Collections de composants pour afficher des ensembles d''éléments","Documentation détaillée dans le répertoire references/","Guides pour la création d''interfaces utilisateur adaptatives","Compatibilité avec le système de conception Spectrum 2 d''Adobe"],"de":["Zugängliche und anpassbare UI-Komponenten","Funktionen für die Tastaturnavigation und Auswahl","Sammlungen von Komponenten zur Anzeige von Elementgruppen","Detaillierte Dokumentation im Verzeichnis references/","Anleitungen für die Erstellung von anpassbaren Benutzeroberflächen","Kompatibilität mit Adobes Spectrum-2-Designsystem"],"pt":["Componentes UI acessíveis e adaptáveis","Suporte a navegação por teclado e seleção","Coleções de itens com funcionalidades avançadas","Documentação detalhada em references/guides/collections.md"],"ru":["Доступные и адаптивные компоненты UI","Поддержка навигации по клавиатуре и выбора","Коллекции элементов с расширенными функциями","Подробная документация в references/guides/collections.md (ИИ Агенты)"],"ar":["مكونات UI قابلة للوصول والتحويل","دعم الملاحة باللوحة المفاتيح والاختيار","مجموعات العناصر مع وظائف متقدمة","توثيق مفصل في references/guides/collections.md (أدوات ذكاء اصطناعي)"]},"keywords":{"en":["how to use react-spectrum-s2","react-spectrum-s2 documentation","react-spectrum-s2 vs material-ui","react-spectrum-s2 install","react-spectrum-s2 setup guide","what is react-spectrum-s2","react-spectrum-s2 alternative","react-spectrum-s2 accessibility features"],"zh":["React Spectrum S2","Adobe Spectrum 2","UI 组件库","React 设计系统","可访问性","适应性","高质量 UI","AIエージェント","前端开发"],"ja":["React Spectrum S2","Adobe Spectrum 2","UI コンポーネント ライブラリ","React デザイン システム","アクセシビリティ","適応性","ハイクオリティ UI","AIエージェント","フロントエンド開発"],"ko":["React Spectrum S2","Adobe Spectrum 2","UI 구성 요소 라이브러리","React 디자인 시스템","접근성","적응성","고품질 UI","AI 에이전트","프론트엔드 개발"],"es":["react-spectrum-s2","componentes UI de Adobe","sistema de diseño Spectrum 2","accesibilidad en React","personalización de interfaces de usuario","navegación por teclado en React","selección de elementos en React","colecciones de componentes en React","documentación de react-spectrum-s2"],"fr":["react-spectrum-s2","composants UI d''Adobe","système de conception Spectrum 2","accessibilité dans React","personnalisation d''interfaces utilisateur","navigation au clavier dans React","sélection d''éléments dans React","collections de composants dans React","documentation de react-spectrum-s2"],"de":["react-spectrum-s2","UI-Komponenten von Adobe","Spectrum-2-Designsystem","Zugänglichkeit in React","Anpassung von Benutzeroberflächen","Tastaturnavigation in React","Auswahl von Elementen in React","Sammlungen von Komponenten in React","Dokumentation von react-spectrum-s2"],"pt":["React Spectrum S2","design system Spectrum 2","componentes UI acessíveis","navegação por teclado","seleção de itens","coleções de itens","documentação React"],"ru":["React Spectrum S2","дизайн-система Spectrum 2","доступные компоненты UI","навигация по клавиатуре","выбор элементов","коллекции элементов","документация React (ИИ Агенты)"],"ar":["React Spectrum S2","نظام التصميم Spectrum 2","مكونات UI قابلة للوصول","الملاحة باللوحة المفاتيح","اختيار العناصر","مجموعات العناصر","توثيق React (أدوات ذكاء اصطناعي)"]}},"owner":"wudong","repo":"tt-players","repoPath":"wudong/tt-players","stars":0,"forks":0,"updatedAt":"2026-03-06T18:47:59Z","topics":[],"category":"community","skillMd":{"name":"react-spectrum-s2","description":"Build accessible UI components with React Spectrum S2 (Spectrum 2). Use when developers mention React Spectrum, Spectrum 2, S2, @react-spectrum/s2, or Adobe design system components. Provides documentation for buttons, forms, dialogs, tables, date/time pickers, color pickers, and other accessible components.","bodyPreview":"# React Spectrum S2 (Spectrum 2)\n\nReact Spectrum S2 is Adobe''s implementation of the Spectrum 2 design system in React. It provides a collection of accessible, adaptive, and high-quality UI components.\n\n## Documentation Structure\n\nThe `references/` directory contains detailed documentation organized as follows:\n\n### Guides\n- [Collections](references/guides/collections.md): Many components display a collection of items, and provide functionality such as keyboard navigation, and selection. Learn h","body":"# React Spectrum S2 (Spectrum 2)\n\nReact Spectrum S2 is Adobe''s implementation of the Spectrum 2 design system in React. It provides a collection of accessible, adaptive, and high-quality UI components.\n\n## Documentation Structure\n\nThe `references/` directory contains detailed documentation organized as follows:\n\n### Guides\n- [Collections](references/guides/collections.md): Many components display a collection of items, and provide functionality such as keyboard navigation, and selection. Learn how to load and render collections using React Spectrum''s compositional API.\n- [Forms](references/guides/forms.md): Learn how to integrate with HTML forms, validate and submit data, and use React Spectrum with form libraries.\n- [Getting started](references/guides/getting-started.md): ## Installation\n- [Migrating to Spectrum 2](references/guides/migrating.md): Learn how to migrate from React Spectrum v3 to Spectrum 2.\n- [Selection](references/guides/selection.md): Many collection components support selecting items by clicking or tapping them, or by using the keyboard. Learn how to handle selection events, how to control selection programmatically, and the data structures used to represent a selection.\n- [Style Macro](references/guides/style-macro.md): The  macro supports a constrained set of values per property that conform to Spectrum 2.\n- [Styling](references/guides/styling.md): Learn how to use the  macro to apply Spectrum tokens directly in your components with type-safe autocompletion.\n- [Working with AI](references/guides/ai.md): Learn how to use the React Spectrum MCP Server, Agent Skills, and more to help you build with AI.\n\n### Components\n- [Accordion](references/components/Accordion.md): An accordion is a container for multiple accordion items.\n- [ActionBar](references/components/ActionBar.md): Action bars are used for single and bulk selection patterns when a user needs to perform actions on one or more items at the same time.\n- [ActionButton](references/components/ActionButton.md): ActionButtons allow users to perform an action.\n- [ActionButtonGroup](references/components/ActionButtonGroup.md): An ActionButtonGroup is a grouping of related ActionButtons.\n- [ActionMenu](references/components/ActionMenu.md): ActionMenu combines an ActionButton with a Menu for simple \"more actions\" use cases.\n- [Avatar](references/components/Avatar.md): An avatar is a thumbnail representation of an entity, such as a user or an organization.\n- [AvatarGroup](references/components/AvatarGroup.md): An avatar group is a grouping of avatars that are related to each other.\n- [Badge](references/components/Badge.md): Badges are used for showing a small amount of color-categorized metadata, ideal for getting a user''s attention.\n- [Breadcrumbs](references/components/Breadcrumbs.md): Breadcrumbs show hierarchy and navigational context for a user''s location within an application.\n- [Button](references/components/Button.md): Buttons allow users to perform an action.\n- [ButtonGroup](references/components/ButtonGroup.md): ButtonGroup handles overflow for a grouping of buttons whose actions are related to each other.\n- [Calendar](references/components/Calendar.md): Calendars display a grid of days in one or more months and allow users to select a single date.\n- [Card](references/components/Card.md): A Card summarizes an object that a user can select or navigate to.\n- [CardView](references/components/CardView.md): A CardView displays a group of related objects, with support for selection and bulk actions.\n- [Checkbox](references/components/Checkbox.md): Checkboxes allow users to select multiple items from a list of individual items,\n- [CheckboxGroup](references/components/CheckboxGroup.md): A CheckboxGroup allows users to select one or more items from a list of choices.\n- [ColorArea](references/components/ColorArea.md): A ColorArea allows users to adjust two channels of an RGB, HSL or HSB color value against a two-dimensional gradient background.\n- [ColorField](references/components/ColorField.md): A color field allows users to edit a hex color or individual color channel value.\n- [ColorSlider](references/components/ColorSlider.md): A ColorSlider allows users to adjust an individual channel of a color value.\n- [ColorSwatch](references/components/ColorSwatch.md): A ColorSwatch displays a preview of a selected color.\n- [ColorSwatchPicker](references/components/ColorSwatchPicker.md): A ColorSwatchPicker displays a list of color swatches and allows a user to select one of them.\n- [ColorWheel](references/components/ColorWheel.md): A ColorWheel allows users to adjust the hue of an HSL or HSB color value on a circular track.\n- [ComboBox](references/components/ComboBox.md): ComboBox allow users to choose a single option from a collapsible list of options when space is limited.\n- [ContextualHelp](references/components/ContextualHelp.md): Contextual help shows a user extra information about the state of an adjacent component, or a total view.\n- [DateField](references/components/DateField.md): DateFields allow users to enter and edit date and time values using a keyboard.\n- [DatePicker](references/components/DatePicker.md): DatePickers combine a DateField and a Calendar popover to allow users to enter or select a date and time value.\n- [DateRangePicker](references/components/DateRangePicker.md): DateRangePickers combine two DateFields and a RangeCalendar popover to allow users\n- [Dialog](references/components/Dialog.md): Dialogs are windows containing contextual information, tasks, or workflows that appear over the user interface.\n- [Disclosure](references/components/Disclosure.md): A disclosure is a collapsible section of content. It is composed of a header with a heading and trigger button, and a panel that contains the content.\n- [Divider](references/components/Divider.md): Dividers bring clarity to a layout by grouping and dividing content in close proximity.\n- [DropZone](references/components/DropZone.md): A drop zone is an area into which one or multiple objects can be dragged and dropped.\n- [Form](references/components/Form.md): Forms allow users to enter data that can be submitted while providing alignment and styling for form fields.\n- [Icons](references/components/icons.md): React Spectrum offers a set of open source icons that can be imported from .\n- [IllustratedMessage](references/components/IllustratedMessage.md): An IllustratedMessage displays an illustration and a message, usually\n- [Illustrations](references/components/illustrations.md): React Spectrum offers a collection of illustrations that can be imported from .\n- [Image](references/components/Image.md): An image with support for skeleton loading and custom error states.\n- [InlineAlert](references/components/InlineAlert.md): Inline alerts display a non-modal message associated with objects in a view.\n- [Link](references/components/Link.md): Links allow users to navigate to a different location.\n- [LinkButton](references/components/LinkButton.md): A LinkButton combines the functionality of a link with the appearance of a button. Useful for allowing users to navigate to another page.\n- [ListView](references/components/ListView.md): A ListView displays a list of interactive items, and allows a user to navigate, select, or perform an action.\n- [mcp](references/components/mcp.md)\n- [Menu](references/components/Menu.md): Menus display a list of actions or options that a user can choose.\n- [Meter](references/components/Meter.md): Meters are visual representations of a quantity or an achievement.\n- [NumberField](references/components/NumberField.md): NumberFields allow users to input number values with a keyboard or increment/decrement with step buttons.\n- [Picker](references/components/Picker.md): Pickers allow users to choose a single option from a collapsible list of options when space is limited.\n- [Popover](references/components/Popover.md): A popover is an overlay element positioned relative to a trigger.\n- [ProgressBar](references/components/ProgressBar.md): ProgressBars show the progression of a system operation: downloading, uploading, processing, etc., in a visual way.\n- [ProgressCircle](references/components/ProgressCircle.md): ProgressCircles show the progression of a system operation such as downloading, uploading, or processing, in a visual way.\n- [Provider](references/components/Provider.md): Provider is the container for all React Spectrum components.\n- [RadioGroup](references/components/RadioGroup.md): Radio groups allow users to select a single option from a list of mutually exclusive options.\n- [RangeCalendar](references/components/RangeCalendar.md): RangeCalendars display a grid of days in one or more months and allow users to select a contiguous range of dates.\n- [RangeSlider](references/components/RangeSlider.md): RangeSliders allow users to quickly select a subset range. They should be used when the upper and lower bounds to the range are invariable.\n- [SearchField](references/components/SearchField.md): A SearchField is a text field designed for searches.\n- [SegmentedControl](references/components/SegmentedControl.md): A SegmentedControl is a mutually exclusive group of buttons used for view switching.\n- [SelectBoxGroup](references/components/SelectBoxGroup.md): SelectBoxGroup allows users to select one or more options from a list.\n- [Skeleton](references/components/Skeleton.md): A Skeleton wraps around content to render it as a placeholder.\n- [Slider](references/components/Slider.md): Sliders allow users to quickly select a value within a range. They should be used when the upper and lower bounds to the range are invariable.\n- [StatusLight](references/components/StatusLight.md): Status lights are used to color code categories and labels commonly found in data visualization.\n- [Switch](references/components/Switch.md): Switches allow users to turn an individual option on or off.\n- [TableView](references/components/TableView.md): Tables are containers for displaying information. They allow users to quickly scan, sort, compare, and take action on large amounts of data.\n- [Tabs](references/components/Tabs.md): Tabs organize content into multiple sections and allow users to navigate between them. The content under the set of tabs should be related and form a coherent unit.\n- [TagGroup](references/components/TagGroup.md): Tags allow users to categorize content. They can represent keywords or people, and are grouped to describe an item or a search request.\n- [TextArea](references/components/TextArea.md): A textarea allows a user to input mult-line text.\n- [TextField](references/components/TextField.md): TextFields are text inputs that allow users to input custom text entries\n- [TimeField](references/components/TimeField.md): TimeFields allow users to enter and edit time values using a keyboard.\n- [Toast](references/components/Toast.md): A ToastContainer renders the queued toasts in an application. It should be placed\n- [ToggleButton](references/components/ToggleButton.md): ToggleButtons allow users to toggle a selection on or off, for example\n- [ToggleButtonGroup](references/components/ToggleButtonGroup.md): A ToggleButtonGroup is a grouping of related ToggleButtons, with single or multiple selection.\n- [Tooltip](references/components/Tooltip.md): Display container for Tooltip content. Has a directional arrow dependent on its placement.\n- [TreeView](references/components/TreeView.md): A tree view provides users with a way to navigate nested hierarchical information.\n\n### Testing\n- [Testing CheckboxGroup](references/testing/CheckboxGroup/testing.md)\n- [Testing ComboBox](references/testing/ComboBox/testing.md)\n- [Testing Dialog](references/testing/Dialog/testing.md)\n- [Testing ListView](references/testing/ListView/testing.md)\n- [Testing Menu](references/testing/Menu/testing.md)\n- [Testing Picker](references/testing/Picker/testing.md)\n- [Testing RadioGroup](references/testing/RadioGroup/testing.md)\n- [Testing TableView](references/testing/TableView/testing.md)\n- [Testing Tabs](references/testing/Tabs/testing.md)\n- [Testing TreeView](references/testing/TreeView/testing.md)\n"},"lastSynced":"2026-03-07T13:13:54.554Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents needing accessible and adaptive UI components for React applications","zh":"适用于需要可访问和自适应UI组件的React应用程序的前端代理","ja":"Reactアプリケーションにアクセス可能で適応性のあるUIコンポーネントを必要とするフロントエンドエージェントに適しています","ko":"접근성이 뛰어나고 적응성이 있는 UI 컴포넌트가 필요한 React 애플리케이션을 위한 프론트엔드 에이전트에 이상적입니다","es":"Ideal para agentes Frontend que necesitan componentes de interfaz de usuario accesibles y adaptables para aplicaciones de React","fr":"Idéal pour les agents Frontend ayant besoin de composants d''interface utilisateur accessibles et adaptables pour les applications React","de":"Ideal für Frontend-Agents, die zugängliche und adaptive Benutzeroberflächen-Komponenten für React-Anwendungen benötigen","pt":"Ideal para Agentes Frontend que necessitam de componentes de UI acessíveis e adaptáveis para aplicações React","ru":"Идеально для агентов Frontend, которым необходимы доступные и адаптивные компоненты UI для приложений React","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى مكونات واجهة مستخدم قابلة للوصول والتعديل للتطبيقات React"},"recommendation":{"en":"Empowers agents to create high-quality, accessible interfaces with detailed documentation using React Spectrum S2, providing a collection of components with adaptive and keyboard navigation capabilities, leveraging the Spectrum 2 design system","zh":"赋予代理创建高质量、可访问的界面能力，使用React Spectrum S2，提供具有自适应和键盘导航功能的组件集合，利用Spectrum 2设计系统，并提供详细的文档","ja":"React Spectrum S2を使用して、詳細なドキュメントを備えた高品質でアクセス可能なインターフェイスを作成するエージェントをEmpowerし、適応性とキーボードナビゲーション機能を備えたコンポーネントコレクションを提供し、Spectrum 2デザインシステムを利用する","ko":"React Spectrum S2를 사용하여 자세한 문서와 함께 높은 품질의 접근 가능한 인터페이스를 만들 수 있는 에이전트를 강화하여 적응성과 키보드 탐색 기능을 갖춘 컴포넌트 컬렉션을 제공하고 Spectrum 2 디자인 시스템을 활용합니다","es":"Habilita a los agentes a crear interfaces de alta calidad y accesibles con documentación detallada utilizando React Spectrum S2, que proporciona una colección de componentes con capacidades de navegación adaptativa y por teclado, aprovechando el sistema de diseño Spectrum 2","fr":"Permet aux agents de créer des interfaces de haute qualité et accessibles avec une documentation détaillée en utilisant React Spectrum S2, qui fournit une collection de composants avec des capacités de navigation adaptative et au clavier, en exploitant le système de conception Spectrum 2","de":"Ermächtigt Agenten, hochwertige und zugängliche Schnittstellen mit detaillierter Dokumentation zu erstellen, indem sie React Spectrum S2 verwenden, das eine Sammlung von Komponenten mit adaptiver und Tastaturnavigationsfunktion bietet und das Spectrum-2-Designsystem nutzt","pt":"Habilita os agentes a criar interfaces de alta qualidade e acessíveis com documentação detalhada usando React Spectrum S2, fornecendo uma coleção de componentes com capacidades de navegação adaptável e por teclado, aproveitando o sistema de design Spectrum 2","ru":"Наделяет агентов возможностью создавать высококачественные и доступные интерфейсы с подробной документацией, используя React Spectrum S2, предоставляя коллекцию компонентов с адаптивными и клавиатурными возможностями навигации, используя систему дизайна Spectrum 2","ar":"يمكن الوكلاء من إنشاء واجهات عالية الجودة وقابلة للوصول مع توثيق مفصل باستخدام React Spectrum S2، مع توفير مجموعة من المكونات بقدرات ملاحة متكيفة وتحكم باللوحة المفاتيح، واستفادة من نظام التصميم Spectrum 2"},"useCases":{"en":["Building accessible and adaptive React applications","Implementing keyboard navigation and selection functionality","Creating collections of items with detailed documentation"],"zh":["构建可访问和自适应的React应用程序","实现键盘导航和选择功能","创建具有详细文档的项目集合"],"ja":["アクセス可能で適応性のあるReactアプリケーションの構築","キーボードナビゲーションと選択機能の実装","詳細なドキュメントを備えたアイテムコレクションの作成"],"ko":["접근성이 뛰어나고 적응성이 있는 React 애플리케이션 구축","키보드 탐색 및 선택 기능 구현","자세한 문서를 갖춘 아이템 컬렉션 생성"],"es":["Creación de aplicaciones React accesibles y adaptables","Implementación de funcionalidad de navegación y selección por teclado","Creación de colecciones de elementos con documentación detallada"],"fr":["Création d''applications React accessibles et adaptables","Mise en œuvre de la fonctionnalité de navigation et de sélection au clavier","Création de collections d''éléments avec documentation détaillée"],"de":["Erstellung von zugänglichen und adaptiven React-Anwendungen","Implementierung von Tastaturnavigations- und Auswahlfunktion","Erstellung von Elementesammlungen mit detaillierter Dokumentation"],"pt":["Construir aplicações React acessíveis e adaptáveis","Implementar funcionalidade de navegação e seleção por teclado","Criar coleções de itens com documentação detalhada"],"ru":["Создание доступных и адаптивных приложений React","Реализация функциональности навигации и выбора с помощью клавиатуры","Создание коллекций элементов с подробной документацией"],"ar":["بناء تطبيقات React قابلة للوصول والتعديل","تنفيذ وظيفة الملاحة والاختيار باللوحة المفاتيح","إنشاء مجاميع من العناصر مع توثيق مفصل"]},"limitations":{"en":["Requires React application setup","Specific to Spectrum 2 design system implementation"],"zh":["需要React应用程序设置","特定于Spectrum 2设计系统实现"],"ja":["Reactアプリケーションの設定が必要","Spectrum 2デザインシステムの実装に特化"],"ko":["React 애플리케이션 설정이 필요함","Spectrum 2 디자인 시스템 구현에 특화"],"es":["Requiere configuración de aplicación React","Específico de la implementación del sistema de diseño Spectrum 2"],"fr":["Nécessite une configuration d''application React","Spécifique à la mise en œuvre du système de conception Spectrum 2"],"de":["Benötigt React-Anwendungskonfiguration","Spezifisch für die Implementierung des Spectrum-2-Designsystems"],"