INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wudong/tt-players/react-spectrum-s2', 'react-spectrum-s2', 'wudong', 'tt-players', 'community', 'react-spectrum-s2 wudong tt-players community react-spectrum-s2 provides accessible, adaptive, and high-quality UI components for React applications, benefiting developers and designers. It offers a collection of components with detailed documentation. React Spectrum S2 是 Adobe 的 Spectrum 2 设计系统在 React 中的实现，提供可访问性、适应性和高质量的 UI 组件 React Spectrum S2 は、Adobe の Spectrum 2 デザインシステムを React で実装したもので、アクセシビリティ、適応性、ハイクオリティの UI コンポーネントを提供します React Spectrum S2는 Adobe의 Spectrum 2 디자인 시스템을 React에서 구현한 것으로 접근성, 적응성, 고품질의 UI 구성 요소를 제공합니다 react-spectrum-s2 es la implementación de Adobe del sistema de diseño Spectrum 2 en React, que ofrece componentes UI accesibles y personalizables react-spectrum-s2 est la mise en œuvre par Adobe du système de conception Spectrum 2 en React, qui propose des composants UI accessibles et personnalisables react-spectrum-s2 ist Adobes Implementierung des Spectrum-2-Designsystems in React, das zugängliche und anpassbare UI-Komponenten bietet O React Spectrum S2 é uma implementação do design system Spectrum 2 em React, fornecendo componentes UI acessíveis e adaptáveis. React Spectrum S2 — это реализация дизайн-системы Spectrum 2 в React, обеспечивающая доступные и адаптивные компоненты UI. React Spectrum S2 هو تنفيذ لنظام التصميم Spectrum 2 في React، يوفر مكونات UI قابلة للوصول والتحويل. how to use react-spectrum-s2 react-spectrum-s2 documentation react-spectrum-s2 vs material-ui react-spectrum-s2 install react-spectrum-s2 setup guide what is react-spectrum-s2 react-spectrum-s2 alternative react-spectrum-s2 accessibility features React Spectrum S2 Adobe Spectrum 2 UI 组件库 React 设计系统 可访问性 适应性 高质量 UI AIエージェント 前端开发 Provides a collection of accessible, adaptive, and high-quality UI components Includes detailed documentation organized in the references/ directory Supports keyboard navigation and selection for components displaying collections of items Offers Guides and Collections documentation, such as collections.md Follows the Spectrum 2 design system implementation react-spectrum-s2 is Adobe''s implementation of the Spectrum 2 design system in React, providing a set of accessible UI components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KaltWulx/prompts/information-retrieval', 'community', 'KaltWulx', 'prompts', 'KaltWulx/prompts', 'information-retrieval', 0, 0, 35, '2026-03-08T01:57:15.265Z', '2026-03-08T01:59:54.173Z', '143cc2448225354cbc074b6e549a00f87140b0cf3e2046f5dd137ed95da09728', '{"id":"KaltWulx/prompts/information-retrieval","name":"information-retrieval","description":{"en":"The information-retrieval skill provides techniques and strategies for finding relevant and reliable information, benefiting developers and researchers who need to efficiently search for specific data.","zh":"信息检索技能提供了精确搜索和探索技术，帮助开发者找到相关和可靠的信息","ja":"情報検索スキルは、開発者が関連性の高い情報を見つけるのに役立つ、正確な検索と探索テクニックを提供します","ko":"정보 검색 스킬은 개발자가 관련성 높은 정보를 찾을 수 있도록 정밀 검색 및 탐색 기술을 제공합니다","es":"La recuperación de información implica técnicas y estrategias para encontrar información relevante y confiable, como búsqueda precisa y exploratoria","fr":"La recherche d''informations implique des techniques et des stratégies pour trouver des informations pertinentes et fiables, comme la recherche précise et exploratoire","de":"Die Informationsrückgewinnung umfasst Techniken und Strategien, um relevante und zuverlässige Informationen zu finden, wie z.B. präzise und exploratorische Suche","pt":"Recuperação de informações é uma técnica para encontrar dados relevantes. Utilize frases exatas, exclusão e busca em sites específicos","ru":"Инструменты ИИ Агентов для поиска информации помогают находить релевантные данные. Используйте точные фразы, исключение и поиск на конкретных сайтах","ar":"استرجاع المعلومات هو تقنية لاسترجاع البيانات ذات الصلة. استخدم العبارات الدقيقة والاستبعاد والبحث في المواقع المحددة"},"seo":{"title":{"en":"Information-Retrieval: Advanced Search Strategies for AI ...","zh":"信息检索Setup Guide：精确搜索和探索技术","ja":"情報検索Setup Guide：正確な検索と探索テクニック","ko":"정보 검색 Setup Guide: 정밀 검색 및 탐색 기술","es":"Guía de configuración para la recuperación de información","fr":"Guide de mise en place pour la recherche d''informations a...","de":"Einrichtungsleitfaden für die Informationsrückgewinnung m...","pt":"Guia de Configuração de Recuperação de Informações com Té...","ru":"Настройка Инструментов ИИ Агентов для Поиска Информации с...","ar":"دليل إعداد استرجاع المعلومات باستخدام تقنيات البحث المتقدمة"},"description":{"en":"Unlock efficient information retrieval with precise search techniques and strategies - learn how to get the most out of your searches now!","zh":"了解信息检索的技巧和策略，包括精确搜索和探索技术，以找到相关和可靠的信息","ja":"情報検索のテクニックと戦略について学び、正確な検索と探索方法で関連性の高い情報を見つけよう","ko":"정보 검색의 기술과 전략을 익히고, 정밀 검색 및 탐색 방법으로 관련성 높은 정보를 찾아보세요","es":"Descubre cómo encontrar información relevante y confiable con técnicas de búsqueda precisa y exploratoria con los agentes de inteligencia artificial","fr":"Découvrez comment trouver des informations pertinentes et fiables avec des techniques de recherche précise et exploratoire avec les outils IA","de":"Erfahren Sie, wie Sie mit präzisen und exploratorischen Suchtechniken mit KI-Tools relevante und zuverlässige Informationen finden","pt":"Aprenda a utilizar técnicas de busca avançadas para encontrar informações relevantes e confiáveis com nossa guia de recuperação de informações","ru":"Узнайте, как использовать передовые методы поиска для нахождения релевантной и достоверной информации с помощью нашего ИИ Агента","ar":"تعرف على كيفية استخدام تقنيات البحث المتقدمة لاسترجاع المعلومات ذات الصلة والموثوقة من خلال دليلنا"},"definition":{"en":"information-retrieval is a set of techniques and strategies used to find relevant and reliable information, including precise search, exploratory search, and more.","zh":"信息检索是指使用各种技巧和策略来找到相关和可靠的信息的过程","ja":"情報検索とは、関連性の高い情報を見つけるために、さまざまなテクニックと戦略を使用するプロセスです","ko":"정보 검색은 관련성 높은 정보를 찾기 위해 다양한 기술과 전략을 사용하는 과정입니다","es":"La recuperación de información es el proceso de encontrar información relevante y confiable a través de técnicas de búsqueda","fr":"La recherche d''informations est le processus de trouver des informations pertinentes et fiables à travers des techniques de recherche","de":"Die Informationsrückgewinnung ist der Prozess, relevante und zuverlässige Informationen durch Suchtechniken zu finden","pt":"Recuperação de informações é uma técnica de busca que utiliza frases exatas e exclusão para encontrar dados relevantes","ru":"Поиск информации - это метод поиска, использующий точные фразы и исключение для нахождения релевантных данных","ar":"استرجاع المعلومات هو طريقة بحث تستخدم العبارات الدقيقة والاستبعاد لاسترجاع البيانات ذات الصلة"},"features":{"en":["Supports precise search using exact phrases, such as \"machine learning\"","Allows exclusion of specific terms, like `python -snake`","Enables site-specific searches, such as `site:github.com authentication`","Supports searching by file type, including `filetype:pdf`","Facilitates exploratory searches for broad topics"],"zh":["使用精确搜索技术，如短语搜索和排除搜索","使用探索搜索技术，如站点特定搜索和文件类型搜索","支持React、Python等开发框架和语言","提供最佳实践和示例代码"],"ja":["正確な検索テクニックを使用すること、例えばフレーズ検索と除外検索","探索検索テクニックを使用すること、例えばサイト特定検索とファイルタイプ検索","React、Pythonなどの開発フレームワークと言語をサポート","ベストプラクティスとサンプルコードを提供"],"ko":["정밀 검색 기술을 사용하는 것, 예를 들어 구문 검색과 제외 검색","탐색 검색 기술을 사용하는 것, 예를 들어 사이트 특정 검색과 파일 유형 검색","React, Python 등의 개발 프레임워크와 언어를 지원","베스트 프랙티스와 샘플 코드를 제공"],"es":["Búsqueda precisa con frases exactas","Búsqueda exploratoria para temas amplios","Exclusión de términos con el operador -","Búsqueda en sitios específicos con el operador site:","Búsqueda por tipo de archivo con el operador filetype:"],"fr":["Recherche précise avec des phrases exactes","Recherche exploratoire pour des sujets larges","Exclusion de termes avec l''opérateur -","Recherche sur des sites spécifiques avec l''opérateur site:","Recherche par type de fichier avec l''opérateur filetype:"],"de":["Präzise Suche mit exakten Phrasen","Exploratorische Suche für breite Themen","Ausschluss von Termen mit dem Operator -","Suche auf bestimmten Websites mit dem Operator site:","Suche nach Dateityp mit dem Operator filetype:"],"pt":["Busca precisa com frases exatas","Exclusão de termos irrelevantes","Busca em sites específicos","Busca por tipo de arquivo","Técnicas de busca exploratória"],"ru":["Точный поиск с помощью точных фраз","Исключение нерелевантных терминов","Поиск на конкретных сайтах","Поиск по типу файла","Методы探аторного поиска"],"ar":["بحث دقيق مع العبارات الدقيقة","استبعاد المصطلحات غير ذات الصلة","البحث في المواقع المحددة","البحث حسب نوع الملف","تقنيات البحث الاستكشافي"]},"keywords":{"en":["how to use information-retrieval","what is information-retrieval","information-retrieval alternative","information-retrieval vs google search","information-retrieval setup guide","information-retrieval install","advanced search strategies","precise search techniques","exploratory search methods"],"zh":["信息检索","精确搜索","探索搜索","React","Python","AIエージェント","信息检索技巧","开发者工具"],"ja":["情報検索","正確な検索","探索検索","React","Python","AIエージェント","情報検索テクニック","開発者ツール"],"ko":["정보 검색","정밀 검색","탐색 검색","React","Python","AI 에이전트","정보 검색 기술","개발자 도구"],"es":["recuperación de información","búsqueda precisa","búsqueda exploratoria","agentes de inteligencia artificial","técnicas de búsqueda","información relevante","información confiable","herramientas de búsqueda"],"fr":["recherche d''informations","recherche précise","recherche exploratoire","outils IA","techniques de recherche","informations pertinentes","informations fiables","outils de recherche"],"de":["Informationsrückgewinnung","präzise Suche","exploratorische Suche","KI-Tools","Suchtechniken","relevante Informationen","zuverlässige Informationen","Suchwerkzeuge"],"pt":["recuperação de informações","busca avançada","frases exatas","exclusão de termos","busca em sites específicos","tipo de arquivo","técnicas de busca exploratória"],"ru":["поиск информации","передовой поиск","точные фразы","исключение терминов","поиск на конкретных сайтах","тип файла","методы探аторного поиска"],"ar":["استرجاع المعلومات","البحث المتقدم","العبارات الدقيقة","استبعاد المصطلحات","البحث في المواقع المحددة","نوع الملف","تقنيات البحث الاستكشافي"]}},"owner":"KaltWulx","repo":"prompts","repoPath":"KaltWulx/prompts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.265Z","topics":[],"category":"community","skillMd":{"name":"information-retrieval","description":"Estrategias efectivas para buscar y recuperar información","tags":["research","search","information","analysis"],"bodyPreview":"# Information Retrieval\n\nTécnicas y estrategias para encontrar información relevante y confiable.\n\n## Estrategias de Búsqueda\n\n### 1. Búsqueda Precisa\n**Cuándo usar:** Conoces exactamente qué buscas.\n\n**Técnicas:**\n- Frases exactas: `\"machine learning\"`\n- Exclusion: `python -snake`\n- Site específico: `site:github.com authentication`\n- Tipo de archivo: `filetype:pdf`\n\n**Ejemplo:**\n```\n\"React hooks\" site:react.dev best practices\n```\n\n### 2. Búsqueda Exploratoria\n**Cuándo usar:** Tema amplio, neces","body":"# Information Retrieval\n\nTécnicas y estrategias para encontrar información relevante y confiable.\n\n## Estrategias de Búsqueda\n\n### 1. Búsqueda Precisa\n**Cuándo usar:** Conoces exactamente qué buscas.\n\n**Técnicas:**\n- Frases exactas: `\"machine learning\"`\n- Exclusion: `python -snake`\n- Site específico: `site:github.com authentication`\n- Tipo de archivo: `filetype:pdf`\n\n**Ejemplo:**\n```\n\"React hooks\" site:react.dev best practices\n```\n\n### 2. Búsqueda Exploratoria\n**Cuándo usar:** Tema amplio, necesitas entender el landscape.\n\n**Técnicas:**\n- Términos generales\n- Palabras clave relacionadas\n- Sinónimos\n- Conceptos padre/hijo\n\n**Ejemplo:**\n```\nstate management React alternatives\n```\n\n### 3. Búsqueda de Soluciones\n**Cuándo usar:** Tienes un problema específico.\n\n**Técnicas:**\n- Error messages exactos\n- Síntomas del problema\n- Stack/versión específica\n- Palabras: \"how to\", \"solution\", \"fix\"\n\n**Ejemplo:**\n```\nReact useEffect infinite loop dependency array solution\n```\n\n## Evaluación de Fuentes\n\n### Credibilidad\n**✅ Fuentes Confiables:**\n- Documentación oficial\n- Papers académicos revisados\n- Blogs de mantenedores/core team\n- GitHub repos oficiales\n\n**⚠️ Fuentes con Cautela:**\n- Stack Overflow (verificar fecha y votos)\n- Medium/Dev.to (verificar autoridad del autor)\n- Tutoriales de YouTube (verificar fecha)\n\n**❌ Evitar:**\n- Sin fecha (posiblemente obsoleto)\n- Sin autor identificado\n- Sitios con exceso de ads\n- Contenido generado automáticamente\n\n### Actualidad\nVerificar fechas:\n- Tecnología: < 1 año ideal\n- Mejores prácticas: < 2 años\n- Conceptos fundamentales: pueden ser más antiguos\n\n### Consistencia\n- ¿Múltiples fuentes dicen lo mismo?\n- ¿Contradice documentación oficial?\n- ¿Hay consenso en la comunidad?\n\n## Técnicas Avanzadas\n\n### Búsqueda Inversa\nParte de la solución, encuentra el problema:\n```\n\"useCallback\" \"dependency array\" solution\n```\n\n### Búsqueda Comparativa\nComparar alternativas:\n```\nRedux vs Zustand vs Jotai 2024\n```\n\n### Búsqueda de Recursos\nEncontrar herramientas/librerías:\n```\nbest React form libraries github stars\n```\n\n### Búsqueda de Expertos\nEncontrar authorities:\n```\n\"Dan Abramov\" React best practices\n```\n\n## Síntesis de Información\n\n### Proceso\n1. **Recopilar**: Guardar fuentes relevantes\n2. **Evaluar**: Verificar credibilidad\n3. **Comparar**: Cruzar información\n4. **Sintetizar**: Consolidar hallazgos\n5. **Presentar**: Organizar de forma clara\n\n### Estructura de Hallazgos\n```\n## Resumen Ejecutivo\n[2-3 oraciones de conclusiones principales]\n\n## Hallazgos Detallados\n\n### [Tema 1]\n- Punto clave 1\n- Punto clave 2\n- Fuente: [link]\n\n### [Tema 2]\n- Punto clave 1\n- Punto clave 2\n- Fuente: [link]\n\n## Fuentes Consultadas\n1. [Título](url) - Autor, Fecha\n2. [Título](url) - Autor, Fecha\n\n## Recomendaciones\n[Basado en evidencia encontrada]\n```\n\n## Búsqueda en Repositorios\n\n### GitHub\n**Búsquedas útiles:**\n- `stars:>1000 language:python`: Repos populares en Python\n- `topic:machine-learning`: Repos con ese topic\n- `filename:docker-compose.yml`: Buscar archivos específicos\n- `path:src/components`: Buscar en paths específicos\n\n### Documentación\n**Tácticas:**\n- Usar search interno de docs\n- Revisar changelog/migration guides\n- Checar issues y PRs para edge cases\n- Leer source code cuando sea necesario\n\n## Búsqueda Académica\n\n### Google Scholar\n- Papers revisados por pares\n- Citas para verificar influencia\n- Related works para contexto\n\n### arXiv\n- Preprints de CS, ML, etc.\n- Acceso libre\n- Versiones actualizadas\n\n## Anti-Patrones\n\n❌ **Evitar:**\n1. **Confirmation Bias**: Solo buscar lo que confirma tu hipótesis\n2. **Primera Fuente**: Tomar el primer resultado sin verificar\n3. **Sin Fecha**: Ignorar cuándo fue publicado\n4. **Sin Contexto**: Aplicar soluciones sin entender el problema\n5. **Fuentes Únicas**: Depender de una sola fuente\n\n## Checklist de Calidad\n\n- [ ] Múltiples fuentes consultadas\n- [ ] Fuentes verificadas como confiables\n- [ ] Información actualizada (< 1-2 años)\n- [ ] Consistencia entre fuentes\n- [ ] Fuentes citadas claramente\n- [ ] Información relevante al contexto\n- [ ] Contradicciones identificadas y resueltas\n"},"lastSynced":"2026-03-08T01:59:54.173Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing precise and efficient information retrieval capabilities.","zh":"非常适合需要精确和高效信息检索能力的研究代理。","ja":"研究エージェントが正確で効率的な情報検索機能を必要とする場合に最適です。","ko":"정확하고 효율적인 정보 검색 기능이 필요한 연구 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Investigación que necesitan capacidades de recuperación de información precisas y eficientes.","fr":"Idéal pour les agents de recherche nécessitant des capacités de récupération d''informations précises et efficaces.","de":"Perfekt für Forschungsagenten, die präzise und effiziente Informationsabrufkapazitäten benötigen.","pt":"Perfeito para Agentes de Pesquisa que necessitam de capacidades de recuperação de informações precisas e eficientes.","ru":"Идеально подходит для агентов-исследователей, которым необходимы точные и эффективные возможности поиска информации.","ar":"مثالي لوكلاء البحث الذين يحتاجون إلى قدرات استرجاع المعلومات دقيقة وفعّالة."},"recommendation":{"en":"Empowers agents to execute precise searches using techniques like exact phrases, exclusion, site-specific queries, and filetype filtering, leveraging protocols and operators to refine results.","zh":"赋予代理执行精确搜索的能力，使用诸如确切短语、排除、站点特定查询和文件类型过滤等技术，利用协议和运算符来改进结果。","ja":"エージェントに正確な検索を実行する能力を与え、正確なフレーズ、除外、サイト特定のクエリ、ファイルタイプのフィルタリングなどの技術を使用し、プロトコルと演算子を利用して結果を改善します。","ko":"에이전트가 정확한 검색을 수행할 수 있는 능력을 부여하여 정확한 구문, 제외, 사이트 특정 쿼리 및 파일 유형 필터링과 같은 기술을 사용하고 프로토콜 및 연산자를 활용하여 결과를 개선합니다.","es":"Habilita a los agentes a ejecutar búsquedas precisas utilizando técnicas como frases exactas, exclusión, consultas específicas de sitio y filtrado de tipo de archivo, aprovechando protocolos y operadores para refinar los resultados.","fr":"Permet aux agents d''exécuter des recherches précises en utilisant des techniques comme des phrases exactes, l''exclusion, des requêtes spécifiques à un site et un filtrage de type de fichier, en exploitant les protocoles et les opérateurs pour affiner les résultats.","de":"Ermächtigt die Agenten, präzise Suchanfragen mit Techniken wie exakte Phrasen, Ausschluss, sitespezifische Abfragen und Dateityp-Filterung auszuführen, indem sie Protokolle und Operatoren nutzen, um die Ergebnisse zu verfeinern.","pt":"Permite que os agentes realizem pesquisas precisas usando técnicas como frases exatas, exclusão, consultas específicas de site e filtragem de tipo de arquivo, aproveitando protocolos e operadores para refinar os resultados.","ru":"Позволяет агентам выполнять точные поиски с использованием техник, таких как точные фразы, исключение, запросы, специфичные для сайта, и фильтрация по типу файла, используя протоколы и операторы для уточнения результатов.","ar":"تمكّن الوكلاء من تنفيذ عمليات بحث دقيقة باستخدام تقنيات مثل العبارات الدقيقة والاستبعاد والاستفسارات المحددة للموقع وترشيح نوع الملف، واستغلال البروتوكولات والoperators لتحسين النتائج."},"useCases":{"en":["Automating fact-checking with precise search queries","Generating relevant data sources for research papers","Debugging information gaps with exploratory search strategies"],"zh":["使用精确的搜索查询自动化事实核查","为研究论文生成相关的数据源","使用探索性的搜索策略调试信息缺口"],"ja":["精確な検索クエリを使用して事実の検証を自動化する","研究論文のための関連データソースを生成する","探索的な検索戦略を使用して情報ギャップをデバッグする"],"ko":["정확한 검색 쿼리를 사용하여 사실 확인을 자동화하는 것","연구 논문에 대한 관련 데이터 소스를 생성하는 것","탐색적 검색 전략을 사용하여 정보 격차를 디버깅하는 것"],"es":["Automatizar la verificación de hechos con consultas de búsqueda precisas","Generar fuentes de datos relevantes para artículos de investigación","Depurar lagunas de información con estrategias de búsqueda exploratoria"],"fr":["Automatiser la vérification des faits avec des requêtes de recherche précises","Générer des sources de données pertinentes pour les articles de recherche","Déboguer les lacunes d''information avec des stratégies de recherche exploratoire"],"de":["Automatisieren von Faktenüberprüfung mit präzisen Suchabfragen","Generieren von relevanten Datenquellen für Forschungsarbeiten","Fehlerbehebung von Informationslücken mit explorativen Suchstrategien"],"pt":["Automatizar a verificação de fatos com consultas de pesquisa precisas","Gerar fontes de dados relevantes para artigos de pesquisa","Depurar lacunas de informação com estratégias de busca exploratória"],"ru":["Автоматизировать проверку фактов с помощью точных поисковых запросов","Генерировать актуальные источники данных для исследовательских работ","Устранять пробелы в информации с помощью исследовательских стратегий поиска"],"ar":["تأتمة التحقق من الحقائق باستخدام استفسارات بحث دقيقة","توليد مصادر بيانات ذات صلة لأوراق البحث","تصحيح فجوات المعلومات باستخدام استراتيجيات بحث استكشافية"]},"limitations":{"en":["Requires internet access for search queries","Dependent on search engine algorithms and indexing"],"zh":["需要互联网访问来进行搜索查询","依赖于搜索引擎的算法和索引"],"ja":["検索クエリを実行するためにインターネットアクセスが必要","検索エンジンのアルゴリズムとインデックスに依存する"],"ko":["검색 쿼리를 수행하려면 인터넷 액세스가 필요함","검색 엔진의 알고리즘과 색인에 의존함"],"es":["Requiere acceso a Internet para consultas de búsqueda","Dependiente de algoritmos y indexación de motores de búsqueda"],"fr":["Nécessite un accès à Internet pour les requêtes de recherche","Dépend des algorithmes et de l''indexation des moteurs de recherche"],"de":["Benötigt Internetzugang für Suchabfragen","Abhängig von Suchmaschinen-Algorithmen und Indexierung"],"pt":["Requer acesso à internet para consultas de pesquisa","Depende dos algoritmos e indexação dos mecanismos de busca"],"ru":["Требует доступа к интернету для поисковых запросов","Зависит от алгоритмов и индексации поисковых систем"],"ar":["يتطلب الوصول إلى الإنترنت للاستفسارات البحثية","يعتمد على خوارزميات وفهارس محركات البحث"]},"version":4},"contentHash":"143cc2448225354cbc074b6e549a00f87140b0cf3e2046f5dd137ed95da09728","qualityScore":35}');
