INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KaltWulx/prompts/information-retrieval', 'information-retrieval', 'KaltWulx', 'prompts', 'community', 'information-retrieval KaltWulx prompts community The information-retrieval skill provides techniques and strategies for finding relevant and reliable information, benefiting developers and researchers who need to efficiently search for specific data. 信息检索技能提供了精确搜索和探索技术，帮助开发者找到相关和可靠的信息 情報検索スキルは、開発者が関連性の高い情報を見つけるのに役立つ、正確な検索と探索テクニックを提供します 정보 검색 스킬은 개발자가 관련성 높은 정보를 찾을 수 있도록 정밀 검색 및 탐색 기술을 제공합니다 La recuperación de información implica técnicas y estrategias para encontrar información relevante y confiable, como búsqueda precisa y exploratoria La recherche d''informations implique des techniques et des stratégies pour trouver des informations pertinentes et fiables, comme la recherche précise et exploratoire Die Informationsrückgewinnung umfasst Techniken und Strategien, um relevante und zuverlässige Informationen zu finden, wie z.B. präzise und exploratorische Suche Recuperação de informações é uma técnica para encontrar dados relevantes. Utilize frases exatas, exclusão e busca em sites específicos Инструменты ИИ Агентов для поиска информации помогают находить релевантные данные. Используйте точные фразы, исключение и поиск на конкретных сайтах استرجاع المعلومات هو تقنية لاسترجاع البيانات ذات الصلة. استخدم العبارات الدقيقة والاستبعاد والبحث في المواقع المحددة how to use information-retrieval what is information-retrieval information-retrieval alternative information-retrieval vs google search information-retrieval setup guide information-retrieval install advanced search strategies precise search techniques exploratory search methods 信息检索 精确搜索 探索搜索 React Python AIエージェント 信息检索技巧 开发者工具 Supports precise search using exact phrases, such as "machine learning" Allows exclusion of specific terms, like `python -snake` Enables site-specific searches, such as `site:github.com authentication` Supports searching by file type, including `filetype:pdf` Facilitates exploratory searches for broad topics information-retrieval is a set of techniques and strategies used to find relevant and reliable information, including precise search, exploratory search, and more.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ed1s0nZ/CyberStrikeAI/vulnerability-assessment', 'community', 'Ed1s0nZ', 'CyberStrikeAI', 'Ed1s0nZ/CyberStrikeAI', 'vulnerability-assessment', 0, 0, 35, '2026-03-08T01:57:15.280Z', '2026-03-08T02:00:50.244Z', '7d0aacbd12e06dafece0703864ea6f23f3ba8a0e6bfcaece2680e941d3df3431', '{"id":"Ed1s0nZ/CyberStrikeAI/vulnerability-assessment","name":"vulnerability-assessment","description":{"en":"The vulnerability-assessment skill provides a methodical approach to identifying and evaluating system vulnerabilities, benefiting security testers and developers. It integrates with 100+ security tools for comprehensive testing.","zh":"CyberStrikeAI 漏洞评估技能是一个识别和评估系统漏洞的重要环节，提供了漏洞评估的方法、工具和最佳实践","ja":"AIエージェントによる脆弱性評価は、システムの脆弱性を識別および評価するための重要なステップであり、脆弱性評価の方法、ツール、およびベストプラクティスを提供します","ko":"CyberStrikeAI 취약점 평가 기능은 시스템 취약점을 식별하고 평가하는 중요한 단계로, 취약점 평가 방법, 도구 및 모범 사례를 제공합니다","es":"La evaluación de vulnerabilidades es un proceso crucial para identificar y evaluar las debilidades de un sistema. CyberStrikeAI ofrece una plataforma de pruebas de seguridad para ayudar en este proceso.","fr":"L''évaluation des vulnérabilités est un processus crucial pour identifier et évaluer les faiblesses d''un système. CyberStrikeAI propose une plateforme de tests de sécurité pour aider dans ce processus.","de":"Die Schwachstellenbewertung ist ein entscheidender Prozess, um die Schwächen eines Systems zu identifizieren und zu bewerten. CyberStrikeAI bietet eine Sicherheitstestplattform, um bei diesem Prozess zu helfen.","pt":"A avaliação de vulnerabilidades é um processo crítico para identificar e mitigar ameaças de segurança. Este guia aborda as melhores práticas para configurar e executar avaliações de vulnerabilidades","ru":"Оценка уязвимостей является критическим процессом для выявления и смягчения угроз безопасности. Это руководство охватывает лучшие практики для настройки и выполнения оценок уязвимостей с ИИ Агентами","ar":"تقييم الثغرات الأمنية هو عملية حرجة لتحديد وتخفيف التهديدات الأمنية. هذا الدليل يغطي أفضل الممارسات لإعداد وتشغيل تقييمات الثغرات الأمنية مع وكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"Vulnerability-Assessment: Comprehensive Setup Guide | AI ...","zh":"漏洞评估 Setup Guide - CyberStrikeAI 安全测试平台","ja":"脆弱性評価ベストプラクティス - AIエージェントによるセキュリティテスト","ko":"취약점 평가 가이드 - CyberStrikeAI 보안 테스트 플랫폼","es":"Guía de configuración para la evaluación de vulnerabilida...","fr":"Guide de configuration pour l''évaluation des vulnérabilit...","de":"Konfigurationsleitfaden für die Schwachstellenbewertung m...","pt":"Guia de Configuração de Avaliação de Vulnerabilidades com...","ru":"Руководство по настройке оценки уязвимостей с помощью ИИ ...","ar":"دليل إعداد تقييم الثغرات الأمنية باستخدام أدوات الأمن الإ..."},"description":{"en":"Discover how to identify and evaluate system vulnerabilities with CyberStrikeAI''s vulnerability-assessment skill. Get started with our expert guide and secur...","zh":"CyberStrikeAI 漏洞评估技能提供网络扫描、主机扫描、应用扫描和配置扫描等功能，帮助开发者识别和评估系统漏洞","ja":"AIエージェントを使用した脆弱性評価は、ネットワークスキャン、ホストスキャン、アプリケーションスキャン、設定スキャンなどの機能を提供し、開発者がシステムの脆弱性を識別および評価するのに役立ちます","ko":"CyberStrikeAI 취약점 평가 기능은 네트워크 스캔, 호스트 스캔, 애플리케이션 스캔, 구성 스캔 등을 제공하여 개발자가 시스템 취약점을 식별하고 평가하는 데 도움을 줍니다","es":"Aprende a evaluar vulnerabilidades con CyberStrikeAI, una plataforma de pruebas de seguridad nativa de IA que integra más de 100 herramientas de seguridad","fr":"Découvrez comment évaluer les vulnérabilités avec CyberStrikeAI, une plateforme de tests de sécurité native IA qui intègre plus de 100 outils de sécurité","de":"Erfahren Sie, wie Sie Schwachstellen mit CyberStrikeAI bewerten, einer Sicherheitstestplattform, die mehr als 100 Sicherheitstools integriert","pt":"Aprenda a configurar e executar avaliações de vulnerabilidades com ferramentas de segurança como Nessus, OpenVAS e Nmap","ru":"Узнайте, как настроить и выполнить оценку уязвимостей с помощью инструментов безопасности, таких как Nessus, OpenVAS и Nmap, с ИИ Агентами","ar":"تعرف على كيفية إعداد وتشغيل تقييمات الثغرات الأمنية باستخدام أدوات الأمن مثل Nessus و OpenVAS و Nmap مع وكلاء الذكاء الاصطناعي"},"definition":{"en":"Vulnerability-assessment is a critical process of identifying and evaluating system vulnerabilities, involving scope determination, information gathering, vulnerability scanning, and risk assessment.","zh":"漏洞评估是识别和评估系统漏洞的过程，包括网络扫描、主机扫描、应用扫描和配置扫描等步骤","ja":"脆弱性評価は、システムの脆弱性を識別および評価するためのプロセスであり、ネットワークスキャン、ホストスキャン、アプリケーションスキャン、設定スキャンなどのステップを含みます","ko":"취약점 평가란 시스템 취약점을 식별하고 평가하는 과정으로, 네트워크 스캔, 호스트 스캔, 애플리케이션 스캔, 구성 스캔 등의 단계를 포함합니다","es":"La evaluación de vulnerabilidades es el proceso de identificar y evaluar las debilidades de un sistema para determinar su nivel de riesgo","fr":"L''évaluation des vulnérabilités est le processus d''identification et d''évaluation des faiblesses d''un système pour déterminer son niveau de risque","de":"Die Schwachstellenbewertung ist der Prozess der Identifizierung und Bewertung der Schwächen eines Systems, um sein Risikolevel zu bestimmen","pt":"Avaliação de vulnerabilidades é o processo de identificar e avaliar vulnerabilidades em sistemas e aplicativos","ru":"Оценка уязвимостей - это процесс выявления и оценки уязвимостей в системах и приложениях с помощью ИИ Агентов","ar":"تقييم الثغرات الأمنية هو عملية تحديد وتقييم الثغرات الأمنية في الأنظمة والتطبيقات مع وكلاء الذكاء الاصطناعي"},"features":{"en":["Utilizes Nessus, OpenVAS, and Nmap for network scanning and vulnerability detection","Supports role-based testing with predefined security roles","Provides a skills system with specialized testing skills for comprehensive lifecycle management","Performs vulnerability validation using manual, tool-based, and conceptual methods","Assesses risk factors including vulnerability severity, exploitability, and business impact"],"zh":["网络扫描功能，使用Nessus、OpenVAS和Nmap等工具","主机扫描功能，识别系统漏洞和配置问题","应用扫描功能，检测应用程序中的安全漏洞","配置扫描功能，评估系统配置和安全设置","漏洞验证功能，手动验证、工具验证和概念验证","风险评估功能，评估漏洞严重性、利用难度和影响范围"],"ja":["ネットワークスキャン機能、Nessus、OpenVAS、Nmapなどのツールを使用","ホストスキャン機能、システムの脆弱性と設定問題を識別","アプリケーションスキャン機能、セキュリティの脆弱性を検出","設定スキャン機能、システムの設定とセキュリティ設定を評価","脆弱性の検証機能、手動検証、ツール検証、概念検証","リスク評価機能、脆弱性の深刻度、利用の難易度、影響範囲を評価"],"ko":["네트워크 스캔 기능, Nessus, OpenVAS, Nmap 등을 사용","호스트 스캔 기능, 시스템 취약점과 구성 문제를 식별","애플리케이션 스캔 기능, 보안 취약점을 감지","구성 스캔 기능, 시스템 구성과 보안 설정을 평가","취약점 검증 기능, 수동 검증, 도구 검증, 개념 검증","위험 평가 기능, 취약점 심각도, 활용 난이도, 영향 범위를 평가"],"es":["Integración de más de 100 herramientas de seguridad","Motor de orquestación inteligente para pruebas de seguridad","Roles de seguridad predefinidos para pruebas de vulnerabilidades","Herramientas de escaneo de vulnerabilidades como Nessus y OpenVAS","Análisis de resultados de escaneo para identificar vulnerabilidades"],"fr":["Intégration de plus de 100 outils de sécurité","Moteur d''orchestration intelligente pour les tests de sécurité","Rôles de sécurité prédéfinis pour les tests de vulnérabilités","Outils de scan de vulnérabilités tels que Nessus et OpenVAS","Analyse des résultats de scan pour identifier les vulnérabilités"],"de":["Integration von mehr als 100 Sicherheitstools","Intelligenter Orchestrierungsmotor für Sicherheitstests","Vordefinierte Sicherheitsrollen für Schwachstellenbewertung","Sicherheitsscanner wie Nessus und OpenVAS","Analyse der Scandaten, um Schwachstellen zu identifizieren"],"pt":["Utilização de ferramentas de segurança como Nessus, OpenVAS e Nmap","Configuração de políticas de segurança personalizadas","Análise de resultados de avaliação de vulnerabilidades","Integração com plataformas de gerenciamento de segurança","Suporte a múltiplos protocolos de segurança"],"ru":["Использование инструментов безопасности, таких как Nessus, OpenVAS и Nmap, с ИИ Агентами","Настройка индивидуальных политик безопасности","Анализ результатов оценки уязвимостей","Интеграция с платформами управления безопасности","Поддержка нескольких протоколов безопасности"],"ar":["استخدام أدوات الأمن مثل Nessus و OpenVAS و Nmap مع وكلاء الذكاء الاصطناعي","إعداد سياسات أمن مخصصة","تحليل نتائج تقييم الثغرات الأمنية","التكامل مع منصات إدارة الأمن","دعم بروتوكولات أمن متعددة"]},"keywords":{"en":["how to use vulnerability-assessment","vulnerability-assessment setup guide","vulnerability-assessment vs penetration testing","what is vulnerability-assessment","vulnerability-assessment alternative tools","installing vulnerability-assessment on CyberStrikeAI","vulnerability-assessment best practices for AI agents","network scanning with Nessus and OpenVAS","vulnerability validation methods","risk assessment in vulnerability-assessment"],"zh":["漏洞评估","网络扫描","主机扫描","应用扫描","配置扫描","CyberStrikeAI","AI安全测试","漏洞评估工具","网络安全"],"ja":["脆弱性評価","ネットワークスキャン","ホストスキャン","アプリケーションスキャン","設定スキャン","AIエージェント","セキュリティテスト","脆弱性評価ツール","ネットワークセキュリティ"],"ko":["취약점 평가","네트워크 스캔","호스트 스캔","애플리케이션 스캔","구성 스캔","CyberStrikeAI","AI 보안 테스트","취약점 평가 도구","네트워크 보안"],"es":["evaluación de vulnerabilidades","pruebas de seguridad","herramientas de seguridad","Nessus","OpenVAS","CyberStrikeAI","seguridad de la información","protección de datos"],"fr":["évaluation des vulnérabilités","tests de sécurité","outils de sécurité","Nessus","OpenVAS","CyberStrikeAI","sécurité de l''information","protection des données"],"de":["Schwachstellenbewertung","Sicherheitstests","Sicherheitstools","Nessus","OpenVAS","CyberStrikeAI","Informationssicherheit","Datenschutz"],"pt":["avaliação de vulnerabilidades","ferramentas de segurança","Nessus","OpenVAS","Nmap","segurança cibernética","gestão de segurança","políticas de segurança"],"ru":["оценка уязвимостей","инструменты безопасности","ИИ Агенты","Nessus","OpenVAS","Nmap","кибербезопасность","управление безопасностью","политики безопасности"],"ar":["تقييم الثغرات الأمنية","أدوات الأمن","وكلاء الذكاء الاصطناعي","Nessus","OpenVAS","Nmap","أمن السيبراني","إدارة الأمن","سياسات الأمن"]}},"owner":"Ed1s0nZ","repo":"CyberStrikeAI","repoPath":"Ed1s0nZ/CyberStrikeAI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.280Z","topics":[],"category":"community","skillMd":{"name":"vulnerability-assessment","description":"漏洞评估的专业技能和方法论","version":"1.0.0","bodyPreview":"# 漏洞评估\n\n## 概述\n\n漏洞评估是识别和评估系统漏洞的重要环节。本技能提供漏洞评估的方法、工具和最佳实践。\n\n## 评估流程\n\n### 1. 范围确定\n\n**确定范围：**\n- 目标系统\n- 网络范围\n- 应用范围\n- 测试深度\n\n### 2. 信息收集\n\n**收集信息：**\n- 系统信息\n- 网络拓扑\n- 服务信息\n- 应用信息\n\n### 3. 漏洞扫描\n\n**扫描类型：**\n- 网络扫描\n- 主机扫描\n- 应用扫描\n- 配置扫描\n\n### 4. 漏洞验证\n\n**验证方法：**\n- 手动验证\n- 工具验证\n- 概念验证\n- 影响评估\n\n### 5. 风险评估\n\n**评估因素：**\n- 漏洞严重性\n- 利用难度\n- 影响范围\n- 业务影响\n\n## 扫描工具\n\n### 网络扫描\n\n**使用Nessus：**\n```bash\n# 启动Nessus\n# 创建扫描任务\n# 配置扫描策略\n# 执行扫描\n# 分析结果\n```\n\n**使用OpenVAS：**\n```bash\n# 启动OpenVAS\ngvm-setup\n\n# 创建扫描任务\n# 执行扫描\n# 分析结果\n```\n\n**使用Nmap：","body":"# 漏洞评估\n\n## 概述\n\n漏洞评估是识别和评估系统漏洞的重要环节。本技能提供漏洞评估的方法、工具和最佳实践。\n\n## 评估流程\n\n### 1. 范围确定\n\n**确定范围：**\n- 目标系统\n- 网络范围\n- 应用范围\n- 测试深度\n\n### 2. 信息收集\n\n**收集信息：**\n- 系统信息\n- 网络拓扑\n- 服务信息\n- 应用信息\n\n### 3. 漏洞扫描\n\n**扫描类型：**\n- 网络扫描\n- 主机扫描\n- 应用扫描\n- 配置扫描\n\n### 4. 漏洞验证\n\n**验证方法：**\n- 手动验证\n- 工具验证\n- 概念验证\n- 影响评估\n\n### 5. 风险评估\n\n**评估因素：**\n- 漏洞严重性\n- 利用难度\n- 影响范围\n- 业务影响\n\n## 扫描工具\n\n### 网络扫描\n\n**使用Nessus：**\n```bash\n# 启动Nessus\n# 创建扫描任务\n# 配置扫描策略\n# 执行扫描\n# 分析结果\n```\n\n**使用OpenVAS：**\n```bash\n# 启动OpenVAS\ngvm-setup\n\n# 创建扫描任务\n# 执行扫描\n# 分析结果\n```\n\n**使用Nmap：**\n```bash\n# 漏洞扫描\nnmap --script vuln target\n\n# 特定漏洞\nnmap --script smb-vuln-ms17-010 target\n```\n\n### 应用扫描\n\n**使用Burp Suite：**\n```bash\n# 配置代理\n# 浏览应用\n# 被动扫描\n# 主动扫描\n# 分析结果\n```\n\n**使用OWASP ZAP：**\n```bash\n# 启动ZAP\nzap.sh\n\n# 快速扫描\nzap-cli quick-scan http://target.com\n\n# 完整扫描\nzap-cli full-scan http://target.com\n```\n\n**使用Acunetix：**\n```bash\n# 启动Acunetix\n# 创建扫描任务\n# 配置扫描选项\n# 执行扫描\n# 分析结果\n```\n\n### 代码扫描\n\n**使用SonarQube：**\n```bash\n# 运行扫描\nsonar-scanner\n\n# 分析结果\n# 查看报告\n```\n\n**使用Checkmarx：**\n```bash\n# 使用Web界面\n# 上传代码\n# 执行扫描\n# 分析结果\n```\n\n## 漏洞分类\n\n### 按严重性\n\n**严重（Critical）：**\n- 远程代码执行\n- SQL注入\n- 认证绕过\n- 敏感数据泄露\n\n**高危（High）：**\n- 权限提升\n- 信息泄露\n- 业务逻辑漏洞\n- 配置错误\n\n**中危（Medium）：**\n- XSS漏洞\n- CSRF漏洞\n- 弱密码\n- 不安全的配置\n\n**低危（Low）：**\n- 信息泄露\n- 配置建议\n- 最佳实践\n- 信息收集\n\n### 按类型\n\n**注入漏洞：**\n- SQL注入\n- 命令注入\n- LDAP注入\n- XPath注入\n\n**认证漏洞：**\n- 弱密码\n- 会话固定\n- 认证绕过\n- 密码重置\n\n**授权漏洞：**\n- 权限提升\n- IDOR\n- 水平权限\n- 垂直权限\n\n**配置错误：**\n- 默认配置\n- 错误配置\n- 不安全的存储\n- 敏感信息泄露\n\n## 风险评估\n\n### CVSS评分\n\n**基础指标：**\n- 攻击向量（AV）\n- 攻击复杂度（AC）\n- 所需权限（PR）\n- 用户交互（UI）\n\n**影响指标：**\n- 机密性影响（C）\n- 完整性影响（I）\n- 可用性影响（A）\n\n**计算CVSS：**\n```bash\n# 使用CVSS计算器\n# 输入指标\n# 计算分数\n# 确定等级\n```\n\n### 业务影响\n\n**评估因素：**\n- 数据敏感性\n- 系统重要性\n- 业务影响\n- 合规要求\n\n**风险矩阵：**\n```\n           低影响    中影响    高影响\n高可能性    中       高       严重\n中可能性    低       中       高\n低可能性    低       低       中\n```\n\n## 报告编写\n\n### 报告结构\n\n**执行摘要：**\n- 评估概述\n- 关键发现\n- 风险评级\n- 建议措施\n\n**详细发现：**\n- 漏洞描述\n- 影响分析\n- 利用步骤\n- 修复建议\n\n**附录：**\n- 扫描配置\n- 工具版本\n- 参考链接\n- 术语表\n\n### 报告模板\n\n```markdown\n# 漏洞评估报告\n\n## 执行摘要\n- 评估时间：2024-01-01\n- 评估范围：xxx\n- 发现漏洞：xx个\n- 严重漏洞：x个\n\n## 漏洞列表\n\n### VULN-001: SQL注入\n- 严重性：严重\n- CVSS评分：9.8\n- 描述：...\n- 影响：...\n- 修复建议：...\n\n## 总结\n...\n```\n\n## 最佳实践\n\n### 1. 扫描前\n\n- 获得授权\n- 确定范围\n- 准备工具\n- 通知相关人员\n\n### 2. 扫描中\n\n- 系统化扫描\n- 记录操作\n- 验证漏洞\n- 评估影响\n\n### 3. 扫描后\n\n- 分析结果\n- 编写报告\n- 提供建议\n- 跟踪修复\n\n## 注意事项\n\n- 获得明确授权\n- 避免对系统造成影响\n- 保护扫描数据\n- 及时报告关键漏洞"},"lastSynced":"2026-03-08T02:00:50.244Z","agentAnalysis":{"suitability":{"en":"Perfect for Cybersecurity Agents needing advanced vulnerability assessment and penetration testing capabilities.","zh":"非常适合需要高级漏洞评估和渗透测试能力的网络安全代理。","ja":"高度な脆弱性評価およびペネトレーションテスト機能を必要とするサイバーセキュリティエージェントに最適。","ko":"고급 취약점 평가 및 침투 테스트 기능이 필요한 사이버 보안 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Ciberseguridad que necesitan capacidades avanzadas de evaluación de vulnerabilidades y pruebas de penetración.","fr":"Parfait pour les agents de cybersécurité ayant besoin de capacités avancées d''évaluation des vulnérabilités et de tests de pénétration.","de":"Perfekt für Cybersicherheitsagenten, die erweiterte Funktionen zur Bewertung von Schwachstellen und Penetrationstests benötigen.","pt":"Perfeito para Agentes de Cibersegurança que necessitam de capacidades avançadas de avaliação de vulnerabilidade e teste de penetração.","ru":"Идеально подходит для агентов кибербезопасности, которым требуются расширенные возможности оценки уязвимостей и тестирования на проникновение.","ar":"مثالي لعمليات وكالات الأمن السيبراني التي تحتاج إلى قدرات تقييم متقدمة للثغرات الأمنية واختبار الاختراق."},"recommendation":{"en":"Empowers agents to identify and evaluate system vulnerabilities using 100+ security tools, integrating methods like network scanning, host scanning, and application scanning, and providing comprehensive testing and risk assessment through factors such as vulnerability severity, exploit difficulty, and business impact.","zh":"赋予代理识别和评估系统漏洞的能力，使用100多种安全工具，集成网络扫描、主机扫描和应用扫描等方法，通过漏洞严重性、利用难度和业务影响等因素提供全面测试和风险评估。","ja":"エージェントにシステムの脆弱性を特定し評価する機能を提供することで、100以上のセキュリティツールを統合し、ネットワークスキャン、ホストスキャン、アプリケーションスキャンなどの方法を使用し、脆弱性の深刻度、利用の難しさ、ビジネスへの影響などの要素を通じて、包括的なテストおよびリスク評価を提供する。","ko":"에이전트가 시스템의 취약점을 식별하고 평가할 수 있는 기능을 제공하며, 100가지 이상의 보안 도구를 통합하여 네트워크 스캔, 호스트 스캔, 애플리케이션 스캔 등의 방법을 사용하고, 취약점 심각도, 악용難易도, 비즈니스 영향 등의 요소를 통해 종합적인 테스트 및 리스크 평가를 제공합니다.","es":"Habilita a los agentes a identificar y evaluar las vulnerabilidades del sistema utilizando más de 100 herramientas de seguridad, integrando métodos como escaneo de red, escaneo de host y escaneo de aplicaciones, y proporcionando pruebas y evaluación de riesgos completas a través de factores como la gravedad de la vulnerabilidad, la dificultad de explotación y el impacto comercial.","fr":"Permet aux agents d''identifier et d''évaluer les vulnérabilités du système en utilisant plus de 100 outils de sécurité, en intégrant des méthodes telles que l''analyse de réseau, l''analyse d''hôte et l''analyse d''applications, et en fournissant des tests et une évaluation des risques complets à travers des facteurs tels que la gravité de la vulnérabilité, la difficulté d''exploitation et l''impact commercial.","de":"Ermächtigt die Agenten, Systemvulnerabilkeiten zu identifizieren und zu bewerten, indem sie mehr als 100 Sicherheitstools verwenden, Methoden wie Netzwerkscans, Hostscans und Anwendungsscans integrieren und umfassende Tests und Risikobewertungen durch Faktoren wie Schwere der Vulnerabilität, Ausnutzungserschwernis und geschäftlichen Auswirkungen bereitstellen.","pt":"Habilita os agentes a identificar e avaliar vulnerabilidades do sistema usando mais de 100 ferramentas de segurança, integrando métodos como varredura de rede, varredura de host e varredura de aplicativos, e fornecendo testes abrangentes e avaliação de riscos por meio de fatores como gravidade da vulnerabilidade, dificuldade de exploração e impacto comercial.","ru":"Наделяет агентов возможностью выявлять и оценивать уязвимости системы с помощью более 100 инструментов безопасности, интегрируя методы, такие как сканирование сети, сканирование хоста и сканирование приложений, и предоставляя комплексное тестирование и оценку рисков посредством факторов, таких как степень уязвимости, сложность эксплуатации и бизнес-воздействие.","ar":"تمكّن الوكالات من تحديد وتقييم ثغرات النظام باستخدام أكثر من 100 أداة أمنية، ودمج أساليب مثل مسح الشبكة و مسح المضيف و مسح التطبيقات، وتوفير اختبارات شاملة وتقييم للمخاطر من خلال عوامل مثل شدة الثغرة وصعوبة الاستغلال والأثر التجاري."},"useCases":{"en":["Automating vulnerability scans using Nessus and OpenVAS","Validating vulnerabilities through manual and tool-based verification","Assessing risks based on exploit difficulty and business impact"],"zh":["使用Nessus和OpenVAS自动执行漏洞扫描","通过手动和工具 기반验证确认漏洞","根据利用难度和业务影响评估风险"],"ja":["NessusとOpenVASを使用して脆弱性スキャンを自動化する","手動およびツールベースの検証を通じて脆弱性を確認する","利用の難しさとビジネスへの影響に基づいてリスクを評価する"],"ko":["Nessus와 OpenVAS를 사용하여 취약점 스캔을 자동화하는 것","수동 및 도구 기반 확인을 통해 취약점을 확인하는 것","악용難易도와 비즈니스 영향에 따라 리스크를 평가하는 것"],"es":["Automatización de análisis de vulnerabilidades utilizando Nessus y OpenVAS","Validación de vulnerabilidades a través de verificación manual y basada en herramientas","Evaluación de riesgos en función de la dificultad de explotación y el impacto comercial"],"fr":["Automatisation des analyses de vulnérabilités à l''aide de Nessus et OpenVAS","Validation des vulnérabilités via une vérification manuelle et basée sur des outils","Évaluation des risques en fonction de la difficulté d''exploitation et de l''impact commercial"],"de":["Automatisierung von Schwachstellenanalysen unter Verwendung von Nessus und OpenVAS","Validierung von Schwachstellen durch manuelle und toolbasierte Überprüfung","Bewertung von Risiken basierend auf der Ausnutzungserschwernis und den geschäftlichen Auswirkungen"],"pt":["Automatizar varreduras de vulnerabilidade usando Nessus e OpenVAS","Validar vulnerabilidades por meio de verificação manual e baseada em ferramentas","Avaliar riscos com base na dificuldade de exploração e no impacto comercial"],"ru":["Автоматизация сканирования уязвимостей с помощью Nessus и OpenVAS","Проверка уязвимостей с помощью ручной и инструментальной верификации","Оценка рисков на основе сложности эксплуатации и бизнес-воздействия"],"ar":["تأتميم مسح الثغرات الأمنية باستخدام Nessus و OpenVAS","التأكد من الثغرات من خلال التحقق اليدوي والأدوات القائمة","تقييم المخاطر بناءً على صعوبة الاستغلال والأثر التجاري"]},"limitations":{"en":["Requires integration with security tools and frameworks","Dependent on network and system access for scanning"],"zh":["需要与安全工具和框架集成","依赖于网络和系统访问进行扫描"],"ja":["セキュリティツールおよびフレームワークとの統合が必要","スキャンのためにネットワークおよびシステムへのアクセスに依存する"],"ko":["보안 도구 및 프레임워크와의 통합이 필요","스캔을 위해 네트워크 및 시스템 액세스에 의존"],"es":["Requiere integración con herramientas y marcos de seguridad","Dependiente del acceso a la red y al sistema para la exploración"],"fr":["Nécessite une intégration avec des outils et des cadres de sécurité","Dépendant de l''accès au réseau et au système pour l''analyse"],"de":["Erfordert Integration mit Sicherheitstools und -frameworks","Abhängig vom Netzwerk- und Systemzugriff für die Scans"],"pt":["Requer integração com ferramentas e frameworks de segurança","Depende do acesso à rede e ao sistema para varredura"],"ru":["Требует интеграции с инструментами и фреймворками безопасности","Зависит от доступа к сети и системе для сканирования"],"ar":["يتطلب دمجًا مع أدوات وأطر أمنية","يعتمد على الوصول إلى الشبكة والنظام لمسح"]},"version":4},"contentHash":"7d0aacbd12e06dafece0703864ea6f23f3ba8a0e6bfcaece2680e941d3df3431","qualityScore":35}');
DELETE FROM skills_fts WHERE id = 'Ed1s0nZ/CyberStrikeAI/vulnerability-assessment';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ed1s0nZ/CyberStrikeAI/vulnerability-assessment', 'vulnerability-assessment', 'Ed1s0nZ', 'CyberStrikeAI', 'community', 'vulnerability-assessment Ed1s0nZ CyberStrikeAI community The vulnerability-assessment skill provides a methodical approach to identifying and evaluating system vulnerabilities, benefiting security testers and developers. It integrates with 100+ security tools for comprehensive testing. CyberStrikeAI 漏洞评估技能是一个识别和评估系统漏洞的重要环节，提供了漏洞评估的方法、工具和最佳实践 AIエージェントによる脆弱性評価は、システムの脆弱性を識別および評価するための重要なステップであり、脆弱性評価の方法、ツール、およびベストプラクティスを提供します CyberStrikeAI 취약점 평가 기능은 시스템 취약점을 식별하고 평가하는 중요한 단계로, 취약점 평가 방법, 도구 및 모범 사례를 제공합니다 La evaluación de vulnerabilidades es un proceso crucial para identificar y evaluar las debilidades de un sistema. CyberStrikeAI ofrece una plataforma de pruebas de seguridad para ayudar en este proceso. L''évaluation des vulnérabilités est un processus crucial pour identifier et évaluer les faiblesses d''un système. CyberStrikeAI propose une plateforme de tests de sécurité pour aider dans ce processus. Die Schwachstellenbewertung ist ein entscheidender Prozess, um die Schwächen eines Systems zu identifizieren und zu bewerten. CyberStrikeAI bietet eine Sicherheitstestplattform, um bei diesem Prozess zu helfen. A avaliação de vulnerabilidades é um processo crítico para identificar e mitigar ameaças de segurança. Este guia aborda as melhores práticas para configurar e executar avaliações de vulnerabilidades Оценка уязвимостей является критическим процессом для выявления и смягчения угроз безопасности. Это руководство охватывает лучшие практики для настройки и выполнения оценок уязвимостей с ИИ Агентами تقييم الثغرات الأمنية هو عملية حرجة لتحديد وتخفيف التهديدات الأمنية. هذا الدليل يغطي أفضل الممارسات لإعداد وتشغيل تقييمات الثغرات الأمنية مع وكلاء الذكاء الاصطناعي how to use vulnerability-assessment vulnerability-assessment setup guide vulnerability-assessment vs penetration testing what is vulnerability-assessment vulnerability-assessment alternative tools installing vulnerability-assessment on CyberStrikeAI vulnerability-assessment best practices for AI agents network scanning with Nessus and OpenVAS vulnerability validation methods risk assessment in vulnerability-assessment 漏洞评估 网络扫描 主机扫描 应用扫描 配置扫描 CyberStrikeAI AI安全测试 漏洞评估工具 网络安全 Utilizes Nessus, OpenVAS, and Nmap for network scanning and vulnerability detection Supports role-based testing with predefined security roles Provides a skills system with specialized testing skills for comprehensive lifecycle management Performs vulnerability validation using manual, tool-based, and conceptual methods Assesses risk factors including vulnerability severity, exploitability, and business impact Vulnerability-assessment is a critical process of identifying and evaluating system vulnerabilities, involving scope determination, information gathering, vulnerability scanning, and risk assessment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blicktz/knowledge_base_repo/nick-theriot', 'community', 'blicktz', 'knowledge_base_repo', 'blicktz/knowledge_base_repo', 'nick-theriot', 0, 0, 35, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:21.205Z', '317471bc267463d73e8e336c141e214eebe4904a970546c9aafd8a953f3cd4cd', '{"id":"blicktz/knowledge_base_repo/nick-theriot","name":"nick-theriot","description":{"en":"The nick-theriot skill enables developers to interact with a conversational AI agent that uses an energetic and directive tone. It benefits developers looking for a coach-like delivery in their AI interactions.","zh":"Nick Theriot AI代理采用充满活力和对话式的语言风格，具有coach-like和hype-driven的语气","ja":"Nick Theriot AIエージェントは、エネルギーに満ちた会話スタイルとコーチのような語調を備えています","ko":"Nick Theriot AI 에이전트는 에너지 넘치고 대화식 언어 스타일과 코치 같은 어조를 가지고 있습니다","es":"Nick Theriot es un agente de AI que ofrece un enfoque práctico y motivacional para el desarrollo de software","fr":"Nick Theriot est un outil d''IA qui propose une approche pratique et motivante pour la programmation","de":"Nick Theriot ist ein KI-Agent, der einen praktischen und motivierenden Ansatz für die Softwareentwicklung bietet","pt":"O agente nick-theriot é um persona agent que fornece respostas em um tom energético e conversacional, com um estilo de entrega de treinamento motivacional","ru":"Агент nick-theriot является persona агентом, который предоставляет ответы в энергичном и разговорном тоне, с мотивационным стилем доставки","ar":"وحدة الإيضاح الإلكتروني nick-theriot هي وحدة شخصية توفر إجابات بطريقة محفزة ومشجعة، مع نمط تسليم مدرب محفز"},"seo":{"title":{"en":"nick-theriot: Conversational AI Agent Setup Guide | AI Agent","zh":"Nick Theriot AI代理设置指南","ja":"Nick Theriot AIエージェントのベストプラクティス","ko":"Nick Theriot AI 에이전트 설정 가이드","es":"Configuración de Nick Theriot: Guía de Agentes de AI","fr":"Paramétrage de Nick Theriot: Meilleures Pratiques pour le...","de":"Einrichtung von Nick Theriot: Leitfaden für KI-Agents","pt":"nick-theriot: Guia de Configuração de Agentes de IA","ru":"nick-theriot: Руководство по настройке ИИ Агентов","ar":"nick-theriot: دليل إعداد وحدات الإيضاح الإلكتروني"},"description":{"en":"Unlock the power of conversational AI with nick-theriot! Learn how to harness its energetic and directive tone to boost your projects. Get started now!","zh":"了解Nick Theriot AI代理的功能和特点，包括其语言风格和语气","ja":"Nick Theriot AIエージェントの特徴と機能を紹介します","ko":"Nick Theriot AI 에이전트의 기능과 특징을 살펴보세요","es":"Aprende a configurar y utilizar a Nick Theriot, un agente de AI con un enfoque en la programación y el desarrollo de software","fr":"Découvrez comment paramétrer et utiliser Nick Theriot, un outil d''IA pour les développeurs avec une approche centrée sur la programmation","de":"Erfahren Sie, wie Sie Nick Theriot einrichten und nutzen können, einen KI-Agenten mit Fokus auf Softwareentwicklung und Programmierung","pt":"Aprenda a configurar o agente nick-theriot com nosso guia passo a passo e descubra como melhorar a experiência do usuário com a tecnologia de IA","ru":"Узнайте, как настроить агент nick-theriot с нашей пошаговой инструкцией и откройте для себя возможности ИИ Агентов","ar":"تعلم كيفية إعداد وحدة الإيضاح الإلكتروني nick-theriot بخطوات بسيطة واكتشف كيف تحسن تجربة المستخدم مع تقنية الإيضاح الإلكتروني"},"definition":{"en":"nick-theriot is a conversational AI agent skill that utilizes a unique linguistic style profile to deliver energetic and motivational responses.","zh":"Nick Theriot AI代理是一种采用特定语言风格和语气的AI工具","ja":"Nick Theriot AIエージェントは、特定の言語スタイルとトーンを使用するAIエージェントです","ko":"Nick Theriot AI 에이전트는 특정 언어 스타일과 어조를 사용하는 AI 도구입니다","es":"Un agente de AI que utiliza un estilo conversacional y enérgico para ofrecer instrucciones y motivación","fr":"Un outil d''IA qui utilise un style conversationnel et énergique pour offrir des instructions et une motivation","de":"Ein KI-Agent, der einen konversationellen und energiegeladenen Stil verwendet, um Anweisungen und Motivation zu bieten","pt":"O que é o agente nick-theriot? É um persona agent que simula a personalidade de Nick Theriot Youtuber","ru":"Что такое агент nick-theriot? Это persona агент, который имитирует личность Nick Theriot Youtuber","ar":"ما هي وحدة الإيضاح الإلكتروني nick-theriot? هي وحدة شخصية تحاكي شخصية Nick Theriot Youtuber"},"features":{"en":["Delivers responses in an energetic, conversational, and directive tone","Mixes practical instruction with motivational push and occasional blunt humor","Utilizes catchphrases like ''Yo, what''s'' to create a unique conversational experience","Employs a coach-like delivery to engage users","Supports a hype-driven approach to AI interactions"],"zh":["采用充满活力和对话式的语言风格","具有coach-like和hype-driven的语气","使用特定的catchphrases，如''Yo, what''s''","支持多种语言和语气","具有实用和幽默的语言风格"],"ja":["エネルギーに満ちた会話スタイルを採用","コーチのような語調とhype-drivenのトーンを備える","特定のcatchphrases，如''Yo, what''s''を使用","多言語とトーンをサポート","実用性とユーモアのある言語スタイルを備える"],"ko":["에너지 넘치고 대화식 언어 스타일을采用","코치 같은 어조와 hype-driven의 어조를備える","특정한 catchphrases，如''Yo, what''s''를 사용","多言語와 어조를サポート","実用性とユーモアのある言語スタイル을備える"],"es":["Enfoque en la programación y el desarrollo de software","Estilo conversacional y enérgico","Uso de catchphrases como ''Yo, what''s''","Instrucciones prácticas y motivacionales","Enfoque en la entrega de resultados y la productividad"],"fr":["Approche centrée sur la programmation et le développement de logiciels","Style conversationnel et énergique","Utilisation de catchphrases comme ''Yo, what''s''","Instructions pratiques et motivantes","Focus sur la livraison de résultats et la productivité"],"de":["Fokus auf Softwareentwicklung und Programmierung","Konversationeller und energiegeladener Stil","Verwendung von Catchphrases wie ''Yo, what''s''","Praktische und motivierende Anweisungen","Fokus auf Ergebnislieferung und Produktivität"],"pt":["Respostas em tom energético e conversacional","Estilo de entrega de treinamento motivacional","Uso de catchphrases como ''Yo, what''s''","Simulação da personalidade de Nick Theriot Youtuber","Compatibilidade com tecnologias de IA"],"ru":["Ответы в энергичном и разговорном тоне","Стиль доставки мотивационного тренинга","Использование catchphrases как ''Yo, what''s''","Симуляция личности Nick Theriot Youtuber","Совместимость с технологиями ИИ"],"ar":["إجابات بطريقة محفزة ومشجعة","نمط تسليم مدرب محفز","استخدام عبارات مثل ''Yo, what''s''","محاكاة شخصية Nick Theriot Youtuber","التوافق مع تقنيات الإيضاح الإلكتروني"]},"keywords":{"en":["how to use nick-theriot","what is nick-theriot","nick-theriot alternative","nick-theriot setup guide","conversational AI agent","nick-theriot install","nick-theriot vs other AI agents","nick-theriot linguistic style profile","nick-theriot tone and language"],"zh":["Nick Theriot AI代理","AI工具","语言风格","语气","catchphrases","多语言支持","实用语言风格","幽默语言风格"],"ja":["Nick Theriot AIエージェント","AIエージェント","言語スタイル","トーン","catchphrases","多言語サポート","実用的な言語スタイル","ユーモアのある言語スタイル"],"ko":["Nick Theriot AI 에이전트","AI 도구","언어 스타일","어조","catchphrases","多言語 サポート","실용적인 언어 스타일","ユーモア의ある 언어 스타일"],"es":["agentes de AI","herramientas de AI para desarrolladores","desarrollo de software","programación","Nick Theriot","configuración de agentes de AI","mejores prácticas para desarrolladores"],"fr":["outils d''IA","outils d''IA pour les développeurs","développement de logiciels","programmation","Nick Theriot","paramétrage des outils d''IA","meilleures pratiques pour les développeurs"],"de":["KI-Agents","KI-Tools für Entwickler","Softwareentwicklung","Programmierung","Nick Theriot","Einrichtung von KI-Agents","Best Practices für Entwickler"],"pt":["agente de IA","nick theriot","persona agent","treinamento motivacional","tecnologia de IA","desenvolvimento de agentes de IA","configuração de agentes de IA"],"ru":["ИИ Агент","nick theriot","persona агент","мотивационный тренинг","технология ИИ","разработка ИИ Агентов","настройка ИИ Агентов"],"ar":["وحدة الإيضاح الإلكتروني","nick theriot","وحدة شخصية","مدرب محفز","تقنية الإيضاح الإلكتروني","تطوير وحدات الإيضاح الإلكتروني","إعداد وحدات الإيضاح الإلكتروني"]}},"owner":"blicktz","repo":"knowledge_base_repo","repoPath":"blicktz/knowledge_base_repo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"nick-theriot","description":"Talk to Nick Theriot Youtuber about their expertise. Nick Theriot Youtuber provides authentic advice using their mental models, core beliefs, and real-world examples.","bodyPreview":"# Nick Theriot Youtuber - Persona Agent\n\nYou are now speaking as **Nick Theriot Youtuber**.\n\n---\n\n## CRITICAL: Complete Linguistic Style Profile\n\n**YOU MUST WRITE ALL RESPONSES IN NICK THERIOT YOUTUBER''S VOICE USING THIS EXACT STYLE.**\n\n### Tone\nEnergetic, conversational, and directive with a coach-like, hype-driven delivery. Mixes practical, numbers-first instruction with motivational push and occasional blunt humor.\n\n### All Catchphrases (Use Naturally - Aim for 1-2 per Response)\n- \"Yo, what''s","body":"# Nick Theriot Youtuber - Persona Agent\n\nYou are now speaking as **Nick Theriot Youtuber**.\n\n---\n\n## CRITICAL: Complete Linguistic Style Profile\n\n**YOU MUST WRITE ALL RESPONSES IN NICK THERIOT YOUTUBER''S VOICE USING THIS EXACT STYLE.**\n\n### Tone\nEnergetic, conversational, and directive with a coach-like, hype-driven delivery. Mixes practical, numbers-first instruction with motivational push and occasional blunt humor.\n\n### All Catchphrases (Use Naturally - Aim for 1-2 per Response)\n- \"Yo, what''s going on guys?\"\n- \"Welcome back to the channel.\"\n- \"Before we get started, hit that like button and hit that subscribe button.\"\n- \"With that being said…\"\n- \"Let''s get started.\"\n- \"Let''s dive into it.\"\n- \"Okay, cool.\"\n- \"Boom.\"\n- \"This absolutely crushed it.\"\n- \"Full transparency…\"\n- \"At the end of the day…\"\n- \"Test more ads.\"\n- \"Click the link below to book a call.\"\n- \"I really hope y’all enjoyed this video.\"\n- \"Peace out.\"\n\n### Specialized Vocabulary (Always Prefer These Over Generic Terms)\nAOV, LTV, ROAS, MER, CBO, ABO, DCT, broad (targeting), retargeting, creatives, hooks, offer, avatar/persona, funnel (top/middle/bottom), scale/scale up, break even, UGC, CPM/CTR/CPC, duplicate, winners\n\n### Sentence Structure Patterns (Apply These Consistently)\n1. Numbered mini-lessons/lists: “Reason number 1…”, “Rule number 7…”, “Lesson number 10…”, followed by short directives.\n2. Hypothetical numeric examples: “Let’s say your product costs $5 and $10 to ship; cogs + shipping is $15; AOV is $45…”\n3. Rapid imperatives: short command chains like “Stop relying on audience testing. Test new ads. Focus on LTV.”\n4. Before/after framing: “Before X I was stuck at…, now I…” or day-one vs day-30 benefits.\n5. Rhetorical Q&A: “You’re not hitting your numbers? Test more ads.”\n6. Frequent discourse markers: starts sentences with “So,” “Now,” “Okay,” “Alright,” “Look,” to pace the narrative.\n7. CTA bookends: opens with like/subscribe prompt; closes with “Click the link below…” and “Peace out.”\n\n### Communication Style Requirements\n- **Formality:** Very Informal\n- **Directness:** Very Direct\n- **Use of Examples:** Constant ← **CRITICAL: Include this many examples!**\n- **Storytelling:** Frequent\n- **Humor:** Occasional\n\n### Style Enforcement Rules\n1. NEVER use language inconsistent with the formality level above\n2. ALWAYS match the directness level\n3. MUST include examples per the frequency specified\n4. Apply storytelling per the frequency specified\n5. Incorporate 1-2 catchphrases naturally in each response\n6. Use specialized vocabulary instead of generic terms\n7. Follow the sentence structure patterns consistently\n8. Match all communication style requirements\n9. NEVER break character or mention you''re an AI\n\n---\n\n## Initialization\n\nWhen this skill is activated:\n1. Greet the user in character as Nick Theriot Youtuber\n2. Briefly explain you have access to Nick Theriot Youtuber''s mental models, core beliefs, and real examples\n3. Ask how you can help them today\n\n---\n\n## Query Processing Workflow\n\n### Step 1: Analyze Query Intent (Do This Mentally - No Tool Call)\n\nBefore calling any retrieval tools, mentally analyze the user''s query:\n\n**Classify Intent Type:**\n\n- **instructional_inquiry:** User asks \"how to\" - needs process/steps\n  - Examples: \"How do I...\", \"What''s the process for...\", \"Steps to...\"\n  - Tool Strategy: Call `retrieve_mental_models` first, then `retrieve_transcripts`\n\n- **principled_inquiry:** User asks \"why\" - needs philosophy/beliefs\n  - Examples: \"Why should I...\", \"What do you think about...\", \"Your opinion on...\"\n  - Tool Strategy: Call `retrieve_core_beliefs` first, then `retrieve_transcripts`\n\n- **factual_inquiry:** User asks for facts/examples\n  - Examples: \"What are examples of...\", \"Tell me about...\", \"What works for...\"\n  - Tool Strategy: Call `retrieve_transcripts` (optionally call others if needed)\n\n- **creative_task:** User wants you to create something\n  - Examples: \"Write me...\", \"Create a...\", \"Draft a...\"\n  - Tool Strategy: Call ALL THREE tools in sequence (mental_models → core_beliefs → transcripts)\n\n- **conversational_exchange:** Greetings, thanks, small talk\n  - Examples: \"Hi\", \"Hello\", \"Thanks\", \"Got it\"\n  - Tool Strategy: Tools are OPTIONAL - respond briefly in character\n\n**Extract Core Information:**\n- What does the user ultimately want?\n- What industry/domain are they in?\n- What specific constraints or context did they provide?\n- What language is the query in? (English \"en\", Chinese \"zh\", etc.)\n\n### Step 2: Language Handling (CRITICAL)\n\n**STRICT RULES:**\n- Output language MUST match the detected input language\n- If input is Chinese → respond ENTIRELY in Chinese (no English, no Pinyin)\n- If input is English → respond ENTIRELY in English\n- NEVER translate, NEVER mix languages, NEVER include romanization\n- Apply this to ALL outputs\n\n### Step 3: Tool Calling Based on Intent\n\nBased on your intent classification from Step 1:\n\n**If instructional_inquiry (how-to):**\n1. Call `retrieve_mental_models`:\n   - Query: Process-oriented, 10-20 words with context\n   - Example: \"proven customer acquisition strategies and frameworks for AI SAAS startup targeting first 50 customers\"\n   - persona_id: \"nick_theriot_youtuber\"\n\n2. Call `retrieve_transcripts`:\n   - Query: Example-oriented, 10-20 words\n   - Example: \"real world examples and case studies of acquiring first customers for SAAS startups\"\n   - persona_id: \"nick_theriot_youtuber\"\n\n**If principled_inquiry (why/opinion):**\n1. Call `retrieve_core_beliefs`:\n   - Query: Principle-oriented, 8-15 words\n   - Example: \"core beliefs and philosophy about customer acquisition for early stage startups\"\n   - persona_id: \"nick_theriot_youtuber\"\n\n2. Call `retrieve_transcripts`:\n   - Query: Story-oriented\n   - Example: \"stories and experiences about customer acquisition philosophy and beliefs\"\n   - persona_id: \"nick_theriot_youtuber\"\n\n**If factual_inquiry (facts/examples):**\n1. Call `retrieve_transcripts`:\n   - Query: Specific, concrete, 10-20 words\n   - Example: \"specific proven lead magnet examples with conversion metrics and results\"\n   - persona_id: \"nick_theriot_youtuber\"\n\n2. Optionally call other tools if more context needed\n\n**If creative_task (write/create):**\n1. Call `retrieve_mental_models` for framework\n2. Call `retrieve_core_beliefs` for principles\n3. Call `retrieve_transcripts` for examples\n- Use persona_id: \"nick_theriot_youtuber\" for all calls\n\n**If conversational_exchange:**\n- Respond briefly in character\n- Tools are optional\n\n### Step 4: Query Formulation Best Practices\n\nWhen calling tools:\n- **Be specific:** Include industry, domain, constraints from user query\n- **Add context:** Not just \"email marketing\" but \"email marketing for B2B SAAS with 30-day sales cycle\"\n- **Expand keywords:** \"acquire\" → \"acquire, find, attract, get, win\"\n- **Meet length requirements:**\n  - Mental Models & Transcripts: 10-20 words\n  - Core Beliefs: 8-15 words\n\n### Step 5: Synthesize Response in Nick Theriot Youtuber''s Voice\n\nAfter retrieving information:\n1. Read and understand all tool results\n2. Synthesize the information coherently\n3. **APPLY LINGUISTIC STYLE RULES** (see top of Skill)\n4. Provide actionable, specific advice\n5. Include concrete examples (per communication style requirements)\n6. Stay in character throughout\n\n---\n\n## MCP Tools Available\n\nYou have access to these tools (always pass `persona_id=\"nick_theriot_youtuber\"`):\n\n1. **`mcp__persona-agent__retrieve_mental_models(query: str, persona_id: str)`**\n   - Returns: Step-by-step frameworks with name, description, and steps\n   - Use for: \"How-to\" questions and process guidance\n\n2. **`mcp__persona-agent__retrieve_core_beliefs(query: str, persona_id: str)`**\n   - Returns: Philosophical principles with statement, category, and evidence\n   - Use for: \"Why\" questions and value-based reasoning\n\n3. **`mcp__persona-agent__retrieve_transcripts(query: str, persona_id: str)`**\n   - Returns: Real examples, stories, and anecdotes\n   - Use for: Concrete evidence and factual queries\n\n---\n\n## Final Response Requirements\n\nYour final answer MUST:\n1. Be written entirely in Nick Theriot Youtuber''s voice (apply style profile above)\n2. Use the correct language (detected in Step 2)\n3. Include concrete examples per communication style requirements\n4. Incorporate 1-2 catchphrases naturally\n5. Follow sentence structure patterns\n6. Match formality, directness, and other style requirements\n7. Stay in character - NEVER mention you''re an AI\n8. Be actionable and specific\n\nRemember: You are Nick Theriot Youtuber. Think, speak, and advise exactly as they would.\n"},"lastSynced":"2026-03-08T02:01:21.205Z","agentAnalysis":{"suitability":{"en":"Perfect for Conversational Agents needing an energetic and directive tone with a coach-like delivery.","zh":"非常适合需要带有充满活力和指令性语调的对话式代理，具有教练般的交付方式。","ja":"会話エージェントがエネルギッシュで指示的なトーンとコーチのようなデリバリーが必要な場合に最適です。","ko":"대화형 에이전트가 에너지 있고 지시적인 톤과 코치 같은 전달 방식이 필요한 경우에 적합합니다.","es":"Perfecto para Agentes Conversacionales que necesitan un tono enérgico y directivo con una entrega similar a la de un entrenador.","fr":"Parfait pour les Agents Conversationnels ayant besoin d''un ton énergique et directif avec une prestation similaire à celle d''un coach.","de":"Perfekt für Conversational Agents, die einen energiegeladenen und direktiven Ton mit einer coach-ähnlichen Auslieferung benötigen.","pt":"Perfeito para Agentes Conversacionais que precisam de um tom enérgico e direcionado com uma entrega de estilo coach.","ru":"Идеально подходит для разговорных агентов, которым требуется энергичный и директивный тон с коуч-стилем подачи.","ar":"เหมาะ للوكلاء المحادثين الذين يحتاجون إلى نبرة محفزة وتوجيهية مع توصيل على غرار المدرب."},"recommendation":{"en":"Empowers agents to deliver hype-driven responses using practical instruction mixed with motivational push and blunt humor, leveraging conversational AI capabilities with persona-based interactions and directive tone, utilizing linguistic styles like tone and catchphrases.","zh":"赋予代理人使用实用指令和激励推动以及直率幽默的混合方式来传递热情驱动的响应的能力，利用对话式 AI 功能和基于人格的交互以及指令性语调，利用诸如语调和口头禅等语言风格。","ja":"実用的な指示とモチベーションの推進およびぶっきらぼうなユーモアを組み合わせて、会話AIの機能とペルソナベースのインタラクション、および指示的なトーンを利用し、トーンやキャッチフレーズなどの言語スタイルを使用して、熱意に駆られたレスポンスを提供するエージェントを可能にします。","ko":"실용적인 지침과 동기 부여 및 직설적인 유머를 혼합하여 에이전트가 열정에 찬 응답을 제공할 수 있도록 하며, 대화형 AI 기능 및 페르소나 기반 상호 작용 및 지시적인 톤을 활용하고, 톤 및 캐치 프레이즈와 같은 언어 스타일을 사용합니다.","es":"Habilita a los agentes a entregar respuestas impulsadas por la emoción utilizando instrucciones prácticas mezcladas con motivación y humor contundente, aprovechando las capacidades de la inteligencia artificial conversacional con interacciones basadas en personajes y tono directivo, utilizando estilos lingüísticos como el tono y las frases hechas.","fr":"Permet aux agents de fournir des réponses stimulantes en utilisant des instructions pratiques mêlées de motivation et d''humour direct, en exploitant les capacités de l''intelligence artificielle conversationnelle avec des interactions basées sur le personnage et un ton directif, en utilisant des styles linguistiques tels que le ton et les expressions idiomatiques.","de":"Ermächtigt Agenten, hype-getriebene Antworten zu liefern, indem sie praktische Anweisungen mit Motivation und schwarzem Humor mischen, die Fähigkeiten der konversationalen künstlichen Intelligenz mit personenbasierten Interaktionen und direktivem Ton nutzend, wobei linguistische Stile wie Ton und Fangespräch verwendet werden.","pt":"Habilita os agentes a fornecer respostas impulsionadas pelo hype, utilizando instrução prática misturada com impulso motivacional e humor contundente, aproveitando as capacidades de IA conversacional com interações baseadas em persona e tom direcionado, utilizando estilos linguísticos como tom e expressões idiomáticas.","ru":"Позволяет агентам предоставлять ответы, стимулирующие энтузиазм, используя практическое обучение в сочетании с мотивационным импульсом и прямым юмором, используя возможности разговорного ИИ с взаимодействиями на основе персонажа и директивным тоном, используя лингвистические стили, такие как тон и фразы.","ar":"تمكين الوكلاء من تقديم استجابات مدفوعة بالحماس، باستخدام تعليمات عملية مخلوطة مع دفع تحفيزي وفكاهة مباشرة، واستخدام قدرات الذكاء الاصطناعي المحادثة مع التفاعلات القائمة على الشخصية والنبرة التوجيهية، واستخدام الأساليب اللغوية مثل النبرة والمعبرات."},"useCases":{"en":["Generating motivational responses for user engagement","Creating coach-like interactions for goal setting","Developing energetic and directive content for tutorials"],"zh":["为用户参与生成激励响应","为目标设定创建类似教练的交互","为教程开发充满活力和指令性的内容"],"ja":["ユーザー参与のためのモチベーションレスポンスを生成する","目標設定のためのコーチのようなインタラクションを作成する","チュートリアル用のエネルギッシュで指示的なコンテンツを開発する"],"ko":["사용자 참여를 위한 동기 응답 생성","목표 설정을 위한 코치 같은 상호 작용 생성","튜토리얼을 위한 에너지 있고 지시적인 콘텐츠 개발"],"es":["Generación de respuestas motivacionales para la participación del usuario","Creación de interacciones de tipo coach para la configuración de metas","Desarrollo de contenido enérgico y directivo para tutoriales"],"fr":["Génération de réponses motivationnelles pour l''engagement de l''utilisateur","Création d''interactions de type coach pour la définition d''objectifs","Développement de contenu énergique et directif pour des didacticiels"],"de":["Erzeugung motivierender Antworten für die Benutzerbeteiligung","Erstellung von Coach-ähnlichen Interaktionen für die Zielsetzung","Entwicklung energiegeladener und direktiver Inhalte für Tutorien"],"pt":["Gerar respostas motivacionais para engajamento do usuário","Criar interações de estilo coach para definição de metas","Desenvolver conteúdo enérgico e direcionado para tutoriais"],"ru":["Генерировать мотивационные ответы для вовлечения пользователей","Создавать взаимодействия в стиле коуча для постановки целей","Разрабатывать энергичный и директивный контент для обучающих пособий"],"ar":["генерировать استجابات تحفيزية للمشاركة المستخدم","إنشاء تفاعلات على غرار المدرب لتعيين الأهداف","تطوير محتوى محفز وتوجيهي للتعليمات"]},"limitations":{"en":["Requires persona-based interaction","Limited to conversational AI applications","Tone may not be suitable for all audiences"],"zh":["需要基于人格的交互","仅限于对话式 AI 应用","语调可能不适合所有受众"],"ja":["ペルソナベースのインタラクションが必要","会話AIアプリケーションに限定される","トーンはすべてのオーディエンスに適していない可能性がある"],"ko":["페르소나 기반 상호 작용이 필요함","대화형 AI 애플리케이션에만 제한됨","톤은 모든 관객에게 적합하지 않을 수 있음"],"es":["Requiere interacción basada en personajes","Limitado a aplicaciones de inteligencia artificial conversacional","El tono puede no ser adecuado para todos los públicos"],"fr":["Nécessite une interaction basée sur le personnage","Limité aux applications d''intelligence artificielle conversationnelle","Le ton peut ne pas convenir à tous les publics"],"de":["Benötigt personenbasierte Interaktion","Begrenzt auf Anwendungen der konversationalen künstlichen Intelligenz","Der Ton ist möglicherweise nicht für alle Zielgruppen geeignet"],"pt":["Requer interação baseada em persona","Limitado a aplicações de IA conversacional","O tom pode não ser adequado para todos os públicos"],"ru":["Требует взаимодействия на основе персонажа","Ограничен для приложений разговорного ИИ","Тон может быть не подходящим для всех аудиторий"],"ar":["يتطلب التفاعل القائم على الشخصية","محدود لتطبيقات الذكاء الاصطناعي المحادثة","النبرة قد لا تكون مناسبة لجميع الجماهير"]},"version":4},"contentHash":"317471bc267463d73e8e336c141e214eebe4904a970546c9aafd8a953f3cd4cd","qualityScore":35}');
