INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blicktz/knowledge_base_repo/nick-theriot', 'nick-theriot', 'blicktz', 'knowledge_base_repo', 'community', 'nick-theriot blicktz knowledge_base_repo community The nick-theriot skill enables developers to interact with a conversational AI agent that uses an energetic and directive tone. It benefits developers looking for a coach-like delivery in their AI interactions. Nick Theriot AI代理采用充满活力和对话式的语言风格，具有coach-like和hype-driven的语气 Nick Theriot AIエージェントは、エネルギーに満ちた会話スタイルとコーチのような語調を備えています Nick Theriot AI 에이전트는 에너지 넘치고 대화식 언어 스타일과 코치 같은 어조를 가지고 있습니다 Nick Theriot es un agente de AI que ofrece un enfoque práctico y motivacional para el desarrollo de software Nick Theriot est un outil d''IA qui propose une approche pratique et motivante pour la programmation Nick Theriot ist ein KI-Agent, der einen praktischen und motivierenden Ansatz für die Softwareentwicklung bietet O agente nick-theriot é um persona agent que fornece respostas em um tom energético e conversacional, com um estilo de entrega de treinamento motivacional Агент nick-theriot является persona агентом, который предоставляет ответы в энергичном и разговорном тоне, с мотивационным стилем доставки وحدة الإيضاح الإلكتروني nick-theriot هي وحدة شخصية توفر إجابات بطريقة محفزة ومشجعة، مع نمط تسليم مدرب محفز how to use nick-theriot what is nick-theriot nick-theriot alternative nick-theriot setup guide conversational AI agent nick-theriot install nick-theriot vs other AI agents nick-theriot linguistic style profile nick-theriot tone and language Nick Theriot AI代理 AI工具 语言风格 语气 catchphrases 多语言支持 实用语言风格 幽默语言风格 Delivers responses in an energetic, conversational, and directive tone Mixes practical instruction with motivational push and occasional blunt humor Utilizes catchphrases like ''Yo, what''s'' to create a unique conversational experience Employs a coach-like delivery to engage users Supports a hype-driven approach to AI interactions nick-theriot is a conversational AI agent skill that utilizes a unique linguistic style profile to deliver energetic and motivational responses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Prorise-cool/Claude-Code-Multi-Agent/internal-comms', 'community', 'Prorise-cool', 'Claude-Code-Multi-Agent', 'Prorise-cool/Claude-Code-Multi-Agent', 'internal-comms', 0, 0, 35, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:38.902Z', 'ed67265afb165cd163bd18e5eb27cf7e60c4ed42ceea2a8fc65c3e6c8a90ff58', '{"id":"Prorise-cool/Claude-Code-Multi-Agent/internal-comms","name":"internal-comms","description":{"en":"The internal-comms skill automates internal communications, enabling teams to efficiently generate updates, newsletters, and reports. This skill benefits teams and organizations seeking to simplify their internal communication processes.","zh":"内部通信AI助手是基于Claude Code构建的智能代理协调工作空间，实现从需求到交付的全流程自动化开发","ja":"内部コミュニケーションのAIエージェントは、Claude Codeを基盤とするスマートエージェントによるワークスペースの調整により、要件から納品までの全プロセスを自動化します","ko":"내부 커뮤니케이션을 위한 AI 에이전트는 Claude Code를 기반으로 하는 스마트 에이전트가 워크스페이스를 조정하여 요구사항에서부터 전달까지의 전체 프로세스를 자동화합니다","es":"Internal-comms es una herramienta de IA que automatiza la comunicación interna, desde actualizaciones de progreso hasta informes de estado","fr":"Internal-comms est un outil d''IA qui automatisé la communication interne, des mises à jour de progression aux rapports de statut","de":"Internal-comms ist ein KI-Tool, das die interne Kommunikation automatisiert, von Fortschrittsberichten bis hin zu Statusberichten","pt":"O Claude-Code-Multi-Agent é um ecossistema de assistentes de programação AI que automatiza comunicações internas, desde atualizações de progresso até relatórios de status","ru":"ИИ Агенты Claude-Code-Multi-Agent - это экосистема помощников программирования AI, которая автоматизирует внутренние коммуникации, от обновлений прогресса до отчетов о статусе","ar":"وكيل Claude-Code-Multi-Agent هو نظام بيئي لمرافقة البرمجة الذكية التي تautomatiza الاتصالات الداخلية، من تحديثات التقدم إلى تقارير الحالة"},"seo":{"title":{"en":"internal-comms: Automated Internal Communications Setup G...","zh":"内部通信AI助手设置指南","ja":"AIエージェントを使用した内部コミュニケーションのベストプラクティス","ko":"내부 커뮤니케이션을 위한 AI 에이전트 구축 가이드","es":"Guía de configuración de internal-comms para agentes de IA","fr":"Guide de mise en place de internal-comms pour les agents ...","de":"Einrichtungsleitfaden für internal-comms mit KI-Agents","pt":"Guia de Configuração de Comunicações Internas com Claude-...","ru":"Настройка внутренних коммуникаций с помощью ИИ Агентов Cl...","ar":"دليل إعداد الاتصالات الداخلية مع وكيل Claude-Code-Multi-A..."},"description":{"en":"Discover how to streamline internal communications with the internal-comms skill. Learn how to automate updates, newsletters, and reports with ease. Get star...","zh":"内部通信AI助手可以帮助您自动化从需求到交付的全流程开发，提高团队协作效率","ja":"AIエージェントを使用すると、内部コミュニケーションの自動化が可能になり、チームのコラボレーションを効率化できます","ko":"내부 커뮤니케이션을 위한 AI 에이전트를 사용하면需求에서부터 전달까지의 전체 개발 프로세스를 자동화하여 팀 협력을 효율화할 수 있습니다","es":"Automatice su comunicación interna con internal-comms, una herramienta de IA para generar informes y noticias de la empresa","fr":"Automatisez vos communications internes avec internal-comms, un outil d''IA pour générer des rapports et des actualités de l''entreprise","de":"Automatisieren Sie Ihre interne Kommunikation mit internal-comms, einem KI-Tool für die Erstellung von Berichten und Unternehmensnachrichten","pt":"Aprenda a configurar comunicações internas automatizadas com o Claude-Code-Multi-Agent, incluindo 3P updates e relatórios de status","ru":"Узнайте, как настроить автоматизированные внутренние коммуникации с помощью ИИ Агентов Claude-Code-Multi-Agent, включая обновления 3P и отчеты о статусе","ar":"تعرف على كيفية إعداد اتصالات داخلية آلية مع وكيل Claude-Code-Multi-Agent، بما في ذلك تحديثات 3P وتقارير الحالة"},"definition":{"en":"internal-comms is a Claude-Code-Multi-Agent driven AI programming assistant ecosystem that automates internal communications, from updates to reports, using guided templates and files.","zh":"内部通信AI助手是一种基于Claude Code的智能代理，用于自动化内部通信和协作","ja":"内部コミュニケーションのAIエージェントは、Claude Codeを基盤とする内部コミュニケーションとコラボレーションの自動化ツールです","ko":"내부 커뮤니케이션을 위한 AI 에이전트는 Claude Code를 기반으로 하는 내부 커뮤니케이션 및 협력을 자동화하는 도구입니다","es":"Internal-comms es un agente de IA que ayuda a automatizar la comunicación interna de una empresa","fr":"Internal-comms est un agent d''IA qui aide à automatiser la communication interne d''une entreprise","de":"Internal-comms ist ein KI-Agent, der dabei hilft, die interne Kommunikation eines Unternehmens zu automatisieren","pt":"O que é um sistema de comunicações internas automatizadas com Claude-Code-Multi-Agent?","ru":"Что такое система автоматизированных внутренних коммуникаций с помощью ИИ Агентов Claude-Code-Multi-Agent?","ar":"ما هو نظام الاتصالات الداخلية الآلية مع وكيل Claude-Code-Multi-Agent?"},"features":{"en":["Generates 3P updates using the examples/3p-updates.md template","Creates company newsletters based on the examples/company-newsletter.md guide","Supports FAQ answer generation using the examples/faq-answers.md file","Loads relevant guideline files from the examples/ directory","Follows specific instructions for format, tone, and content collection"],"zh":["支持3P更新（Progress、Plans、Problems）","提供公司通讯和常见问题解答功能","实现状态报告和领导更新","支持项目更新和事件报告","基于Claude Code构建的智能代理协调工作空间","实现从需求到交付的全流程自动化开发"],"ja":["3P更新（Progress、Plans、Problems）をサポート","会社のニュースレターとよくある質問の回答機能を提供","ステータス報告とリーダーの更新を実現","プロジェクトの更新とイベント報告をサポート","Claude Codeを基盤とするスマートエージェントによるワークスペースの調整","要件から納品までの全プロセスを自動化"],"ko":["3P 업데이트（Progress、Plans、Problems）를 지원","회사 뉴스레터와 자주하는 질문의 답변 기능을 제공","상태 보고와 리더의 업데이트를 구현","프로젝트 업데이트와 이벤트 보고를 지원","Claude Code를 기반으로 하는 스마트 에이전트가 워크스페이스를 조정","요구사항에서부터 전달까지의 전체 프로세스를 자동화"],"es":["Generación automática de informes de progreso","Creación de newsletters de la empresa","Respuestas automáticas a preguntas frecuentes","Informes de estado personalizados","Actualizaciones de liderazgo y proyectos","Informes de eventos y noticias de la empresa"],"fr":["Génération automatique de rapports de progression","Création de newsletters de l''entreprise","Réponses automatiques aux questions fréquentes","Rapports de statut personnalisés","Mises à jour de leadership et de projets","Rapports d''événements et actualités de l''entreprise"],"de":["Automatische Erstellung von Fortschrittsberichten","Erstellung von Unternehmensnewslettern","Automatische Antworten auf häufig gestellte Fragen","Individuelle Statusberichte","Führungskräfte- und Projektnachrichten","Ereignis- und Unternehmensnachrichten"],"pt":["Automatização de comunicações internas com 3P updates","Geração de relatórios de status personalizados","Integração com ecossistemas de desenvolvimento de software","Suporte a múltiplos formatos de comunicação","Capacidade de personalizar templates de comunicação"],"ru":["Автоматизация внутренних коммуникаций с обновлениями 3P","Генерация индивидуальных отчетов о статусе","Интеграция с экосистемами разработки программного обеспечения","Поддержка нескольких форматов коммуникации","Возможность настройки шаблонов коммуникации"],"ar":["التحكم الآلي في الاتصالات الداخلية مع تحديثات 3P","إنشاء تقارير حالة مخصصة","التكامل مع نظم تطوير البرمجيات","دعم صيغ متعددة للاتصال","القدرة على تخصيص قوالب الاتصال"]},"keywords":{"en":["how to use internal-comms","internal-comms setup guide","automated internal communications","internal-comms alternative","internal-comms vs competitors","internal-comms install","what is internal-comms","internal-comms tutorial","internal-comms best practices"],"zh":["内部通信AI助手","Claude Code","智能代理","内部通信自动化","团队协作","项目管理","公司通讯","常见问题解答"],"ja":["AIエージェント","内部コミュニケーション","Claude Code","スマートエージェント","内部コミュニケーションの自動化","チームコラボレーション","プロジェクトマネジメント","会社のニュースレター","よくある質問"],"ko":["AI 에이전트","내부 커뮤니케이션","Claude Code","스마트 에이전트","내부 커뮤니케이션 자동화","팀 협력","프로젝트 관리","회사 뉴스레터","자주하는 질문"],"es":["agentes de IA para comunicación interna","herramientas de automatización de comunicación","generación de informes de progreso","creación de newsletters de la empresa","respuestas automáticas a preguntas frecuentes","informes de estado personalizados","internal-comms para empresas"],"fr":["agents d''IA pour la communication interne","outils d''automatisation de la communication","génération de rapports de progression","création de newsletters de l''entreprise","réponses automatiques aux questions fréquentes","rapports de statut personnalisés","internal-comms pour les entreprises"],"de":["KI-Agents für interne Kommunikation","Werkzeuge für die Automatisierung der Kommunikation","Erstellung von Fortschrittsberichten","Erstellung von Unternehmensnewslettern","automatische Antworten auf häufig gestellte Fragen","individuelle Statusberichte","internal-comms für Unternehmen"],"pt":["comunicações internas automatizadas","Claude-Code-Multi-Agent","3P updates","relatórios de status","ecossistemas de desenvolvimento de software","automatização de comunicações","ferramentas de AI para desenvolvedores"],"ru":["автоматизированные внутренние коммуникации","ИИ Агенты Claude-Code-Multi-Agent","обновления 3P","отчеты о статусе","экосистемы разработки программного обеспечения","автоматизация коммуникации","инструменты ИИ для разработчиков"],"ar":["الاتصالات الداخلية الآلية","وكيل Claude-Code-Multi-Agent","تحديثات 3P","تقارير الحالة","نظم تطوير البرمجيات","تحكم آلي في الاتصالات","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"Prorise-cool","repo":"Claude-Code-Multi-Agent","repoPath":"Prorise-cool/Claude-Code-Multi-Agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"internal-comms","description":"一套资源，帮助我使用公司喜欢的格式编写各种内部通信。每当要求编写某种内部通信（状态报告、领导更新、3P 更新、公司通讯、常见问题、事件报告、项目更新等）时，Claude 应使用此技能。","bodyPreview":"## When to use this skill\n要编写内部通信，请将此技能用于：\n- 3P 更新（Progress、Plans、Problems）\n- 公司通讯\n- 常见问题解答\n- 状态报告\n- 领导更新\n- 项目更新\n- 事件报告\n\n## How to use this skill\n\n要编写任何内部通信：\n\n1. **识别通信类型** 从请求中\n2. **加载相应的指南文件** 从 `examples/` 目录：\n    - `examples/3p-updates.md` - 用于 Progress/Plans/Problems 团队更新\n    - `examples/company-newsletter.md` - 用于全公司通讯\n    - `examples/faq-answers.md` - 用于回答常见问题\n    - `examples/general-comms.md` - 用于其他不明确匹配上述任何一项的内容\n3. **遵循该文件中的具体说明** 关于格式、语气和内容收集\n\n如果通信类型与任何现有指南不匹配，请询问澄清或更多关于所需格式的上下文。\n\n## K","body":"## When to use this skill\n要编写内部通信，请将此技能用于：\n- 3P 更新（Progress、Plans、Problems）\n- 公司通讯\n- 常见问题解答\n- 状态报告\n- 领导更新\n- 项目更新\n- 事件报告\n\n## How to use this skill\n\n要编写任何内部通信：\n\n1. **识别通信类型** 从请求中\n2. **加载相应的指南文件** 从 `examples/` 目录：\n    - `examples/3p-updates.md` - 用于 Progress/Plans/Problems 团队更新\n    - `examples/company-newsletter.md` - 用于全公司通讯\n    - `examples/faq-answers.md` - 用于回答常见问题\n    - `examples/general-comms.md` - 用于其他不明确匹配上述任何一项的内容\n3. **遵循该文件中的具体说明** 关于格式、语气和内容收集\n\n如果通信类型与任何现有指南不匹配，请询问澄清或更多关于所需格式的上下文。\n\n## Keywords\n3P updates, company newsletter, company comms, weekly update, faqs, common questions, updates, internal comms\n"},"lastSynced":"2026-03-08T02:03:38.902Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing automated internal communication generation for team updates, newsletters, and reports.","zh":"适用于像 Cursor、Windsurf 和 Claude Code 这样的 AI Agent，需要为团队更新、新闻稿和报告生成自动内部通信。","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。チームの更新、ニュースレター、レポートの自動内部コミュニケーション生成が必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 팀 업데이트, 뉴스레터, 보고서를 위한 자동 내부 커뮤니케이션 생성이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan generación automática de comunicación interna para actualizaciones de equipo, boletines y informes.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin de génération automatisée de communication interne pour les mises à jour d''équipe, les newsletters et les rapports.","de":"Ideal für KI-Agenten wie Cursor, Windsurf und Claude Code, die eine automatisierte interne Kommunikationserstellung für Team-Updates, Newsletter und Berichte benötigen.","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que precisam de geração automática de comunicação interna para atualizações de equipe, boletins e relatórios.","ru":"Идеально для ИИ-агентов, таких как Cursor, Windsurf и Claude Code, которые нуждаются в автоматизированном внутреннем общении для обновлений команды, новостей и отчетов.","ar":"مثالي لعمليات الوكيل الذكي مثل Cursor و Windsurf و Claude Code التي تحتاج إلى توليد تلقائي للاتصالات الداخلية لتحديثات الفريق والمنشورات والتقارير."},"recommendation":{"en":"Empowers agents to generate comprehensive internal communications, including 3P updates, company newsletters, and FAQs, using markdown files like `3p-updates.md` and `company-newsletter.md` for formatting and content guidance.","zh":"赋予代理生成综合内部通信的能力，包括 3P 更新、公司新闻稿和常见问题解答，使用 markdown 文件（如 `3p-updates.md` 和 `company-newsletter.md`）来指导格式和内容。","ja":"エージェントに、3P 更新、会社のニュースレター、FAQ などを含む包括的な内部コミュニケーションを生成する能力を提供します。フォーマットとコンテンツのガイダンスとして、`3p-updates.md` および `company-newsletter.md` などの markdown ファイルを使用します。","ko":"에이전트가 3P 업데이트, 회사 뉴스레터, FAQ 등을 포함한 포괄적인 내부 커뮤니케이션을 생성할 수 있는 능력을 부여합니다. 형식 및 내용에 대한 안내로 `3p-updates.md` 및 `company-newsletter.md`와 같은 마크다운 파일을 사용합니다.","es":"Habilita a los agentes a generar comunicaciones internas completas, incluyendo actualizaciones de 3P, newsletters de la empresa y FAQs, utilizando archivos markdown como `3p-updates.md` y `company-newsletter.md` para la guía de formato y contenido.","fr":"Permet aux agents de générer des communications internes complètes, y compris les mises à jour 3P, les newsletters de l''entreprise et les FAQs, en utilisant des fichiers markdown comme `3p-updates.md` et `company-newsletter.md` pour la guidance de format et de contenu.","de":"Ermächtigt die Agenten, umfassende interne Kommunikationen zu generieren, einschließlich 3P-Updates, Firmen-Newslettern und FAQs, unter Verwendung von Markdown-Dateien wie `3p-updates.md` und `company-newsletter.md` für die Format- und Inhaltsanleitung.","pt":"Habilita agentes a gerar comunicações internas abrangentes, incluindo atualizações 3P, boletins da empresa e Perguntas frequentes, usando arquivos markdown como `3p-updates.md` e `company-newsletter.md` para orientação de formatação e conteúdo.","ru":"Наделяет агентов возможностью генерировать всесторонние внутренние коммуникации, включая обновления 3P, новости компании и ЧаВо, используя файлы markdown, такие как `3p-updates.md` и `company-newsletter.md`, для руководства по форматированию и содержанию.","ar":"تمكّن الوكلاء من توليد اتصالات داخلية شاملة، بما في ذلك تحديثات 3P والمنشورات الداخلية للشركة والأسئلة الشائعة، باستخدام ملفات markdown مثل `3p-updates.md` و `company-newsletter.md` لتوجيه التنسيق والمحتوى."},"useCases":{"en":["Automating team progress updates","Generating company-wide newsletters","Creating FAQs for common queries"],"zh":["自动化团队进度更新","生成公司范围的新闻稿","为常见查询创建 FAQ"],"ja":["チームの進捗状況の更新を自動化する","会社全体のニュースレターを生成する","一般的な質問に対する FAQ を作成する"],"ko":["팀 진행 상황 업데이트를 자동화하는 것","전사 뉴스레터를 생성하는 것","일반적인 쿼리에 대한 FAQ를 생성하는 것"],"es":["Automatización de actualizaciones de progreso del equipo","Generación de newsletters a nivel de empresa","Creación de FAQs para consultas comunes"],"fr":["Automatisation des mises à jour de progression d''équipe","Génération de newsletters à l''échelle de l''entreprise","Création de FAQs pour des requêtes courantes"],"de":["Automatisierung von Team-Fortschrittsupdates","Generierung von firmenweiten Newslettern","Erstellung von FAQs für häufige Anfragen"],"pt":["Automatizar atualizações de progresso da equipe","Gerar boletins da empresa em todo o mundo","Criar Perguntas frequentes para consultas comuns"],"ru":["Автоматизировать обновления прогресса команды","Генерировать новости компании во всем мире","Создавать ЧаВо для обычных запросов"],"ar":["أتمتة تحديثات تقدم الفريق","توليد المنشورات الداخلية للشركة في جميع أنحاء العالم","إنشاء الأسئلة الشائعة للاستفسارات الشائعة"]},"limitations":{"en":["Requires specific communication type identification","Limited to predefined guide files in the `examples/` directory"],"zh":["需要特定的通信类型识别","仅限于 `examples/` 目录中的预定义指南文件"],"ja":["特定のコミュニケーションタイプの識別が必要","`examples/` ディレクトリ内の事前定義されたガイドファイルのみに制限される"],"ko":["특정 커뮤니케이션 유형 식별이 필요","`examples/` 디렉토리 내의 사전 정의된 가이드 파일만으로 제한"],"es":["Requiere identificación de tipo de comunicación específica","Limitado a archivos de guía predefinidos en el directorio `examples/`"],"fr":["Nécessite l''identification d''un type de communication spécifique","Limité aux fichiers de guide prédéfinis dans le répertoire `examples/`"],"de":["Erfordert die Identifizierung eines bestimmten Kommunikationstyps","Begrenzt auf vordefinierte Leitdateien im Verzeichnis `examples/`"],"pt":["Exige identificação específica do tipo de comunicação","Limitado a arquivos de guia pré-definidos no diretório `examples/`"],"ru":["Требует конкретной идентификации типа коммуникации","Ограничен предопределенными файлами-руководствами в директории `examples/`"],"ar":["يتطلب تحديد نوع الاتصال بشكل محدد","محدود بالملفات التوجيهية المحددة مسبقًا في الدليل `examples/`"]},"version":4},"contentHash":"ed67265afb165cd163bd18e5eb27cf7e60c4ed42ceea2a8fc65c3e6c8a90ff58","qualityScore":35}');
