INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Prorise-cool/Claude-Code-Multi-Agent/internal-comms', 'internal-comms', 'Prorise-cool', 'Claude-Code-Multi-Agent', 'community', 'internal-comms Prorise-cool Claude-Code-Multi-Agent community The internal-comms skill automates internal communications, enabling teams to efficiently generate updates, newsletters, and reports. This skill benefits teams and organizations seeking to simplify their internal communication processes. 内部通信AI助手是基于Claude Code构建的智能代理协调工作空间，实现从需求到交付的全流程自动化开发 内部コミュニケーションのAIエージェントは、Claude Codeを基盤とするスマートエージェントによるワークスペースの調整により、要件から納品までの全プロセスを自動化します 내부 커뮤니케이션을 위한 AI 에이전트는 Claude Code를 기반으로 하는 스마트 에이전트가 워크스페이스를 조정하여 요구사항에서부터 전달까지의 전체 프로세스를 자동화합니다 Internal-comms es una herramienta de IA que automatiza la comunicación interna, desde actualizaciones de progreso hasta informes de estado Internal-comms est un outil d''IA qui automatisé la communication interne, des mises à jour de progression aux rapports de statut Internal-comms ist ein KI-Tool, das die interne Kommunikation automatisiert, von Fortschrittsberichten bis hin zu Statusberichten O Claude-Code-Multi-Agent é um ecossistema de assistentes de programação AI que automatiza comunicações internas, desde atualizações de progresso até relatórios de status ИИ Агенты Claude-Code-Multi-Agent - это экосистема помощников программирования AI, которая автоматизирует внутренние коммуникации, от обновлений прогресса до отчетов о статусе وكيل Claude-Code-Multi-Agent هو نظام بيئي لمرافقة البرمجة الذكية التي تautomatiza الاتصالات الداخلية، من تحديثات التقدم إلى تقارير الحالة how to use internal-comms internal-comms setup guide automated internal communications internal-comms alternative internal-comms vs competitors internal-comms install what is internal-comms internal-comms tutorial internal-comms best practices 内部通信AI助手 Claude Code 智能代理 内部通信自动化 团队协作 项目管理 公司通讯 常见问题解答 Generates 3P updates using the examples/3p-updates.md template Creates company newsletters based on the examples/company-newsletter.md guide Supports FAQ answer generation using the examples/faq-answers.md file Loads relevant guideline files from the examples/ directory Follows specific instructions for format, tone, and content collection internal-comms is a Claude-Code-Multi-Agent driven AI programming assistant ecosystem that automates internal communications, from updates to reports, using guided templates and files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dfujiwara/kindle-notes-reminder/psql', 'community', 'dfujiwara', 'kindle-notes-reminder', 'dfujiwara/kindle-notes-reminder', 'psql', 0, 0, 35, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:07.737Z', '1a297a3a0b3c6041cca2dd254ef9a154995f31a71cf32061b847e48cec345c23', '{"id":"dfujiwara/kindle-notes-reminder/psql","name":"psql","description":{"en":"The psql skill assists users in querying their local Kindle notes database using PostgreSQL. It provides a secure way to execute psql commands via the Bash tool.","zh":"psql 是一个 PostgreSQL 查询助手，帮助用户查询本地 Kindle 笔记数据库。使用 Bash 工具执行 psql 命令，实现安全高效的查询","ja":"psql は PostgreSQL クエリアシスタントであり、ユーザーがローカルの Kindle ノートデータベースを照会するのに役立ちます。Bash ツールを使用して psql コマンドを実行し、安全で効率的な照会を実現します","ko":"psql은 PostgreSQL 쿼리 도우미로 사용자에게 로컬 Kindle 노트 데이터베이스를 쿼리하는 데 도움을 줍니다. Bash 도구를 사용하여 psql 명령을 실행하고 보안 및 효율적인 쿼리를 구현합니다","es":"El agente psql es una herramienta de asistencia para bases de datos PostgreSQL que permite consultar notas de Kindle de manera segura","fr":"L''agent psql est un outil d''assistance pour les bases de données PostgreSQL qui permet d''interroger les notes Kindle de manière sécurisée","de":"Der psql-Agent ist ein Assistenztool für PostgreSQL-Datenbanken, das das Abfragen von Kindle-Notizen auf sichere Weise ermöglicht","pt":"O psql é uma habilidade de consulta de banco de dados PostgreSQL que ajuda a executar comandos psql de forma segura. Ele permite consultar o banco de dados local de notas do Kindle","ru":"psql - это навык запроса базы данных PostgreSQL, который помогает выполнять команды psql безопасно. Он позволяет запросить локальную базу данных заметок Kindle с помощью ИИ Агентов","ar":"psql هو مهارة استعلام قاعدة بيانات PostgreSQL التي تساعد على تشغيل أوامر psql بأمان. وهي تسمح بالاستعلام عن قاعدة بيانات ملاحظات Kindle المحلية مع الأدوات الذكية"},"seo":{"title":{"en":"psql: PostgreSQL Query Setup Guide | AI Agent Skill","zh":"psql Setup Guide: PostgreSQL 查询助手","ja":"psql Setup Guide: PostgreSQL クエリアシスタント","ko":"psql 설정 가이드: PostgreSQL 쿼리 도우미","es":"Guía de configuración de psql para bases de datos PostgreSQL","fr":"Guide de mise en place de psql pour les bases de données ...","de":"Einrichtungsleitfaden für psql in PostgreSQL-Datenbanken","pt":"Guia de Configuração psql: Consultas de Banco de Dados Po...","ru":"Руководство по настройке psql: Запросы к базе данных Post...","ar":"دليل إعداد psql: استعلامات قاعدة بيانات PostgreSQL للأدوا..."},"description":{"en":"Unlock efficient PostgreSQL querying with psql! Learn how to leverage this skill for secure and precise database interactions - try it now!","zh":"使用 psql 查询本地 Kindle 笔记数据库，了解如何使用 Bash 工具执行 psql 命令","ja":"psql を使用してローカルの Kindle ノートデータベースを照会し、Bash ツールで psql コマンドを実行する方法を学びます","ko":"psql을 사용하여 로컬 Kindle 노트 데이터베이스를 쿼리하고 Bash 도구에서 psql 명령을 실행하는 방법을 알아보세요","es":"Aprende a utilizar psql para consultar tus notas de Kindle en una base de datos local, con restricciones de seguridad críticas","fr":"Découvrez comment utiliser psql pour interroger vos notes Kindle dans une base de données locale, avec des restrictions de sécurité critiques","de":"Erfahren Sie, wie Sie psql verwenden können, um auf Ihre Kindle-Notizen in einer lokalen Datenbank zuzugreifen, mit kritischen Sicherheitsbeschränkungen","pt":"Aprenda a usar o psql para consultar seu banco de dados local de notas do Kindle. Descubra como executar comandos psql de forma segura","ru":"Узнайте, как использовать psql для запросов к вашей локальной базе данных заметок Kindle. Откройте для себя, как выполнить команды psql безопасно с помощью И...","ar":"تعلم كيفية استخدام psql لاستعلام قاعدة بيانات ملاحظات Kindle المحلية. اكتشف كيفية تشغيل أوامر psql بأمان مع الأدوات الذكية"},"definition":{"en":"psql is a PostgreSQL database assistant skill that helps users query their databases securely using specific psql commands and Bash tool restrictions.","zh":"psql 是一个 PostgreSQL 查询工具，用于执行 SQL 命令和查询数据库","ja":"psql は PostgreSQL クエリツールであり、SQL コマンドを実行し、データベースを照会するために使用されます","ko":"psql은 PostgreSQL 쿼리 도구로서 SQL 명령을 실행하고 데이터베이스를 쿼리하는 데 사용됩니다","es":"psql es una herramienta de línea de comandos para interactuar con bases de datos PostgreSQL","fr":"psql est un outil de ligne de commande pour interagir avec les bases de données PostgreSQL","de":"psql ist ein Kommandozeilen-Tool zur Interaktion mit PostgreSQL-Datenbanken","pt":"O psql é uma ferramenta de linha de comando para interagir com bancos de dados PostgreSQL","ru":"psql - это командная строка для взаимодействия с базами данных PostgreSQL от ИИ Агентов","ar":"psql هو أداة سطر أوامر للتفاعل مع قواعد بيانات PostgreSQL للأدوات الذكية"},"features":{"en":["Executes psql commands via Bash tool for secure database interactions","Supports valid patterns like `psql \"<connection>\" -c \"<query>\"` for precise querying","Restricts usage to only psql commands for enhanced security","Polite refusal of non-psql commands with explanatory feedback","Utilizes `psql <connection> -c \"<query>\"` format for efficient querying"],"zh":["使用 Bash 工具执行 psql 命令","支持安全的 psql 连接","实现本地 Kindle 笔记数据库的查询","严格遵守安全要求，仅允许 psql 命令","支持多种 psql 查询模式"],"ja":["Bash ツールを使用して psql コマンドを実行","安全な psql 接続をサポート","ローカルの Kindle ノートデータベースの照会を実現","厳格なセキュリティ要件を遵守し、psql コマンドのみを許可","多様な psql クエリモードをサポート"],"ko":["Bash 도구를 사용하여 psql 명령을 실행","보안적인 psql 연결을 지원","로컬 Kindle 노트 데이터베이스의 쿼리를 구현","엄격한 보안 요구사항을 준수하고 psql 명령만 허용","다양한 psql 쿼리 모드를 지원"],"es":["Ejecución de comandos psql con conexión a base de datos local","Soporte para consultas SQL seguras","Restricciones de seguridad críticas para evitar accesos no autorizados","Uso de Bash para ejecutar comandos psql","Patrones de comandos válidos: psql \"<connection>\" -c \"<query>\" o psql <connection> -c \"<query>\""],"fr":["Exécution de commandes psql avec connexion à une base de données locale","Prise en charge de requêtes SQL sécurisées","Restrictions de sécurité critiques pour éviter les accès non autorisés","Utilisation de Bash pour exécuter des commandes psql","Modèles de commandes valides : psql \"<connection>\" -c \"<query>\" ou psql <connection> -c \"<query>\""],"de":["Ausführung von psql-Befehlen mit Verbindung zu lokalen Datenbanken","Unterstützung für sichere SQL-Abfragen","Kritische Sicherheitsbeschränkungen zur Verhinderung von unbefugtem Zugriff","Verwendung von Bash zur Ausführung von psql-Befehlen","Gültige Befehlsmuster: psql \"<connection>\" -c \"<query>\" oder psql <connection> -c \"<query>\""],"pt":["Execução de comandos psql de forma segura","Consulta ao banco de dados local de notas do Kindle","Uso do Bash tool para executar comandos psql","Padrões de comando válidos: psql \"<connection>\" -c \"<query>\"","Suporte a consultas de banco de dados PostgreSQL"],"ru":["Выполнение команд psql безопасно с помощью ИИ Агентов","Запрос к локальной базе данных заметок Kindle","Использование Bash tool для выполнения команд psql","Допустимые шаблоны команд: psql \"<connection>\" -c \"<query>\"","Поддержка запросов к базе данных PostgreSQL от ИИ Агентов"],"ar":["تشغيل أوامر psql بأمان مع الأدوات الذكية","استعلام قاعدة بيانات ملاحظات Kindle المحلية","استخدام أداة Bash لتشغيل أوامر psql","أنماط أوامر صالحة: psql \"<connection>\" -c \"<query>\"","دعم استعلامات قاعدة بيانات PostgreSQL للأدوات الذكية"]},"keywords":{"en":["how to use psql","psql setup guide","what is psql","psql alternative","psql vs PostgreSQL","psql install","PostgreSQL query optimization","psql command examples","Bash tool psql integration"],"zh":["psql","PostgreSQL 查询","Bash 工具","Kindle 笔记数据库","安全查询","psql 命令","SQL 查询","数据库查询"],"ja":["psql","PostgreSQL クエリ","Bash ツール","Kindle ノートデータベース","安全なクエリ","psql コマンド","SQL クエリ","データベースクエリ"],"ko":["psql","PostgreSQL 쿼리","Bash 도구","Kindle 노트 데이터베이스","보안 쿼리","psql 명령","SQL 쿼리","데이터베이스 쿼리"],"es":["psql","PostgreSQL","bases de datos","notas de Kindle","seguridad crítica","Bash","comandos psql","consultas SQL","herramientas de desarrollo","Agente de inteligencia artificial"],"fr":["psql","PostgreSQL","bases de données","notes Kindle","sécurité critique","Bash","commandes psql","requêtes SQL","outils de développement","Agent d''intelligence artificielle"],"de":["psql","PostgreSQL","Datenbanken","Kindle-Notizen","kritische Sicherheit","Bash","psql-Befehle","SQL-Abfragen","Entwicklungstools","Künstliche Intelligenz-Tool"],"pt":["psql","PostgreSQL","Banco de dados","Consulta de banco de dados","Segurança de banco de dados","Bash tool","Comandos psql","Kindle notes","Desenvolvimento de banco de dados"],"ru":["psql","PostgreSQL","База данных","Запрос базы данных","Безопасность базы данных","Bash tool","Команды psql","Заметки Kindle","Разработка базы данных","ИИ Агенты"],"ar":["psql","PostgreSQL","قاعدة بيانات","استعلام قاعدة بيانات","أمان قاعدة بيانات","أداة Bash","أوامر psql","ملاحظات Kindle","تطوير قاعدة بيانات","الأدوات الذكية"]}},"owner":"dfujiwara","repo":"kindle-notes-reminder","repoPath":"dfujiwara/kindle-notes-reminder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"psql","description":"Execute SQL queries against the local PostgreSQL database. Accepts raw SQL or natural language queries that get converted to SQL automatically. Use for inspecting data, running queries, or managing the Kindle notes database.","bodyPreview":"# PostgreSQL Query Skill\n\nYou are a PostgreSQL database assistant. Your job is to help the user query their local Kindle notes database.\n\n## IMPORTANT: Tool Usage Restrictions\n\n**CRITICAL SECURITY REQUIREMENT:**\n- You may ONLY use the Bash tool to execute `psql` commands\n- ANY other bash command is STRICTLY FORBIDDEN\n- Valid patterns: `psql \"<connection>\" -c \"<query>\"` or `psql <connection> -c \"<query>\"`\n- If the user requests any non-psql command, politely refuse and explain this skill is restr","body":"# PostgreSQL Query Skill\n\nYou are a PostgreSQL database assistant. Your job is to help the user query their local Kindle notes database.\n\n## IMPORTANT: Tool Usage Restrictions\n\n**CRITICAL SECURITY REQUIREMENT:**\n- You may ONLY use the Bash tool to execute `psql` commands\n- ANY other bash command is STRICTLY FORBIDDEN\n- Valid patterns: `psql \"<connection>\" -c \"<query>\"` or `psql <connection> -c \"<query>\"`\n- If the user requests any non-psql command, politely refuse and explain this skill is restricted to database queries only\n- You may use the Read tool ONLY to check for the `.env` file to get `DATABASE_URL`\n\n## Your Task\n\nThe user has provided a query input. You must:\n\n1. **Detect the input type:**\n   - If it looks like raw SQL (starts with SELECT, INSERT, UPDATE, DELETE, WITH, or psql commands like \\d, \\dt, \\l, etc.),  execute it directly\n   - If it''s natural language, convert to SQL first, show the generated query, then execute\n\n2. **Get database connection details:**\n   - Check if `.env` file exists and contains `DATABASE_URL`\n   - If not, use default: `postgresql://postgres:postgres@localhost:5432/fastapi_db`\n\n3. **For natural language queries:**\n   - First, fetch the database schema by running: `psql <connection> -c \"\\d\"`\n   - Analyze the schema to understand available tables and columns\n   - Generate appropriate SQL query based on the user''s request\n   - Show the generated SQL to the user with an explanation\n   - For write operations (INSERT/UPDATE/DELETE), ask for confirmation before executing\n   - For read operations (SELECT), auto-execute\n\n4. **Execute the query:**\n   - Use the `psql` command-line tool with the connection string\n   - Format: `psql \"<DATABASE_URL>\" -c \"<query>\"`\n   - Display results in a readable format\n\n5. **Handle errors gracefully:**\n   - If query fails, show the error message\n   - Suggest corrections if possible\n\n## Database Schema Reference\n\nThe Kindle notes database has these main tables:\n- `books` - Book information (id, title, author, asin, etc.)\n- `notes` - Individual highlights/notes (id, book_id, content, location, etc.)\n- `evaluations` - LLM-generated context evaluations (note_id, score, reasoning, etc.)\n\nNote: Always fetch the actual schema with `\\d` for accurate column names and types.\n\n## Example Interactions\n\n**Direct SQL:**\nUser: `SELECT * FROM books LIMIT 5;`\nYou: Execute directly using psql\n\n**Natural Language:**\nUser: `show me the 5 most recent books`\nYou:\n1. Fetch schema with `\\d`\n2. Generate SQL: `SELECT * FROM books ORDER BY created_at DESC LIMIT 5;`\n3. Show user: \"I''ll run this query: `SELECT * FROM books ORDER BY created_at DESC LIMIT 5;`\"\n4. Execute and display results\n\n**psql Commands:**\nUser: `\\dt`\nYou: Execute `psql \"<DATABASE_URL>\" -c \"\\dt\"` to list tables\n\n## Important Notes\n\n- Always show the user what query you''re running\n- For natural language, explain your SQL reasoning briefly\n- If the user''s request is ambiguous, ask clarifying questions\n- Use the Bash tool to execute psql commands\n- Present results in a clear, formatted way\n- For large result sets, consider adding LIMIT clauses\n\n## Safety\n\n- For destructive operations (DROP, TRUNCATE), always warn and confirm\n- For UPDATE/DELETE without WHERE clauses, strongly warn about affecting all rows\n- Never expose sensitive credentials in output\n\nNow, process the user''s query based on these instructions.\n"},"lastSynced":"2026-03-08T02:04:07.737Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Analysis Agents requiring secure PostgreSQL query execution via Bash tool integration.","zh":"适合需要通过Bash工具集成安全执行PostgreSQL查询的数据分析代理。","ja":"Bashツールの統合を介して安全にPostgreSQLクエリを実行する必要があるデータ分析エージェントに適しています。","ko":"Bash 툴 통합을 통해 안전하게 PostgreSQL 쿼리를 실행해야 하는 데이터 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Datos que requieren una ejecución de consultas de PostgreSQL segura a través de la integración de herramientas de Bash.","fr":"Idéal pour les Agents d''Analyse de Données nécessitant une exécution de requêtes PostgreSQL sécurisée via l''intégration d''outils Bash.","de":"Ideal für Data-Analytics-Agents, die eine sichere Ausführung von PostgreSQL-Abfragen über die Integration von Bash-Tools erfordern.","pt":"Ideal para Agentes de Análise de Dados que exigem execução segura de consulta PostgreSQL via integração de ferramenta Bash.","ru":"Идеально для агентов анализа данных, требующих безопасного выполнения запросов PostgreSQL через интеграцию с инструментом Bash.","ar":"مثالي لعميل تحليل البيانات الذي يتطلب تنفيذ استفسار PostgreSQL آمن عبر دمج أداة Bash."},"recommendation":{"en":"Empowers agents to execute psql commands securely, utilizing PostgreSQL query capabilities and adhering to strict Bash tool usage restrictions, ensuring secure interaction with local Kindle notes databases through valid psql patterns like `psql \"<connection>\" -c \"<query>\"`.","zh":"赋予代理安全执行psql命令的能力，利用PostgreSQL查询功能，并遵守严格的Bash工具使用限制，确保通过有效的psql模式（如`psql \"<connection>\" -c \"<query>\"`）与本地Kindle笔记数据库安全交互。","ja":"エージェントに、psqlコマンドを安全に実行する機能を提供し、PostgreSQLのクエリ機能を利用し、厳格なBashツールの使用制限に従い、有効なpsqlパターン（例：`psql \"<connection>\" -c \"<query>\"`）を使用して、ローカルのKindleノートデータベースと安全にやり取りします。","ko":"에이전트가 psql 명령을 안전하게 실행할 수 있는 기능을 제공하여 PostgreSQL 쿼리 기능을 활용하고严格한 Bash 툴 사용 제한을 준수하여 유효한 psql 패턴（예：`psql \"<connection>\" -c \"<query>\"`）을 통해 로컬 Kindle 노트 데이터베이스와 안전하게 상호 작용할 수 있습니다.","es":"Habilita a los agentes a ejecutar comandos psql de manera segura, utilizando las capacidades de consulta de PostgreSQL y cumpliendo con las estrictas restricciones de uso de herramientas de Bash, asegurando una interacción segura con bases de datos de notas locales de Kindle a través de patrones psql válidos como `psql \"<connection>\" -c \"<query>\"`.","fr":"Permet aux agents d''exécuter des commandes psql de manière sécurisée, en utilisant les capacités de requête PostgreSQL et en respectant les restrictions d''utilisation d''outils Bash strictes, assurant une interaction sécurisée avec les bases de données de notes Kindle locales via des modèles psql valides comme `psql \"<connection>\" -c \"<query>\"`.","de":"Ermächtigt die Agenten, psql-Befehle sicher auszuführen, wobei die PostgreSQL-Abfragefunktionen genutzt und die strengen Bash-Tool-Verwendungsbeschränkungen eingehalten werden, um eine sichere Interaktion mit lokalen Kindle-Notiz-Datenbanken über gültige psql-Muster wie `psql \"<connection>\" -c \"<query>\"` sicherzustellen.","pt":"Habilita os agentes a executar comandos psql de forma segura, utilizando as capacidades de consulta do PostgreSQL e aderindo a restrições estritas de uso da ferramenta Bash, garantindo interação segura com bancos de dados de notas do Kindle local por meio de padrões psql válidos como `psql \"<connection>\" -c \"<query>\"`.","ru":"Наделяет агентов возможностью безопасно выполнять команды psql, используя возможности запросов PostgreSQL и соблюдая строгие ограничения использования инструмента Bash, обеспечивая безопасное взаимодействие с локальными базами данных заметок Kindle через действительные шаблоны psql, такие как `psql \"<connection>\" -c \"<query>\"`.","ar":"يمنح الوكلاء khảية تنفيذ أوامر psql بشكل آمن، مستخدمين إمكانيات استفسار PostgreSQL والامتثال للقيود الصارمة لاستخدام أداة Bash، مما يضمن التفاعل الآمن مع قواعد بيانات ملاحظات Kindle المحلية من خلال أنماط psql صالحة مثل `psql \"<connection>\" -c \"<query>\"`."},"useCases":{"en":["Querying local Kindle notes databases","Executing secure psql commands via Bash","Analyzing PostgreSQL database content"],"zh":["查询本地Kindle笔记数据库","通过Bash安全执行psql命令","分析PostgreSQL数据库内容"],"ja":["ローカルのKindleノートデータベースを照会する","Bashを介して安全にpsqlコマンドを実行する","PostgreSQLデータベースの内容を分析する"],"ko":["로컬 Kindle 노트 데이터베이스 쿼리","Bash를 통해 안전한 psql 명령 실행","PostgreSQL 데이터베이스 내용 분석"],"es":["Consultar bases de datos de notas locales de Kindle","Ejecutar comandos psql seguros a través de Bash","Analizar contenido de bases de datos de PostgreSQL"],"fr":["Interroger les bases de données de notes Kindle locales","Exécuter des commandes psql sécurisées via Bash","Analyser le contenu des bases de données PostgreSQL"],"de":["Abfrage lokaler Kindle-Notiz-Datenbanken","Sichere Ausführung von psql-Befehlen über Bash","Analyse des Inhalts von PostgreSQL-Datenbanken"],"pt":["Consulta de bancos de dados de notas do Kindle local","Execução de comandos psql seguros via Bash","Análise de conteúdo do banco de dados PostgreSQL"],"ru":["Запрос локальных баз данных заметок Kindle","Выполнение безопасных команд psql через Bash","Анализ содержимого базы данных PostgreSQL"],"ar":["استفسار قواعد بيانات ملاحظات Kindle المحلية","تنفيذ أوامر psql آمنة عبر Bash","تحليل محتوى قاعدة بيانات PostgreSQL"]},"limitations":{"en":["Strictly limited to psql commands","Bash tool usage only","PostgreSQL database connection required"],"zh":["仅限psql命令","仅Bash工具使用","需要PostgreSQL数据库连接"],"ja":["psqlコマンドのみ","Bashツールのみ","PostgreSQLデータベース接続が必要"],"ko":["psql 명령만","Bash 툴만","PostgreSQL 데이터베이스 연결 필요"],"es":["Estrictamente limitado a comandos psql","Solo uso de herramientas de Bash","Se requiere una conexión a la base de datos de PostgreSQL"],"fr":["Strictement limité aux commandes psql","Utilisation d''outils Bash uniquement","Connexion à la base de données PostgreSQL requise"],"de":["Streng auf psql-Befehle beschränkt","Nur Verwendung von Bash-Tools","Verbindung zur PostgreSQL-Datenbank erforderlich"],"pt":["Limitado estritamente a comandos psql","Uso apenas da ferramenta Bash","Conexão com banco de dados PostgreSQL necessária"],"ru":["Ограничен строго командами psql","Использование только инструмента Bash","Требуется подключение к базе данных PostgreSQL"],"ar":["محدد строго بأوامر psql","استخدام أداة Bash فقط","تطلب الاتصال بقاعدة بيانات PostgreSQL"]},"version":4},"contentHash":"1a297a3a0b3c6041cca2dd254ef9a154995f31a71cf32061b847e48cec345c23","qualityScore":35}');
DELETE FROM skills_fts WHERE id = 'dfujiwara/kindle-notes-reminder/psql';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dfujiwara/kindle-notes-reminder/psql', 'psql', 'dfujiwara', 'kindle-notes-reminder', 'community', 'psql dfujiwara kindle-notes-reminder community The psql skill assists users in querying their local Kindle notes database using PostgreSQL. It provides a secure way to execute psql commands via the Bash tool. psql 是一个 PostgreSQL 查询助手，帮助用户查询本地 Kindle 笔记数据库。使用 Bash 工具执行 psql 命令，实现安全高效的查询 psql は PostgreSQL クエリアシスタントであり、ユーザーがローカルの Kindle ノートデータベースを照会するのに役立ちます。Bash ツールを使用して psql コマンドを実行し、安全で効率的な照会を実現します psql은 PostgreSQL 쿼리 도우미로 사용자에게 로컬 Kindle 노트 데이터베이스를 쿼리하는 데 도움을 줍니다. Bash 도구를 사용하여 psql 명령을 실행하고 보안 및 효율적인 쿼리를 구현합니다 El agente psql es una herramienta de asistencia para bases de datos PostgreSQL que permite consultar notas de Kindle de manera segura L''agent psql est un outil d''assistance pour les bases de données PostgreSQL qui permet d''interroger les notes Kindle de manière sécurisée Der psql-Agent ist ein Assistenztool für PostgreSQL-Datenbanken, das das Abfragen von Kindle-Notizen auf sichere Weise ermöglicht O psql é uma habilidade de consulta de banco de dados PostgreSQL que ajuda a executar comandos psql de forma segura. Ele permite consultar o banco de dados local de notas do Kindle psql - это навык запроса базы данных PostgreSQL, который помогает выполнять команды psql безопасно. Он позволяет запросить локальную базу данных заметок Kindle с помощью ИИ Агентов psql هو مهارة استعلام قاعدة بيانات PostgreSQL التي تساعد على تشغيل أوامر psql بأمان. وهي تسمح بالاستعلام عن قاعدة بيانات ملاحظات Kindle المحلية مع الأدوات الذكية how to use psql psql setup guide what is psql psql alternative psql vs PostgreSQL psql install PostgreSQL query optimization psql command examples Bash tool psql integration psql PostgreSQL 查询 Bash 工具 Kindle 笔记数据库 安全查询 psql 命令 SQL 查询 数据库查询 Executes psql commands via Bash tool for secure database interactions Supports valid patterns like `psql "<connection>" -c "<query>"` for precise querying Restricts usage to only psql commands for enhanced security Polite refusal of non-psql commands with explanatory feedback Utilizes `psql <connection> -c "<query>"` format for efficient querying psql is a PostgreSQL database assistant skill that helps users query their databases securely using specific psql commands and Bash tool restrictions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('growupanand/ConvoForm/ai-sdk', 'community', 'growupanand', 'ConvoForm', 'growupanand/ConvoForm', 'ai-sdk', 0, 0, 35, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:24.851Z', 'af48f91f4fbfc387387a3e1cc203caf3375f45aa9558bd67aaa77dc92d24e57d', '{"id":"growupanand/ConvoForm/ai-sdk","name":"ai-sdk","description":{"en":"ai-sdk transforms forms into conversations with AI. It benefits developers by providing a package to install via pnpm add ai, and later adding provider packages like @ai-sdk/openai as needed.","zh":"AI SDK是一个将表单转换为对话的工具，使用node_modules/ai/docs/安装和配置","ja":"AIエージェント SDKはフォームを会話に変換するツールで、node_modules/ai/docs/を使用してインストールと設定を行う","ko":"AI SDK는 양식을 대화로 전환하는 도구로, node_modules/ai/docs/를 사용하여 설치하고 설정","es":"El ai-sdk permite convertir formularios en conversaciones con inteligencia artificial. Requiere Node.js y paquetes específicos como @ai-sdk/openai y @ai-sdk/react","fr":"L''ai-sdk permet de convertir les formulaires en conversations avec l''intelligence artificielle. Il nécessite Node.js et des packages spécifiques tels que @ai-sdk/openai et @ai-sdk/react","de":"Das ai-sdk ermöglicht die Umwandlung von Formularen in Konversationen mit künstlicher Intelligenz. Es benötigt Node.js und spezifische Pakete wie @ai-sdk/openai und @ai-sdk/react","pt":"O ai-sdk permite transformar formulários em conversas com IA. Instale o pacote ai e siga as etapas para começar.","ru":"ИИ Агенты: ai-sdk позволяет преобразовать формы в разговоры с ИИ. Установите пакет ai и следуйте инструкциям.","ar":"يسمح ai-sdk بتحويل النماذج إلى محادثات مع الذكاء الاصطناعي. قم بتثبيت حزمة ai واتبع الإرشادات."},"seo":{"title":{"en":"ai-sdk: Setup Guide for AI Agents | AI Agent Skill","zh":"AI SDK集成指南 - 将表单转换为对话","ja":"AIエージェント SDKセットアップガイド - フォームを会話に変換","ko":"AI SDK 설정 가이드 - 양식을 대화로 전환","es":"Guía de configuración de ai-sdk para agentes de in