INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('growupanand/ConvoForm/ai-sdk', 'ai-sdk', 'growupanand', 'ConvoForm', 'community', 'ai-sdk growupanand ConvoForm community ai-sdk transforms forms into conversations with AI. It benefits developers by providing a package to install via pnpm add ai, and later adding provider packages like @ai-sdk/openai as needed. AI SDK是一个将表单转换为对话的工具，使用node_modules/ai/docs/安装和配置 AIエージェント SDKはフォームを会話に変換するツールで、node_modules/ai/docs/を使用してインストールと設定を行う AI SDK는 양식을 대화로 전환하는 도구로, node_modules/ai/docs/를 사용하여 설치하고 설정 El ai-sdk permite convertir formularios en conversaciones con inteligencia artificial. Requiere Node.js y paquetes específicos como @ai-sdk/openai y @ai-sdk/react L''ai-sdk permet de convertir les formulaires en conversations avec l''intelligence artificielle. Il nécessite Node.js et des packages spécifiques tels que @ai-sdk/openai et @ai-sdk/react Das ai-sdk ermöglicht die Umwandlung von Formularen in Konversationen mit künstlicher Intelligenz. Es benötigt Node.js und spezifische Pakete wie @ai-sdk/openai und @ai-sdk/react O ai-sdk permite transformar formulários em conversas com IA. Instale o pacote ai e siga as etapas para começar. ИИ Агенты: ai-sdk позволяет преобразовать формы в разговоры с ИИ. Установите пакет ai и следуйте инструкциям. يسمح ai-sdk بتحويل النماذج إلى محادثات مع الذكاء الاصطناعي. قم بتثبيت حزمة ai واتبع الإرشادات. how to use ai-sdk ai-sdk setup guide ai-sdk vs conversational ai ai-sdk install with pnpm what is ai-sdk ai-sdk alternative solutions ai-sdk documentation ai-sdk provider packages ai-sdk client packages AI SDK 表单转换 对话式界面 node_modules/ai/docs/ AIエージェント 软件开发工具 Installs via pnpm add ai command Utilizes node_modules/ai/docs/ for documentation Supports provider packages like @ai-sdk/openai Requires separate installation of client packages like @ai-sdk/react Warns against trusting internal knowledge for outdated information Specifies critical prerequisites before searching documentation ai-sdk is a development package that enables the conversion of forms into AI-driven conversations, utilizing node_modules and specific provider packages');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gabrielelanaro/wrongodb/review', 'community', 'gabrielelanaro', 'wrongodb', 'gabrielelanaro/wrongodb', 'review', 0, 0, 35, '2026-03-08T01:57:15.373Z', '2026-03-08T02:04:31.590Z', '2f48a41349c8e9349570e679d6ee14c4b31cfd86e73284fb04b527bd47e9bcf3', '{"id":"gabrielelanaro/wrongodb/review","name":"review","description":{"en":"The review skill helps developers improve code quality by reviewing individual files and providing suggestions. It''s ideal for code review and quality assurance.","zh":"代码审查技能用于提高代码质量，通过审查文件和提供改进建议","ja":"コードレビュースキルは、ファイルのレビューと改善提案を提供することでコードの品質向上に役立ちます","ko":"코드 리뷰 기능은 파일을 리뷰하고 개선 제안을 제공하여 코드 품질을 향상시킵니다","es":"La habilidad de revisión es una herramienta de AI que ayuda a mejorar la calidad del código revisando cambios y sugiriendo mejoras. Se utiliza para revisar archivos individuales y seleccionar los aspectos más importantes que necesitan ser abordados","fr":"La compétence de revue est un outil d''IA qui aide à améliorer la qualité du code en révisant les modifications et en suggérant des améliorations. Il est utilisé pour réviser des fichiers individuels et sélectionner les aspects les plus importants qui nécessitent une attention","de":"Die Fähigkeit zur Überprüfung ist ein KI-Tool, das bei der Verbesserung der Code-Qualität hilft, indem es Änderungen überprüft und Vorschläge für Verbesserungen macht. Es wird verwendet, um einzelne Dateien zu überprüfen und die wichtigsten Aspekte auszuwählen, die angegangen werden müssen","pt":"O skill de revisão é usado para revisar alterações e melhorar a qualidade do código, permitindo que os desenvolvedores se concentrem nos principais aspectos que precisam ser abordados","ru":"Инструмент обзора используется для проверки изменений и повышения качества кода, позволяя разработчикам сосредоточиться на основных аспектах, которые необходимо устранить","ar":"تستخدم أداة المراجعة لمراجعة التغييرات وتحسين جودة الشفرة، مما يسمح للمطورين بالتركيز على الجوانب الرئيسية التي تحتاج إلى معالجة"},"seo":{"title":{"en":"Review: Code Quality Improvement Guide | AI Agent Skill","zh":"代码审查设置指南：提高代码质量","ja":"コードレビューセットアップガイド：AIエージェントを使用した品質向上","ko":"코드 리뷰 설정 가이드: 코드 품질 향상을 위한 AI 도구","es":"Guía de configuración de revisión de código con herramien...","fr":"Guide de mise en place de la revue de code avec des outil...","de":"Einrichtungsleitfaden für Code-Review mit KI-Tools","pt":"Guia de Configuração de Revisão de Código","ru":"ИИ Агенты: Настройка Инструмента Обзора","ar":"إعداد أداة المراجعة للبرمجيات"},"description":{"en":"Discover how to efficiently review code changes and improve quality with our AI agent skill. Get started with code review best practices today!","zh":"了解如何使用代码审查技能提高代码质量，包括文件审查和改进建议","ja":"AIエージェントを使用したコードレビューの方法について説明します。コードの品質向上に役立つファイルレビューと改善提案を含みます","ko":"코드 리뷰 기능을 사용하여 코드 품질을 향상시키는 방법에 대해 알아보십시오. 파일 리뷰 및 개선 제안을 포함합니다","es":"Aprende a utilizar la habilidad de revisión para mejorar la calidad del código con herramientas de AI. Descubre cómo funciona y cómo integrarla en tu flujo d...","fr":"Découvrez comment utiliser la compétence de revue pour améliorer la qualité du code avec des outils d''IA. Apprenez comment l''utiliser et l''intégrer dans votr...","de":"Erfahren Sie, wie Sie die Fähigkeit zur Überprüfung nutzen können, um die Code-Qualität mit KI-Tools zu verbessern. Entdecken Sie, wie es funktioniert und wi...","pt":"Aprenda a configurar a revisão de código para melhorar a qualidade do seu projeto com o skill de revisão","ru":"Узнайте, как настроить инструмент обзора для повышения качества вашего проекта с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد أداة المراجعة لتحسين جودة مشروعك باستخدام أداة المراجعة"},"definition":{"en":"Review is a code analysis skill that evaluates individual files to identify areas for improvement and provides targeted suggestions.","zh":"代码审查是一种通过审查文件和提供改进建议来提高代码质量的过程","ja":"コードレビューは、ファイルのレビューと改善提案を提供することでコードの品質向上を図るプロセスです","ko":"코드 리뷰는 파일을 리뷰하고 개선 제안을 제공하여 코드 품질을 향상시키는 과정입니다","es":"La revisión es una habilidad de AI que se utiliza para evaluar y mejorar la calidad del código","fr":"La revue est une compétence d''IA qui est utilisée pour évaluer et améliorer la qualité du code","de":"Die Überprüfung ist eine KI-Fähigkeit, die zum Bewerten und Verbessern der Code-Qualität verwendet wird","pt":"O que é revisão de código? É o processo de revisar e melhorar a qualidade do código-fonte","ru":"Что такое обзор кода? Это процесс проверки и повышения качества исходного кода","ar":"ما هي مراجعة الشفرة؟ هي عملية مراجعة وتحسين جودة الشفرة المصدرية"},"features":{"en":["Reviews each individual file for quality improvements","Supports review of uncommitted files, PR diffs, and user-specified files or directories","Provides focused feedback on top 2-3 aspects that need improvement","Offers short, actionable suggestions for code refinement","Enables efficient code review and quality assurance"],"zh":["文件审查：审查文件以确定需要改进的领域","改进建议：提供改进建议以提高代码质量","代码质量提高：通过审查和改进建议提高代码质量","个性化审查：根据用户的需求和目标进行审查","简洁报告：提供简洁的报告以帮助用户快速理解审查结果"],"ja":["ファイルレビュー：ファイルをレビューして改善すべき領域を特定する","改善提案：コードの品質向上のために改善提案を提供する","コード品質向上：レビューと改善提案を通じてコードの品質向上を図る","カスタマイズレビュー：ユーザーのニーズと目標に基づいてレビューを行う","簡潔な報告：レビュー結果を迅速に理解できる簡潔な報告を提供する"],"ko":["파일 리뷰：파일을 리뷰하여 개선해야 할 영역을 식별한다","개선 제안：코드 품질을 향상시키기 위한 개선 제안을 제공한다","코드 품질 향상：리뷰 및 개선 제안을 통해 코드 품질을 향상시킨다","개인화 리뷰：사용자의需求과 목표에 따라 리뷰를 수행한다","간결한 보고서：리뷰 결과를 신속하게 이해할 수 있는 간결한 보고서를 제공한다"],"es":["Revisión de archivos individuales","Selección de los aspectos más importantes que necesitan ser abordados","Sugerencias de mejora para el código","Integración con flujos de trabajo de desarrollo","Compatibilidad con herramientas de AI para una revisión más eficaz"],"fr":["Révision de fichiers individuels","Sélection des aspects les plus importants qui nécessitent une attention","Suggestions d''amélioration pour le code","Intégration avec les flux de travail de développement","Compatibilité avec les outils d''IA pour une révision plus efficace"],"de":["Überprüfung von einzelnen Dateien","Auswahl der wichtigsten Aspekte, die angegangen werden müssen","Vorschläge für Verbesserungen des Codes","Integration in Entwicklungsworkflows","Kompatibilität mit KI-Tools für eine effizientere Überprüfung"],"pt":["Revisão de arquivos individuais","Foco nos principais aspectos que precisam ser abordados","Sugestões curtas para melhorar a qualidade do código","Integração com diffs e PRs","Suporte a revisão de diretórios e arquivos específicos"],"ru":["Просмотр отдельных файлов","Фокус на основных аспектах, которые необходимо устранить","Краткие предложения для улучшения качества кода","Интеграция с diffs и PR","Поддержка просмотра директорий и конкретных файлов"],"ar":["مراجعة الملفات الفردية","التركيز على الجوانب الرئيسية التي تحتاج إلى معالجة","اقتراحات قصيرة لتحسين جودة الشفرة","التكامل مع diffs و PRs","دعم مراجعة الدلائل والملفات المحددة"]},"keywords":{"en":["how to use review for code quality","what is review in software development","review alternative for code analysis","review vs code inspection","review install guide for AI agents","review setup for improved code quality"],"zh":["代码审查","代码质量","文件审查","改进建议","AI工具","代码审查设置","代码质量提高","代码审查技巧","代码审查工具"],"ja":["コードレビュー","コード品質","ファイルレビュー","改善提案","AIエージェント","コードレビューセットアップ","コード品質向上","コードレビューテクニック","コードレビューツール"],"ko":["코드 리뷰","코드 품질","파일 리뷰","개선 제안","AI 도구","코드 리뷰 설정","코드 품질 향상","코드 리뷰 기술","코드 리뷰 툴"],"es":["revisión de código","herramientas de AI","mejora de la calidad del código","desarrollo de software","integración con flujos de trabajo","revisión de archivos individuales","sugerencias de mejora","compatibilidad con herramientas de AI"],"fr":["revue de code","outils d''IA","amélioration de la qualité du code","développement de logiciels","intégration avec les flux de travail","révision de fichiers individuels","suggestions d''amélioration","compatibilité avec les outils d''IA"],"de":["Code-Überprüfung","KI-Tools","Verbesserung der Code-Qualität","Software-Entwicklung","Integration in Arbeitsabläufe","Überprüfung von einzelnen Dateien","Vorschläge für Verbesserungen","Kompatibilität mit KI-Tools"],"pt":["revisão de código","melhoria de qualidade","desenvolvimento de software","ferramentas de revisão","revisão de arquivos","revisão de diretórios","revisão de PRs","revisão de diffs"],"ru":["обзор кода","повышение качества","разработка программного обеспечения","инструменты обзора","просмотр файлов","просмотр директорий","просмотр PR","просмотр diffs"],"ar":["مراجعة الشفرة","تحسين الجودة","تطوير البرمجيات","أدوات المراجعة","مراجعة الملفات","مراجعة الدلائل","مراجعة PRs","مراجعة diffs"]}},"owner":"gabrielelanaro","repo":"wrongodb","repoPath":"gabrielelanaro/wrongodb","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.373Z","topics":[],"category":"community","skillMd":{"name":"review","description":"Review code or changes, and suggest improvements","bodyPreview":"# Review\n\n## When to use this skill\nUse this skill when you need to review changes and improve quality\n\n## How to use\n\nReview EACH individual file that is likely in scope to be reviewed (either uncommitted or in the PR, diff to main, depending on context, or the user specified file or directory)\n\nReally focus on the review on what the user intend to get out of it.\n\nAt the end select the top 2-3 aspects that need to be addressed and a short suggestion. The user doesn''t want to read a whole essay","body":"# Review\n\n## When to use this skill\nUse this skill when you need to review changes and improve quality\n\n## How to use\n\nReview EACH individual file that is likely in scope to be reviewed (either uncommitted or in the PR, diff to main, depending on context, or the user specified file or directory)\n\nReally focus on the review on what the user intend to get out of it.\n\nAt the end select the top 2-3 aspects that need to be addressed and a short suggestion. The user doesn''t want to read a whole essay on the PR. Concise-focused suggestions are best. Like a skilled code reviewer would do.\n\nProvide links to the relevant parts of the code for each suggestion so I can quickly jump to the relevant parts.\n\nLimit strictly to the following aspects and criteria:\n\n## Criteria\n\n### Single responsibility principle (SRP)\n\n- Does the current file contains a single isolated functionality or is it a mix? Consider splitting it into multiple files if it''s not the case.\n\n- Does the current class contain a single isolated functionality or is it expanding into a god class? Think again on the overall purpose and evaluate how the responsibility can be split.\n\n## Dependency injection (DI)\n\n- Are we doing some weird initialization in the main constructor? Consider accepting dependencies directly by simplifying the main constructor and moving the initialization of its to a separate factory method. Or whether we need the factory method at all (maybe this is internally initialized class and we don''t care)\n\n### Naming\n\n- Files: does each file has a clear name that reflects its purpose? Or does it look like a leftover or a hack?\n\n### Layout\n\n- Does the file belong to its location? Does the file belong to this module or specific directory? If not or it''s weird consider renames, or repositioning the file in another place.\n\n### Simplicity\n\n- Are we having unnecessary indirection? If a function is just calling another function, consider inlining it.\n\n## Consistency\n\n- Are we duplicating logic that already exists elsewhere in the codebase? Search for similar patterns, helper methods, or services that we should be using instead.\n- Are there other places in the codebase with similar situations where this same logic/fix should be applied? We don''t want inconsistency.\n- Check for opportunities to consolidate with existing utilities, concerns, or services.\n\n### Comments\n\n- Do comments explain the \"why\" and not the \"what\"? Comments should only be added in confusing parts and explain why this particular decision was made. If the code is clear, it should not need comments, so consider removing them.\n\n### Meaningful, tight interfaces\n\n- Are the interfaces defined meaningful and tight, are they a pleasure to use?\n- Are they too broad or too narrow?\n- Are they redundant?\n- Are they all used outside Are there too many publid methods? 3–7 public methods is a sweet spot.\n- Does it follow ISP, the interface segregation principle?\n"},"lastSynced":"2026-03-08T02:04:31.590Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing comprehensive content analysis and quality assurance capabilities.","zh":"适用于需要全面内容分析和质量保证功能的代码审查代理。","ja":"コードレビューエージェントが包括的なコンテンツ分析と品質保証機能を必要とする場合に適しています。","ko":"전면적인 내용 분석 및 품질 보증 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que necesitan un análisis de contenido integral y capacidades de garantía de calidad.","fr":"Idéal pour les Agents de Revue de Code nécessitant une analyse de contenu complète et des capacités d''assurance qualité.","de":"Ideal für Code-Review-Agenten, die eine umfassende Inhaltsanalyse und Qualitäts-sicherungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de análise de conteúdo abrangente e capacidades de garantia de qualidade.","ru":"Идеально для агентов кода обзора, требующих всестороннего анализа контента и возможностей обеспечения качества.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى تحليل محتوى شامل وقدرات ضمان الجودة."},"recommendation":{"en":"Empowers agents to review individual files, provide suggestions, and improve code quality using diff to main, uncommitted, or user-specified files and directories, focusing on top aspects that need to be addressed.","zh":"赋予代理查看个别文件、提供建议和使用diff到主分支、未提交或用户指定文件和目录来改进代码质量的能力，关注需要解决的主要方面。","ja":"エージェントが個々のファイルをレビューし、提案を提供し、diff to main、未コミット、またはユーザー指定のファイルとディレクトリを使用してコードの品質を向上させる機能を提供します。主に改善する必要がある部分に焦点を当てています。","ko":"에이전트가 개별 파일을 검토하고 제안을 제공하며 diff to main, 커밋되지 않은 파일 또는 사용자 지정 파일 및 디렉토리를 사용하여 코드 품질을 개선할 수 있는 기능을 제공합니다. 주로 해결해야 할 주요 측면에 중점을 둡니다.","es":"Permite a los agentes revisar archivos individuales, proporcionar sugerencias y mejorar la calidad del código usando diff con archivos o directorios principales, no comprometidos o especificados por el usuario, centrándose en los aspectos principales que deben abordarse.","fr":"Permet aux agents de réviser des fichiers individuels, de fournir des suggestions et d''améliorer la qualité du code en utilisant diff avec des fichiers ou des répertoires principaux, non validés ou spécifiés par l''utilisateur, en se concentrant sur les aspects les plus importants à aborder.","de":"Ermöglicht es Agenten, einzelne Dateien zu überprüfen, Vorschläge zu machen und die Codequalität zu verbessern, indem diff mit den Haupt-, nicht committeten oder benutzerspezifischen Dateien und Verzeichnissen verwendet wird, wobei der Schwerpunkt auf den wichtigsten Aspekten liegt, die angegangen werden müssen.","pt":"Habilita os agentes a revisar arquivos individuais, fornecer sugestões e melhorar a qualidade do código usando diff para arquivos principais, não comprometidos ou especificados pelo usuário e diretórios, focando nos principais aspectos que precisam ser abordados.","ru":"Наделяет агентов возможностью рассматривать отдельные файлы, предоставлять предложения и улучшать качество кода с помощью diff к основным, незафиксированным или указанным пользователем файлам и директориям, сосредотачиваясь на главных аспектах, которые необходимо устранить.","ar":"يمنح الوكلاء القدرة على مراجعة الملفات الفردية وتقديم اقتراحات وتحسين جودة الكود باستخدام diff إلى الملفات الرئيسية أو غير الملتزمة أو المحددة من قبل المستخدم والمجلدات، مع التركيز على الجوانب الرئيسية التي يتعين معالجتها."},"useCases":{"en":["Reviewing code changes for quality assurance","Analyzing individual files for improvements","Providing suggestions for code optimization"],"zh":["用于质量保证的代码更改审查","分析个别文件以进行改进","为代码优化提供建议"],"ja":["品質保証のためのコード変更のレビュー","改善のための個々のファイルの分析","コード最適化のための提案"],"ko":["품질 보증을 위한 코드 변경 검토","개선 사항을 위한 개별 파일 분석","코드 최적화를 위한 제안"],"es":["Revisar cambios de código para la garantía de calidad","Analizar archivos individuales para mejoras","Proporcionar sugerencias para la optimización del código"],"fr":["Réviser les modifications de code pour l''assurance qualité","Analyser des fichiers individuels pour améliorations","Fournir des suggestions pour l''optimisation du code"],"de":["Überprüfen von Code-Änderungen für die Qualitäts-sicherung","Analysieren einzelner Dateien für Verbesserungen","Bereitstellen von Vorschlägen für die Code-Optimierung"],"pt":["Revisar alterações de código para garantia de qualidade","Analysar arquivos individuais para melhorias","Fornecer sugestões para otimização de código"],"ru":["Просмотр изменений кода для обеспечения качества","Анализ отдельных файлов для улучшений","Предоставление предложений для оптимизации кода"],"ar":["مراجعة تغييرات الكود لضمان الجودة","تحليل الملفات الفردية للتحسينات","تقديم اقتراحات لتحسين الكود"]},"limitations":{"en":["Requires access to files or directories to be reviewed","Limited to reviewing individual files or small code changes"],"zh":["需要访问要审查的文件或目录","仅限审查个别文件或小代码更改"],"ja":["レビュー対象のファイルまたはディレクトリへのアクセスが必要","個々のファイルまたは小規模なコード変更のみのレビュー"],"ko":["검토할 파일 또는 디렉토리에 대한 액세스가 필요","개별 파일 또는 작은 코드 변경만을 위한 검토"],"es":["Requiere acceso a archivos o directorios para ser revisados","Limitado a la revisión de archivos individuales o pequeños cambios de código"],"fr":["Nécessite l''accès aux fichiers ou aux répertoires à réviser","Limité à la révision de fichiers individuels ou de petits changements de code"],"de":["Benötigt Zugriff auf Dateien oder Verzeichnisse, die überprüft werden sollen","Begrenzt auf die Überprüfung einzelner Dateien oder kleiner Code-Änderungen"],"pt":["Requer acesso a arquivos ou diretórios para serem revisados","Limitado à revisão de arquivos individuais ou pequenas alterações de código"],"ru":["Требует доступа к файлам или директориям для обзора","Ограничен просмотром отдельных файлов или небольших изменений кода"],"ar":["يتطلب الوصول إلى الملفات أو المجلدات المراد مراجعتها","محدود بمراجعة الملفات الفردية أو التحديثات الصغيرة للكود"]},"version":4},"contentHash":"2f48a41349c8e9349570e679d6ee14c4b31cfd86e73284fb04b527bd47e9bcf3","qualityScore":35}');
