INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gabrielelanaro/wrongodb/review', 'review', 'gabrielelanaro', 'wrongodb', 'community', 'review gabrielelanaro wrongodb community The review skill helps developers improve code quality by reviewing individual files and providing suggestions. It''s ideal for code review and quality assurance. 代码审查技能用于提高代码质量，通过审查文件和提供改进建议 コードレビュースキルは、ファイルのレビューと改善提案を提供することでコードの品質向上に役立ちます 코드 리뷰 기능은 파일을 리뷰하고 개선 제안을 제공하여 코드 품질을 향상시킵니다 La habilidad de revisión es una herramienta de AI que ayuda a mejorar la calidad del código revisando cambios y sugiriendo mejoras. Se utiliza para revisar archivos individuales y seleccionar los aspectos más importantes que necesitan ser abordados La compétence de revue est un outil d''IA qui aide à améliorer la qualité du code en révisant les modifications et en suggérant des améliorations. Il est utilisé pour réviser des fichiers individuels et sélectionner les aspects les plus importants qui nécessitent une attention Die Fähigkeit zur Überprüfung ist ein KI-Tool, das bei der Verbesserung der Code-Qualität hilft, indem es Änderungen überprüft und Vorschläge für Verbesserungen macht. Es wird verwendet, um einzelne Dateien zu überprüfen und die wichtigsten Aspekte auszuwählen, die angegangen werden müssen O skill de revisão é usado para revisar alterações e melhorar a qualidade do código, permitindo que os desenvolvedores se concentrem nos principais aspectos que precisam ser abordados Инструмент обзора используется для проверки изменений и повышения качества кода, позволяя разработчикам сосредоточиться на основных аспектах, которые необходимо устранить تستخدم أداة المراجعة لمراجعة التغييرات وتحسين جودة الشفرة، مما يسمح للمطورين بالتركيز على الجوانب الرئيسية التي تحتاج إلى معالجة how to use review for code quality what is review in software development review alternative for code analysis review vs code inspection review install guide for AI agents review setup for improved code quality 代码审查 代码质量 文件审查 改进建议 AI工具 代码审查设置 代码质量提高 代码审查技巧 代码审查工具 Reviews each individual file for quality improvements Supports review of uncommitted files, PR diffs, and user-specified files or directories Provides focused feedback on top 2-3 aspects that need improvement Offers short, actionable suggestions for code refinement Enables efficient code review and quality assurance Review is a code analysis skill that evaluates individual files to identify areas for improvement and provides targeted suggestions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dickymoore/macs/loop', 'community', 'dickymoore', 'macs', 'dickymoore/macs', 'loop', 0, 0, 35, '2026-03-08T01:57:15.375Z', '2026-03-08T02:04:35.489Z', 'b81e76576038b22b43530b2542bb1de03a02a792ce9eef1107fb65b02b4ca80a', '{"id":"dickymoore/macs/loop","name":"loop","description":{"en":"The loop skill enables AI coding agents to work autonomously without interruption. It''s ideal for developers who want to progress through tasks without routine decision interruptions.","zh":"Loop是一种基于tmux的多代理控制系统，用于实现AI编码代理人的自动化进程和无缝控制","ja":"Loopは、tmuxを使用したAIエージェントのオーケストレーションを可能にするマルチエージェント制御システムです","ko":"Loop는 tmux 기반의 다중 에이전트 제어 시스템으로, AI 코딩 에이전트의 자동화와 무중단 제어가 가능합니다","es":"Loop es un modo de control que permite a los agentes de AI trabajar de forma autónoma sin interrupciones","fr":"Loop est un mode de contrôle qui permet aux agents d''IA de travailler de manière autonome sans interruptions","de":"Loop ist ein Kontrollmodus, der es AI-Agenten ermöglicht, autonom und ohne Unterbrechung zu arbeiten","pt":"O modo de loop permite que os agentes de codificação AI trabalhem sem interrupção. Carregue o prompt com /prompts:loop.","ru":"Режим цикла позволяет ИИ Агентам работать без перерывов. Загрузите запрос с /prompts:loop.","ar":"الوضع الحلقي يسمح لوكلاء الترميز الإصطناعي بالعمل دون انقطاع. حمل الطلب بمسار /prompts:loop."},"seo":{"title":{"en":"loop: Autonomous AI Coding Orchestration Setup Guide | AI...","zh":"Loop_SETUP GUIDE - 基于tmux的AI编码代理人控制","ja":"Loopベストプラクティス - tmuxを使用したAIエージェントのオーケストレーション","ko":"Loop구성 가이드 - tmux 기반 AI 코딩 에이전트 오케스트레이션","es":"Guía de configuración de Loop para Agentes de AI","fr":"Guide de mise en place de Loop pour les Agents d''IA","de":"Einrichtungsleitfaden für Loop in Multi-Agenten-Systemen","pt":"Guia de Configuração do Loop: Controle de Agentes de Codi...","ru":"Настройка цикла: Руководство по испо