INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dickymoore/macs/loop', 'loop', 'dickymoore', 'macs', 'community', 'loop dickymoore macs community The loop skill enables AI coding agents to work autonomously without interruption. It''s ideal for developers who want to progress through tasks without routine decision interruptions. Loop是一种基于tmux的多代理控制系统，用于实现AI编码代理人的自动化进程和无缝控制 Loopは、tmuxを使用したAIエージェントのオーケストレーションを可能にするマルチエージェント制御システムです Loop는 tmux 기반의 다중 에이전트 제어 시스템으로, AI 코딩 에이전트의 자동화와 무중단 제어가 가능합니다 Loop es un modo de control que permite a los agentes de AI trabajar de forma autónoma sin interrupciones Loop est un mode de contrôle qui permet aux agents d''IA de travailler de manière autonome sans interruptions Loop ist ein Kontrollmodus, der es AI-Agenten ermöglicht, autonom und ohne Unterbrechung zu arbeiten O modo de loop permite que os agentes de codificação AI trabalhem sem interrupção. Carregue o prompt com /prompts:loop. Режим цикла позволяет ИИ Агентам работать без перерывов. Загрузите запрос с /prompts:loop. الوضع الحلقي يسمح لوكلاء الترميز الإصطناعي بالعمل دون انقطاع. حمل الطلب بمسار /prompts:loop. how to use loop loop alternative loop setup guide what is loop loop vs tmux loop install for AI agents autonomous AI coding tmux-based orchestration loop prompt loading AI编码代理人 tmux 多代理控制 自动化进程 无缝控制 Loop AI工具 编码代理人 Loads prompts with /prompts:loop for autonomous task progression Utilizes tmux-based orchestration for AI coding agents Supports uninterrupted work until completely blocked or complete Stores prompt files at .codex/prompts/loop.md for easy access Enables controllers to break silence only when necessary loop is a tmux-based orchestration system for AI coding agents, allowing continuous work without interruption until blocked');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ijindal1/jaunt/openai-gpt5-prompting', 'community', 'ijindal1', 'jaunt', 'ijindal1/jaunt', 'openai-gpt5-prompting', 0, 0, 35, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:33.468Z', 'dd98f560f5d069f4ed642a242e3950cce522e2dcfd56d8d2bca2a03a727ac2f4', '{"id":"ijindal1/jaunt/openai-gpt5-prompting","name":"openai-gpt5-prompting","description":{"en":"The openai-gpt5-prompting skill helps developers create robust prompts for AI agents, ensuring testability and reliability. It provides a system message template for defining role, priorities, and safety bounds.","zh":"OpenAI GPT-5 提示是一种高级的 AI 工具，用于生成清晰、可测试、强健的提示，适用于开发者","ja":"OpenAI GPT-5 プロンプティングは、開発者向けの明確でテスト可能なプロンプトを生成する高度な AI エージェントです","ko":"OpenAI GPT-5 프롬프팅은 개발자를 위한 명확하고 테스트 가능한 프롬프트를 생성하는 고급 AI 도구입니다","es":"openai-gpt5-prompting es una habilidad que te permite producir prompts de IA claros y robustos. Aprende a configurar y utilizar esta habilidad para mejorar tus proyectos de desarrollo.","fr":"openai-gpt5-prompting est une compétence qui vous permet de produire des invites d''IA claires et robustes. Apprenez à configurer et à utiliser cette compétence pour améliorer vos projets de développement.","de":"openai-gpt5-prompting ist eine Fähigkeit, die es Ihnen ermöglicht, klare und robuste AI-Prompts zu erstellen. Erfahren Sie, wie Sie diese Fähigkeit konfigurieren und verwenden können, um Ihre Entwicklungsprojekte zu verbessern.","pt":"O openai-gpt5-prompting é uma habilidade que ajuda a criar prompts claros e testáveis. Use-o para melhorar a robustez e a confiabilidade dos seus modelos.","ru":"Openai-gpt5-prompting - это навык, помогающий создавать четкие и тестируемые промпты. Используйте его, чтобы повысить устойчивость и надежность ваших моделей.","ar":"openai-gpt5-prompting هو مهارة تساعد على إنشاء أشكال استفهام واضحة وقابلة للفحص. استخدمها لتحسين متانتها وموثوقيتها."},"seo":{"title":{"en":"openai-gpt5-prompting: Best Practices for AI Agents | AI ...","zh":"OpenAI GPT-5 提示设置指南","ja":"OpenAI GPT-5 プロンプティングベストプラクティス","ko":"OpenAI GPT-5 프롬프팅 설정 가이드","es":"Guía de configuración para openai-gpt5-prompting: Mejores...","fr":"Guide de configuration pour openai-gpt5-prompting: Meille...","de":"Konfigurationsleitfaden für openai-gpt5-prompting: Best P...","pt":"Guia de Configuração do openai-gpt5-prompting para Desenv...","ru":"Настройка openai-gpt5-prompting: Руководство для Разработ...","ar":"دليل إعداد openai-gpt5-prompting لمنشئي الأدوات الذكية"},"description":{"en":"Discover how to craft unambiguous prompts with openai-gpt5-prompting. Learn to avoid hardcoding model IDs and optimize your AI agent workflows today!","zh":"了解 OpenAI GPT-5 提示的技术细节，包括系统消息模板和提示包，实现更好的 AI 工具集成","ja":"OpenAI GPT-5 プロンプティングのテクニカルな詳細をマスターし、AI エージェントの統合を強化する","ko":"OpenAI GPT-5 프롬프팅의 기술적인 세부 사항을 확인하고 AI 도구의 통합을 개선하세요","es":"Aprende a crear prompts efectivos con openai-gpt5-prompting. Descubre cómo producir solicitudes de IA claras y robustas para tus proyectos de desarrollo.","fr":"Apprenez à créer des invites efficaces avec openai-gpt5-prompting. Découvrez comment produire des requêtes d''IA claires et robustes pour vos projets de dével...","de":"Erfahren Sie, wie Sie effektive Prompts mit openai-gpt5-prompting erstellen. Entdecken Sie, wie Sie klare und robuste AI-Anfragen für Ihre Entwicklungsprojek...","pt":"Aprenda a usar o openai-gpt5-prompting para criar prompts robustos e testáveis, alinhados com as necessidades de velocidade e confiabilidade dos desenvolvedo...","ru":"Узнайте, как использовать openai-gpt5-prompting для создания промптов, устойчивых к крайним случаям и соответствующих требованиям скорости и надежности разра...","ar":"تعرف على كيفية استخدام openai-gpt5-prompting لإنشاء أشكال استفهام قوية ومتينة، تتماشى مع احتياجات السرعة والموثوقية لمطوري الأدوات الذكية."},"definition":{"en":"openai-gpt5-prompting is a skill that enables the generation of high-quality prompts for AI agents, focusing on clarity, testability, and edge case robustness.","zh":"OpenAI GPT-5 提示是一种 AI 技术，用于生成高质量的提示","ja":"OpenAI GPT-5 プロンプティングは、高品質のプロンプトを生成する AI 技術です","ko":"OpenAI GPT-5 프롬프팅은 고품질의 프롬프트를 생성하는 AI 기술입니다","es":"openai-gpt5-prompting es una habilidad de agente de IA que produce prompts claros y robustos para proyectos de desarrollo.","fr":"openai-gpt5-prompting est une compétence d''agent d''IA qui produit des invites claires et robustes pour les projets de développement.","de":"openai-gpt5-prompting ist eine Fähigkeit von AI-Agenten, die klare und robuste Prompts für Entwicklungsprojekte produziert.","pt":"O openai-gpt5-prompting é uma habilidade de IA que gera prompts unívocos e robustos para modelos de linguagem.","ru":"Openai-gpt5-prompting - это навык ИИ, генерирующий неоднозначные и прочные промпты для языковых моделей.","ar":"openai-gpt5-prompting هو مهارة ذكاء اصطناعي تُولِد أشكالاً استفهامية واضحة وقوية لتنفيذ نماذج اللغة."},"features":{"en":["Generates prompts that are unambiguous and testable","Supports system message templates for defining role and priorities","Allows for confirmation of current model names and features with $openai-docs","Enables alignment with desired tradeoffs between speed and reliability","Avoids hardcoding model IDs or limits for improved flexibility"],"zh":["系统消息模板","提示包","支持多种模型","可测试的提示","强健的边缘情况处理"],"ja":["システムメッセージテンプレート","プロンプトパック","複数モデルに対応","テスト可能なプロンプト","ロバストなエッジケース処理"],"ko":["시스템 메시지 템플릿","프롬프트 팩","다중 모델 지원","테스트 가능한 프롬프트","강력한 에지 케이스 처리"],"es":["Producción de prompts de IA claros y sin ambigüedades","Compatibilidad con la plantilla de mensaje de sistema para definir roles y prioridades","Robustez en casos límite y alineación con el equilibrio deseado entre velocidad y confiabilidad","Evitación de la codificación dura de IDs de modelo o límites","Confirmación de nombres y características de modelos actuales con $openai-docs"],"fr":["Production d''invites d''IA clairs et sans ambiguïtés","Compatibilité avec le modèle de message système pour définir les rôles et les priorités","Robustesse dans les cas limites et alignement sur l''équilibre souhaité entre vitesse et fiabilité","Évitement de la codification rigide des IDs de modèle ou des limites","Confirmation des noms et des fonctionnalités de modèles actuels avec $openai-docs"],"de":["Erstellung von klaren und unambigen AI-Prompts","Kompatibilität mit der Systemnachrichtenvorlage zur Definition von Rollen und Prioritäten","Robustheit in Randfällen und Ausrichtung auf das gewünschte Gleichgewicht zwischen Geschwindigkeit und Zuverlässigkeit","Vermeidung von Hardcoding von Modell-IDs oder Grenzwerten","Bestätigung von aktuellen Modellnamen und Funktionen mit $openai-docs"],"pt":["Criação de prompts unívocos e testáveis","Robustez em relação a casos extremos","Alinhamento com as necessidades de velocidade e confiabilidade","Uso de mensagens de sistema personalizadas","Definição de role e prioridades"],"ru":["Создание неоднозначных и тестируемых промптов","Устойчивость к крайним случаям","Соответствие требованиям скорости и надежности","Использование настраиваемых системных сообщений","Определение роли и приоритетов"],"ar":["إنشاء أشكال استفهام واضحة وقابلة للفحص","المتانتة في مواجهة الحالات القصوى","التوافق مع احتياجات السرعة والموثوقية","استخدام رسائل نظام مخصصة","تحديد الدور والاولويات"]},"keywords":{"en":["how to use openai-gpt5-prompting","openai-gpt5-prompting setup guide","openai-gpt5-prompting alternative","openai-gpt5-prompting vs other AI tools","what is openai-gpt5-prompting","openai-gpt5-prompting install","openai-gpt5-prompting best practices","openai-gpt5-prompting for AI agents","openai-gpt5-prompting documentation"],"zh":["OpenAI GPT-5","AI 工具","提示设置","系统消息模板","提示包","AI 技术","开发者工具","自然语言处理"],"ja":["OpenAI GPT-5","AI エージェント","プロンプティング","システムメッセージテンプレート","プロンプトパック","AI 技術","開発者ツール","自然言語処理"],"ko":["OpenAI GPT-5","AI 도구","프롬프팅","시스템 메시지 템플릿","프롬프트 팩","AI 기술","개발자 도구","자연어 처리"],"es":["openai-gpt5-prompting","agente de IA","prompts de IA","desarrollo de software","configuración de modelos de lenguaje","mejores prácticas para prompts de IA","herramientas de desarrollo de IA","IA para desarrollo de software"],"fr":["openai-gpt5-prompting","agent d''IA","invites d''IA","développement de logiciels","configuration de modèles de langage","meilleures pratiques pour les invites d''IA","outils de développement d''IA","IA pour le développement de logiciels"],"de":["openai-gpt5-prompting","AI-Agent","AI-Prompts","Software-Entwicklung","Konfiguration von Sprachmodellen","Best Practices für AI-Prompts","Entwicklungs-Tools für AI","KI für Software-Entwicklung"],"pt":["openai-gpt5-prompting","desenvolvimento de IA","modelos de linguagem","prompts robustos","velocidade e confiabilidade","mensagens de sistema personalizadas","role e prioridades"],"ru":["openai-gpt5-prompting","разработка ИИ","языковые модели","прочные промпты","скорость и надежность","настраиваемые системные сообщения","роль и приоритеты","ИИ Агенты"],"ar":["openai-gpt5-prompting","تطوير الذكاء الاصطناعي","نماذج اللغة","أشكال استفهام قوية","السرعة والموثوقية","رسائل نظام مخصصة","الدور والاولويات","الأدوات الذكية"]}},"owner":"ijindal1","repo":"jaunt","repoPath":"ijindal1/jaunt","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"openai-gpt5-prompting","description":"Write, critique, and iterate prompts for OpenAI GPT-5 series models. Use for tasks like: (1) turning vague requirements into high-signal instructions, (2) selecting between quick vs deep reasoning behaviors, (3) creating robust structured-output prompts (JSON schemas, tool calls), (4) designing evaluation prompts and rubrics, and (5) debugging prompt failures (hallucinations, format drift, tool misuse). Trigger when the user mentions GPT-5, prompt engineering, system/developer messages, structured outputs, agent prompts, or wants best-practice templates.","bodyPreview":"# GPT-5 Prompting (OpenAI)\n\n## Overview\n\nUse this skill to produce prompts that are: unambiguous, testable, robust to edge cases, and aligned to the desired tradeoff between speed and reliability. Avoid hardcoding model IDs or limits; confirm current model names and features with `$openai-docs` when needed.\n\n## Prompt Pack (Use These Defaults)\n\n### System Message Template\n\nUse a system message that defines role, priorities, safety bounds, and formatting constraints.\n\nRequired elements:\n- Role: w","body":"# GPT-5 Prompting (OpenAI)\n\n## Overview\n\nUse this skill to produce prompts that are: unambiguous, testable, robust to edge cases, and aligned to the desired tradeoff between speed and reliability. Avoid hardcoding model IDs or limits; confirm current model names and features with `$openai-docs` when needed.\n\n## Prompt Pack (Use These Defaults)\n\n### System Message Template\n\nUse a system message that defines role, priorities, safety bounds, and formatting constraints.\n\nRequired elements:\n- Role: what the model is (and is not) responsible for.\n- Output contract: exact format, sections, and any JSON schema constraints.\n- Non-goals: what to avoid (guessing, inventing APIs, ignoring inputs).\n- Clarification policy: what to ask if required info is missing.\n\n### Developer Message Template\n\nUse a developer message for task-specific instructions, context, and constraints (without contradicting system).\n\nInclude:\n- Task statement (1 sentence).\n- Inputs provided and their meaning.\n- Constraints and preferences (libraries, time, cost).\n- Acceptance criteria (how you will judge success).\n\n### User Message Template\n\nMake the user message concrete and data-heavy:\n- Provide examples (good and bad).\n- Provide edge cases.\n- Provide “definition of done”.\n\n## Workflow: Draft -> Test -> Patch\n\n1. Draft the prompt (system/developer/user separation).\n2. Add 3 to 10 targeted test cases:\n- Typical case, tricky case, adversarial case, empty/degenerate input.\n3. Run a “prompt diff” patch cycle:\n- Identify failure mode (ambiguity, missing constraints, competing goals).\n- Patch the smallest instruction that fixes it.\n- Re-run tests.\n\n## Structured Output Guidance\n\nPrefer:\n- Explicit JSON schema (or a strict example) plus “no extra keys”.\n- Deterministic ordering only if needed.\n- “If you cannot comply, return an error object with fields …” (never silently fallback).\n\n## Common Failure Modes (And Fixes)\n\n1. Hallucinated facts:\n- Add: “If unknown, say `I don’t know` and ask for X.”\n- Add: cite-only-from-provided-sources rule when applicable.\n\n2. Format drift:\n- Add: strict schema, no prose, and a single top-level object.\n- Add: “Validate output against schema before responding.”\n\n3. Tool misuse:\n- Add: tool selection rule (“Only call tools when …”), plus examples.\n- Add: “Never fabricate tool outputs.”\n\n## References\n\nSee `references/templates.md` for copy-paste prompt templates and a test-case checklist.\n"},"lastSynced":"2026-03-08T02:05:33.468Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing robust and testable prompt generation for OpenAI GPT-5 models.","zh":"适合需要为 OpenAI GPT-5 模型生成强健且可测试的提示的高级 AI 代理。","ja":"OpenAI GPT-5 モデルにロバストでテスト可能なプロンプトを生成する必要がある高度な AI エージェントに適しています。","ko":"OpenAI GPT-5 모델에 대해 강력하고 테스트 가능한 프롬프트를 생성해야 하는 고급 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA avanzados que necesitan una generación de solicitudes robusta y probada para modelos OpenAI GPT-5.","fr":"Parfait pour les agents d''IA avancés ayant besoin d''une génération de invites robuste et testable pour les modèles OpenAI GPT-5.","de":"Perfekt für fortschrittliche KI-Agents, die eine robuste und testbare Promptgenerierung für OpenAI-GPT-5-Modelle benötigen.","pt":"Perfeito para Agentes de IA Avançados que necessitam de geração de prompts robusta e testável para modelos OpenAI GPT-5.","ru":"Идеально для продвинутых агентов ИИ, которым требуется прочная и тестируемая генерация подсказок для моделей OpenAI GPT-5.","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم الذين يحتاجون إلى توليد صيغ قوية وقابلةสำหร اختبار لطرازات OpenAI GPT-5."},"recommendation":{"en":"Empowers agents to create unambiguous and reliable prompts using a system message template that defines role, priorities, safety bounds, and formatting constraints, ensuring alignment with the desired tradeoff between speed and reliability via OpenAI''s API and $openai-docs.","zh":"使代理能够使用定义角色、优先级、安全边界和格式约束的系统消息模板创建无歧义和可靠的提示，确保通过 OpenAI 的 API 和 $openai-docs 与所需的速度和可靠性之间的权衡保持一致。","ja":"エージェントが役割、優先順位、セーフティバウンド、フォーマットの制約を定義するシステムメッセージテンプレートを使用して、曖昧さのない信頼できるプロンプトを作成できるようにし、OpenAI の API および $openai-docs を介して、速度と信頼性のトレードオフと一致させる。","ko":"에이전트가 역할, 우선 순위, 안전 경계 및 형식 제약을 정의하는 시스템 메시지 템플릿을 사용하여 모호하지 않은 안정적인 프롬프트를 생성할 수 있도록 하여 OpenAI의 API 및 $openai-docs를 통해 원하는 속도와 안정성 간의 트레이드 오프와 일치합니다.","es":"Habilita a los agentes a crear solicitudes inequívocas y confiables utilizando una plantilla de mensaje del sistema que define el rol, las prioridades, los límites de seguridad y las restricciones de formato, asegurando la alineación con el compromiso deseado entre velocidad y confiabilidad a través de la API de OpenAI y $openai-docs.","fr":"Permet aux agents de créer des invites sans ambiguïté et fiables en utilisant un modèle de message système qui définit le rôle, les priorités, les limites de sécurité et les contraintes de mise en forme, assurant l''alignement avec le compromis souhaité entre vitesse et fiabilité via l''API d''OpenAI et $openai-docs.","de":"Ermächtigt Agents, unmissverständliche und zuverlässige Prompts mithilfe einer Systemnachrichtenvorlage zu erstellen, die Rolle, Prioritäten, Sicherheitsgrenzen und Formatierungsbeschränkungen definiert, und stellt sicher, dass die gewünschte Abwägung zwischen Geschwindigkeit und Zuverlässigkeit über die OpenAI-API und $openai-docs erreicht wird.","pt":"Habilita os agentes a criar prompts inequívocos e confiáveis usando um modelo de mensagem do sistema que define papel, prioridades, limites de segurança e restrições de formatação, garantindo alinhamento com o compromisso desejado entre velocidade e confiabilidade via API da OpenAI e $openai-docs.","ru":"Наделяет агентов возможностью создавать беспроблемные и надежные подсказки, используя шаблон системного сообщения, определяющий роль, приоритеты, пределы безопасности и ограничения форматирования, обеспечивая соответствие желаемому балансу между скоростью и надежностью через API OpenAI и $openai-docs.","ar":"تمكّن الوكلاء من إنشاء صيغ واضحة وموثوقة باستخدام قالب رسالة نظام يحدد الدور والأولويات وحدود السلامة وقيود التنسيق، مما يضمن الاتساق مع التوفيق المرغوب بين السرعة والموثوقية عبر واجهة برمجة التطبيقات OpenAI و $openai-docs."},"useCases":{"en":["Generating testable prompts for edge cases","Defining role and priorities for AI tasks","Ensuring safety bounds for sensitive information"],"zh":["为边缘情况生成可测试的提示","为 AI 任务定义角色和优先级","为敏感信息确保安全边界"],"ja":["エッジケースのテスト可能なプロンプトを生成する","AI タスクの役割と優先順位を定義する","機密情報のセーフティバウンドを確保する"],"ko":["엣지 케이스에 대한 테스트 가능한 프롬프트 생성","AI 태스크의 역할 및 우선 순위 정의","민감한 정보에 대한 안전 경계 보장"],"es":["Generación de solicitudes probadas para casos límite","Definir el rol y las prioridades para tareas de IA","Asegurar los límites de seguridad para información sensible"],"fr":["Génération d''invites testables pour les cas limites","Définition du rôle et des priorités pour les tâches d''IA","Assurance des limites de sécurité pour les informations sensibles"],"de":["Generierung von testbaren Prompts für Randfälle","Definieren von Rolle und Prioritäten für KI-Aufgaben","Sicherstellung der Sicherheitsgrenzen für sensible Informationen"],"pt":["Geração de prompts testáveis para casos de bordo","Definição de papel e prioridades para tarefas de IA","Garantia de limites de segurança para informações sensíveis"],"ru":["Генерация тестируемых подсказок для граничных случаев","Определение роли и приоритетов для задач ИИ","Обеспечение пределов безопасности для конфиденциальной информации"],"ar":[" توليد صيغ قابلة للاختبار لحالات الحدود","تعريف الدور والأولويات لمهام الذكاء الاصطناعي","ضمان حدود السلامة للمعلومات الحساسة"]},"limitations":{"en":["Requires knowledge of OpenAI GPT-5 models and features","Must confirm current model names and features with $openai-docs"],"zh":["需要了解 OpenAI GPT-5 模型和功能","必须与 $openai-docs 确认当前模型名称和功能"],"ja":["OpenAI GPT-5 モデルと機能の知識が必要","現在のモデル名と機能を $openai-docs と確認する必要がある"],"ko":["OpenAI GPT-5 모델 및 기능에 대한 지식이 필요","현재 모델 이름 및 기능을 $openai-docs와 확인해야 함"],"es":["Requiere conocimiento de los modelos y características de OpenAI GPT-5","Debe confirmar los nombres y características actuales de los modelos con $openai-docs"],"fr":["Nécessite des connaissances sur les modèles et les fonctionnalités d''OpenAI GPT-5","Doit confirmer les noms et les fonctionnalités actuels des modèles avec $openai-docs"],"de":["Benötigt Kenntnisse über die Modelle und Funktionen von OpenAI GPT-5","Muss die aktuellen Modellnamen und -funktionen mit $openai-docs bestätigen"],"pt":["Requer conhecimento de modelos e recursos OpenAI GPT-5","Deve confirmar os nomes e recursos atuais do modelo com $openai-docs"],"ru":["Требует знания моделей и функций OpenAI GPT-5","Необходимо подтвердить текущие имена и функции модели с $openai-docs"],"ar":["يتطلب معرفة بطرازات وسمات OpenAI GPT-5","يجب التأكد من أسماء وسمات الطراز الحالية مع $openai-docs"]},"version":4},"contentHash":"dd98f560f5d069f4ed642a242e3950cce522e2dcfd56d8d2bca2a03a727ac2f4","qualityScore":35}');
