INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ijindal1/jaunt/openai-gpt5-prompting', 'openai-gpt5-prompting', 'ijindal1', 'jaunt', 'community', 'openai-gpt5-prompting ijindal1 jaunt community The openai-gpt5-prompting skill helps developers create robust prompts for AI agents, ensuring testability and reliability. It provides a system message template for defining role, priorities, and safety bounds. OpenAI GPT-5 提示是一种高级的 AI 工具，用于生成清晰、可测试、强健的提示，适用于开发者 OpenAI GPT-5 プロンプティングは、開発者向けの明確でテスト可能なプロンプトを生成する高度な AI エージェントです OpenAI GPT-5 프롬프팅은 개발자를 위한 명확하고 테스트 가능한 프롬프트를 생성하는 고급 AI 도구입니다 openai-gpt5-prompting es una habilidad que te permite producir prompts de IA claros y robustos. Aprende a configurar y utilizar esta habilidad para mejorar tus proyectos de desarrollo. openai-gpt5-prompting est une compétence qui vous permet de produire des invites d''IA claires et robustes. Apprenez à configurer et à utiliser cette compétence pour améliorer vos projets de développement. openai-gpt5-prompting ist eine Fähigkeit, die es Ihnen ermöglicht, klare und robuste AI-Prompts zu erstellen. Erfahren Sie, wie Sie diese Fähigkeit konfigurieren und verwenden können, um Ihre Entwicklungsprojekte zu verbessern. O openai-gpt5-prompting é uma habilidade que ajuda a criar prompts claros e testáveis. Use-o para melhorar a robustez e a confiabilidade dos seus modelos. Openai-gpt5-prompting - это навык, помогающий создавать четкие и тестируемые промпты. Используйте его, чтобы повысить устойчивость и надежность ваших моделей. openai-gpt5-prompting هو مهارة تساعد على إنشاء أشكال استفهام واضحة وقابلة للفحص. استخدمها لتحسين متانتها وموثوقيتها. how to use openai-gpt5-prompting openai-gpt5-prompting setup guide openai-gpt5-prompting alternative openai-gpt5-prompting vs other AI tools what is openai-gpt5-prompting openai-gpt5-prompting install openai-gpt5-prompting best practices openai-gpt5-prompting for AI agents openai-gpt5-prompting documentation OpenAI GPT-5 AI 工具 提示设置 系统消息模板 提示包 AI 技术 开发者工具 自然语言处理 Generates prompts that are unambiguous and testable Supports system message templates for defining role and priorities Allows for confirmation of current model names and features with $openai-docs Enables alignment with desired tradeoffs between speed and reliability Avoids hardcoding model IDs or limits for improved flexibility openai-gpt5-prompting is a skill that enables the generation of high-quality prompts for AI agents, focusing on clarity, testability, and edge case robustness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LEE-SANG-BOK/VKC-2-/vkc-i18n-ko-vi-safety', 'community', 'LEE-SANG-BOK', 'VKC-2-', 'LEE-SANG-BOK/VKC-2-', 'vkc-i18n-ko-vi-safety', 0, 0, 35, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:00.738Z', '71cfa5b4df41eefd6119f88b88b7a49e0c9db2ca4337308164aebb55b6e401ad', '{"id":"LEE-SANG-BOK/VKC-2-/vkc-i18n-ko-vi-safety","name":"vkc-i18n-ko-vi-safety","description":{"en":"vkc-i18n-ko-vi-safety ensures UI safety for Korean, English, and Vietnamese strings. It helps developers maintain consistent key structures and avoid hardcoded literal strings.","zh":"vkc-i18n-ko-vi-safety是一种确保AI工具国际化安全的技术规范，涉及代码检查和UI安全","ja":"vkc-i18n-ko-vi-safetyは、AIエージェントの安全性を確保するための技術規格であり、コードチェックとUI安全性を含みます","ko":"vkc-i18n-ko-vi-safety는 AI 에이전트의 안전성을 보장하는 기술 규격으로 코드检查과 UI 안전성을 포함합니다","es":"vkc-i18n-ko-vi-safety es una habilidad de seguridad para la internacionalización que ayuda a mantener la consistencia en los mensajes de usuario","fr":"vkc-i18n-ko-vi-safety est une compétence de sécurité pour l''internationalisation qui aide à maintenir la cohérence dans les messages utilisateur","de":"vkc-i18n-ko-vi-safety ist eine Sicherheitsfunktion für die Internationalisierung, die dabei hilft, die Konsistenz in den Benachrichtigungen zu gewährleisten","pt":"O vkc-i18n-ko-vi-safety é uma habilidade que ajuda a garantir a segurança da UI em diferentes idiomas. Ele fornece regras e verificações para manter a consistência nos arquivos de mensagens.","ru":"vkc-i18n-ko-vi-safety - это навык, который помогает обеспечить безопасность UI на разных языках. Он предоставляет правила и проверки для поддержания согласованности в файлах сообщений.","ar":"vkc-i18n-ko-vi-safety هو مهارة تساعد على ضمان سلامة الواجهة المستخدمة بلغات مختلفة. يوفر قواعد وفحوصات لضمان الاتساق في ملفات الرسائل."},"seo":{"title":{"en":"vkc-i18n-ko-vi-safety: UI Safety Setup Guide for AI Agents","zh":"vkc-i18n-ko-vi-safety Setup Guide - AI工具国际化安全","ja":"vkc-i18n-ko-vi-safety ベストプラクティス - AIエージェントの安全性","ko":"vkc-i18n-ko-vi-safety Configuration Best Practices - AI 에...","es":"Guía de configuración de vkc-i18n-ko-vi-safety para segur...","fr":"Guide de mise en œuvre de vkc-i18n-ko-vi-safety pour la s...","de":"Einrichtungsleitfaden für vkc-i18n-ko-vi-safety zur Siche...","pt":"Guia de Configuração do vkc-i18n-ko-vi-safety para Ferram...","ru":"Руководство по настройке vkc-i18n-ko-vi-safety для ИИ Аге...","ar":"دليل إعداد vkc-i18n-ko-vi-safety لأدوات الذكاء الاصطناعي"},"description":{"en":"Ensure UI safety for Vietnamese strings with vkc-i18n-ko-vi-safety. Learn how to run lint-i18n-keys.sh and apply layout-safe padding for a seamless user expe...","zh":"了解vkc-i18n-ko-vi-safety的技术细节，确保AI工具的国际化安全性，点击查看详细信息","ja":"vkc-i18n-ko-vi-safetyの技術的な詳細を学び、AIエージェントの安全性を確保する方法を確認する","ko":"vkc-i18n-ko-vi-safety의 기술적인 세부 정보를 알아보고 AI 에이전트의 안전성을 보장하는 방법을 확인하세요","es":"Aprende a implementar vkc-i18n-ko-vi-safety para asegurar la seguridad en la internacionalización de tus aplicaciones con Herramientas de Inteligencia Artifi...","fr":"Découvrez comment mettre en œuvre vkc-i18n-ko-vi-safety pour assurer la sécurité de l''internationalisation de vos applications avec des Outils d''Intelligence...","de":"Erfahren Sie, wie Sie vkc-i18n-ko-vi-safety implementieren, um die Sicherheit bei der Internationalisierung Ihrer Anwendungen mit KI-Tools zu gewährleisten","pt":"Aprenda a configurar o vkc-i18n-ko-vi-safety para garantir a segurança da UI em diferentes idiomas, incluindo coreano, inglês e vietnamita.","ru":"Узнайте, как настроить vkc-i18n-ko-vi-safety, чтобы обеспечить безопасность UI на разных языках, включая корейский, английский и вьетнамский.","ar":"تعرف على كيفية إعداد vkc-i18n-ko-vi-safety لضمان سلامة الواجهة المستخدمة بلغات مختلفة، بما في ذلك الكورية والإنجليزية والفيتنامية."},"definition":{"en":"vkc-i18n-ko-vi-safety is a skill that provides guidelines for maintaining UI safety across multiple languages, including Korean, English, and Vietnamese.","zh":"vkc-i18n-ko-vi-safety是一种技术规范，用于确保AI工具在国际化方面的安全性","ja":"vkc-i18n-ko-vi-safetyは、AIエージェントの国際化における安全性を確保するための技術規格です","ko":"vkc-i18n-ko-vi-safety는 AI 에이전트의 국제화 안전성을 보장하는 기술 규격입니다","es":"vkc-i18n-ko-vi-safety es una habilidad que garantiza la seguridad en la internacionalización de aplicaciones","fr":"vkc-i18n-ko-vi-safety est une compétence qui assure la sécurité de l''internationalisation des applications","de":"vkc-i18n-ko-vi-safety ist eine Funktion, die die Sicherheit bei der Internationalisierung von Anwendungen gewährleistet","pt":"O vkc-i18n-ko-vi-safety é uma habilidade de Ferramentas de IA que garante a segurança da UI em coreano, inglês e vietnamita.","ru":"vkc-i18n-ko-vi-safety - это навык ИИ Агентов, обеспечивающий безопасность UI на корейском, английском и вьетнамском языках.","ar":"vkc-i18n-ko-vi-safety هو مهارة أدوات الذكاء الاصطناعي التي تضمن سلامة الواجهة المستخدمة باللغات الكورية والإنجليزية والفيتنامية."},"features":{"en":["Runs lint-i18n-keys.sh to check for consistent key structures","Maintains nested key structure consistency across ko.json, en.json, and vi.json","Applies layout-safe padding for long Vietnamese strings","Prevents shipping keys in only one of ko/vi","Avoids hardcoded literal strings in components using message keys"],"zh":["代码检查：运行bash .codex/skills/vkc-repo-guardrails/scripts/lint-i18n-keys.sh","UI安全性：应用“layout-safe”参数","国际化安全：保持嵌套键结构的一致性","避免硬编码字符串：使用消息键","支持多语言：ko、en、vi"],"ja":["コードチェック：bash .codex/skills/vkc-repo-guardrails/scripts/lint-i18n-keys.shを実行","UI安全性：「layout-safe」パラメータを適用","国際化安全：ネストされたキー構造の一貫性を保持","ハードコーディング文字列の回避：メッセージキーを使用","複数言語対応：ko、en、vi"],"ko":["코드检查：bash .codex/skills/vkc-repo-guardrails/scripts/lint-i18n-keys.sh 실행","UI 안전성：“layout-safe” 파라미터 적용","국제화 안전성：중첩된 키 구조的一致性 유지","하드코딩 문자열 回避：메시지 키 사용","다중 언어 지원：ko、en、vi"],"es":["Mantener la estructura de claves anidadas coherente en archivos JSON","Evitar cadenas literales codificadas en componentes","Utilizar la herramienta de lint para comprobar las claves de internacionalización","Aplicar el diseño seguro para cadenas largas en vietnamita","Seguir reglas estrictas para la seguridad en la internacionalización"],"fr":["Maintenir la structure des clés imbriquées cohérente dans les fichiers JSON","Éviter les chaînes littérales codées dans les composants","Utiliser l''outil de lint pour vérifier les clés d''internationalisation","Appliquer la conception sécurisée pour les chaînes longues en vietnamien","Suivre des règles strictes pour la sécurité de l''internationalisation"],"de":["Aufrechterhaltung der konsistenten Struktur von verschachtelten Schlüsseln in JSON-Dateien","Vermeidung von hartcodierten Literalzeichenfolgen in Komponenten","Verwendung des Lint-Tools zur Überprüfung von Internationalisierungsschlüsseln","Anwendung des sicherheitsgerechten Designs für lange vietnamesische Zeichenfolgen","Befolgen strenger Regeln für die Sicherheit bei der Internationalisierung"],"pt":["Regras para manter a consistência nos arquivos de mensagens","Verificações para garantir a segurança da UI em diferentes idiomas","Suporte a coreano, inglês e vietnamita","Integração com scripts de lint para verificar chaves de i18n","Aplicação de layout seguro para strings longas em vietnamita","Uso de chaves de mensagem em vez de strings literais hardcoded"],"ru":["Правила для поддержания согласованности в файлах сообщений","Проверки для обеспечения безопасности UI на разных языках","Поддержка корейского, английского и вьетнамского языков","Интеграция со скриптами lint для проверки ключей i18n","Применение безопасного макета для длинных строк на вьетнамском языке","Использование ключей сообщений вместо hardcoded строк"],"ar":["قواعد للحفاظ على الاتساق في ملفات الرسائل","فحوصات لضمان سلامة الواجهة المستخدمة بلغات مختلفة","دعم اللغات الكورية والإنجليزية والفيتنامية","التكامل مع سكريبتات لينت لفحص مفاتيح i18n","تطبيق تخطيط آمن لالسلاسل الطويلة بالفيتنامية","استخدام مفاتيح الرسائل بدلاً من السلاسل الحرفية المبرمجة"]},"keywords":{"en":["vkc-i18n-ko-vi-safety setup guide","how to use vkc-i18n-ko-vi-safety","what is vkc-i18n-ko-vi-safety","vkc-i18n-ko-vi-safety alternative","vkc-i18n-ko-vi-safety vs i18n tools","vkc-i18n-ko-vi-safety install","lint-i18n-keys.sh command","UI safety for Vietnamese strings"],"zh":["AI工具国际化安全","vkc-i18n-ko-vi-safety","代码检查","UI安全性","国际化安全","嵌套键结构","消息键","多语言支持"],"ja":["AIエージェントの安全性","vkc-i18n-ko-vi-safety","コードチェック","UI安全性","国際化安全","ネストされたキー構造","メッセージキー","複数言語対応"],"ko":["AI 에이전트 안전성","vkc-i18n-ko-vi-safety","코드检查","UI 안전성","국제화 안전성","중첩된 키 구조","메시지 키","다중 언어 지원"],"es":["vkc-i18n-ko-vi-safety","seguridad en la internacionalización","Herramientas de Inteligencia Artificial","internacionalización de aplicaciones","messages.json","lint-i18n-keys.sh","diseño seguro para cadenas largas"],"fr":["vkc-i18n-ko-vi-safety","sécurité de l''internationalisation","Outils d''Intelligence Artificielle","internationalisation des applications","messages.json","lint-i18n-keys.sh","conception sécurisée pour les chaînes longues"],"de":["vkc-i18n-ko-vi-safety","Sicherheit bei der Internationalisierung","KI-Tools","Internationalisierung von Anwendungen","messages.json","lint-i18n-keys.sh","sicherheitsgerechtes Design für lange Zeichenfolgen"],"pt":["vkc-i18n-ko-vi-safety","Ferramentas de IA","segurança da UI","i18n","coreano","inglês","vietnamita","lint","layout seguro"],"ru":["vkc-i18n-ko-vi-safety","ИИ Агенты","безопасность UI","i18n","корейский","английский","вьетнамский","lint","безопасный макет"],"ar":["vkc-i18n-ko-vi-safety","أدوات الذكاء الاصطناعي","سلامة الواجهة المستخدمة","i18n","الكورية","الإنجليزية","الفيتنامية","lint","تخطيط آمن"]}},"owner":"LEE-SANG-BOK","repo":"VKC-2-","repoPath":"LEE-SANG-BOK/VKC-2-","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.389Z","topics":[],"category":"community","skillMd":{"name":"vkc-i18n-ko-vi-safety","description":"Prevent i18n regressions for ko/en/vi (missing keys, long Vietnamese text UI breakage). Use when changing messages/*.json or adding user-facing strings. (키워드= 다국어, 번역, i18n, 메시지 키, ko/vi 키 동기화, 베트남어 긴 문장)","bodyPreview":"# VKC i18n (ko/en/vi) Safety\n\n## When to use\n\n- You add/edit user-facing strings\n- You touch `messages/*.json`\n- A UI breaks only in Vietnamese\n\n## Rules\n\n- Never ship a key in only one of `ko/vi`.\n- Keep nested key structure consistent across `ko.json`, `en.json`, `vi.json`.\n- Avoid hardcoded literal strings in components; prefer message keys.\n\n## Checks\n\n- Run: `bash .codex/skills/vkc-repo-guardrails/scripts/lint-i18n-keys.sh`\n\n## UI safety for long Vietnamese strings\n\n- Apply “layout-safe” pa","body":"# VKC i18n (ko/en/vi) Safety\n\n## When to use\n\n- You add/edit user-facing strings\n- You touch `messages/*.json`\n- A UI breaks only in Vietnamese\n\n## Rules\n\n- Never ship a key in only one of `ko/vi`.\n- Keep nested key structure consistent across `ko.json`, `en.json`, `vi.json`.\n- Avoid hardcoded literal strings in components; prefer message keys.\n\n## Checks\n\n- Run: `bash .codex/skills/vkc-repo-guardrails/scripts/lint-i18n-keys.sh`\n\n## UI safety for long Vietnamese strings\n\n- Apply “layout-safe” patterns by default:\n  - `min-w-0` on flex children that contain text\n  - `break-words` or `whitespace-pre-line` where wrapping is required\n  - `line-clamp-*` where space must be capped\n  - avoid fixed widths for text containers unless truncation is intentional\n\n## Reference\n\n- `.codex/skills/vkc-i18n-ko-vi-safety/references/i18n-ui-safety.md`\n"},"lastSynced":"2026-03-08T02:06:00.738Z","agentAnalysis":{"suitability":{"en":"Ideal for Multilingual UI Agents ensuring consistency across Korean, English, and Vietnamese strings","zh":"适用于多语言 UI 代理，确保韩语、英语和越南语字符串的一致性","ja":"マルチリンガル UI エージェントに適しており、韓国語、英語、ベトナム語の文字列の整合性を確保する","ko":"한국어, 영어, 베트남어 문자열의 일관성을 보장하는 멀티링구얼 UI 에이전트에 적합","es":"Ideal para agentes de interfaz de usuario multilingüe que garantizan la consistencia en cadenas coreanas, inglesas y vietnamitas","fr":"Idéal pour les agents d''interface utilisateur multilingues qui assurent la cohérence des chaînes coréennes, anglaises et vietnamiennes","de":"Ideal für multilinguale Benutzeroberflächenagenten, die die Konsistenz über koreanische, englische und vietnamesische Zeichenfolgen hinweg gewährleisten","pt":"Ideal para Agentes de UI Multilíngues que garantem a consistência em cadeias de caracteres coreanas, inglesas e vietnamitas","ru":"Идеально подходит для многоязычных агентов UI, обеспечивающих согласованность в корейских, английских и вьетнамских строках","ar":"مثالي لوكلاء واجهة المستخدم المتعددة اللغات التي تضمن الاتساق عبر السلاسل الكورية والإنجليزية والفيتنامية"},"recommendation":{"en":"Empowers agents to maintain UI safety by enforcing consistent key structures and avoiding hardcoded literal strings in JSON files, specifically `ko.json`, `en.json`, and `vi.json`, through the use of `lint-i18n-keys.sh` script","zh":"通过使用 `lint-i18n-keys.sh` 脚本，强制执行一致的密钥结构，避免在 JSON 文件（特别是 `ko.json`、`en.json` 和 `vi.json`）中硬编码字面字符串，从而赋予代理维护 UI 安全的能力","ja":"`lint-i18n-keys.sh` スクリプトを使用して、一貫したキー構造を適用し、JSON ファイル（特に `ko.json`、`en.json`、`vi.json`）のハードコードされたリテラル文字列を避けることで、UI の安全性を維持するエージェントの能力を強化する","ko":"`lint-i18n-keys.sh` 스크립트를 사용하여 일관된 키 구조를 적용하고 JSON 파일(특히 `ko.json`, `en.json`, `vi.json`)의 하드코딩된 리터럴 문자열을 피함으로써 UI의 안전성을 유지하는 에이전트의 능력을 강화한다","es":"Habilita a los agentes a mantener la seguridad de la interfaz de usuario mediante la aplicación de estructuras de claves consistentes y la evitación de cadenas literales codificadas en archivos JSON, específicamente `ko.json`, `en.json` y `vi.json`, a través del uso del script `lint-i18n-keys.sh`","fr":"Permet aux agents de maintenir la sécurité de l''interface utilisateur en appliquant des structures de clés cohérentes et en évitant les chaînes littérales codées en dur dans les fichiers JSON, spécifiquement `ko.json`, `en.json` et `vi.json`, grâce à l''utilisation du script `lint-i18n-keys.sh`","de":"Ermächtigt Agenten, die Sicherheit der Benutzeroberfläche durch die Durchsetzung konsistenter Schlüsselstrukturen und die Vermeidung von hartcodierten Literalzeichenfolgen in JSON-Dateien, insbesondere `ko.json`, `en.json` und `vi.json`, durch die Verwendung des Skripts `lint-i18n-keys.sh` aufrechtzuerhalten","pt":"Habilita os agentes a manter a segurança da UI aplicando estruturas de chave consistentes e evitando cadeias literais hardcoded em arquivos JSON, especificamente `ko.json`, `en.json` e `vi.json`, por meio do uso do script `lint-i18n-keys.sh`","ru":"Наделяет агентов возможностью поддерживать безопасность UI, обеспечивая согласованность ключевых структур и избегая жестко закодированных литеральных строк в файлах JSON, а именно `ko.json`, `en.json` и `vi.json`, посредством использования скрипта `lint-i18n-keys.sh`","ar":"تمكين الوكلاء من الحفاظ على سلامة واجهة المستخدم من خلال فرض بنية مفتاح متسقة وتجنب السلاسل الحرفية المحسنة في ملفات JSON، على وجه التحديد `ko.json` و `en.json` و `vi.json`، من خلال استخدام سكريبت `lint-i18n-keys.sh`"},"useCases":{"en":["Validating JSON key structures for Korean and Vietnamese translations","Automating checks for hardcoded strings in UI components","Debugging UI breaks specific to Vietnamese translations"],"zh":["验证韩语和越南语翻译的 JSON 密钥结构","自动检查 UI 组件中的硬编码字符串","调试特定于越南语翻译的 UI 中断"],"ja":["韓国語とベトナム語の翻訳の JSON キー構造を検証する","UI コンポーネントのハードコードされた文字列を自動的にチェックする","ベトナム語の翻訳に特有の UI ブレークをデバッグする"],"ko":["한국어와 베트남어 번역의 JSON 키 구조를 검증","UI 컴포넌트의 하드코딩된 문자열을 자동으로 체크","베트남어 번역에 특정한 UI 브레이크를 디버깅"],"es":["Validar las estructuras de claves JSON para las traducciones coreanas y vietnamitas","Automatizar las comprobaciones de cadenas codificadas en componentes de interfaz de usuario","Depurar las interrupciones de la interfaz de usuario específicas de las traducciones vietnamitas"],"fr":["Valider les structures de clés JSON pour les traductions coréennes et vietnamiennes","Automatiser les vérifications de chaînes codées en dur dans les composants d''interface utilisateur","Déboguer les interruptions de l''interface utilisateur spécifiques aux traductions vietnamiennes"],"de":["Validieren der JSON-Schlüsselstrukturen für koreanische und vietnamesische Übersetzungen","Automatisieren der Prüfungen von hartcodierten Zeichenfolgen in Benutzeroberflächenelementen","Fehlerbehebung bei Benutzeroberflächenfehlern, die spezifisch für vietnamesische Übersetzungen sind"],"pt":["Validar estruturas de chave JSON para traduções coreanas e vietnamitas","Automatizar verificações de cadeias hardcoded em componentes de UI","Depurar quebras de UI específicas para traduções vietnamitas"],"ru":["Проверка структуры ключей JSON для корейских и вьетнамских переводов","Автоматизация проверок на наличие жестко закодированных строк в компонентах UI","Отладка сбоев UI, специфичных для вьетнамских переводов"],"ar":["التحقق من بنية مفتاح JSON لترجمات اللغة الكورية والفيتنامية","تأتمة فحص السلاسل المحسنة في مكونات واجهة المستخدم","تصحيح أخطاء كسر واجهة المستخدم الخاصة بترجمات اللغة الفيتنامية"]},"limitations":{"en":["Requires execution of `lint-i18n-keys.sh` script","Limited to JSON file formats","Specifically designed for Korean, English, and Vietnamese language support"],"zh":["需要执行 `lint-i18n-keys.sh` 脚本","仅限 JSON 文件格式","专门为韩语、英语和越南语语言支持而设计"],"ja":["`lint-i18n-keys.sh` スクリプトの実行が必要","JSON ファイル形式のみ","韓国語、英語、ベトナム語言語サポート専用に設計"],"ko":["`lint-i18n-keys.sh` 스크립트의 실행이 필요","JSON 파일 형식만 해당","한국어, 영어, 베트남어 언어 지원을 위한 특화된 설계"],"es":["Requiere la ejecución del script `lint-i18n-keys.sh`","Limitado a formatos de archivo JSON","Diseñado específicamente para el soporte de los idiomas coreano, inglés y vietnamita"],"fr":["Nécessite l''exécution du script `lint-i18n-keys.sh`","Limité aux formats de fichiers JSON","Conçu spécifiquement pour le support des langues coréenne, anglaise et vietnamienne"],"de":["Erfordert die Ausführung des Skripts `lint-i18n-keys.sh`","Begrenzt auf JSON-Dateiformate","Speziell für die Unterstützung der Sprachen Koreanisch, Englisch und Vietnamesisch entwickelt"],"pt":["Exige a execução do script `lint-i18n-keys.sh`","Limitado a formatos de arquivo JSON","Especificamente projetado para suporte a idiomas coreano, inglês e vietnamita"],"ru":["Требует выполнения скрипта `lint-i18n-keys.sh`","Ограничен форматами файлов JSON","Специально разработан для поддержки корейского, английского и вьетнамского языков"],"ar":["يتطلب تشغيل سكريبت `lint-i18n-keys.sh`","محدود بتنسيقات ملفات JSON","صُمم خصيصًا لدعم اللغات الكورية والإنجليزية والفيتنامية"]},"version":4},"contentHash":"71cfa5b4df41eefd6119f88b88b7a49e0c9db2ca4337308164aebb55b6e401ad","qualityScore":35}');
