INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LEE-SANG-BOK/VKC-2-/vkc-i18n-ko-vi-safety', 'vkc-i18n-ko-vi-safety', 'LEE-SANG-BOK', 'VKC-2-', 'community', 'vkc-i18n-ko-vi-safety LEE-SANG-BOK VKC-2- community vkc-i18n-ko-vi-safety ensures UI safety for Korean, English, and Vietnamese strings. It helps developers maintain consistent key structures and avoid hardcoded literal strings. vkc-i18n-ko-vi-safety是一种确保AI工具国际化安全的技术规范，涉及代码检查和UI安全 vkc-i18n-ko-vi-safetyは、AIエージェントの安全性を確保するための技術規格であり、コードチェックとUI安全性を含みます vkc-i18n-ko-vi-safety는 AI 에이전트의 안전성을 보장하는 기술 규격으로 코드检查과 UI 안전성을 포함합니다 vkc-i18n-ko-vi-safety es una habilidad de seguridad para la internacionalización que ayuda a mantener la consistencia en los mensajes de usuario vkc-i18n-ko-vi-safety est une compétence de sécurité pour l''internationalisation qui aide à maintenir la cohérence dans les messages utilisateur vkc-i18n-ko-vi-safety ist eine Sicherheitsfunktion für die Internationalisierung, die dabei hilft, die Konsistenz in den Benachrichtigungen zu gewährleisten O vkc-i18n-ko-vi-safety é uma habilidade que ajuda a garantir a segurança da UI em diferentes idiomas. Ele fornece regras e verificações para manter a consistência nos arquivos de mensagens. vkc-i18n-ko-vi-safety - это навык, который помогает обеспечить безопасность UI на разных языках. Он предоставляет правила и проверки для поддержания согласованности в файлах сообщений. vkc-i18n-ko-vi-safety هو مهارة تساعد على ضمان سلامة الواجهة المستخدمة بلغات مختلفة. يوفر قواعد وفحوصات لضمان الاتساق في ملفات الرسائل. vkc-i18n-ko-vi-safety setup guide how to use vkc-i18n-ko-vi-safety what is vkc-i18n-ko-vi-safety vkc-i18n-ko-vi-safety alternative vkc-i18n-ko-vi-safety vs i18n tools vkc-i18n-ko-vi-safety install lint-i18n-keys.sh command UI safety for Vietnamese strings AI工具国际化安全 vkc-i18n-ko-vi-safety 代码检查 UI安全性 国际化安全 嵌套键结构 消息键 多语言支持 Runs lint-i18n-keys.sh to check for consistent key structures Maintains nested key structure consistency across ko.json, en.json, and vi.json Applies layout-safe padding for long Vietnamese strings Prevents shipping keys in only one of ko/vi Avoids hardcoded literal strings in components using message keys vkc-i18n-ko-vi-safety is a skill that provides guidelines for maintaining UI safety across multiple languages, including Korean, English, and Vietnamese.');
