INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('unusualify/modularous/superficial', 'superficial', 'unusualify', 'modularous', 'community', 'superficial unusualify modularous community The superficial AI Agent skill assists senior developers building modular toolkits with Laravel and Vue 3/Vuetify. It generates code following strict patterns like the Repository pattern and Service layer, specifically for the src/, vue/src/, and tests/ directories. Superficial是一个强大的工具，帮助Laravel和Vue/Vuetify开发者构建模块化的应用程序 Superficialは、LaravelとVue/Vuetify開発者がモジュラーなアプリケーションを構築するための強力なツールです Superficial은 Laravel 및 Vue/Vuetify 개발자가 모듈식 애플리케이션을 구축하는 데 도움이 되는 강력한 도구입니다 Superficial es una herramienta de desarrollo que utiliza Laravel y Vue para crear aplicaciones modulares Superficial est un outil de développement qui utilise Laravel et Vue pour créer des applications modulaires Superficial ist ein Entwicklungstool, das Laravel und Vue verwendet, um modulare Anwendungen zu erstellen O Superficial é uma ferramenta para desenvolvedores Laravel e Vue, que utiliza padrões de repositório e arquitetura limpa Superficial - это инструмент для разработчиков Laravel и Vue, который использует шаблоны репозитория и чистой архитектуры السطحي هو أداة لمطوري Laravel و Vue، التي تستخدم أنماط المستودع والهندسة المعمارية النظيفة superficial AI Agent skill how to use superficial Laravel superficial vs other Laravel tools superficial install guide superficial setup Laravel Vue what is superficial AI Laravel Repository pattern AI Vue Vuetify AI code generation Superficial Laravel Vue/Vuetify Repository模式 服务层业务逻辑 Traits Base类 模块化开发 AIエージェント Generates Laravel-specific code using service containers, Eloquent, and traits Implements the Repository pattern and Clean Architecture principles Creates Vue 3 components with Vuetify and the Composition API Operates within defined src/, vue/src/, and tests/ directory structures Utilizes base classes and traits for code reuse and extensibility superficial is an AI Agent skill designed for senior software developers working on a Laravel and Vue/Vuetify modular toolkit. It provides expert assistance by generating code that adheres to conventions like the Repository pattern, service containers, Eloquent traits, and Vue 3 composition API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Clement-ccy/PalpitatingForever/docs-writer', 'community', 'Clement-ccy', 'PalpitatingForever', 'Clement-ccy/PalpitatingForever', 'docs-writer', 0, 0, 35, '2026-03-08T01:57:15.464Z', '2026-03-08T02:09:19.705Z', '35dd9d9d254dcf1af7239054fb4a79c7511e69c3611efce7070f11a8b51f51fb', '{"id":"Clement-ccy/PalpitatingForever/docs-writer","name":"docs-writer","description":{"en":"The docs-writer skill enables developers to produce high-quality documentation for the Gemini CLI project, adhering to strict guidelines and contribution processes. It benefits developers and technical writers seeking to create accurate and clear documentation.","zh":"docs-writer技能是专为Gemini CLI项目设计的技术文档编写工具，帮助开发者创建准确、清晰、符合项目标准的文档","ja":"docs-writer AIエージェントは、Gemini CLIプロジェクト用の技術文書を作成するためのエキスパート向けツールです","ko":"docs-writer는 Gemini CLI 프로젝트를 위한 기술文档을 작성하기 위한 전문가용 도구입니다","es":"El skill docs-writer es un agente de IA especializado en generar documentación técnica para el proyecto Gemini CLI. Sigue un proceso estricto basado en CONTRIBUTING.md y se adhiere a la Google Developer Documentation Style Guide para garantizar claridad y coherencia.","fr":"La compétence docs-writer est un agent IA spécialisé dans la génération de documentation technique pour le projet Gemini CLI. Il suit un processus strict basé sur CONTRIBUTING.md et adhère au Google Developer Documentation Style Guide pour garantir clarté et cohérence.","de":"Die Skill docs-writer ist ein KI-Agent, der speziell für die Erstellung technischer Dokumentation für das Gemini CLI-Projekt entwickelt wurde. Er folgt einem strengen Prozess aus CONTRIBUTING.md und hält sich an den Google Developer Documentation Style Guide.","pt":"O docs-writer é uma habilidade de escrita técnica para o projeto Gemini CLI, que visa produzir documentação precisa e clara, seguindo as diretrizes do Google Developer Documentation Style Guide","ru":"ИИ Агент docs-writer - это навык технического письма для проекта Gemini CLI, целью которого является создание точной и ясной документации, соответствующей руководству по стилю документации Google","ar":"docs-writer هو مهارة كتابة تقنية لمشروع Gemini CLI ، هدفها إنتاج وثائق دقيقة وواضحة ، متبعًا إرشادات نمط توثيق مطور جوجل"},"seo":{"title":{"en":"docs-writer: Technical Writing Setup Guide | AI Agent Skill","zh":"docs-writer 技术文档编写指南","ja":"docs-writer AIエージェントのセットアップガイド","ko":"docs-writer 개발자 문서 작성 가이드","es":"docs-writer: Guía de configuración para documentación téc...","fr":"docs-writer : Guide de configuration pour la documentatio...","de":"docs-writer: Setup-Anleitung für KI-gestützte Technische ...","pt":"Guia de Configuração do docs-writer para Desenvolvedores","ru":"Настройка ИИ Агента docs-writer: Лучшие Практики","ar":"دليل الإعداد الخاص ب docs-writer للأدوات الذكية"},"description":{"en":"Discover how to create accurate documentation with docs-writer, following the Gemini CLI project''s standards and Google Developer Documentation Style Guide -...","zh":"了解docs-writer技能，掌握技术文档编写的最佳实践和Google Developer Documentation Style Guide","ja":"docs-writer AIエージェントを使用して、高質の技術文書を作成する方法を学ぶ","ko":"docs-writer를 사용하여 개발자 문서를 작성하고 Gemini CLI 프로젝트의 표준을 준수하는 방법","es":"Automatiza la escritura técnica para Gemini CLI con el agente de IA docs-writer. Aprende a configurarlo para generar documentación precisa siguiendo las guía...","fr":"Automatisez la rédaction technique pour Gemini CLI avec l''agent IA docs-writer. Configurez-le pour générer une documentation précise conforme au guide de sty...","de":"Automatisieren Sie technisches Schreiben für Gemini CLI mit dem KI-Agenten docs-writer. Richten Sie ihn für präzise Dokumentation nach Google Style Guide ein.","pt":"Aprenda a configurar o docs-writer para criar documentação de alta qualidade para o projeto Gemini CLI, seguindo as diretrizes do Google Developer Documentat...","ru":"Узнайте, как настроить ИИ Агент docs-writer для создания качественной документации для проекта Gemini CLI, соблюдая руководство по стилю документации Google","ar":"تعلم كيفية إعداد docs-writer لإنشاء وثائق عالية الجودة لمشروع Gemini CLI ، متبعًا إرشادات نمط توثيق مطور جوجل"},"definition":{"en":"docs-writer is a technical writing skill for the Gemini CLI project, focused on producing accurate, clear, and consistent documentation according to the project''s standards and style guidelines.","zh":"docs-writer是Gemini CLI项目的技术文档编写工具，用于创建准确、清晰的文档","ja":"docs-writerはGemini CLIプロジェクト用の技術文書作成ツールであり、正確で明確な文書を作成するために使用されます","ko":"docs-writer는 Gemini CLI 프로젝트를 위한 기술문서 작성 도구로, 정확하고 명확한 문서를 작성하기 위해 사용됩니다","es":"docs-writer es un agente de IA configurado como escritor técnico experto para el proyecto Gemini CLI. Su función principal es producir documentación que sea precisa, clara y consistente, siguiendo un proceso de contribución definido y las guías de estilo de Google para desarrolladores.","fr":"docs-writer est un agent IA configuré en tant que rédacteur technique expert pour le projet Gemini CLI. Sa fonction principale est de produire une documentation précise, claire et cohérente, en suivant un processus de contribution défini et le guide de style Google pour les développeurs.","de":"docs-writer ist ein KI-Agent, der als technischer Experte für das Gemini CLI-Projekt konfiguriert ist. Seine Hauptaufgabe ist die Erstellung präziser, klarer und konsistenter Dokumentation gemäß einem definierten Beitragsprozess und dem Google Developer Documentation Style Guide.","pt":"O docs-writer é uma habilidade de escrita técnica que cria documentação de alta qualidade para o projeto Gemini CLI","ru":"ИИ Агент docs-writer - это навык технического письма, создающий качественную документацию для проекта Gemini CLI","ar":"docs-writer هو مهارة كتابة تقنية لإنشاء وثائق عالية الجودة لمشروع Gemini CLI"},"features":{"en":["Adheres to the documentation contribution process outlined in CONTRIBUTING.md","Follows the style guidelines from the Google Developer Documentation Style Guide","Enables clarification of user documentation requests","Supports creation of plans for documentation development","Aligns with the Gemini CLI project''s standards for documentation"],"zh":["遵循Google Developer Documentation Style Guide","符合Gemini CLI项目的文档贡献流程","创建准确、清晰、符合项目标准的文档","支持CLI项目的文档开发","确保文档的一致性和质量"],"ja":["Google Developer Documentation Style Guideに準拠","Gemini CLIプロジェクトのドキュメント貢献プロセスに従う","正確で明確なドキュメントを作成","CLIプロジェクトのドキュメント開発をサポート","ドキュメントの一貫性と品質を確保"],"ko":["Google Developer Documentation Style Guide를 따름","Gemini CLI 프로젝트의 문서 기여 프로세스에従う","정확하고 명확한 문서를 작성","CLI 프로젝트의 문서 개발을 지원","문서의 일관성과 품질을 보장"],"es":["Escritor técnico especializado para Gemini CLI","Adhesión estricta a CONTRIBUTING.md para el proceso de documentación","Cumplimiento de la Google Developer Documentation Style Guide","Enfoque en documentación precisa, clara y coherente","Clarificación de solicitudes y creación de un plan inicial"],"fr":["Rédacteur technique spécialisé pour Gemini CLI","Adhésion stricte à CONTRIBUTING.md pour le processus de documentation","Conformité au Google Developer Documentation Style Guide","Production d''une documentation précise, claire et cohérente","Clarification des demandes et création d''un plan initial"],"de":["Technischer Experte für die Gemini CLI","Strikte Einhaltung von CONTRIBUTING.md für Dokumentationsprozesse","Einhaltung des Google Developer Documentation Style Guide","Fokus auf präzise, klare und konsistente Dokumentation","Anfragenklärung und Erstellung eines initialen Plans"],"pt":["Adere às diretrizes do Google Developer Documentation Style Guide","Segue o processo de contribuição de documentação do projeto Gemini CLI","Cria documentação precisa e clara para o projeto Gemini CLI","Utiliza a CLI do Gemini para gerar documentação","Segue as instruções do arquivo CONTRIBUTING.md"],"ru":["Соблюдает руководство по стилю документации Google","Следует процессу внесения вклада в документацию проекта Gemini CLI","Создает точную и ясную документацию для проекта Gemini CLI","Использует CLI Gemini для генерации документации","Следует инструкциям файла CONTRIBUTING.md"],"ar":["يتابع إرشادات نمط توثيق مطور جوجل","يتابع عملية المساهمة في توثيق مشروع Gemini CLI","ينشئ وثائق دقيقة وواضحة لمشروع Gemini CLI","يستخدم واجهة سطر الأوامر في جيميني لإنشاء الوثائق","يتابع الإرشادات الموجودة في ملف CONTRIBUTING.md"]},"keywords":{"en":["how to use docs-writer","docs-writer setup guide","what is docs-writer","docs-writer alternative","docs-writer vs google documentation","docs-writer install","gemini cli documentation","technical writing for ai agents","docs-writer best practices"],"zh":["docs-writer","技术文档编写","Gemini CLI","Google Developer Documentation Style Guide","文档贡献流程","CLI项目文档开发","技术文档工具","AIエージェント"],"ja":["docs-writer","技術文書作成","Gemini CLI","Google Developer Documentation Style Guide","ドキュメント貢献プロセス","CLIプロジェクトのドキュメント開発","技術文書ツール","AIエージェント"],"ko":["docs-writer","개발자 문서 작성","Gemini CLI","Google Developer Documentation Style Guide","문서 기여 프로세스","CLI 프로젝트 문서 개발","기술문서 작성 도구","AI 에이전트"],"es":["agente de IA docs-writer","automatizar documentación técnica","Gemini CLI documentación","Google Developer Documentation Style Guide","CONTRIBUTING.md proceso","escritor técnico con IA","guía configuración docs-writer"],"fr":["agent IA docs-writer","automatiser documentation technique","Gemini CLI documentation","Google Developer Documentation Style Guide","processus CONTRIBUTING.md","rédacteur technique IA","guide configuration docs-writer"],"de":["KI-Agent docs-writer","technische Dokumentation automatisieren","Gemini CLI Dokumentation","Google Developer Documentation Style Guide","CONTRIBUTING.md Prozess","technischer Autor KI","docs-writer Setup Anleitung"],"pt":["docs-writer","Gemini CLI","documentação técnica","Google Developer Documentation Style Guide","CLI","contribuição de documentação","desenvolvedores","ferramentas de desenvolvimento"],"ru":["ИИ Агент docs-writer","Gemini CLI","техническая документация","руководство по стилю документации Google","CLI","внесение вклада в документацию","разработчики","инструменты разработки","ИИ Агенты"],"ar":["docs-writer","جيميني سي ال آي","توثيق تقني","إرشادات نمط توثيق مطور جوجل","واجهة سطر الأوامر","مساهمة في التوثيق","مطورون","أدوات التطوير","الأدوات الذكية"]}},"owner":"Clement-ccy","repo":"PalpitatingForever","repoPath":"Clement-ccy/PalpitatingForever","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.464Z","topics":[],"category":"community","skillMd":{"name":"docs-writer","description":"","bodyPreview":"# `docs-writer` skill instructions\n\nAs an expert technical writer for the Gemini CLI project, your goal is to\nproduce documentation that is accurate, clear, and consistent with the project''s\nstandards. You must adhere to the documentation contribution process outlined in\n`CONTRIBUTING.md` and the style guidelines from the Google Developer\nDocumentation Style Guide.\n\n## Step 1: Understand the goal and create a plan\n\n1.  **Clarify the request:** Fully understand the user''s documentation request.","body":"# `docs-writer` skill instructions\n\nAs an expert technical writer for the Gemini CLI project, your goal is to\nproduce documentation that is accurate, clear, and consistent with the project''s\nstandards. You must adhere to the documentation contribution process outlined in\n`CONTRIBUTING.md` and the style guidelines from the Google Developer\nDocumentation Style Guide.\n\n## Step 1: Understand the goal and create a plan\n\n1.  **Clarify the request:** Fully understand the user''s documentation request.\n    Identify the core feature, command, or concept that needs to be documented.\n2.  **Ask questions:** If the request is ambiguous or lacks detail, ask\n    clarifying questions. Don''t invent or assume. It''s better to ask than to\n    write incorrect documentation.\n3.  **Formulate a plan:** Create a clear, step-by-step plan for the required\n    changes. If requested or necessary, store this plan in a temporary file or\n    a file identified by the user.\n\n## Step 2: Investigate and gather information\n\n1.  **Read the code:** Thoroughly examine the relevant codebase, primarily within\n    the `packages/` directory, to ensure your writing is backed by the\n    implementation.\n2.  **Identify files:** Locate the specific documentation files in the `docs/`\n    directory that need to be modified. Always read the latest\n    version of a file before you begin to edit it.\n3.  **Check for connections:** Consider related documentation. If you add a new\n    page, check if `docs/sidebar.json` needs to be updated. If you change a\n    command''s behavior, check for other pages that reference it. Make sure links\n    in these pages are up to date.\n\n## Step 3: Draft the documentation\n\n1.  **Follow the style guide:**\n    - Text must be wrapped at 80 characters. Exceptions are long links or\n      tables, unless otherwise stated by the user.\n    - Use sentence case for headings, titles, and bolded text.\n    - Address the reader as \"you\".\n    - Use contractions to keep the tone more casual.\n    - Use simple, direct, and active language and the present tense.\n    - Keep paragraphs short and focused.\n    - Always refer to Gemini CLI as `Gemini CLI`, never `the Gemini CLI`.\n2.  **Use `replace` and `write_file`:** Use the file system tools to apply your\n    planned changes precisely. For small edits, `replace` is preferred. For new\n    files or large rewrites, `write_file` is more appropriate.\n\n## Step 4: Verify and finalize\n\n1.  **Review your work:** After making changes, re-read the files to ensure the\n    documentation is well-formatted, content is correct and based on existing\n    code, and that all new links are valid.\n2.  **Offer to run npm format:** Once all changes are complete and the user\n    confirms they have no more requests, offer to run the project''s formatting\n    script to ensure consistency. Propose the following command:\n    `npm run format`\n"},"lastSynced":"2026-03-08T02:09:19.705Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing to generate high-quality documentation for CLI projects.","zh":"非常适合需要为CLI项目生成高质量文档的技术写作Agent。","ja":"CLIプロジェクトの高品質なドキュメント生成を必要とする技術文書作成エージェントに最適です。","ko":"CLI 프로젝트를 위한 고품질 문서 생성을 필요로 하는 기술 문서 작성 에이전트에 완벽합니다.","es":"Ideal para agentes de redacción técnica que necesitan generar documentación de alta calidad para proyectos CLI.","fr":"Parfait pour les agents de rédaction technique ayant besoin de générer une documentation de haute qualité pour des projets CLI.","de":"Perfekt für technische Redaktionsagenten, die hochwertige Dokumentationen für CLI-Projekte erstellen müssen.","pt":"Perfeito para Agentes de Redação Técnica que precisam gerar documentação de alta qualidade para projetos CLI.","ru":"Идеально подходит для технических писателей-агентов, которым необходимо создавать высококачественную документацию для CLI проектов.","ar":"مثالي لوكلاء الكتابة الفنية الذين يحتاجون إلى إنشاء وثائق عالية الجودة لمشاريع CLI."},"recommendation":{"en":"Empowers agents to produce accurate and clear documentation adhering to strict guidelines and contribution processes, utilizing the Google Developer Documentation Style Guide and following the documentation contribution process outlined in CONTRIBUTING.md.","zh":"使Agent能够生成准确清晰的文档，严格遵守指南和贡献流程，利用Google开发者文档风格指南并遵循CONTRIBUTING.md中概述的文档贡献流程。","ja":"Google Developer Documentation Style Guideを利用し、CONTRIBUTING.mdで概説されたドキュメント貢献プロセスに従うことで、エージェントが厳格なガイドラインと貢献プロセスに準拠した正確で明確なドキュメントを作成することを可能にします。","ko":"Google 개발자 문서 스타일 가이드를 활용하고 CONTRIBUTING.md에 명시된 문서 기여 프로세스를 따르며, 에이전트가 엄격한 가이드라인과 기여 프로세스를 준수하는 정확하고 명확한 문서를 생성할 수 있도록 합니다.","es":"Capacita a los agentes para producir documentación precisa y clara que se adhiera a pautas estrictas y procesos de contribución, utilizando la Guía de estilo de documentación para desarrolladores de Google y siguiendo el proceso de contribución a la documentación descrito en CONTRIBUTING.md.","fr":"Permet aux agents de produire une documentation précise et claire respectant des directives strictes et des processus de contribution, en utilisant le Google Developer Documentation Style Guide et en suivant le processus de contribution documentaire décrit dans CONTRIBUTING.md.","de":"Ermöglicht es Agenten, präzise und klare Dokumentationen zu erstellen, die strikten Richtlinien und Beitragsprozessen entsprechen, unter Verwendung des Google Developer Documentation Style Guide und unter Befolgung des in CONTRIBUTING.md beschriebenen Dokumentationsbeitragsprozesses.","pt":"Capacita os agentes a produzir documentação precisa e clara, aderindo a diretrizes rigorosas e processos de contribuição, utilizando o Google Developer Documentation Style Guide e seguindo o processo de contribuição de documentação descrito em CONTRIBUTING.md.","ru":"Позволяет агентам создавать точную и понятную документацию, соответствующую строгим рекомендациям и процессам вклада, с использованием Google Developer Documentation Style Guide и соблюдением процесса внесения вклада в документацию, изложенного в CONTRIBUTING.md.","ar":"يمكّن الوكلاء من إنتاج وثائق دقيقة وواضحة تلتزم بإرشادات صارمة وعمليات المساهمة، باستخدام دليل نمط وثائق مطور Google واتباع عملية مساهمة الوثائق الموضحة في CONTRIBUTING.md."},"useCases":{"en":["Generating documentation for CLI commands","Creating user manuals for technical projects","Validating documentation against project standards"],"zh":["为CLI命令生成文档","为技术项目创建用户手册","根据项目标准验证文档"],"ja":["CLIコマンドのドキュメント生成","技術プロジェクトのユーザーマニュアル作成","プロジェクト標準に基づくドキュメントの検証"],"ko":["CLI 명령어에 대한 문서 생성","기술 프로젝트를 위한 사용자 매뉴얼 작성","프로젝트 표준에 대한 문서 검증"],"es":["Generar documentación para comandos CLI","Crear manuales de usuario para proyectos técnicos","Validar la documentación según los estándares del proyecto"],"fr":["Générer une documentation pour les commandes CLI","Créer des manuels utilisateur pour des projets techniques","Valider la documentation par rapport aux standards du projet"],"de":["Erstellen von Dokumentationen für CLI-Befehle","Erstellen von Benutzerhandbüchern für technische Projekte","Validieren von Dokumentationen anhand von Projektstandards"],"pt":["Geração de documentação para comandos CLI","Criação de manuais do usuário para projetos técnicos","Validação de documentação em relação aos padrões do projeto"],"ru":["Создание документации для CLI команд","Создание пользовательских руководств для технических проектов","Проверка документации на соответствие стандартам проекта"],"ar":["إنشاء وثائق لأوامر CLI","إنشاء كتيبات المستخدم للمشاريع الفنية","التحقق من صحة الوثائق مقابل معايير المشروع"]},"limitations":{"en":["Requires adherence to CONTRIBUTING.md guidelines","Limited to Gemini CLI project documentation"],"zh":["需要遵守CONTRIBUTING.md指南","仅限于Gemini CLI项目文档"],"ja":["CONTRIBUTING.mdガイドラインの遵守が必要","Gemini CLIプロジェクトのドキュメントに限定"],"ko":["CONTRIBUTING.md 가이드라인 준수 필요","Gemini CLI 프로젝트 문서로 제한됨"],"es":["Requiere la adhesión a las pautas de CONTRIBUTING.md","Limitado a la documentación del proyecto Gemini CLI"],"fr":["Nécessite le respect des directives de CONTRIBUTING.md","Limité à la documentation du projet Gemini CLI"],"de":["Erfordert die Einhaltung der CONTRIBUTING.md-Richtlinien","Beschränkt sich auf die Dokumentation des Gemini CLI-Projekts"],"pt":["Requer adesão às diretrizes do CONTRIBUTING.md","Limitado à documentação do projeto Gemini CLI"],"ru":["Требует соблюдения рекомендаций CONTRIBUTING.md","Ограничено документацией проекта Gemini CLI"],"ar":["يتطلب الالتزام بإرشادات CONTRIBUTING.md","مقتصر على وثائق مشروع Gemini CLI"]},"version":4},"contentHash":"35dd9d9d254dcf1af7239054fb4a79c7511e69c3611efce7070f11a8b51f51fb","qualityScore":35}');
