INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Clement-ccy/PalpitatingForever/docs-writer', 'docs-writer', 'Clement-ccy', 'PalpitatingForever', 'community', 'docs-writer Clement-ccy PalpitatingForever community The docs-writer skill enables developers to produce high-quality documentation for the Gemini CLI project, adhering to strict guidelines and contribution processes. It benefits developers and technical writers seeking to create accurate and clear documentation. docs-writer技能是专为Gemini CLI项目设计的技术文档编写工具，帮助开发者创建准确、清晰、符合项目标准的文档 docs-writer AIエージェントは、Gemini CLIプロジェクト用の技術文書を作成するためのエキスパート向けツールです docs-writer는 Gemini CLI 프로젝트를 위한 기술文档을 작성하기 위한 전문가용 도구입니다 El skill docs-writer es un agente de IA especializado en generar documentación técnica para el proyecto Gemini CLI. Sigue un proceso estricto basado en CONTRIBUTING.md y se adhiere a la Google Developer Documentation Style Guide para garantizar claridad y coherencia. La compétence docs-writer est un agent IA spécialisé dans la génération de documentation technique pour le projet Gemini CLI. Il suit un processus strict basé sur CONTRIBUTING.md et adhère au Google Developer Documentation Style Guide pour garantir clarté et cohérence. Die Skill docs-writer ist ein KI-Agent, der speziell für die Erstellung technischer Dokumentation für das Gemini CLI-Projekt entwickelt wurde. Er folgt einem strengen Prozess aus CONTRIBUTING.md und hält sich an den Google Developer Documentation Style Guide. O docs-writer é uma habilidade de escrita técnica para o projeto Gemini CLI, que visa produzir documentação precisa e clara, seguindo as diretrizes do Google Developer Documentation Style Guide ИИ Агент docs-writer - это навык технического письма для проекта Gemini CLI, целью которого является создание точной и ясной документации, соответствующей руководству по стилю документации Google docs-writer هو مهارة كتابة تقنية لمشروع Gemini CLI ، هدفها إنتاج وثائق دقيقة وواضحة ، متبعًا إرشادات نمط توثيق مطور جوجل how to use docs-writer docs-writer setup guide what is docs-writer docs-writer alternative docs-writer vs google documentation docs-writer install gemini cli documentation technical writing for ai agents docs-writer best practices docs-writer 技术文档编写 Gemini CLI Google Developer Documentation Style Guide 文档贡献流程 CLI项目文档开发 技术文档工具 AIエージェント Adheres to the documentation contribution process outlined in CONTRIBUTING.md Follows the style guidelines from the Google Developer Documentation Style Guide Enables clarification of user documentation requests Supports creation of plans for documentation development Aligns with the Gemini CLI project''s standards for documentation docs-writer is a technical writing skill for the Gemini CLI project, focused on producing accurate, clear, and consistent documentation according to the project''s standards and style guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eKoh951/hytale-gg/zod', 'community', 'eKoh951', 'hytale-gg', 'eKoh951/hytale-gg', 'zod', 0, 0, 35, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:25.514Z', '245fc4ab7341a8ac0864c9535e2a6d782aaf012ba6975a36cd51240bcf82e443', '{"id":"eKoh951/hytale-gg/zod","name":"zod","description":{"en":"Zod provides a comprehensive schema validation guide for TypeScript applications, offering 43 rules across 8 categories. It helps developers write new Zod schemas and handle validation errors","zh":"Zod 是一个 TypeScript 应用中的模式验证库，提供 43 条规则和 8 个类别来优化代码生成和自动重构","ja":"Zod は、TypeScript アプリケーションのスキーマ検証を提供するライブラリで、43 のルールと 8 つのカテゴリを備えています","ko":"Zod는 TypeScript 애플리케이션의 스키마 유효성 검사를 제공하는 라이브러리로 43개의 규칙과 8개의 카테고리가 있습니다","es":"Zod es una herramienta de validación de esquemas para TypeScript que ofrece 43 reglas en 8 categorías para garantizar la precisión de los datos","fr":"Zod est un outil de validation de schémas pour TypeScript qui propose 43 règles dans 8 catégories pour garantir la précision des données","de":"Zod ist ein Schema-Validierungstool für TypeScript, das 43 Regeln in 8 Kategorien bietet, um die Genauigkeit der Daten zu gewährleisten","pt":"Zod é uma biblioteca de validação de esquemas para aplicações TypeScript. Este guia apresenta as melhores práticas para configurar Zod.","ru":"Zod - это библиотека для валидации схем в приложениях TypeScript. Это руководство содержит лучшие практики для настройки Zod.","ar":"Zod هو مكتبة للتحقق من صحة مخططات البيانات في تطبيقات TypeScript. هذا الدليل يقدم أفضل الممارسات لإعداد Zod."},"seo":{"title":{"en":"Zod: Comprehensive Schema Validation Guide for TypeScript...","zh":"Zod 最佳实践指南 - TypeScript 应用中的模式验证","ja":"Zod ベストプラクティスガイド - TypeScript アプリケーションのスキーマ検証","ko":"Zod 최적화 가이드 - TypeScript 애플리케이션의 스키마 유효성 검사","es":"Guía de configuración de Zod para validación de esquemas ...","fr":"Guide de mise en place de Zod pour la validation de schém...","de":"Zod-Setup-Leitfaden für Schema-Validierung in TypeScript-...","pt":"Guia de Configuração Zod: Melhores Práticas para Validaçã...","ru":"ИИ Агенты: Настройка Zod - Руководство по валидации схем","ar":"إعداد Zod: دليل أفضل الممارسات للتحقق من صحة مخططات البيانات"},"description":{"en":"Unlock the full potential of Zod with expert best practices and automated refactoring. Learn how to write efficient schemas and handle validation errors","zh":"了解 Zod 的 43 条规则和 8 个类别，优化您的 TypeScript 应用中的模式验证和代码生成","ja":"Zod の 43 のルールと 8 つのカテゴリをマスターし、TypeScript アプリケーションのスキーマ検証とコード生成を最適化","ko":"Zod의 43개 규칙과 8개 카테고리를 배우고 TypeScript 애플리케이션의 스키마 유효성 검사 및 코드 생성을 최적화","es":"Aprende a utilizar Zod para validar esquemas en TypeScript con nuestra guía completa, que cubre 43 reglas en 8 categorías","fr":"Découvrez comment utiliser Zod pour valider les schémas dans les applications TypeScript avec notre guide complet, qui couvre 43 règles dans 8 catégories","de":"Erfahren Sie, wie Sie Zod verwenden, um Schemata in TypeScript-Anwendungen zu validieren, mit unserer umfassenden Anleitung, die 43 Regeln in 8 Kategorien ab...","pt":"Aprenda a configurar Zod para validação de esquemas em aplicações TypeScript com nosso guia de melhores práticas","ru":"Настройте Zod для валидации схем в приложениях TypeScript с помощью нашего руководства","ar":"تعلم كيفية إعداد Zod للتحقق من صحة مخططات البيانات في تطبيقات TypeScript باستخدام دليل أفضل الممارسات"},"definition":{"en":"Zod is a TypeScript-based schema validation library that provides a set of rules and guidelines for writing efficient and effective schemas","zh":"Zod 是一个 TypeScript 库，用于模式验证和代码生成","ja":"Zod は、TypeScript のスキーマ検証とコード生成を提供するライブラリです","ko":"Zod는 TypeScript의 스키마 유효성 검사 및 코드 생성을 제공하는 라이브러리입니다","es":"Zod es una biblioteca de validación de esquemas para TypeScript que permite la validación automática de datos","fr":"Zod est une bibliothèque de validation de schémas pour TypeScript qui permet la validation automatique des données","de":"Zod ist eine Bibliothek für die Validierung von Schemata in TypeScript, die die automatische Validierung von Daten ermöglicht","pt":"Zod é uma biblioteca de validação de esquemas para TypeScript que fornece recursos para validação de dados","ru":"Zod - это библиотека для валидации схем в TypeScript, которая предоставляет средства для проверки данных","ar":"Zod هو مكتبة للتحقق من صحة مخططات البيانات في TypeScript التي توفر أدوات للتحقق من البيانات"},"features":{"en":["Provides 43 rules across 8 categories for comprehensive schema validation","Supports automated refactoring and code generation","Offers type inference with z.infer for improved schema accuracy","Handles validation errors for user feedback and composing complex object schemas","Allows for refinements and transforms to optimize schema performance","Includes guidelines for choosing between parse() and safeParse() functions"],"zh":["提供 43 条规则和 8 个类别来优化代码生成和自动重构","支持 parse() 和 safeParse() 两种模式验证方法","实现类型推断和 z.infer","处理验证错误以提供用户反馈","支持复杂对象模式的组合","提供精炼和转换功能"],"ja":["43 のルールと 8 つのカテゴリを提供してコード生成と自動リファクタリングを最適化","parse() と safeParse() の 2 つのスキーマ検証方法をサポート","型推論と z.infer を実現","検証エラーを処理してユーザーフィードバックを提供","複雑なオブジェクトスキーマの構成をサポート","精製と変換機能を提供"],"ko":["43개의 규칙과 8개의 카테고리를 제공하여 코드 생성과 자동 리팩토링을 최적화","parse()와 safeParse()의 2가지 스키마 유효성 검사 방법을 지원","타입 추론과 z.infer를 구현","유효성 검사 오류를 처리하여 사용자 피드백을 제공","복잡한 객체 스키마의 구성 및 최적화를 지원","정제 및 변환 기능을 제공"],"es":["Validación automática de esquemas con 43 reglas","Compatibilidad con type inference y z.infer","Manejo de errores de validación para retroalimentación del usuario","Composición de esquemas de objetos complejos","Uso de refinamientos y transformaciones","Optimización de la validación de datos"],"fr":["Validation automatique des schémas avec 43 règles","Compatibilité avec l''inférence de type et z.infer","Gestion des erreurs de validation pour la rétroaction de l''utilisateur","Composition de schémas d''objets complexes","Utilisation de raffinements et de transformations","Optimisation de la validation des données"],"de":["Automatische Validierung von Schemata mit 43 Regeln","Kompatibilität mit Typinferenz und z.infer","Handhabung von Validierungsfehlern für Benutzerfeedback","Zusammensetzung von komplexen Objektschemata","Verwendung von Verfeinerungen und Transformationen","Optimierung der Datenvalidierung"],"pt":["Validação de esquemas com 43 regras em 8 categorias","Suporte a parse() e safeParse() para validação de dados","Recursos de inferência de tipo com z.infer","Manipulação de erros de validação para feedback de usuário","Criação de esquemas de objetos complexos","Uso de refinamentos e transformações"],"ru":["Валидация схем с 43 правилами в 8 категориях","Поддержка parse() и safeParse() для проверки данных","Возможности вывода типов с z.infer","Обработка ошибок валидации для обратной связи пользователя","Создание сложных объектных схем","Использование уточнений и преобразований"],"ar":["التحقق من صحة مخططات البيانات مع 43 قاعدة في 8 فئات","دعم parse() و safeParse() للتحقق من البيانات","ميزات استنتاج النوع مع z.infer","تعامل مع أخطاء التحقق من الصحة لتعليقات المستخدم","إنشاء مخططات كائنية معقدة","استخدام التخصيصات والتحويلات"]},"keywords":{"en":["how to use zod","zod best practices","zod vs joi","zod install","zod setup guide","zod schema validation","zod type inference","zod error handling","zod typescript integration"],"zh":["Zod","TypeScript","模式验证","代码生成","自动重构","parse()","safeParse()","类型推断","z.infer"],"ja":["Zod","TypeScript","スキーマ検証","コード生成","自動リファクタリング","parse()","safeParse()","型推論","z.infer"],"ko":["Zod","TypeScript","스키마 유효성 검사","코드 생성","자동 리팩토링","parse()","safeParse()","타입 추론","z.infer"],"es":["zod","validación de esquemas","typescript","type inference","z.infer","errores de validación","composición de esquemas","refinamientos y transformaciones","optimización de la validación de datos"],"fr":["zod","validation de schémas","typescript","inférence de type","z.infer","erreurs de validation","composition de schémas","raffinements et transformations","optimisation de la validation des données"],"de":["zod","schema-validierung","typescript","typinferenz","z.infer","validierungsfehler","zusammensetzung von schemata","verfeinerungen und transformationen","optimierung der datenvalidierung"],"pt":["Zod","validação de esquemas","TypeScript","parse()","safeParse()","z.infer","erros de validação","esquemas de objetos complexos","refinamentos","transformações"],"ru":["Zod","валидация схем","TypeScript","parse()","safeParse()","z.infer","ошибки валидации","сложные объектные схемы","уточнения","преобразования"],"ar":["Zod","التحقق من صحة مخططات البيانات","TypeScript","parse()","safeParse()","z.infer","أخطاء التحقق من الصحة","مخططات كائنية معقدة","التخصيصات","التحويلات"]}},"owner":"eKoh951","repo":"hytale-gg","repoPath":"eKoh951/hytale-gg","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.466Z","topics":[],"category":"community","skillMd":{"name":"zod","description":"Zod schema validation best practices for type safety, parsing, and error handling. This skill should be used when defining z.object schemas, using z.string validations, safeParse, or z.infer. This skill does NOT cover React Hook Form integration patterns (use react-hook-form skill) or OpenAPI client generation (use orval skill).","bodyPreview":"# Zod Best Practices\n\nComprehensive schema validation guide for Zod in TypeScript applications. Contains 43 rules across 8 categories, prioritized by impact to guide automated refactoring and code generation.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing new Zod schemas\n- Choosing between parse() and safeParse()\n- Implementing type inference with z.infer\n- Handling validation errors for user feedback\n- Composing complex object schemas\n- Using refinements and transforms\n- Optimizi","body":"# Zod Best Practices\n\nComprehensive schema validation guide for Zod in TypeScript applications. Contains 43 rules across 8 categories, prioritized by impact to guide automated refactoring and code generation.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing new Zod schemas\n- Choosing between parse() and safeParse()\n- Implementing type inference with z.infer\n- Handling validation errors for user feedback\n- Composing complex object schemas\n- Using refinements and transforms\n- Optimizing bundle size and validation performance\n- Reviewing Zod code for best practices\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Schema Definition | CRITICAL | `schema-` |\n| 2 | Parsing & Validation | CRITICAL | `parse-` |\n| 3 | Type Inference | HIGH | `type-` |\n| 4 | Error Handling | HIGH | `error-` |\n| 5 | Object Schemas | MEDIUM-HIGH | `object-` |\n| 6 | Schema Composition | MEDIUM | `compose-` |\n| 7 | Refinements & Transforms | MEDIUM | `refine-` |\n| 8 | Performance & Bundle | LOW-MEDIUM | `perf-` |\n\n## Quick Reference\n\n### 1. Schema Definition (CRITICAL)\n\n- `schema-use-primitives-correctly` - Use correct primitive schemas for each type\n- `schema-use-unknown-not-any` - Use z.unknown() instead of z.any() for type safety\n- `schema-avoid-optional-abuse` - Avoid overusing optional fields\n- `schema-string-validations` - Apply string validations at schema definition\n- `schema-use-enums` - Use enums for fixed string values\n- `schema-coercion-for-form-data` - Use coercion for form and query data\n\n### 2. Parsing & Validation (CRITICAL)\n\n- `parse-use-safeparse` - Use safeParse() for user input\n- `parse-async-for-async-refinements` - Use parseAsync for async refinements\n- `parse-handle-all-issues` - Handle all validation issues not just first\n- `parse-validate-early` - Validate at system boundaries\n- `parse-avoid-double-validation` - Avoid validating same data twice\n- `parse-never-trust-json` - Never trust JSON.parse output\n\n### 3. Type Inference (HIGH)\n\n- `type-use-z-infer` - Use z.infer instead of manual types\n- `type-input-vs-output` - Distinguish z.input from z.infer for transforms\n- `type-export-schemas-and-types` - Export both schemas and inferred types\n- `type-branded-types` - Use branded types for domain safety\n- `type-enable-strict-mode` - Enable TypeScript strict mode\n\n### 4. Error Handling (HIGH)\n\n- `error-custom-messages` - Provide custom error messages\n- `error-use-flatten` - Use flatten() for form error display\n- `error-path-for-nested` - Use issue.path for nested error location\n- `error-i18n` - Implement internationalized error messages\n- `error-avoid-throwing-in-refine` - Return false instead of throwing in refine\n\n### 5. Object Schemas (MEDIUM-HIGH)\n\n- `object-strict-vs-strip` - Choose strict() vs strip() for unknown keys\n- `object-partial-for-updates` - Use partial() for update schemas\n- `object-pick-omit` - Use pick() and omit() for schema variants\n- `object-extend-for-composition` - Use extend() for adding fields\n- `object-optional-vs-nullable` - Distinguish optional() from nullable()\n- `object-discriminated-unions` - Use discriminated unions for type narrowing\n\n### 6. Schema Composition (MEDIUM)\n\n- `compose-shared-schemas` - Extract shared schemas into reusable modules\n- `compose-intersection` - Use intersection() for type combinations\n- `compose-lazy-recursive` - Use z.lazy() for recursive schemas\n- `compose-preprocess` - Use preprocess() for data normalization\n- `compose-pipe` - Use pipe() for multi-stage validation\n\n### 7. Refinements & Transforms (MEDIUM)\n\n- `refine-vs-superrefine` - Choose refine() vs superRefine() correctly\n- `refine-transform-coerce` - Distinguish transform() from refine() and coerce()\n- `refine-add-path` - Add path to refinement errors\n- `refine-defaults` - Use default() for optional fields with defaults\n- `refine-catch` - Use catch() for fault-tolerant parsing\n\n### 8. Performance & Bundle (LOW-MEDIUM)\n\n- `perf-cache-schemas` - Cache schema instances\n- `perf-zod-mini` - Use Zod Mini for bundle-sensitive applications\n- `perf-avoid-dynamic-creation` - Avoid dynamic schema creation in hot paths\n- `perf-lazy-loading` - Lazy load large schemas\n- `perf-arrays` - Optimize large array validation\n\n## How to Use\n\nRead individual reference files for detailed explanations and code examples:\n\n- [Section definitions](references/_sections.md) - Category structure and impact levels\n- [Rule template](assets/templates/_template.md) - Template for adding new rules\n- Individual rules: `references/{prefix}-{slug}.md`\n\n## Full Compiled Document\n\nFor the complete guide with all rules expanded: `AGENTS.md`\n\n## Related Skills\n\n- For React Hook Form integration, see `react-hook-form` skill\n- For API client generation, see `orval` skill\n\n## Sources\n\n- [Zod Official Documentation](https://zod.dev/)\n- [Zod v4 Release Notes](https://zod.dev/v4)\n- [Zod GitHub Repository](https://github.com/colinhacks/zod)\n- [Zod Mini](https://zod.dev/packages/mini)\n- [Total TypeScript Zod Tutorial](https://www.totaltypescript.com/tutorials/zod)\n"},"lastSynced":"2026-03-08T02:09:25.514Z","agentAnalysis":{"suitability":{"en":"Ideal for TypeScript Validation Agents requiring robust schema enforcement and type inference.","zh":"非常适合需要强大模式强制和类型推断的 TypeScript 验证 Agent。","ja":"堅牢なスキーマ強制と型推論を必要とする TypeScript 検証 Agent に理想的です。","ko":"강력한 스키마 강제 및 타입 추론이 필요한 TypeScript 검증 에이전트에 이상적입니다.","es":"Ideal para agentes de validación de TypeScript que requieren una aplicación robusta de esquemas e inferencia de tipos.","fr":"Idéal pour les agents de validation TypeScript nécessitant une application robuste des schémas et une inférence de types.","de":"Ideal für TypeScript-Validierungs-Agents, die eine robuste Schema-Durchsetzung und Typ-Inferenz erfordern.","pt":"Ideal para Agentes de Validação TypeScript que requerem imposição robusta de esquema e inferência de tipo.","ru":"Идеально подходит для валидационных агентов TypeScript, требующих надежного применения схем и вывода типов.","ar":"مثالي لوكلاء التحقق من TypeScript الذين يتطلبون فرضًا قويًا للمخطط واستنتاج النوع."},"recommendation":{"en":"Enables comprehensive schema validation with 43 prioritized rules across 8 categories, providing automated refactoring guidance and safeParse() error handling for user feedback. Directly supports z.infer for type inference and complex object composition with refinements and transforms.","zh":"通过 8 个类别中的 43 条优先级规则实现全面的模式验证，提供自动重构指导和用于用户反馈的 safeParse() 错误处理。直接支持使用 z.infer 进行类型推断，并通过 refinements 和 transforms 实现复杂的对象组合。","ja":"8つのカテゴリーにわたる43の優先順位付けられたルールによる包括的なスキーマ検証を可能にし、自動リファクタリングガイダンスとユーザーフィードバックのための safeParse() エラー処理を提供します。z.infer を使用した型推論と、refinements および transforms による複雑なオブジェクト構成を直接サポートします。","ko":"8개 범주의 43개 우선순위 규칙을 통한 포괄적인 스키마 검증을 가능하게 하여, 자동 리팩토링 지침과 사용자 피드백을 위한 safeParse() 오류 처리를 제공합니다. z.infer를 사용한 타입 추론과 refinements 및 transforms를 통한 복잡한 객체 구성을 직접 지원합니다.","es":"Permite una validación de esquema completa con 43 reglas priorizadas en 8 categorías, proporcionando orientación automatizada de refactorización y manejo de errores safeParse() para retroalimentación del usuario. Admite directamente z.infer para la inferencia de tipos y la composición de objetos complejos con refinamientos y transformaciones.","fr":"Permet une validation de schéma complète avec 43 règles prioritaires réparties en 8 catégories, fournissant des conseils automatisés de refactorisation et une gestion des erreurs safeParse() pour les retours utilisateur. Prend directement en charge z.infer pour l''inférence de types et la composition d''objets complexes avec des refinements et des transformations.","de":"Ermöglicht eine umfassende Schema-Validierung mit 43 priorisierten Regeln in 8 Kategorien, bietet automatische Refactoring-Anleitung und safeParse()-Fehlerbehandlung für Benutzerfeedback. Unterstützt direkt z.infer für Typ-Inferenz und komplexe Objektkomposition mit Verfeinerungen und Transformationen.","pt":"Permite validação abrangente de esquema com 43 regras priorizadas em 8 categorias, fornecendo orientação automatizada de refatoração e manipulação de erros safeParse() para feedback do usuário. Suporta diretamente z.infer para inferência de tipo e composição de objetos complexos com refinamentos e transformações.","ru":"Обеспечивает комплексную проверку схемы с помощью 43 приоритетных правил в 8 категориях, предоставляет автоматизированные рекомендации по рефакторингу и обработку ошибок safeParse() для обратной связи с пользователем. Непосредственно поддерживает z.infer для вывода типов и композиции сложных объектов с уточнениями и преобразованиями.","ar":"يتيح التحقق الشامل من المخطط بـ 43 قاعدة ذات أولوية عبر 8 فئات، ويوفر توجيهًا آليًا لإعادة الهيكلة ومعالجة أخطاء safeParse() لملاحظات المستخدم. يدعم مباشرة z.infer لاستنتاج النوع وتكوين كائنات معقدة مع التحسينات والتحويلات."},"useCases":{"en":["Writing new Zod schemas for TypeScript applications","Handling validation errors to provide user feedback","Implementing type inference with z.infer","Composing complex object schemas with refinements and transforms"],"zh":["为 TypeScript 应用程序编写新的 Zod schemas","处理验证错误以提供用户反馈","使用 z.infer 实现类型推断","通过 refinements 和 transforms 组合复杂的对象 schemas"],"ja":["TypeScript アプリケーションのための新しい Zod スキーマの作成","ユーザーフィードバックを提供するための検証エラーの処理","z.infer を使用した型推論の実装","refinements と transforms を使用した複雑なオブジェクトスキーマの構成"],"ko":["TypeScript 애플리케이션을 위한 새로운 Zod 스키마 작성","사용자 피드백을 제공하기 위한 검증 오류 처리","z.infer를 사용한 타입 추론 구현","refinements 및 transforms를 사용한 복잡한 객체 스키마 구성"],"es":["Escribir nuevos esquemas Zod para aplicaciones TypeScript","Manejar errores de validación para proporcionar retroalimentación al usuario","Implementar inferencia de tipos con z.infer","Componer esquemas de objetos complejos con refinamientos y transformaciones"],"fr":["Écrire de nouveaux schémas Zod pour les applications TypeScript","Gérer les erreurs de validation pour fournir des retours utilisateur","Mettre en œuvre l''inférence de types avec z.infer","Composer des schémas d''objets complexes avec des refinements et des transformations"],"de":["Schreiben neuer Zod-Schemata für TypeScript-Anwendungen","Behandeln von Validierungsfehlern, um Benutzerfeedback zu geben","Implementieren von Typ-Inferenz mit z.infer","Zusammensetzen komplexer Objektschemata mit Verfeinerungen und Transformationen"],"pt":["Escrever novos esquemas Zod para aplicações TypeScript","Lidar com erros de validação para fornecer feedback ao usuário","Implementar inferência de tipo com z.infer","Compor esquemas de objetos complexos com refinamentos e transformações"],"ru":["Создание новых схем Zod для приложений TypeScript","Обработка ошибок валидации для предоставления обратной связи пользователю","Реализация вывода типов с помощью z.infer","Составление сложных схем объектов с уточнениями и преобразованиями"],"ar":["كتابة مخططات Zod جديدة لتطبيقات TypeScript","معالجة أخطاء التحقق لتقديم ملاحظات للمستخدم","تنفيذ استنتاج النوع باستخدام z.infer","تكوين مخططات كائنات معقدة مع التحسينات والتحويلات"]},"limitations":{"en":["TypeScript applications only","Requires understanding of Zod''s 43 rules across 8 categories","Optimization knowledge needed for best performance"],"zh":["仅限 TypeScript 应用程序","需要理解 Zod 在 8 个类别中的 43 条规则","需要优化知识以获得最佳性能"],"ja":["TypeScript アプリケーションのみ","8つのカテゴリーにわたる Zod の43のルールの理解が必要","最高のパフォーマンスを得るには最適化の知識が必要"],"ko":["TypeScript 애플리케이션만 해당","8개 범주의 Zod 43개 규칙에 대한 이해 필요","최상의 성능을 위해 최적화 지식 필요"],"es":["Solo aplicaciones TypeScript","Requiere comprensión de las 43 reglas de Zod en 8 categorías","Se necesitan conocimientos de optimización para el mejor rendimiento"],"fr":["Applications TypeScript uniquement","Nécessite une compréhension des 43 règles de Zod réparties en 8 catégories","Des connaissances en optimisation sont nécessaires pour les meilleures performances"],"de":["Nur TypeScript-Anwendungen","Erfordert ein Verständnis der 43 Regeln von Zod in 8 Kategorien","Optimierungswissen für die beste Leistung erforderlich"],"pt":["Apenas aplicações TypeScript","Requer compreensão das 43 regras do Zod em 8 categorias","Conhecimento de otimização necessário para melhor desempenho"],"ru":["Только для приложений TypeScript","Требует понимания 43 правил Zod в 8 категориях","Для достижения наилучшей производительности необходимы знания по оптимизации"],"ar":["تطبيقات TypeScript فقط","يتطلب فهم 43 قاعدة من Zod عبر 8 فئات","معرفة بالتحسين مطلوبة لأفضل أداء"]},"version":4},"contentHash":"245fc4ab7341a8ac0864c9535e2a6d782aaf012ba6975a36cd51240bcf82e443","qualityScore":35}');
