INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eKoh951/hytale-gg/zod', 'zod', 'eKoh951', 'hytale-gg', 'community', 'zod eKoh951 hytale-gg community Zod provides a comprehensive schema validation guide for TypeScript applications, offering 43 rules across 8 categories. It helps developers write new Zod schemas and handle validation errors Zod 是一个 TypeScript 应用中的模式验证库，提供 43 条规则和 8 个类别来优化代码生成和自动重构 Zod は、TypeScript アプリケーションのスキーマ検証を提供するライブラリで、43 のルールと 8 つのカテゴリを備えています Zod는 TypeScript 애플리케이션의 스키마 유효성 검사를 제공하는 라이브러리로 43개의 규칙과 8개의 카테고리가 있습니다 Zod es una herramienta de validación de esquemas para TypeScript que ofrece 43 reglas en 8 categorías para garantizar la precisión de los datos Zod est un outil de validation de schémas pour TypeScript qui propose 43 règles dans 8 catégories pour garantir la précision des données Zod ist ein Schema-Validierungstool für TypeScript, das 43 Regeln in 8 Kategorien bietet, um die Genauigkeit der Daten zu gewährleisten Zod é uma biblioteca de validação de esquemas para aplicações TypeScript. Este guia apresenta as melhores práticas para configurar Zod. Zod - это библиотека для валидации схем в приложениях TypeScript. Это руководство содержит лучшие практики для настройки Zod. Zod هو مكتبة للتحقق من صحة مخططات البيانات في تطبيقات TypeScript. هذا الدليل يقدم أفضل الممارسات لإعداد Zod. how to use zod zod best practices zod vs joi zod install zod setup guide zod schema validation zod type inference zod error handling zod typescript integration Zod TypeScript 模式验证 代码生成 自动重构 parse() safeParse() 类型推断 z.infer Provides 43 rules across 8 categories for comprehensive schema validation Supports automated refactoring and code generation Offers type inference with z.infer for improved schema accuracy Handles validation errors for user feedback and composing complex object schemas Allows for refinements and transforms to optimize schema performance Includes guidelines for choosing between parse() and safeParse() functions Zod is a TypeScript-based schema validation library that provides a set of rules and guidelines for writing efficient and effective schemas');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joolbits/slabbed/slabbed-ceiling-support', 'community', 'joolbits', 'slabbed', 'joolbits/slabbed', 'slabbed-ceiling-support', 0, 0, 35, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:26.859Z', '5bdc6a51000cdfd5009df03caa00e41d7bea61692d7e2aa3b61e0b332b6824b8', '{"id":"joolbits/slabbed/slabbed-ceiling-support","name":"slabbed-ceiling-support","description":{"en":"The slabbed-ceiling-support skill allows blocks that require ceiling attachment to place on and survive under top slabs and double slabs, benefiting developers working with ceiling-attached blocks.","zh":"slabbed-ceiling-support允许需要天井附着的方块（如链条、悬挂标志、灯笼）放置在顶板和双顶板上并生存下来","ja":"Slabbed Ceiling Supportは、天井に付着する必要があるブロック（チェーン、サイン、ランタンなど）をスラブやダブルスラブの上に置くことができるようにします","ko":"slabbed-ceiling-support는 천장 부착이 필요한 블록(체인, 사인, 랜턴 등)을 슬래브와 더블 슬래브 위에 놓고 생존할 수 있도록 합니다","es":"El skill slabbed-ceiling-support permite a los bloques que requieren sujeción al techo colocarse y sobrevivir bajo losas y dobles losas","fr":"Le skill slabbed-ceiling-support permet aux blocs qui nécessitent une attache au plafond de se placer et de survivre sous les dalles et les doubles dalles","de":"Das Skill slabbed-ceiling-support ermöglicht es Blöcken, die eine Deckenbefestigung benötigen, sich unter Platten und Doppelplatten zu platzieren und zu überleben","pt":"O Slabbed-Ceiling-Support permite que blocos que requerem fixação no teto sejam colocados em lajes superiores e duplas lajes","ru":"Slabbed-Ceiling-Support позволяет размещать блоки, требующие крепления к потолку, на верхних и двойных слэбах","ar":"دعم السقف المشكل يسمح بوضع الكتل التي تتطلب تثبيت السقف على السقف العلوي والسقف المزدوج"},"seo":{"title":{"en":"slabbed-ceiling-support: Ceiling Attachment Setup Guide |...","zh":"slabbed-ceiling-support 技术指南：顶板支撑设置","ja":"Slabbed Ceiling Support のベストプラクティス：AIエージェントを使用した天井サポート","ko":"slabbed-ceiling-support 개발자 가이드: 천장 지지 설정","es":"Guía de configuración de slabbed-ceiling-support para age...","fr":"Guide de mise en œuvre de slabbed-ceiling-support pour le...","de":"Einrichtungsleitfaden für slabbed-ceiling-support in KI-A...","pt":"Guia de Configuração do Slabbed-Ceiling-Support para Dese...","ru":"Настройка ИИ Агентов: Slabbed-Ceiling-Support Руководство","ar":"دليل تنفيذ دعم السقف المشكل للمطورين"},"description":{"en":"Discover how slabbed-ceiling-support enables blocks to attach to ceilings under top slabs and double slabs. Learn more and get started today!","zh":"了解slabbed-ceiling-support的技术细节和实现方法，包括SlabSupportStateMixin和SlabSupportBlockMixin的使用","ja":"Slabbed Ceiling Supportの詳細を掘り下げる：天井サポートの実装方法とAIエージェントの活用","ko":"slabbed-ceiling-support의 핵심 기능과 기술 세부 사항을 확인하세요: 천장 지지 설정과 블록 혼합의 사용","es":"Aprende a utilizar slabbed-ceiling-support para permitir que los bloques se adjunten al techo y sobrevivan bajo losas y dobles losas","fr":"Découvrez comment utiliser slabbed-ceiling-support pour permettre aux blocs de s''attacher au plafond et de survivre sous les dalles et les doubles dalles","de":"Erfahren Sie, wie Sie slabbed-ceiling-support verwenden, um Blöcke an der Decke zu befestigen und unter Platten und Doppelplatten zu überleben","pt":"Aprenda a configurar o Slabbed-Ceiling-Support para permitir que blocos sejam colocados em lajes superiores e duplas lajes","ru":"Узнайте, как настроить Slabbed-Ceiling-Support для ИИ Агентов, чтобы блоки могли быть размещены на верхних и двойных слэбах","ar":"اكتشف كيفية تنفيذ دعم السقف المشكل لتنسيق الكتل على السقف العلوي والسقف المزدوج"},"definition":{"en":"slabbed-ceiling-support is a skill that enables ceiling attachment for blocks under top slabs and double slabs without requiring additional mixins.","zh":"slabbed-ceiling-support是一种允许方块在顶板和双顶板上放置和生存的技术","ja":"Slabbed Ceiling Supportは、ブロックをスラブやダブルスラブの上に置くことができるようにする技術です","ko":"slabbed-ceiling-support는 블록을 슬래브와 더블 슬래브 위에 놓고 생존할 수 있도록 하는 기술입니다","es":"Slabbed-ceiling-support es un skill que permite a los bloques adjuntarse al techo y sobrevivir bajo losas y dobles losas","fr":"Slabbed-ceiling-support est un skill qui permet aux blocs de s''attacher au plafond et de survivre sous les dalles et les doubles dalles","de":"Slabbed-ceiling-support ist ein Skill, der es Blöcken ermöglicht, sich an der Decke zu befestigen und unter Platten und Doppelplatten zu überleben","pt":"O Slabbed-Ceiling-Support é uma funcionalidade que permite que blocos sejam colocados em lajes superiores e duplas lajes","ru":"Slabbed-Ceiling-Support - это функция, которая позволяет размещать блоки на верхних и двойных слэбах","ar":"دعم السقف المشكل هو ميزة تسمح بوضع الكتل على السقف العلوي والسقف المزدوج"},"features":{"en":["Utilizes SlabSupportStateMixin.isSideSolid to determine solid sides","Leverages SlabSupportBlockMixin.sideCoversSmallSquare for small square coverage","Supports ceiling attachment for chains, hanging signs, and lanterns","Works with top slabs and double slabs of all SideShapeType variants","Eliminates the need for additional mixins for ceiling support"],"zh":["SlabSupportStateMixin.isSideSolid返回true用于顶板的Direction.DOWN","SlabSupportBlockMixin.sideCoversSmallSquare返回true用于顶板的Direction.DOWN","支持顶板和双顶板","允许需要天井附着的方块放置和生存","无需额外的mixin即可实现天井支持"],"ja":["SlabSupportStateMixin.isSideSolidはスラブのDirection.DOWNでtrueを返す","SlabSupportBlockMixin.sideCoversSmallSquareはスラブのDirection.DOWNでtrueを返す","スラブとダブルスラブをサポート","天井に付着する必要があるブロックを置くことができる","追加のmixin不要で天井サポートを実現"],"ko":["SlabSupportStateMixin.isSideSolid는 슬래브의 Direction.DOWN에서 true를 반환","SlabSupportBlockMixin.sideCoversSmallSquare는 슬래브의 Direction.DOWN에서 true를 반환","슬래브와 더블 슬래브를 지원","천장 부착이 필요한 블록을 놓을 수 있음","추가 mixin 없이 천장 지지를 구현"],"es":["Permite la colocación de bloques que requieren sujeción al techo bajo losas y dobles losas","Utiliza la clase SlabSupportStateMixin para comprobar la solidez de los lados","Utiliza la clase SlabSupportBlockMixin para comprobar la cobertura de los lados","Funciona sin necesidad de mixins adicionales","Soporta todos los tipos de formas de lados de las losas","Permite la supervivencia de los bloques bajo top slabs y double slabs"],"fr":["Permet la placement de blocs qui nécessitent une attache au plafond sous les dalles et les doubles dalles","Utilise la classe SlabSupportStateMixin pour vérifier la solidité des côtés","Utilise la classe SlabSupportBlockMixin pour vérifier la couverture des côtés","Fonctionne sans besoin de mixins supplémentaires","Prend en charge tous les types de formes de côtés des dalles","Permet la survie des blocs sous les dalles et les doubles dalles"],"de":["Ermöglicht die Platzierung von Blöcken, die eine Deckenbefestigung benötigen, unter Platten und Doppelplatten","Verwendet die Klasse SlabSupportStateMixin, um die Festigkeit der Seiten zu überprüfen","Verwendet die Klasse SlabSupportBlockMixin, um die Abdeckung der Seiten zu überprüfen","Funktioniert ohne zusätzliche Mixins","Unterstützt alle Arten von Seitenformen von Platten","Ermöglicht das Überleben von Blöcken unter Platten und Doppelplatten"],"pt":["Suporte a blocos que requerem fixação no teto","Funcionamento com lajes superiores e duplas lajes","Utilização de `SlabSupportStateMixin.isSideSolid` para verificar a solidez da laje","Utilização de `SlabSupportBlockMixin.sideCoversSmallSquare` para verificar a cobertura da laje","Compatibilidade com diferentes variantes de `SideShapeType`"],"ru":["Поддержка блоков, требующих крепления к потолку","Работа с верхними и двойными слэбами","Использование `SlabSupportStateMixin.isSideSolid` для проверки твердости слэба","Использование `SlabSupportBlockMixin.sideCoversSmallSquare` для проверки покрытия слэба","Совместимость с разными вариантами `SideShapeType`"],"ar":["دعم الكتل التي تتطلب تثبيت السقف","التوافق مع السقف العلوي والسقف المزدوج","استخدام `SlabSupportStateMixin.isSideSolid` لتحقق من صلابة السقف","استخدام `SlabSupportBlockMixin.sideCoversSmallSquare` لتحقق من تغطية السقف","التوافق مع متغيرات مختلفة من `SideShapeType`"]},"keywords":{"en":["how to use slabbed-ceiling-support","slabbed-ceiling-support setup guide","what is slabbed-ceiling-support","slabbed-ceiling-support alternative","slabbed-ceiling-support vs ceiling attachment mods","slabbed-ceiling-support install","ceiling attachment for blocks","top slab and double slab support"],"zh":["slabbed-ceiling-support","顶板支撑","天井附着","SlabSupportStateMixin","SlabSupportBlockMixin","AIエージェント","游戏开发","Minecraft模组"],"ja":["Slabbed Ceiling Support","天井サポート","チェーン","サイン","ランタン","AIエージェント","ゲーム開発","Minecraftモード"],"ko":["slabbed-ceiling-support","천장 지지","천장 부착","체인","사인","랜턴","AI 에이전트","게임 개발","Minecraft 모드"],"es":["slabbed-ceiling-support","agentes de IA","bloques que requieren sujeción al techo","losas y dobles losas","SlabSupportStateMixin","SlabSupportBlockMixin","configuración de slabbed-ceiling-support"],"fr":["slabbed-ceiling-support","outils d''IA","blocs qui nécessitent une attache au plafond","dalles et doubles dalles","SlabSupportStateMixin","SlabSupportBlockMixin","mise en œuvre de slabbed-ceiling-support"],"de":["slabbed-ceiling-support","KI-Agenten","Blöcke, die eine Deckenbefestigung benötigen","Platten und Doppelplatten","SlabSupportStateMixin","SlabSupportBlockMixin","Einrichtung von slabbed-ceiling-support"],"pt":["Slabbed-Ceiling-Support","desenvolvimento de jogos","blocos de jogo","lajes superiores","duplas lajes","fixação no teto","SlabSupportStateMixin","SlabSupportBlockMixin"],"ru":["Slabbed-Ceiling-Support","ИИ Агенты","разработка игр","блоки игры","верхние слэбы","двойные слэбы","крепление к потолку","SlabSupportStateMixin","SlabSupportBlockMixin"],"ar":["دعم السقف المشكل","أدوات الذكاء الاصطناعي","تنمية الألعاب","كتل اللعبة","السقف العلوي","السقف المزدوج","تثبيت السقف","SlabSupportStateMixin","SlabSupportBlockMixin"]}},"owner":"joolbits","repo":"slabbed","repoPath":"joolbits/slabbed","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.466Z","topics":[],"category":"community","skillMd":{"name":"slabbed-ceiling-support","description":"Add hanging/ceiling attachment support for blocks under top slabs, using SlabSupport.isCeilingSupportSurface as the single source of truth.","bodyPreview":"# Slabbed — Skill: Ceiling Support\n\n## Goal\nAllow blocks that require ceiling attachment (chains, hanging signs, lanterns) to place on and survive under top slabs and double slabs.\n\n## Key finding (2026-02-07)\nAnalysis showed that ceiling support **already works** without additional mixins:\n- `SlabSupportStateMixin.isSideSolid` returns true for `Direction.DOWN` on top slabs (all `SideShapeType` variants)\n- `SlabSupportBlockMixin.sideCoversSmallSquare` returns true for `Direction.DOWN` on top sla","body":"# Slabbed — Skill: Ceiling Support\n\n## Goal\nAllow blocks that require ceiling attachment (chains, hanging signs, lanterns) to place on and survive under top slabs and double slabs.\n\n## Key finding (2026-02-07)\nAnalysis showed that ceiling support **already works** without additional mixins:\n- `SlabSupportStateMixin.isSideSolid` returns true for `Direction.DOWN` on top slabs (all `SideShapeType` variants)\n- `SlabSupportBlockMixin.sideCoversSmallSquare` returns true for `Direction.DOWN` on top slabs\n- Top slab collision shape `[0,0.5,0 → 1,1,1]` natively satisfies `isSideSolid(DOWN, CENTER)` via shape cache\n- `ChainBlock` has no `canPlaceAt` override — places anywhere\n- `HangingSignBlock.canPlaceAt` checks `isSideSolid(pos.up(), DOWN, CENTER)` — satisfied by top slabs natively\n- Lanterns use `sideCoversSmallSquare(DOWN)` — covered by `SlabSupportBlockMixin`\n\n## When to use this skill\nWhen adding ceiling-attachment support for a new block type under top slabs.\n\n## Hard stops\n- Ceiling support leaks to bottom slabs, stairs, fences, walls, or panes\n- Baseline full-block behavior changes\n- Build fails\n\n## Steps\n1. Test whether existing `isSideSolid` / `sideCoversSmallSquare` changes already enable placement\n2. If not: check what placement method the block uses (`isSideSolid`, `sideCoversSmallSquare`, or custom)\n3. If custom: add a narrow per-block mixin (`canPlaceAt` inject with early return) routing through `SlabSupport`\n4. Verify survival after neighbor updates (break and replace the slab above)\n5. Verify visual alignment (flush against slab bottom)\n6. Build gate\n7. Test matrix\n8. Commit + tag\n\n## Note on `isCeilingSupportSurface`\nA dedicated `SlabSupport.isCeilingSupportSurface(BlockView, BlockPos)` helper was planned but is NOT needed currently. The existing shared hooks cover all known ceiling-attachment blocks. Only add this helper if a future block requires a custom check that the shared hooks don''t cover.\n"},"lastSynced":"2026-03-08T02:09:26.859Z","agentAnalysis":{"suitability":{"en":"Perfect for Minecraft Modding Agents needing advanced block placement capabilities with ceiling support","zh":"适用于需要高级块放置功能并支持天花板的Minecraft Modding Agents","ja":"天井サポートを必要とするMinecraft Modding Agents向けのブロック配置の高度な機能を必要とするエージェントに適しています","ko":"천장 지원이 필요한 Minecraft Modding Agents를 위한 고급 블록 배치 기능이 필요한 에이전트에게 적합합니다","es":"Perfecto para Agentes de Modificación de Minecraft que necesitan capacidades avanzadas de colocación de bloques con soporte de techo","fr":"Parfait pour les Agents de modification de Minecraft ayant besoin de fonctionnalités avancées de placement de blocs avec support de plafond","de":"Perfekt für Minecraft-Modding-Agents, die erweiterte Blockplatzierungsfunktionen mit Deckenunterstützung benötigen","pt":"Perfeito para Agentes de Modding do Minecraft que precisam de capacidades avançadas de colocação de blocos com suporte ao teto","ru":"Идеально подходит для агентов моддинга Minecraft, которым необходимы продвинутые возможности размещения блоков с поддержкой потолка","ar":"مثالي لعميل تعديل ماين كرافت الذي يحتاج إلى قدرات متقدمة لوضع الكتل مع دعم السقف"},"recommendation":{"en":"Empowers agents to generate and manage ceiling-attached blocks, such as chains, hanging signs, and lanterns, under top slabs and double slabs using SlabSupportStateMixin and SlabSupportBlockMixin","zh":"赋予代理生成和管理天花板附着的块，例如链条、悬挂标志和灯笼，在顶部板和双板下使用SlabSupportStateMixin和SlabSupportBlockMixin","ja":"エージェントが天井に付いたブロックを生成して管理できるようにし、チェーン、サイン、ランタンなどのブロックをトップスラブとダブルスラブの下でSlabSupportStateMixinとSlabSupportBlockMixinを使用して配置します","ko":"에이전트가 천장에 부착된 블록을 생성하고 관리할 수 있도록 하며, 체인, 사인, 랜턴 등과 같은 블록을 상부 슬래브와 이중 슬래브 아래에서 SlabSupportStateMixin과 SlabSupportBlockMixin을 사용하여 구성합니다","es":"Habilita a los agentes a generar y gestionar bloques adjuntos al techo, como cadenas, letreros colgantes y lámparas, bajo losas superiores y dobles losas utilizando SlabSupportStateMixin y SlabSupportBlockMixin","fr":"Permet aux agents de générer et de gérer des blocs attachés au plafond, tels que des chaînes, des panneaux suspendus et des lanternes, sous les dalles supérieures et les dalles doubles en utilisant SlabSupportStateMixin et SlabSupportBlockMixin","de":"Ermächtigt Agents, Decken-attachierte Blöcke wie Ketten, hängende Schilder und Laternen unter oberen Schichten und Doppelschichten mit Hilfe von SlabSupportStateMixin und SlabSupportBlockMixin zu generieren und zu verwalten","pt":"Habilita os agentes a gerar e gerenciar blocos presos ao teto, como correntes, placas penduradas e lanternas, sob lajes superiores e lajes duplas usando SlabSupportStateMixin e SlabSupportBlockMixin","ru":"Наделяет агентов возможностью генерировать и управлять блоками, прикрепленными к потолку, такими как цепи, висящие знаки и фонари, под верхними и двойными плитками с использованием SlabSupportStateMixin и SlabSupportBlockMixin","ar":"يمنح الوكيل القدرة على إنشاء و إدارة الكتل المثبتة على السقف ، مثل السلاسل واللافتات المعلقة والمصابيح ، تحت البلاطات العلوية والبلاطات المزدوجة باستخدام SlabSupportStateMixin و SlabSupportBlockMixin"},"useCases":{"en":["Automating block placement for ceiling-attached structures","Generating compatible block configurations for top slabs and double slabs","Debugging issues with block placement and ceiling support"],"zh":["自动化天花板附着结构的块放置","为顶部板和双板生成兼容的块配置","调试块放置和天花板支持的问题"],"ja":["天井付属構造のブロック配置を自動化する","トップスラブとダブルスラブ用の互換性のあるブロック構成を生成する","ブロック配置と天井サポートの問題をデバッグする"],"ko":["천장 부착 구조의 블록 배치를 자동화하는 것","상부 슬래브와 이중 슬래브를 위한 호환되는 블록 구성 생성","블록 배치와 천장 지원 문제를 디버깅하는 것"],"es":["Automatizar la colocación de bloques para estructuras adjuntas al techo","Generar configuraciones de bloques compatibles para losas superiores y dobles losas","Depurar problemas con la colocación de bloques y soporte de techo"],"fr":["Automatiser le placement de blocs pour les structures attachées au plafond","Générer des configurations de blocs compatibles pour les dalles supérieures et les dalles doubles","Déboguer les problèmes de placement de blocs et de support de plafond"],"de":["Automatisieren der Blockplatzierung für decken-attachierte Strukturen","Erzeugen von kompatiblen Blockkonfigurationen für obere Schichten und Doppelschichten","Fehlerbehebung bei Blockplatzierungs- und Deckenunterstützungsproblemen"],"pt":["Automatizar a colocação de blocos para estruturas presas ao teto","Gerar configurações de blocos compatíveis para lajes superiores e lajes duplas","Depurar problemas com a colocação de blocos e suporte ao teto"],"ru":["Автоматизировать размещение блоков для потолочно-присоединенных структур","Генерировать совместимые конфигурации блоков для верхних и двойных плиток","Отлаживать проблемы с размещением блоков и поддержкой потолка"],"ar":["أتمتة وضع الكتل للstructures المثبتة على السقف ","إنشاء تكوينات الكتل المتوافقة للبلاطات العلوية والبلاطات المزدوجة ","تصحيح الأخطاء المتعلقة بوضع الكتل ودعم السقف "]},"limitations":{"en":["Requires Minecraft modding environment","Limited to blocks that require ceiling attachment","Compatibility with existing mixins, such as SlabSupportStateMixin and SlabSupportBlockMixin"],"zh":["需要Minecraft模组环境","仅限于需要天花板附着的块","与现有mixin的兼容性，例如SlabSupportStateMixin和SlabSupportBlockMixin"],"ja":["Minecraftモディング環境が必要","天井付属が必要なブロックに限定される","SlabSupportStateMixinやSlabSupportBlockMixinなどの既存のmixinとの互換性"],"ko":["Minecraft 모딩 환경이 필요","천장 부착이 필요한 블록으로 제한","SlabSupportStateMixin 및 SlabSupportBlockMixin과 같은 기존 mixin과의 호환성"],"es":["Requiere un entorno de modificación de Minecraft","Limitado a bloques que requieren sujeción al techo","Compatibilidad con mixins existentes, como SlabSupportStateMixin y SlabSupportBlockMixin"],"fr":["Nécessite un environnement de modification de Minecraft","Limité aux blocs qui nécessitent un attachement au plafond","Compatibilité avec les mixins existants, tels que SlabSupportStateMixin et SlabSupportBlockMixin"],"de":["Benötigt eine Minecraft-Modding-Umgebung","Begrenzt auf Blöcke, die eine Deckenbefestigung erfordern","Kompatibilität mit bestehenden Mixins, wie z.B. SlabSupportStateMixin und SlabSupportBlockMixin"],"pt":["Exige ambiente de modding do Minecraft","Limitado a blocos que exigem fixação ao teto","Compatibilidade com mixins existentes, como SlabSupportStateMixin e SlabSupportBlockMixin"],"ru":["Требует среды моддинга Minecraft","Ограничен блоками, требующими потолочной установки","Совместимость с существующими миксинами, такими как SlabSupportStateMixin и SlabSupportBlockMixin"],"ar":["يتطلب بيئة تعديل ماين كرافت","محدود بالكتل التي تتطلب تثبيتًا على السقف ","التوافق مع المكونات الإضافية الموجودة ، مثل SlabSupportStateMixin و SlabSupportBlockMixin"]},"version":4},"contentHash":"5bdc6a51000cdfd5009df03caa00e41d7bea61692d7e2aa3b61e0b332b6824b8","qualityScore":35}');
