INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joolbits/slabbed/slabbed-ceiling-support', 'slabbed-ceiling-support', 'joolbits', 'slabbed', 'community', 'slabbed-ceiling-support joolbits slabbed community The slabbed-ceiling-support skill allows blocks that require ceiling attachment to place on and survive under top slabs and double slabs, benefiting developers working with ceiling-attached blocks. slabbed-ceiling-support允许需要天井附着的方块（如链条、悬挂标志、灯笼）放置在顶板和双顶板上并生存下来 Slabbed Ceiling Supportは、天井に付着する必要があるブロック（チェーン、サイン、ランタンなど）をスラブやダブルスラブの上に置くことができるようにします slabbed-ceiling-support는 천장 부착이 필요한 블록(체인, 사인, 랜턴 등)을 슬래브와 더블 슬래브 위에 놓고 생존할 수 있도록 합니다 El skill slabbed-ceiling-support permite a los bloques que requieren sujeción al techo colocarse y sobrevivir bajo losas y dobles losas Le skill slabbed-ceiling-support permet aux blocs qui nécessitent une attache au plafond de se placer et de survivre sous les dalles et les doubles dalles Das Skill slabbed-ceiling-support ermöglicht es Blöcken, die eine Deckenbefestigung benötigen, sich unter Platten und Doppelplatten zu platzieren und zu überleben O Slabbed-Ceiling-Support permite que blocos que requerem fixação no teto sejam colocados em lajes superiores e duplas lajes Slabbed-Ceiling-Support позволяет размещать блоки, требующие крепления к потолку, на верхних и двойных слэбах دعم السقف المشكل يسمح بوضع الكتل التي تتطلب تثبيت السقف على السقف العلوي والسقف المزدوج how to use slabbed-ceiling-support slabbed-ceiling-support setup guide what is slabbed-ceiling-support slabbed-ceiling-support alternative slabbed-ceiling-support vs ceiling attachment mods slabbed-ceiling-support install ceiling attachment for blocks top slab and double slab support slabbed-ceiling-support 顶板支撑 天井附着 SlabSupportStateMixin SlabSupportBlockMixin AIエージェント 游戏开发 Minecraft模组 Utilizes SlabSupportStateMixin.isSideSolid to determine solid sides Leverages SlabSupportBlockMixin.sideCoversSmallSquare for small square coverage Supports ceiling attachment for chains, hanging signs, and lanterns Works with top slabs and double slabs of all SideShapeType variants Eliminates the need for additional mixins for ceiling support slabbed-ceiling-support is a skill that enables ceiling attachment for blocks under top slabs and double slabs without requiring additional mixins.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('webdevarif/rejoes-pos/rejoes-workspace', 'community', 'webdevarif', 'rejoes-pos', 'webdevarif/rejoes-pos', 'rejoes-workspace', 0, 0, 35, '2026-03-08T01:57:15.522Z', '2026-03-08T02:10:49.681Z', 'b12c0173c7ae678f2aff08829db3b64e53d98473be76376af097f44b25f9f205', '{"id":"webdevarif/rejoes-pos/rejoes-workspace","name":"rejoes-workspace","description":{"en":"rejoes-workspace enables AI agents to confidently develop and manage Node.js backend applications with Express, Prisma, and PostgreSQL. It benefits developers by providing a robust and scalable framework.","zh":"rejoes-workspace后端开发技能，专注于Node.js、Express、Prisma ORM等技术的应用","ja":"ReJoEs Backend AIエージェントは、Node.js、Express、Prisma ORMなどの技術を活用した開発を支援します","ko":"rejoes-workspace 백엔드 개발 스킬은 Node.js, Express, Prisma ORM 등을 사용하여 개발을 지원합니다","es":"ReJoEs Workspace es un entorno de desarrollo para crear aplicaciones backend con Node.js y TypeScript. Incluye Express, Prisma ORM y Sharp para procesamiento de imágenes.","fr":"ReJoEs Workspace est un environnement de développement pour créer des applications backend avec Node.js et TypeScript. Il inclut Express, Prisma ORM et Sharp pour le traitement d''images.","de":"ReJoEs Workspace ist eine Entwicklungsumgebung für die Erstellung von Backend-Anwendungen mit Node.js und TypeScript. Es umfasst Express, Prisma ORM und Sharp für Bildverarbeitung.","pt":"O ReJoEs Workspace é uma ferramenta de desenvolvimento de backend que utiliza Node.js, Express e Prisma para criar aplicações robustas. Com ele, você pode desenvolver APIs RESTful e lógica de transações seguras.","ru":"ReJoEs Workspace - это инструмент для разработки бэкенда, который использует Node.js, Express и Prisma для создания прочных приложений. С его помощью вы можете разрабатывать RESTful API и логика транзакций.","ar":"مساحة عمل ReJoEs هي أداة تطوير خلفية تستخدم Node.js و Express و Prisma لإنشاء تطبيقات قوية. من خلالها، يمكنك تطوير واجهات برمجة تطبيقات RESTful و 논리جية معاملات آمنة."},"seo":{"title":{"en":"rejoes-workspace: Node.js Backend Development Setup Guide...","zh":"rejoes-workspace 后端开发设置指南","ja":"ReJoEs Backend AIエージェントのベストプラクティス","ko":"rejoes-workspace 백엔드 개발 가이드","es":"Guía de configuración de ReJoEs Workspace: Desarrollo de ...","fr":"Guide de mise en place de ReJoEs Workspace : Développemen...","de":"Einrichtungsleitfaden für ReJoEs Workspace: Backend-Entwi...","pt":"Guia de Configuração do ReJoEs Workspace - Desenvolviment...","ru":"Настройка ReJoEs Workspace - Руководство по разработке бэ...","ar":"دليل إعداد مساحة عمل ReJoEs - تطوير الخلفية باستخدام Node..."},"description":{"en":"Unlock efficient backend development with rejoes-workspace. Explore its capabilities and learn how to set up a robust Node.js environment with Express, Prism...","zh":"了解如何使用rejoes-workspace后端开发技能，包括Node.js、Express、Prisma ORM等技术","ja":"ReJoEs Backend AIエージェントを使用した開発方法について学びましょう。Node.js、Express、Prisma ORMなど","ko":"rejoes-workspace 백엔드 개발 스킬을 사용하여 Node.js, Express, Prisma ORM 등을 활용하는 방법을 알아보세요","es":"Aprende a configurar ReJoEs Workspace para desarrollar aplicaciones backend con Node.js, TypeScript, Express y Prisma ORM. Mejora tus habilidades en desarrol...","fr":"Découvrez comment configurer ReJoEs Workspace pour développer des applications backend avec Node.js, TypeScript, Express et Prisma ORM. Améliorez vos compéte...","de":"Erfahren Sie, wie Sie ReJoEs Workspace einrichten, um Backend-Anwendungen mit Node.js, TypeScript, Express und Prisma ORM zu entwickeln. Verbessern Sie Ihre ...","pt":"Aprenda a configurar o ReJoEs Workspace para desenvolver aplicações de backend com Node.js, Express, Prisma e SQLite. Descubra como criar APIs RESTful e lógi...","ru":"Узнайте, как настроить ReJoEs Workspace для разработки бэкенда с Node.js, Express, Prisma и SQLite. Откройте для себя, как создавать RESTful API и логика тра...","ar":"تعرف على كيفية إعداد مساحة عمل ReJoEs لتطوير تطبيقات الخلفية باستخدام Node.js و Express و Prisma و SQLite. اكتشف كيفية إنشاء واجهات برمجة تطبيقات RESTful و 논..."},"definition":{"en":"rejoes-workspace is a technical skill that defines the capabilities and responsibilities of an AI agent in developing and managing a Node.js backend application using Express, Prisma, and PostgreSQL.","zh":"rejoes-workspace是后端开发技能，涉及Node.js、Express、Prisma ORM等技术","ja":"ReJoEs Backend AIエージェントは、Node.js、Express、Prisma ORMなどの技術を使用した後端開発スキルです","ko":"rejoes-workspace는 Node.js, Express, Prisma ORM 등을 사용하는 백엔드 개발 스킬입니다","es":"ReJoEs Workspace es un entorno de desarrollo de backend que utiliza Node.js, TypeScript y tecnologías como Express y Prisma ORM.","fr":"ReJoEs Workspace est un environnement de développement backend qui utilise Node.js, TypeScript et des technologies comme Express et Prisma ORM.","de":"ReJoEs Workspace ist eine Entwicklungsumgebung für Backend, die Node.js, TypeScript und Technologien wie Express und Prisma ORM verwendet.","pt":"O que é ReJoEs Workspace? É uma ferramenta de desenvolvimento de backend que permite criar aplicações robustas com Node.js e Prisma.","ru":"Что такое ReJoEs Workspace? Это инструмент для разработки бэкенда, который позволяет создавать прочные приложения с Node.js и Prisma для ИИ Агентов.","ar":"ما هي مساحة عمل ReJoEs? هي أداة تطوير خلفية تمكن من إنشاء تطبيقات قوية باستخدام Node.js و Prisma لأدوات الذكاء الاصطناعي."},"features":{"en":["Generates Node.js applications with TypeScript and explicit routing using Express or Fastify","Utilizes Prisma ORM for database management with SQLite and PostgreSQL","Supports image processing with Sharp and multipart file uploads","Implements RESTful API design and transaction-safe logic","Develops production-ready schemas with PostgreSQL"],"zh":["支持Node.js和TypeScript","使用Express或Fastify进行路由管理","集成Prisma ORM进行数据库管理","支持SQLite和PostgreSQL数据库","提供Sharp图像处理功能","支持Multipart文件上传"],"ja":["Node.jsとTypeScriptをサポート","ExpressまたはFastifyを使用したルーティング管理","Prisma ORMを使用したデータベース管理","SQLiteとPostgreSQLデータベースをサポート","Sharp画像処理機能を提供","Multipartファイルアップロードをサポート"],"ko":["Node.js와 TypeScript 지원","Express 또는 Fastify를 사용한 라우팅 관리","Prisma ORM을 사용한 데이터베이스 관리","SQLite와 PostgreSQL 데이터베이스 지원","Sharp 이미지 처리 기능 제공","Multipart 파일 업로드 지원"],"es":["Soporte para Node.js y TypeScript","Integración con Express y Prisma ORM","Procesamiento de imágenes con Sharp","Diseño de API RESTful","Lógica de transacciones seguras"],"fr":["Prise en charge de Node.js et TypeScript","Intégration avec Express et Prisma ORM","Traitement d''images avec Sharp","Conception d''API RESTful","Logique de transactions sécurisées"],"de":["Unterstützung für Node.js und TypeScript","Integration mit Express und Prisma ORM","Bildverarbeitung mit Sharp","Entwurf von RESTful-APIs","Transaktions-sichere Logik"],"pt":["Desenvolvimento de backend com Node.js e TypeScript","Criação de APIs RESTful com Express ou Fastify","Utilização de Prisma ORM para gerenciamento de banco de dados","Suporte a SQLite e PostgreSQL","Processamento de imagens com Sharp","Upload de arquivos multipart"],"ru":["Разработка бэкенда с Node.js и TypeScript","Создание RESTful API с Express или Fastify","Использование Prisma ORM для управления базами данных","Поддержка SQLite и PostgreSQL","Обработка изображений с Sharp","Загрузка файлов multipart"],"ar":["تطوير الخلفية باستخدام Node.js و TypeScript","إنشاء واجهات برمجة تطبيقات RESTful مع Express أو Fastify","استخدام Prisma ORM لإدارة قواعد البيانات","دعم SQLite و PostgreSQL","معالجة الصور مع Sharp","تحميل الملفات المultipart"]},"keywords":{"en":["how to use rejoes-workspace","rejoes-workspace alternative","rejoes-workspace setup guide","Node.js backend development with rejoes-workspace","rejoes-workspace vs Prisma","rejoes-workspace install","Express and Prisma tutorial","PostgreSQL schema design with rejoes-workspace","rejoes-workspace and Sharp image processing"],"zh":["rejoes-workspace","后端开发","Node.js","Express","Prisma ORM","SQLite","PostgreSQL","Sharp","Multipart文件上传"],"ja":["ReJoEs Backend","AIエージェント","後端開発","Node.js","Express","Prisma ORM","SQLite","PostgreSQL","Sharp","Multipartファイルアップロード"],"ko":["rejoes-workspace","백엔드 개발","Node.js","Express","Prisma ORM","SQLite","PostgreSQL","Sharp","Multipart 파일 업로드"],"es":["ReJoEs Workspace","desarrollo de backend","Node.js","TypeScript","Express","Prisma ORM","Sharp","API RESTful","lógica de transacciones"],"fr":["ReJoEs Workspace","développement backend","Node.js","TypeScript","Express","Prisma ORM","Sharp","API RESTful","logique de transactions"],"de":["ReJoEs Workspace","Backend-Entwicklung","Node.js","TypeScript","Express","Prisma ORM","Sharp","RESTful-API","Transaktions-Logik"],"pt":["ReJoEs Workspace","desenvolvimento de backend","Node.js","TypeScript","Express","Fastify","Prisma ORM","SQLite","PostgreSQL","Sharp","upload de arquivos"],"ru":["ReJoEs Workspace","разработка бэкенда","Node.js","TypeScript","Express","Fastify","Prisma ORM","SQLite","PostgreSQL","Sharp","загрузка файлов","ИИ Агенты"],"ar":["مساحة عمل ReJoEs","تطوير الخلفية","Node.js","TypeScript","Express","Fastify","Prisma ORM","SQLite","PostgreSQL","Sharp","تحميل الملفات","أدوات الذكاء الاصطناعي"]}},"owner":"webdevarif","repo":"rejoes-pos","repoPath":"webdevarif/rejoes-pos","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.522Z","topics":[],"category":"community","skillMd":{"name":"rejoes-workspace","description":"ReJoEs Backend – AI Skills & Responsibilities","bodyPreview":"# ReJoEs Backend – AI Skills & Responsibilities\n\nThis file defines what the AI agent IS ALLOWED and EXPECTED to do\nwhen working on the ReJoEs backend.\n\n---\n\n## 1. Core Technical Stack Skills\n\nThe AI should confidently use and generate:\n\n- Node.js (TypeScript)\n- Express or Fastify (explicit routing)\n- Prisma ORM\n- SQLite (dev/test)\n- PostgreSQL (production-ready schemas)\n- Sharp (image processing)\n- Multipart file uploads\n- RESTful API design\n- Transaction-safe logic\n\n---\n\n## 2. Backend Architect","body":"# ReJoEs Backend – AI Skills & Responsibilities\n\nThis file defines what the AI agent IS ALLOWED and EXPECTED to do\nwhen working on the ReJoEs backend.\n\n---\n\n## 1. Core Technical Stack Skills\n\nThe AI should confidently use and generate:\n\n- Node.js (TypeScript)\n- Express or Fastify (explicit routing)\n- Prisma ORM\n- SQLite (dev/test)\n- PostgreSQL (production-ready schemas)\n- Sharp (image processing)\n- Multipart file uploads\n- RESTful API design\n- Transaction-safe logic\n\n---\n\n## 2. Backend Architecture Skills\n\nThe AI is expected to:\n\n- Design clean controller → service → data layers\n- Centralize business rules (tiers, allowances, limits)\n- Use Prisma transactions for all mutations\n- Keep controllers thin and logic testable\n- Avoid duplication of rule logic\n\n---\n\n## 3. API Design Responsibilities\n\nThe AI may:\n- Create REST endpoints exactly matching the spec\n- Validate request payloads\n- Return structured, predictable JSON errors\n- Enforce idempotency and safety rules\n\nThe AI may NOT:\n- Add extra endpoints\n- Modify API contracts without instruction\n- Add optional behavior not described\n\n---\n\n## 4. Subscription Sync Handling\n\nThe AI should:\n- Parse Shopify subscription webhook payloads\n- Map Shopify fields → internal member fields\n- Normalize tier and status values\n- Detect billing cycle changes\n- Trigger counter resets safely\n\n---\n\n## 5. Image Handling Skills\n\nThe AI may:\n- Accept multipart uploads\n- Compress images\n- Generate thumbnails\n- Store local file paths\n- Return URLs relative to the server\n\nThe AI must:\n- Treat photos as immutable loan identifiers\n- Never overwrite an existing loan photo\n\n---\n\n## 6. Data Integrity Skills\n\nThe AI is expected to:\n- Prevent race conditions\n- Prevent double-loans\n- Prevent counter drift\n- Handle retry-safe operations\n- Use idempotency keys correctly\n\n---\n\n## 7. Testing & Dev Workflow\n\nThe AI may:\n- Generate Prisma schemas\n- Create seed data\n- Write basic API tests\n- Support SQLite file-based databases\n\nThe AI should:\n- Keep production compatibility in mind\n- Avoid SQLite-only hacks\n\n---\n\n## 8. Error Handling Expectations\n\nThe AI should:\n- Return meaningful error messages for POS staff\n- Fail fast on rule violations\n- Avoid silent failures\n- Never partially complete a swap\n\n---\n\n## 9. Security Awareness\n\nThe AI must:\n- Verify Shopify webhooks\n- Avoid leaking internal IDs unnecessarily\n- Assume POS runs in semi-trusted environments\n- Never expose admin-only logic publicly\n\n---\n\n## 10. Delivery Expectations\n\nWhen asked to build:\n- The AI should generate **complete, production-grade backend code**\n- File trees must be explicit\n- Functions must match the spec exactly\n- No placeholder or speculative logic\n\n---\n\n## 11. Mental Model Alignment\n\nThe AI should always reason using this model:\n\n- Photos = items\n- Loans = circulation\n- Time = velocity\n- Subscriptions = funding\n- Shopify = billing truth\n- Backend = operational truth\n\nIf a proposed feature breaks this mental model,\nthe AI should reject it.\n\n"},"lastSynced":"2026-03-08T02:10:49.681Z","agentAnalysis":{"suitability":{"en":"Perfect for Node.js Agents needing comprehensive backend development capabilities with Express, Prisma, and PostgreSQL.","zh":"适用于需要全面后端开发功能的Node.js代理，包括Express、Prisma和PostgreSQL。","ja":"Node.jsエージェントがExpress、Prisma、PostgreSQLを使用した包括的なバックエンド開発機能を必要とする場合に最適です。","ko":"Express, Prisma 및 PostgreSQL을 사용한 포괄적인 백엔드 개발 기능이 필요한 Node.js 에이전트에게 적합합니다.","es":"Perfecto para agentes de Node.js que necesitan capacidades de desarrollo de backend integral con Express, Prisma y PostgreSQL.","fr":"Parfait pour les agents Node.js qui ont besoin de capacités de développement de backend complet avec Express, Prisma et PostgreSQL.","de":"Perfekt für Node.js-Agents, die umfassende Backend-Entwicklungsfähigkeiten mit Express, Prisma und PostgreSQL benötigen.","pt":"Perfeito para Agentes Node.js que necessitam de capacidades de desenvolvimento de backend abrangentes com Express, Prisma e PostgreSQL.","ru":"Идеально для агентов Node.js, которым требуются всесторонние возможности разработки бэкэнда с помощью Express, Prisma и PostgreSQL.","ar":"مثالي للوكلاء Node.js الذين يحتاجون إلى قدرات تطوير خلفية شاملة مع Express و Prisma و PostgreSQL."},"recommendation":{"en":"Empowers agents to develop and manage scalable Node.js backend applications using Express for routing, Prisma ORM for database interactions, and PostgreSQL for production-ready schemas, while also handling multipart file uploads and image processing with Sharp.","zh":"赋予代理开发和管理使用Express进行路由、Prisma ORM进行数据库交互以及PostgreSQL进行生产就绪模式的可扩展Node.js后端应用程序的能力，同时还处理multipart文件上传和Sharp的图像处理。","ja":"Expressをルーティングに、Prisma ORMをデータベース操作に、PostgreSQLを本番環境のスキーマに使用することで、スケーラブルなNode.jsバックエンドアプリケーションを開発および管理できるようにエージェントをEmpowerします。また、multipartファイルのアップロードやSharpによる画像処理も処理します。","ko":"Express를 라우팅에, Prisma ORM을 데이터베이스 상호 작용에, PostgreSQL을 프로덕션 준비 스키마에 사용하여 확장 가능한 Node.js 백엔드 애플리케이션을 개발하고 관리할 수 있는 에이전트를 강화합니다. 또한 multipart 파일 업로드 및 Sharp를 통한 이미지 처리도 처리합니다.","es":"Habilita a los agentes para desarrollar y gestionar aplicaciones de backend escalables de Node.js utilizando Express para enrutamiento, Prisma ORM para interacciones con la base de datos y PostgreSQL para esquemas de producción listos, mientras también maneja cargas de archivos multipart y procesamiento de imágenes con Sharp.","fr":"Permet aux agents de développer et de gérer des applications de backend scalable Node.js en utilisant Express pour le routage, Prisma ORM pour les interactions avec la base de données et PostgreSQL pour les schémas de production prêts, tout en gérant les téléchargements de fichiers multipart et le traitement d''images avec Sharp.","de":"Ermächtigt Agenten, skalierbare Node.js-Backend-Anwendungen zu entwickeln und zu verwalten, indem Express für das Routing, Prisma ORM für Datenbankinteraktionen und PostgreSQL für produktionssreife Schemata verwendet werden, während auch der Upload von Dateien im Mehrteil-Format und die Bildverarbeitung mit Sharp gehandhabt werden.","pt":"Habilita os agentes a desenvolver e gerenciar aplicações de backend escaláveis Node.js usando Express para roteamento, Prisma ORM para interações de banco de dados e PostgreSQL para esquemas de produção prontos, além de lidar com uploads de arquivos multipart e processamento de imagens com Sharp.","ru":"Наделяет агентов возможностью разрабатывать и управлять масштабируемыми приложениями бэкэнда Node.js, используя Express для маршрутизации, Prisma ORM для взаимодействия с базами данных и PostgreSQL для схем, готовых к производству, а также обрабатывать загрузку файлов multipart и обработку изображений с помощью Sharp.","ar":"تمكّن الوكلاء من تطوير وإدارة تطبيقات خلفية قابلة للتوسع ل Node.js باستخدام Express لتحديد المسار و Prisma ORM للتفاعل مع قواعد البيانات و PostgreSQL لschemas جاهزة للإنتاج، بالإضافة إلى التعامل مع تحميل الملفات المتنوعة والمعالجة الصورية باستخدام Sharp."},"useCases":{"en":["Generating RESTful API designs with explicit routing using Express or Fastify","Developing transaction-safe logic for secure database operations with Prisma and PostgreSQL","Implementing image processing and multipart file uploads in Node.js applications"],"zh":["使用Express或Fastify生成RESTful API设计并显式路由","使用Prisma和PostgreSQL开发事务安全逻辑以进行安全的数据库操作","在Node.js应用程序中实现图像处理和multipart文件上传"],"ja":["ExpressまたはFastifyを使用したRESTful API設計の生成と明示的なルーティング","PrismaおよびPostgreSQLを使用したトランザクションセーフロジックの開発による安全なデータベース操作","Node.jsアプリケーションにおける画像処理およびmultipartファイルアップロードの実装"],"ko":["Express 또는 Fastify를 사용하여 RESTful API 설계 생성 및 명시적 라우팅","Prisma 및 PostgreSQL을 사용하여 트랜잭션 안전 로직 개발 및 안전한 데이터베이스操作","Node.js 애플리케이션에서 이미지 처리 및 멀티파트 파일 업로드 구현"],"es":["Generar diseños de API RESTful con enrutamiento explícito utilizando Express o Fastify","Desarrollar lógica de transacciones seguras para operaciones de base de datos seguras con Prisma y PostgreSQL","Implementar el procesamiento de imágenes y la carga de archivos multipart en aplicaciones de Node.js"],"fr":["Générer des conceptions d''API RESTful avec des routages explicites en utilisant Express ou Fastify","Développer une logique de transactions sécurisées pour des opérations de base de données sécurisées avec Prisma et PostgreSQL","Mettre en œuvre le traitement d''images et le téléchargement de fichiers multipart dans les applications Node.js"],"de":["Erstellung von RESTful-API-Entwürfen mit explizitem Routing unter Verwendung von Express oder Fastify","Entwicklung von transaktionssicherer Logik für sichere Datenbankoperationen mit Prisma und PostgreSQL","Implementierung der Bildverarbeitung und des Uploads von Dateien im Mehrteil-Format in Node.js-Anwendungen"],"pt":["Gerar projetos de API RESTful com roteamento explícito usando Express ou Fastify","Desenvolver lógica de transação segura para operações de banco de dados seguras com Prisma e PostgreSQL","Implementar processamento de imagens e uploads de arquivos multipart em aplicações Node.js"],"ru":["Генерировать проекты API RESTful с явным маршрутизацией, используя Express или Fastify","Разрабатывать транзакционно-безопасную логику для безопасных операций с базами данных с помощью Prisma и PostgreSQL","Реализовывать обработку изображений и загрузку файлов multipart в приложениях Node.js"],"ar":["توليد تصاميم API RESTful مع تحديد مسار صريح باستخدام Express أو Fastify","تطوير منطق معاملات آمنة لعمليات قواعد البيانات الآمنة مع Prisma و PostgreSQL","تنفيذ معالجة الصور والتحميل المتنوع لملفات في تطبيقات Node.js"]},"limitations":{"en":["Requires Node.js and TypeScript knowledge","Specific to PostgreSQL and Prisma ORM for database operations","Dependent on Sharp for image processing capabilities"],"zh":["需要Node.js和TypeScript知识","特定于PostgreSQL和Prisma ORM的数据库操作","依赖于Sharp的图像处理能力"],"ja":["Node.jsおよびTypeScriptの知識が必要","データベース操作はPostgreSQLおよびPrisma ORMに特定","Sharpの画像処理能力に依存"],"ko":["Node.js 및 TypeScript 지식이 필요","데이터베이스操作은 PostgreSQL 및 Prisma ORM에 특정","Sharp의 이미지 처리 능력에 의존"],"es":["Requiere conocimiento de Node.js y TypeScript","Específico de PostgreSQL y Prisma ORM para operaciones de base de datos","Dependiente de Sharp para capacidades de procesamiento de imágenes"],"fr":["Nécessite des connaissances en Node.js et TypeScript","Spécifique à PostgreSQL et Prisma ORM pour les opérations de base de données","Dépendant de Sharp pour les capacités de traitement d''images"],"de":["Benötigt Kenntnisse von Node.js und TypeScript","Spezifisch für PostgreSQL und Prisma ORM für Datenbankoperationen","Abhängig von Sharp für Bildverarbeitungsfähigkeiten"],"pt":["Exige conhecimento de Node.js e TypeScript","Específico para PostgreSQL e Prisma ORM para operações de banco de dados","Dependente de Sharp para capacidades de processamento de imagens"],"ru":["Требует знания Node.js и TypeScript","Спецефичен для PostgreSQL и Prisma ORM для операций с базами данных","Зависит от Sharp для возможностей обработки изображений"],"ar":["يتطلب معرفة Node.js و TypeScript","محدد ل PostgreSQL و Prisma ORM لعمليات قواعد البيانات","يعتمد على Sharp لقدرات معالجة الصور"]},"version":4},"contentHash":"b12c0173c7ae678f2aff08829db3b64e53d98473be76376af097f44b25f9f205","qualityScore":35}');
