INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('webdevarif/rejoes-pos/rejoes-workspace', 'rejoes-workspace', 'webdevarif', 'rejoes-pos', 'community', 'rejoes-workspace webdevarif rejoes-pos community rejoes-workspace enables AI agents to confidently develop and manage Node.js backend applications with Express, Prisma, and PostgreSQL. It benefits developers by providing a robust and scalable framework. rejoes-workspace后端开发技能，专注于Node.js、Express、Prisma ORM等技术的应用 ReJoEs Backend AIエージェントは、Node.js、Express、Prisma ORMなどの技術を活用した開発を支援します rejoes-workspace 백엔드 개발 스킬은 Node.js, Express, Prisma ORM 등을 사용하여 개발을 지원합니다 ReJoEs Workspace es un entorno de desarrollo para crear aplicaciones backend con Node.js y TypeScript. Incluye Express, Prisma ORM y Sharp para procesamiento de imágenes. ReJoEs Workspace est un environnement de développement pour créer des applications backend avec Node.js et TypeScript. Il inclut Express, Prisma ORM et Sharp pour le traitement d''images. ReJoEs Workspace ist eine Entwicklungsumgebung für die Erstellung von Backend-Anwendungen mit Node.js und TypeScript. Es umfasst Express, Prisma ORM und Sharp für Bildverarbeitung. O ReJoEs Workspace é uma ferramenta de desenvolvimento de backend que utiliza Node.js, Express e Prisma para criar aplicações robustas. Com ele, você pode desenvolver APIs RESTful e lógica de transações seguras. ReJoEs Workspace - это инструмент для разработки бэкенда, который использует Node.js, Express и Prisma для создания прочных приложений. С его помощью вы можете разрабатывать RESTful API и логика транзакций. مساحة عمل ReJoEs هي أداة تطوير خلفية تستخدم Node.js و Express و Prisma لإنشاء تطبيقات قوية. من خلالها، يمكنك تطوير واجهات برمجة تطبيقات RESTful و 논리جية معاملات آمنة. how to use rejoes-workspace rejoes-workspace alternative rejoes-workspace setup guide Node.js backend development with rejoes-workspace rejoes-workspace vs Prisma rejoes-workspace install Express and Prisma tutorial PostgreSQL schema design with rejoes-workspace rejoes-workspace and Sharp image processing rejoes-workspace 后端开发 Node.js Express Prisma ORM SQLite PostgreSQL Sharp Multipart文件上传 Generates Node.js applications with TypeScript and explicit routing using Express or Fastify Utilizes Prisma ORM for database management with SQLite and PostgreSQL Supports image processing with Sharp and multipart file uploads Implements RESTful API design and transaction-safe logic Develops production-ready schemas with PostgreSQL rejoes-workspace is a technical skill that defines the capabilities and responsibilities of an AI agent in developing and managing a Node.js backend application using Express, Prisma, and PostgreSQL.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('abstratium-dev/abstrauth/run-tests', 'community', 'abstratium-dev', 'abstrauth', 'abstratium-dev/abstrauth', 'run-tests', 0, 0, 35, '2026-03-08T01:57:15.534Z', '2026-03-08T02:11:09.197Z', 'caa388b7aa4d7608c429cec8690409913b3361c17d74f92de383988850fe2ccf', '{"id":"abstratium-dev/abstrauth/run-tests","name":"run-tests","description":{"en":"The run-tests skill automates testing for developers, supporting Maven and Playwright for efficient unit, integration, and e2e testing. It benefits developers working with Quarkus backend and Angular frontend.","zh":"Run Tests技能允许您运行Angular和Quarkus测试，包括单元测试、集成测试和端到端测试","ja":"Run TestsスキルはAngularとQuarkusのテストを実行するためのものです","ko":"Run Tests 스킬은 Angular와 Quarkus 테스트를 실행하기 위한 것입니다","es":"El skill ''run-tests'' permite ejecutar pruebas de unidad, integración y extremo a extremo para el frontend de Angular y el backend de Quarkus","fr":"Le skill ''run-tests'' permet d''exécuter des tests d''unité, d''intégration et de bout en bout pour le frontend Angular et le backend Quarkus","de":"Das Skill ''run-tests'' ermöglicht die Ausführung von Einheit-, Integrations- und End-to-End-Tests für das Angular-Frontend und das Quarkus-Backend","pt":"O Run-Tests é uma habilidade que permite executar testes de unidade e integração para o frontend e backend de uma aplicação","ru":"Run-Tests - это навык, который позволяет запускать модульные и интеграционные тесты для frontend и backend приложения","ar":"Run-Tests هو مهارة يسمح بتشغيل الاختبارات الوحدوية والتكاملية للواجهة الأمامية والخلفية لتطبيق"},"seo":{"title":{"en":"run-tests: Automated Testing Setup Guide | AI Agent Skill","zh":"AIエージェントRun Tests Setup Guide","ja":"AIエージェントのRun Testsベストプラクティス","ko":"AI 에이전트 Run Tests 설정 가이드","es":"Guía de configuración para ejecutar pruebas con herramien...","fr":"Guide de configuration pour exécuter des tests