INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('abstratium-dev/abstrauth/run-tests', 'run-tests', 'abstratium-dev', 'abstrauth', 'community', 'run-tests abstratium-dev abstrauth community The run-tests skill automates testing for developers, supporting Maven and Playwright for efficient unit, integration, and e2e testing. It benefits developers working with Quarkus backend and Angular frontend. Run Tests技能允许您运行Angular和Quarkus测试，包括单元测试、集成测试和端到端测试 Run TestsスキルはAngularとQuarkusのテストを実行するためのものです Run Tests 스킬은 Angular와 Quarkus 테스트를 실행하기 위한 것입니다 El skill ''run-tests'' permite ejecutar pruebas de unidad, integración y extremo a extremo para el frontend de Angular y el backend de Quarkus Le skill ''run-tests'' permet d''exécuter des tests d''unité, d''intégration et de bout en bout pour le frontend Angular et le backend Quarkus Das Skill ''run-tests'' ermöglicht die Ausführung von Einheit-, Integrations- und End-to-End-Tests für das Angular-Frontend und das Quarkus-Backend O Run-Tests é uma habilidade que permite executar testes de unidade e integração para o frontend e backend de uma aplicação Run-Tests - это навык, который позволяет запускать модульные и интеграционные тесты для frontend и backend приложения Run-Tests هو مهارة يسمح بتشغيل الاختبارات الوحدوية والتكاملية للواجهة الأمامية والخلفية لتطبيق how to use run-tests run-tests setup guide automated testing with run-tests run-tests vs Jest run-tests install what is run-tests run-tests alternative run-tests for Quarkus run-tests for Angular AIエージェント Run Tests Angular测试 Quarkus测试 端到端测试 mvn test playwright test Runs Angular frontend tests using `mvn test -DskipTests -DskipITs` Executes unit and integration tests of the Quarkus backend with `mvn test` Supports e2e tests with Playwright using `npx playwright test` Allows for signup tests with `ALLOW_SIGNUP=true` environment variable Enables skipping of certain tests with `DskipTests` and `DskipITs` flags run-tests is a skill that provides a minimal implementation of an OAuth authorization server for automating tests, including unit, integration, and e2e tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alvaretto/proyecto-r-exams-icfes-matematicas-optimizado/generar-schoice', 'community', 'alvaretto', 'proyecto-r-exams-icfes-matematicas-optimizado', 'alvaretto/proyecto-r-exams-icfes-matematicas-optimizado', 'generar-schoice', 0, 0, 35, '2026-03-08T01:57:15.552Z', '2026-03-08T02:11:31.071Z', '47dcd30c09e1d4287f4c61ce6933082c089d9c85be2e461d3961ffddaa458e30', '{"id":"alvaretto/proyecto-r-exams-icfes-matematicas-optimizado/generar-schoice","name":"generar-schoice","description":{"en":"generar-schoice generates metacognitive exercises for Saber ICFES in Matemáticas, utilizing Progressive Disclosure. It benefits developers and educators seeking to create interactive math exercises.","zh":"generar-schoice 是一个用于生成 Metacognitivo Ejercicios 的工具，具有 Progressive Disclosure 和 Decision Tree 功能","ja":"generar-schoice は、Progressive Disclosure と Decision Tree 機能を備えたメタ認知的エクササイズ生成ツールです","ko":"generar-schoice는渐进披露와 의사결정 트리 기능을 갖춘 메타인식적 연습 생성기입니다","es":"Generar-Schoice es una herramienta para crear ejercicios metacognitivos con Progressive Disclosure. Se utiliza en el proyecto r-exams para Saber ICFES en Matemáticas.","fr":"Generar-Schoice est un outil pour créer des exercices métacognitifs avec Progressive Disclosure. Il est utilisé dans le projet r-exams pour Saber ICFES en Mathématiques.","de":"Generar-Schoice ist ein Tool zur Erstellung metakognitiver Übungen mit Progressive Disclosure. Es wird im r-exams-Projekt für Saber ICFES in Mathematik verwendet.","pt":"O gerador de exercicios SCHOICE é uma ferramenta para projetos de matemática que utiliza Progressive Disclosure e metacognição","ru":"ИИ Агент generar-schoice - это инструмент для проектов по математике, использующий прогрессивное раскрытие и метакогнитивные упражнения","ar":"أداة generar-schoice هي أداة لإنشاء تمارين متعدية المعرفة مع إفصاح تدريجي ل مشاريع الرياضيات"},"seo":{"title":{"en":"generar-schoice: Progressive Disclosure Setup Guide | AI ...","zh":"generar-schoice Setup Guide: 使用 Progressive Disclosure 的 ...","ja":"generar-schoice セットアップガイド: 逐次開示を使用したメタ認知的エクササイズ生成器","ko":"generar-schoice 설정 가이드: Progressive Disclosure를 사용한 메타인식적...","es":"Guía de Configuración de Generar-Schoice para Ejercicios ...","fr":"Guide de Configuration de Generar-Schoice pour des Exerci...","de":"Konfigurationsleitfaden für Generar-Schoice zur Erstellun...","pt":"Guia de Configuração do Gerador de Ejercicios SCHOICE","ru":"Настройка ИИ Агента generar-schoice для Метакогнитивных У...","ar":"دليل إعداد أداة generar-schoice لإنشاء تمارين متعدية المعرفة"},"description":{"en":"Unlock metacognitive exercises with generar-schoice. Discover how to implement Progressive Disclosure and explore TikZ, Python, and R integrations.","zh":"了解如何使用 generar-schoice 生成 Metacognitivo Ejercicios，并探索其 Decision Tree 和 Progressive Disclosure 功能","ja":"generar-schoice を使用してメタ認知的エクササイズを生成する方法を学び、その Decision Tree と Progressive Disclosure 機能を探索する","ko":"generar-schoice를 사용하여 메타인식적 연습을 생성하는 방법을 알아보고, 그 의사결정 트리와渐进披露 기능을 탐색하세요","es":"Aprende a configurar Generar-Schoice para crear ejercicios metacognitivos con Progressive Disclosure y analiza el enfoque del proyecto r-exams para Saber ICF...","fr":"Découvrez comment configurer Generar-Schoice pour créer des exercices métacognitifs avec Progressive Disclosure et analysez l''approche du projet r-exams pour...","de":"Erfahren Sie, wie Sie Generar-Schoice konfigurieren, um metakognitive Übungen mit Progressive Disclosure zu erstellen und analysieren Sie den Ansatz des r-ex...","pt":"Aprenda a configurar o gerador de exercicios SCHOICE para projetos de matemática com enfoque metacognitivo e Progressive Disclosure","ru":"Узнайте, как настроить ИИ Агент generar-schoice для создания метакогнитивных упражнений с прогрессивным раскрытием","ar":"تعلم كيفية إعداد أداة generar-schoice لإنشاء تمارين متعدية المعرفة مع إفصاح تدريجي"},"definition":{"en":"generar-schoice is a project for generating metacognitive exercises with a focus on Progressive Disclosure, designed for Saber ICFES in Matemáticas.","zh":"generar-schoice 是一个用于生成 Metacognitivo Ejercicios 的 AI 工具，具有 Progressive Disclosure 功能","ja":"generar-schoice は、メタ認知的エクササイズを生成する AI エージェントです","ko":"generar-schoice는 메타인식적 연습을 생성하는 AI 에이전트입니다","es":"Generar-Schoice es una herramienta de creación de ejercicios metacognitivos que utiliza Progressive Disclosure","fr":"Generar-Schoice est un outil de création d''exercices métacognitifs qui utilise Progressive Disclosure","de":"Generar-Schoice ist ein Tool zur Erstellung metakognitiver Übungen, das Progressive Disclosure verwendet","pt":"O que é um gerador de exercicios SCHOICE? É uma ferramenta que cria exercicios metacognitivos com Progressive Disclosure","ru":"Что такое ИИ Агент generar-schoice? Это инструмент, создающий метакогнитивные упражнения с прогрессивным раскрытием","ar":"ما هي أداة generar-schoice? هي أداة لإنشاء تمارين متعدية المعرفة مع إفصاح تدريجي"},"features":{"en":["Generates metacognitive exercises with Progressive Disclosure","Supports TikZ, Python, and R for graphical representations","Utilizes decision trees for user task analysis","Consults functional examples with graphics for reference","Executes /analizar-icfes for initial analysis"],"zh":["使用 Progressive Disclosure 生成 Metacognitivo Ejercicios"," Decision Tree 功能用于优化生成过程","支持 TikZ、Python 和 R 语言","具有 Consultar ejemplos funcionales similares 功能"],"ja":["Progressive Disclosure を使用してメタ認知的エクササイズを生成","Decision Tree 機能を使用して生成プロセスを最適化","TikZ、Python、R言語をサポート","Consultar ejemplos funcionales similares 機能を備える"],"ko":["渐进披露를 사용하여 메타인식적 연습을 생성","의사결정 트리 기능을 사용하여 생성 프로세스를 최적화","TikZ, Python, R 언어를 지원","Consultar ejemplos funcionales similares 기능을 갖춘"],"es":["Creación de ejercicios metacognitivos con Progressive Disclosure","Integración con el proyecto r-exams para Saber ICFES en Matemáticas","Análisis de ejercicios con TikZ, Python y R","Soporte para la creación de gráficos y ejemplos funcionales","Implementación de la regla crítica para ejercicios SCHOICE","Uso de Decision Tree para la toma de decisiones"],"fr":["Création d''exercices métacognitifs avec Progressive Disclosure","Intégration avec le projet r-exams pour Saber ICFES en Mathématiques","Analyse d''exercices avec TikZ, Python et R","Prise en charge de la création de graphiques et d''exemples fonctionnels","Mise en œuvre de la règle critique pour les exercices SCHOICE","Utilisation de Decision Tree pour la prise de décision"],"de":["Erstellung metakognitiver Übungen mit Progressive Disclosure","Integration mit dem r-exams-Projekt für Saber ICFES in Mathematik","Analyse von Übungen mit TikZ, Python und R","Unterstützung für die Erstellung von Grafiken und funktionalen Beispielen","Umsetzung der kritischen Regel für SCHOICE-Übungen","Verwendung von Decision Tree für die Entscheidungsfindung"],"pt":["Geração de exercicios metacognitivos com Progressive Disclosure","Análise ICFES para projetos de matemática","Suporte a gráficos com TikZ, Python e R","Estrutura de decisão para execução de tarefas","Integração com regras de metacognição"],"ru":["Генерация метакогнитивных упражнений с прогрессивным раскрытием","Анализ ICFES для проектов по математике","Поддержка графиков с помощью TikZ, Python и R","Структура принятия решений для выполнения задач","Интеграция с правилами метакогнитивных упражнений"],"ar":["إنشاء تمارين متعدية المعرفة مع إفصاح تدريجي","تحليل ICFES لمشاريع الرياضيات","دعم الرسومات باستخدام TikZ و Python و R","هيكل اتخاذ القرارات لتنفيذ المهام","التكامل مع قواعد التمارين المتعدية المعرفة"]},"keywords":{"en":["how to use generar-schoice","generar-schoice alternative","generar-schoice setup guide","what is generar-schoice","generar-schoice vs other math exercise generators","installing generar-schoice for AI agents"],"zh":["generar-schoice","Metacognitivo Ejercicios","Progressive Disclosure","Decision Tree","AI 工具","TikZ","Python","R 语言"],"ja":["generar-schoice","メタ認知的エクササイズ","Progressive Disclosure","Decision Tree","AI エージェント","TikZ","Python","R言語"],"ko":["generar-schoice","메타인식적 연습","渐进披露","의사결정 트리","AI 에이전트","TikZ","Python","R 언어"],"es":["Generar-Schoice","ejercicios metacognitivos","Progressive Disclosure","r-exams","Saber ICFES","Matemáticas","TikZ","Python","R","Decision Tree"],"fr":["Generar-Schoice","exercices métacognitifs","Progressive Disclosure","r-exams","Saber ICFES","Mathématiques","TikZ","Python","R","Decision Tree","outils d''intelligence artificielle"],"de":["Generar-Schoice","metakognitive Übungen","Progressive Disclosure","r-exams","Saber ICFES","Mathematik","TikZ","Python","R","Decision Tree","Künstliche Intelligenz Tools"],"pt":["gerador de exercicios SCHOICE","metacognição","Progressive Disclosure","projetos de matemática","análise ICFES","TikZ","Python","R","desenvolvimento de software educacional"],"ru":["ИИ Агент generar-schoice","метакогнитивные упражнения","прогрессивное раскрытие","проекты по математике","анализ ICFES","TikZ","Python","R","разработка образовательного программного обеспечения"],"ar":["أداة generar-schoice","تمارين متعدية المعرفة","إفصاح تدريجي","مشاريع الرياضيات","تحليل ICFES","TikZ","Python","R","تطوير البرمجيات التعليمية"]}},"owner":"alvaretto","repo":"proyecto-r-exams-icfes-matematicas-optimizado","repoPath":"alvaretto/proyecto-r-exams-icfes-matematicas-optimizado","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.552Z","topics":[],"category":"community","skillMd":{"name":"generar-schoice","description":">","version":"3.0","bodyPreview":"# Generador de Ejercicios SCHOICE Metacognitivos\n\n## REGLA CRÍTICA\n\n**⚠️ TODO ejercicio SCHOICE DEBE ser metacognitivo con Progressive Disclosure.**\n\nVer regla completa: `.claude/rules/ejercicios-metacognitivos.md`\n\n## Decision Tree\n\n```\nUser task -> Tiene analisis ICFES?\n    |-- No -> Ejecutar /analizar-icfes primero\n    +-- Si -> Tiene graficos?\n        |-- Si -> Preguntar version grafica (TikZ/Python/R)\n        |        +-- Consultar ejemplos funcionales similares con grafico\n        +-- No -","body":"# Generador de Ejercicios SCHOICE Metacognitivos\n\n## REGLA CRÍTICA\n\n**⚠️ TODO ejercicio SCHOICE DEBE ser metacognitivo con Progressive Disclosure.**\n\nVer regla completa: `.claude/rules/ejercicios-metacognitivos.md`\n\n## Decision Tree\n\n```\nUser task -> Tiene analisis ICFES?\n    |-- No -> Ejecutar /analizar-icfes primero\n    +-- Si -> Tiene graficos?\n        |-- Si -> Preguntar version grafica (TikZ/Python/R)\n        |        +-- Consultar ejemplos funcionales similares con grafico\n        +-- No -> Consultar ejemplos funcionales similares sin grafico\n                 +-- Seleccionar PATRON METACOGNITIVO\n                    |-- Patron 1: Analisis de Error Ajeno\n                    |-- Patron 2: Evaluacion de Afirmacion\n                    +-- Patron 3: Comparacion de Procedimientos\n                 +-- Generar .Rmd con nomenclatura oficial\n                    +-- Validar: Rscript scripts/validar-renderizado.R\n```\n\n## Proceso paso a paso\n\n### PASO 0: Seleccionar patron metacognitivo (OBLIGATORIO)\n\n**ANTES de cualquier otra accion, definir el patron metacognitivo:**\n\n| Patron | Cuando usar | Bloom | DOK |\n|--------|-------------|-------|-----|\n| **Analisis de Error Ajeno** | Ejercicios de calculo donde hay errores comunes | Analizar/Evaluar | 3 |\n| **Evaluacion de Afirmacion** | Ejercicios conceptuales sobre propiedades | Evaluar | 3 |\n| **Comparacion de Procedimientos** | Ejercicios con multiples metodos de solucion | Analizar | 3 |\n\n**Ejemplos:**\n\n```\nPatron 1 (Error Ajeno):\n\"Juan calculo el area de un circulo con radio 5 y obtuvo 10π.\n ¿Cual error conceptual cometio Juan?\"\n\nPatron 2 (Afirmacion):\n\"Maria afirma: ''Si duplico el radio, el area se duplica''.\n ¿Por que esta afirmacion es INCORRECTA?\"\n\nPatron 3 (Comparacion):\n\"Tres estudiantes resolvieron 2x + 5 = 13:\n Estudiante A: x = 4\n Estudiante B: x = 9\n Estudiante C: x = 6\n ¿Cual aplico correctamente el despeje?\"\n```\n\n### PASO 0.5: Seleccion de version grafica (si aplica)\n\nPreguntar al usuario:\n\n1. TikZ (imagen externa)\n2. Python (reticulate)\n3. R/ggplot2 (RECOMENDADO - nativo)\n\nNO continuar sin respuesta del usuario.\n\n### PASO 1: Verificar analisis ICFES\n\nConfirmar que existe clasificacion previa: Nivel, Competencia, Componente, Tipo = schoice.\n\n### PASO 2: Consultar ejemplos funcionales METACOGNITIVOS\n\nNUNCA generar codigo sin consultar ejemplos primero.\n\n```bash\n# Buscar ejemplos metacognitivos existentes\nls A-Produccion/03-En-Produccion/**/*metacognitivo*.Rmd\n\n# O ejemplos funcionales generales\nls A-Produccion/Ejemplos-Funcionales-Rmd/*.Rmd\n```\n\nLeer ejemplo completo y copiar patrones.\n\n### PASO 3: Definir pool de errores conceptuales (OBLIGATORIO)\n\n**ANTES de generar el codigo, documentar minimo 4-6 errores:**\n\n```r\nerrores_conceptuales <- list(\n  list(\n    codigo = \"XXX-YYY-01\",          # Ej: ALG-OPE-01\n    nombre = \"Nombre descriptivo\",\n    descripcion_corta = \"...\",       # Para opciones (max 80 chars)\n    descripcion_larga = \"...\",       # Para solucion (detallada)\n    causa_raiz = \"...\",              # Diagnostico pedagogico\n    calcula = function(...) { ... }  # Funcion que produce el distractor\n  ),\n  # ... mas errores\n)\n```\n\n**Taxonomia de codigos:**\n\n| Prefijo | Area |\n|---------|------|\n| ALG | Algebra |\n| ARI | Aritmetica |\n| EST | Estadistica |\n| GEO | Geometria |\n| FUN | Funciones |\n\n### PASO 4: Generar nombre con nomenclatura\n\nFormato: `[ejercicio]_metacognitivo_[competencia]_n[nivel]_schoice_v[version].Rmd`\n\n| Parte | Valores |\n|-------|---------|\n| `[ejercicio]` | Descriptivo snake_case |\n| `metacognitivo` | OBLIGATORIO en el nombre |\n| `[competencia]` | `interpretacion` / `formulacion` / `argumentacion` |\n| `n[nivel]` | `n2` / `n3` / `n4` (metacognitivo = minimo n2) |\n| `v[version]` | `v1`, `v2`, ... |\n\nVer: .claude/docs/NOMENCLATURA_ARCHIVOS_RMD.md\n\n### PASO 5: Crear carpeta en En-Desarrollo\n\n```bash\nmkdir -p A-Produccion/02-En-Desarrollo/[nombre_ejercicio]\n```\n\n### PASO 6: Generar codigo .Rmd METACOGNITIVO\n\nVer [anatomia metacognitiva del .Rmd](references/anatomia-metacognitiva.md) para las 8 secciones obligatorias.\n\n**Estructura OBLIGATORIA:**\n\n```\n1. ENCABEZADO YAML (con taxonomias cognitivas)\n2. CHUNK setup\n3. CHUNK data_generation (con pool de errores)\n4. CHUNK version_diversity_test\n5. CHUNK validaciones_matematicas\n6. SECCION Question (patron metacognitivo)\n7. SECCION Solution (analisis de error + reflexion)\n8. META-INFORMATION (DOK, Bloom, SOLO obligatorios)\n```\n\n### PASO 7: Validar renderizado\n\n```bash\nRscript .claude/skills/generar-schoice/scripts/validar-renderizado.R ejercicio.Rmd\n```\n\n### PASO 8: Verificar checklist metacognitivo\n\n**Pre-promocion, verificar:**\n\n- [ ] Pool de errores conceptuales con codigos\n- [ ] Respuesta erronea ≠ respuesta correcta\n- [ ] Distractores unicos\n- [ ] Solucion incluye analisis de error\n- [ ] Solucion incluye reflexion metacognitiva\n- [ ] Metadatos DOK, Bloom, SOLO presentes\n- [ ] DOK >= 2 (preferible 3)\n\n### PASO 9: Promocion\n\n```bash\n/promover-ejercicio [nombre_ejercicio]\n```\n\n## Condiciones criticas\n\n### Pre-generacion\n\n- Analisis ICFES completado\n- **Patron metacognitivo seleccionado**\n- **Pool de errores conceptuales definido (minimo 4)**\n- Ejemplo funcional similar identificado y leido\n- Nomenclatura calculada (incluye \"metacognitivo\")\n- Carpeta destino creada\n\n### Durante generacion\n\n- Funcion `generar_datos()` con aleatorizacion\n- **Pool de errores con funciones `calcula`**\n- **Pool de reflexiones metacognitivas**\n- Distractores basados en errores conceptuales (NUNCA aleatorios)\n- Formato espanol en todos los numeros\n- Metadatos ICFES completos (6 dimensiones)\n- **Metadatos cognitivos: DOK, Bloom, SOLO**\n- `exshuffle: TRUE` obligatorio (excepción: FALSE en SCHOICE con opciones gráficas PNG — ver `graficos-como-opciones.md`)\n\n### Post-generacion\n\n- Renderizado exitoso en 4 formatos (HTML, PDF, DOCX, NOPS)\n- Coherencia matematica pregunta-respuesta-distractores\n- **Respuesta erronea diferente de correcta**\n- Test de diversidad > 250 versiones unicas\n- **Solucion incluye todas las subsecciones obligatorias**\n\nNO terminar con errores pendientes.\n\n## Antipatrones PROHIBIDOS\n\n### 1. Ejercicio puramente procedimental\n\n```markdown\n❌ \"Calcula el area de un rectangulo con base 8 cm.\"\n```\n\n**Correccion:** Convertir a analisis de error:\n```markdown\n✓ \"Un estudiante calculo 8 + 5 = 13 como area. ¿Cual fue su error?\"\n```\n\n### 2. Distractores aleatorios\n\n```r\n❌ distractores <- respuesta + sample(-10:10, 3)\n```\n\n**Correccion:** Usar pool de errores:\n```r\n✓ distractores <- sapply(errores_conceptuales, function(e) e$calcula(...))\n```\n\n### 3. Solucion sin analisis\n\n```markdown\n❌ Solution\n========\nLa respuesta correcta es 40.\n```\n\n**Correccion:** Incluir analisis completo:\n```markdown\n✓ ### Analisis del Error\n✓ **Error identificado:** ...\n✓ **Causa raiz:** ...\n✓ ### Procedimiento Correcto\n✓ **Paso 1:** ...\n✓ ### Reflexion Metacognitiva\n✓ ...\n```\n\n## Referencias\n\n- [Anatomia Metacognitiva .Rmd](references/anatomia-metacognitiva.md) - Las 8 secciones obligatorias\n- [Anatomia .Rmd basica](references/anatomia-rmd.md) - Estructura general\n- [Errores comunes](references/errores-comunes.md) - Patrones incorrecto/correcto\n- [Ejemplos completos](references/ejemplos.md) - Nivel 1 aritmetica + Nivel 3 estadistica\n- Regla Metacognitiva: .claude/rules/ejercicios-metacognitivos.md\n- Ejemplos Funcionales: A-Produccion/Ejemplos-Funcionales-Rmd/\n- Nomenclatura: .claude/docs/NOMENCLATURA_ARCHIVOS_RMD.md\n- Ciclo Validacion: .claude/rules/ciclo-validacion.md\n- Metadatos: .claude/rules/codigo-rmd.md\n\n## Integracion con otros skills\n\n```\nanalizar-icfes -> generar-schoice -> validar-renderizado -> promover-ejercicio\n                       ↑\n                       |\n              Regla ejercicios-metacognitivos.md OBLIGATORIA\n```\n"},"lastSynced":"2026-03-08T02:11:31.071Z","agentAnalysis":{"suitability":{"en":"Perfect for Education Agents needing to generate metacognitive math exercises with Progressive Disclosure","zh":"非常适合需要生成具有进展性披露的元认知数学练习的教育代理","ja":"進歩的開示を持つメタ認知数学演習を生成する必要がある教育エージェントに最適","ko":"진행적 공개를 갖춘 메타인지 수학 연습을 생성해야 하는 교육 에이전트에게 적합","es":"Perfecto para Agentes de Educación que necesitan generar ejercicios matemáticos metacognitivos con Divulgación Progresiva","fr":"Parfait pour les Agents d''éducation ayant besoin de générer des exercices mathématiques métacognitifs avec Divulgation Progressive","de":"Perfekt für Bildungsagenten, die metakognitive Mathematikübungen mit progressiver Offenlegung erstellen müssen","pt":"Perfeito para Agentes de Educação que precisam gerar exercícios matemáticos metacognitivos com Divulgação Progressiva","ru":"Идеально подходит для образовательных агентов, которым необходимо генерировать метакогнитивные математические упражнения с прогрессивным раскрытием","ar":"مثالي لوسائل التعليم التي تحتاج إلى إنشاء تمارين رياضية متعاقبة مع الإفصاح التدريجي"},"recommendation":{"en":"Empowers agents to create interactive Saber ICFES math exercises utilizing Progressive Disclosure, benefiting developers and educators with metacognitive exercises in Matemáticas, and provides a decision tree for analysis and generation of exercises","zh":"赋予代理创建使用进展性披露的交互式Saber ICFES数学练习的能力，惠及开发人员和教育者以元认知练习在数学领域，并为分析和生成练习提供决策树","ja":"進歩的開示を使用したインタラクティブなSaber ICFES数学演習を作成するエージェントをエンパワーメントし、開発者と教育者にメタ認知演習を提供し、数学の分野で演習の分析と生成のための決定木を提供する","ko":"진행적 공개를 사용한 상호작용형 Saber ICFES 수학 연습을 생성할 수 있는 에이전트를 강화하여 개발자와 교육자에게 수학 분야의 메타인지 연습을 제공하고 연습의 분석 및 생성을 위한 의사결정 트리를 제공","es":"Habilita a los agentes a crear ejercicios interactivos de matemáticas Saber ICFES utilizando Divulgación Progresiva, beneficiando a los desarrolladores y educadores con ejer