INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alvaretto/proyecto-r-exams-icfes-matematicas-optimizado/generar-schoice', 'generar-schoice', 'alvaretto', 'proyecto-r-exams-icfes-matematicas-optimizado', 'community', 'generar-schoice alvaretto proyecto-r-exams-icfes-matematicas-optimizado community generar-schoice generates metacognitive exercises for Saber ICFES in Matemáticas, utilizing Progressive Disclosure. It benefits developers and educators seeking to create interactive math exercises. generar-schoice 是一个用于生成 Metacognitivo Ejercicios 的工具，具有 Progressive Disclosure 和 Decision Tree 功能 generar-schoice は、Progressive Disclosure と Decision Tree 機能を備えたメタ認知的エクササイズ生成ツールです generar-schoice는渐进披露와 의사결정 트리 기능을 갖춘 메타인식적 연습 생성기입니다 Generar-Schoice es una herramienta para crear ejercicios metacognitivos con Progressive Disclosure. Se utiliza en el proyecto r-exams para Saber ICFES en Matemáticas. Generar-Schoice est un outil pour créer des exercices métacognitifs avec Progressive Disclosure. Il est utilisé dans le projet r-exams pour Saber ICFES en Mathématiques. Generar-Schoice ist ein Tool zur Erstellung metakognitiver Übungen mit Progressive Disclosure. Es wird im r-exams-Projekt für Saber ICFES in Mathematik verwendet. O gerador de exercicios SCHOICE é uma ferramenta para projetos de matemática que utiliza Progressive Disclosure e metacognição ИИ Агент generar-schoice - это инструмент для проектов по математике, использующий прогрессивное раскрытие и метакогнитивные упражнения أداة generar-schoice هي أداة لإنشاء تمارين متعدية المعرفة مع إفصاح تدريجي ل مشاريع الرياضيات how to use generar-schoice generar-schoice alternative generar-schoice setup guide what is generar-schoice generar-schoice vs other math exercise generators installing generar-schoice for AI agents generar-schoice Metacognitivo Ejercicios Progressive Disclosure Decision Tree AI 工具 TikZ Python R 语言 Generates metacognitive exercises with Progressive Disclosure Supports TikZ, Python, and R for graphical representations Utilizes decision trees for user task analysis Consults functional examples with graphics for reference Executes /analizar-icfes for initial analysis generar-schoice is a project for generating metacognitive exercises with a focus on Progressive Disclosure, designed for Saber ICFES in Matemáticas.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kevoreilly/capemon/capemon-developer', 'community', 'kevoreilly', 'capemon', 'kevoreilly/capemon', 'capemon-developer', 0, 0, 35, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:38.587Z', '25b0266c3933f3b48b96dcbac37f1d9860493b08986fc9d319afa75a0a190f19', '{"id":"kevoreilly/capemon/capemon-developer","name":"capemon-developer","description":{"en":"capemon-developer is a sophisticated monitoring engine for malware analysis and configuration extraction, benefiting developers and security researchers. It provides deep visibility into application behavior.","zh":"capemon-developer 是一个用于恶意代码分析和CAPE 监控的监控引擎","ja":"capemon-developer は、AIエージェントのためのCAPE モニタリングとマルウェア分析を実現するモニタリングエンジン","ko":"capemon-developer는 악성 코드 분석과 CAPE 모니터링을 위한 모니터링 엔진","es":"Capemon-developer es un motor de monitoreo y instrumentación sofisticado para análisis de malware y extracción de configuraciones. Ofrece visibilidad profunda en el comportamiento de aplicaciones","fr":"Capemon-developer est un moteur de surveillance et d''instrumentation sophistiqué pour l''analyse de malware et l''extraction de configurations. Il offre une visibilité profonde dans le comportement des applications","de":"Capemon-developer ist ein fortschrittlicher Überwachungs- und Instrumentierungsmotor für Malware-Analyse und Konfigurationsextraktion. Er bietet tiefere Einblicke in das Verhalten von Anwendungen","pt":"O Capemon-Developer é um mecanismo de monitoramento e instrumentação sofisticado para análise de malware e recuperação de payload","ru":"Capemon-Developer - это сложный механизм мониторинга и инструментации для анализа вредоносного ПО и восстановления полезной нагрузки","ar":"Capemon-Developer هو ميكانيكي مراقبة ومؤشر متقدم لتحليل البرمجيات الخبيثة واستعادة الحمولة"},"seo":{"title":{"en":"capemon-developer: Advanced Monitoring Setup Guide | AI A...","zh":"ca