INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kevoreilly/capemon/capemon-developer', 'capemon-developer', 'kevoreilly', 'capemon', 'community', 'capemon-developer kevoreilly capemon community capemon-developer is a sophisticated monitoring engine for malware analysis and configuration extraction, benefiting developers and security researchers. It provides deep visibility into application behavior. capemon-developer 是一个用于恶意代码分析和CAPE 监控的监控引擎 capemon-developer は、AIエージェントのためのCAPE モニタリングとマルウェア分析を実現するモニタリングエンジン capemon-developer는 악성 코드 분석과 CAPE 모니터링을 위한 모니터링 엔진 Capemon-developer es un motor de monitoreo y instrumentación sofisticado para análisis de malware y extracción de configuraciones. Ofrece visibilidad profunda en el comportamiento de aplicaciones Capemon-developer est un moteur de surveillance et d''instrumentation sophistiqué pour l''analyse de malware et l''extraction de configurations. Il offre une visibilité profonde dans le comportement des applications Capemon-developer ist ein fortschrittlicher Überwachungs- und Instrumentierungsmotor für Malware-Analyse und Konfigurationsextraktion. Er bietet tiefere Einblicke in das Verhalten von Anwendungen O Capemon-Developer é um mecanismo de monitoramento e instrumentação sofisticado para análise de malware e recuperação de payload Capemon-Developer - это сложный механизм мониторинга и инструментации для анализа вредоносного ПО и восстановления полезной нагрузки Capemon-Developer هو ميكانيكي مراقبة ومؤشر متقدم لتحليل البرمجيات الخبيثة واستعادة الحمولة how to use capemon-developer capemon-developer setup guide capemon-developer alternative capemon-developer vs cuckoomon capemon-developer install advanced monitoring with capemon-developer malware analysis with capemon-developer capev2 sandbox integration capemon-developer CAPE 监控 恶意代码分析 API Hooking Process Management CAPEv2 Sandbox 配置提取 Payload Recovery Implements an extensive hooking engine derived from cuckoomon-modified Provides deep visibility into application behavior across multiple subsystems Monitors process and thread management, including creation and termination Supports API hooking and monitoring for advanced malware analysis Enables configuration extraction and payload recovery for security research capemon-developer is a core injection component for the CAPEv2 sandbox, designed for advanced monitoring and instrumentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('William-XiaodongAn/cardiac-agent/cardiac-model-generate', 'community', 'William-XiaodongAn', 'cardiac-agent', 'William-XiaodongAn/cardiac-agent', 'cardiac-model-generate', 0, 0, 35, '2026-03-08T01:57:15.570Z', '2026-03-08T02:11:45.294Z', '33529ef89e625109975e0373822a6ae0d7d7b6468ac0fe1e89174b5529c23b5f', '{"id":"William-XiaodongAn/cardiac-agent/cardiac-model-generate","name":"cardiac-model-generate","description":{"en":"The cardiac-model-generate skill generates Html simulation files based on provided model names and parameters, benefiting developers and researchers working with cardiac models.","zh":"心脏模型生成工具是一个用于生成HTML模拟文件的AI工具，支持模型参数的自定义和优化","ja":"Cardiac Model Generate Skillは、AIエージェントを使用して心脏モデルシミュレーションファイルを生成するツールです","ko":"심장 모델 생성 스킬은 HTML 시뮬레이션 파일을 생성하는 AI 도구로 모델 파라미터를 최적화 할 수 있습니다","es":"El generador de modelos cardíacos es una herramienta que permite a los usuarios obtener códigos y resultados de modelos cardíacos personalizados. Se utiliza para cambiar parámetros y generar archivos de simulación HTML","fr":"Le générateur de modèles cardiaques est un outil qui permet aux utilisateurs d''obtenir des codes et des résultats de modèles cardiaques sur mesure. Il est utilisé pour modifier des paramètres et générer des fichiers de simulation HTML","de":"Der Kardiomyokel-Generierung ist ein Tool, das es Benutzern ermöglicht, personalisierte Codes und Ergebnisse von Kardiomyokel-Modellen zu erhalten. Es wird verwendet, um Parameter zu ändern und HTML-Simulationsdateien zu generieren","pt":"O Cardiac Model Generate é uma habilidade que gera códigos e resultados de modelos cardíacos personalizados com base em parâmetros fornecidos.","ru":"ИИ Агент Cardiac Model Generate генерирует коды и результаты из кардиологических моделей на основе предоставленных параметров.","ar":"نموذج القلب التوليدي هو سمة تُولِّد أكو