INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('William-XiaodongAn/cardiac-agent/cardiac-model-generate', 'cardiac-model-generate', 'William-XiaodongAn', 'cardiac-agent', 'community', 'cardiac-model-generate William-XiaodongAn cardiac-agent community The cardiac-model-generate skill generates Html simulation files based on provided model names and parameters, benefiting developers and researchers working with cardiac models. 心脏模型生成工具是一个用于生成HTML模拟文件的AI工具，支持模型参数的自定义和优化 Cardiac Model Generate Skillは、AIエージェントを使用して心脏モデルシミュレーションファイルを生成するツールです 심장 모델 생성 스킬은 HTML 시뮬레이션 파일을 생성하는 AI 도구로 모델 파라미터를 최적화 할 수 있습니다 El generador de modelos cardíacos es una herramienta que permite a los usuarios obtener códigos y resultados de modelos cardíacos personalizados. Se utiliza para cambiar parámetros y generar archivos de simulación HTML Le générateur de modèles cardiaques est un outil qui permet aux utilisateurs d''obtenir des codes et des résultats de modèles cardiaques sur mesure. Il est utilisé pour modifier des paramètres et générer des fichiers de simulation HTML Der Kardiomyokel-Generierung ist ein Tool, das es Benutzern ermöglicht, personalisierte Codes und Ergebnisse von Kardiomyokel-Modellen zu erhalten. Es wird verwendet, um Parameter zu ändern und HTML-Simulationsdateien zu generieren O Cardiac Model Generate é uma habilidade que gera códigos e resultados de modelos cardíacos personalizados com base em parâmetros fornecidos. ИИ Агент Cardiac Model Generate генерирует коды и результаты из кардиологических моделей на основе предоставленных параметров. نموذج القلب التوليدي هو سمة تُولِّد أكواد ونَتائج مُخصّصة من نماذج القلب بناءً على المعلمات المُقدمة. how to use cardiac-model-generate cardiac-model-generate setup guide cardiac model simulation Html simulation file generation cardiac-model-generate alternative cardiac-model-generate install 心脏模型生成工具 AI工具 HTML模拟文件 模型参数优化 AI技术 快速部署 心脏模型模拟 AIエージェント Generates Html simulation files based on provided model names Allows parameter changes for customized model simulations Copies corresponding models from reference based on input Returns Html simulation files for further analysis or use Supports model simulation customization via parameter modification cardiac-model-generate is a skill that generates Html simulation files from cardiac models based on provided names and parameters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chongdashu/threejs-capacitor-ios-game/threejs-capacitor-ios', 'community', 'chongdashu', 'threejs-capacitor-ios-game', 'chongdashu/threejs-capacitor-ios-game', 'threejs-capacitor-ios', 0, 0, 35, '2026-03-08T01:57:15.586Z', '2026-03-08T02:11:57.626Z', '9aa8326a0cd837637dfacca7c906e209c334bc1399a45b0108619f8f66a8feb6', '{"id":"chongdashu/threejs-capacitor-ios-game/threejs-capacitor-ios","name":"threejs-capacitor-ios","description":{"en":"The threejs-capacitor-ios skill enables developers to build interactive 3D apps that run in the browser and on iOS devices via Capacitor. It focuses on the integration of web build output, animation contracts, and native sync/run workflow.","zh":"Three.js Capacitor iOS是用于构建交互式Three.js应用的技能，实现web和native的无缝集成","ja":"Three.js Capacitor iOSは、インタラクティブなThree.jsアプリを構築するためのスキルで、webとnativeのシームレスな統合を実現","ko":"Three.js Capacitor iOS는 상호작용하는 Three.js 애플리케이션을 구축하기 위한 스킬로 웹과 네이티브의 무결한 통합을 제공","es":"Three.js Capacitor iOS es una habilidad que permite crear aplicaciones web y nativas interactivas con renderizado y animaciones suaves. Se centra en la integración de la salida de la construcción web, los contratos de animación y los controles","fr":"Three.js Capacitor iOS est une compétence qui permet de créer des applications web et natives interactives avec un rendu et des animations fluides. Elle se concentre sur l''intégration de la sortie de construction web, des contrats d''animation et des contrôles","de":"Three.js Capacitor iOS ist eine Fähigkeit, die die Erstellung interaktiver Web- und Native-Apps mit glatter Renderung und Animation ermöglicht. Sie konzentriert sich auf die Integration der Web-Build-Ausgabe, der Animationsverträge und der Steuerung","pt":"O threejs-capacitor-ios permite a criação de aplicações interativas que funcionam em navegadores e dispositivos móveis, utilizando o Three.js e o Capacitor iOS","ru":"ИИ Агенты: threejs-capacitor-ios позволяет создавать интерактивные приложения, работающие в браузерах и на мобильных устройствах, используя Three.js и Capacitor iOS","ar":"ثلاثي الأبعاد مع threejs-capacitor-ios يتيح إنشاء تطبيقات تفاعلية تعمل على المتصفحات والأجهزة النقالة باستخدام Three.js و Capacitor iOS"},"seo":{"title":{"en":"threejs-capacitor-ios: Build Interactive 3D Apps with Two...","zh":"Three.js Capacitor iOS 集成指南","ja":"Three.js Capacitor iOS統合ガイド","ko":"Three.js Capacitor iOS 설정 가이드","es":"Guía de configuración de Three.js Capacitor iOS para apli...","fr":"Guide de mise en place de Three.js Capacitor iOS pour les...","de":"Einrichtungsleitfaden für Three.js Capacitor iOS für Web-...","pt":"Guia de Configuração threejs-capacitor-ios para Desenvolv...","ru":"ИИ Агенты: Настройка threejs-capacitor-ios для Мобильных ...","ar":"إعداد ثلاثي الأبعاد مع threejs-capacitor-ios للويب والموبايل"},"description":{"en":"Discover how to integrate Three.js with Capacitor for iOS, enabling seamless 3D app development. Learn more and get started with our expert guide!","zh":"使用Three.js和Capacitor构建交互式iOS应用，实现web和native的无缝集成","ja":"Three.jsとCapacitorを使用してインタラクティブなiOSアプリを構築し、webとnativeのシームレスな統合を実現","ko":"Three.js와 Capacitor를 사용하여 상호작용하는 iOS 애플리케이션을 구축하고 웹 및 네이티브의 무缝한 통합을实现","es":"Aprende a integrar Three.js con Capacitor iOS para crear aplicaciones web y nativas interactivas con renderizado y animaciones suaves","fr":"Découvrez comment intégrer Three.js avec Capacitor iOS pour créer des applications web et natives interactives avec un rendu et des animations fluides","de":"Erfahren Sie, wie Sie Three.js mit Capacitor iOS integrieren, um interaktive Web- und Native-Apps mit glatter Renderung und Animation zu erstellen","pt":"Aprenda a integrar o Three.js com o Capacitor iOS para criar aplicações interativas que funcionam em navegadores e dispositivos móveis","ru":"Интегрируйте Three.js с Capacitor iOS для создания интерактивных приложений, работающих в браузерах и на мобильных устройствах","ar":"تعلم كيفية دمج Three.js مع Capacitor iOS لإنشاء تطبيقات تفاعلية تعمل على المتصفحات والأجهزة النقالة"},"definition":{"en":"threejs-capacitor-ios is a skill that integrates Three.js with Capacitor for iOS, allowing for the development of interactive 3D apps that run on both web and native platforms.","zh":"Three.js Capacitor iOS是用于构建交互式Three.js应用的技能，实现web和native的集成","ja":"Three.js Capacitor iOSは、インタラクティブなThree.jsアプリを構築するためのスキル","ko":"Three.js Capacitor iOS는 상호작용하는 Three.js 애플리케이션을 구축하기 위한 스킬","es":"Three.js Capacitor iOS es una habilidad que integra Three.js con Capacitor iOS para crear aplicaciones web y nativas interactivas","fr":"Three.js Capacitor iOS est une compétence qui intègre Three.js avec Capacitor iOS pour créer des applications web et natives interactives","de":"Three.js Capacitor iOS ist eine Fähigkeit, die Three.js mit Capacitor iOS integriert, um interaktive Web- und Native-Apps zu erstellen","pt":"O threejs-capacitor-ios é uma habilidade que permite a integração do Three.js com o Capacitor iOS","ru":"ИИ Агенты: threejs-capacitor-ios - это навык, позволяющий интегрировать Three.js с Capacitor iOS","ar":"ثلاثي الأبعاد مع threejs-capacitor-ios هو مهارة تتيح دمج Three.js مع Capacitor iOS"},"features":{"en":["Integrates Three.js with Capacitor for iOS native shell","Supports web build output and animation contracts","Enables native sync/run workflow for seamless app development","Utilizes Vite for web renderer runtime","Treats the project as two systems with a single contract: web and native"],"zh":["使用Three.js和Vite构建交互式web应用","使用Capacitor实现web和native的无缝集成","支持animation contracts和controls","实现native sync/run workflow"],"ja":["Three.jsとViteを使用してインタラクティブなwebアプリを構築","Capacitorを使用してwebとnativeのシームレスな統合を実現","animation contractsとcontrolsをサポート","native sync/run workflowを実現"],"ko":["Three.js와 Vite를 사용하여 상호작용하는 웹 애플리케이션을 구축","Capacitor를 사용하여 웹과 네이티브의 무결한 통합을 제공","animation contracts와 controls를 지원","네이티브 동기화/실행 워크플ロー 구현"],"es":["Integración de Three.js con Capacitor iOS","Renderizado y animaciones suaves en aplicaciones web y nativas","Contratos de animación y controles personalizables","Compatibilidad con Vite y otros frameworks de construcción web","Soporte para aplicaciones web y nativas en iOS"],"fr":["Intégration de Three.js avec Capacitor iOS","Rendu et animations fluides dans les applications web et natives","Contrats d''animation et contrôles personnalisables","Compatibilité avec Vite et d''autres frameworks de construction web","Prise en charge des applications web et natives sous iOS"],"de":["Integration von Three.js mit Capacitor iOS","Glatter Renderung und Animation in Web- und Native-Apps","Anpassbare Animationsverträge und Steuerung","Kompatibilität mit Vite und anderen Web-Build-Frameworks","Unterstützung für Web- und Native-Apps unter iOS"],"pt":["Integração do Three.js com o Capacitor iOS","Criação de aplicações interativas que funcionam em navegadores e dispositivos móveis","Utilização do Vite para renderização web","Compatibilidade com a filosofia de dois tempos de execução","Suporte a animações e controles","Sincronização e execução de workflows nativos"],"ru":["Интеграция Three.js с Capacitor iOS","Создание интерактивных приложений, работающих в браузерах и на мобильных устройствах","Использование Vite для веб-рендеринга","Соответствие философии двух систем выполнения","Поддержка анимаций и контролей","Синхронизация и выполнение родных рабочих процессов"],"ar":["دمج Three.js مع Capacitor iOS","إنشاء تطبيقات تفاعلية تعمل على المتصفحات والأجهزة النقالة","استخدام Vite للترndering الويب","الامتثال لفلسفة النظامين الزمنيين","دعم Animations والتحكم","مزامنة وتشغيل سير العمل الأصلي"]},"keywords":{"en":["how to use threejs-capacitor-ios","threejs-capacitor-ios alternative","threejs-capacitor-ios install","threejs-capacitor-ios setup guide","what is threejs-capacitor-ios","threejs-capacitor-ios vs react native"],"zh":["Three.js","Capacitor","iOS","web和native集成","交互式应用","AIエージェント","前端开发"],"ja":["Three.js","Capacitor","iOS","webとnativeの統合","インタラクティブなアプリ","AIエージェント","フロントエンド開発"],"ko":["Three.js","Capacitor","iOS","웹과 네이티브 통합","상호작용하는 애플리케이션","AI 도구","프론트엔드 개발"],"es":["Three.js Capacitor iOS","aplicaciones web y nativas","renderizado y animaciones","integrated Three.js","Capacitor iOS","Vite","frameworks de construcción web","iOS"],"fr":["Three.js Capacitor iOS","applications web et natives","rendu et animations","integrated Three.js","Capacitor iOS","Vite","frameworks de construction web","iOS"],"de":["Three.js Capacitor iOS","Web- und Native-Apps","Renderung und Animation","integrated Three.js","Capacitor iOS","Vite","Web-Build-Frameworks","iOS"],"pt":["threejs-capacitor-ios","Desenvolvimento de aplicações móveis","Integração do Three.js com o Capacitor iOS","Criação de aplicações interativas","Vite","Filosofia de dois tempos de execução","Animações e controles","Sincronização e execução de workflows nativos"],"ru":["threejs-capacitor-ios","Разработка мобильных приложений","Интеграция Three.js с Capacitor iOS","Создание интерактивных приложений","Vite","Философия двух систем выполнения","Анимации и контроли","Синхронизация и выполнение родных рабочих процессов"],"ar":["threejs-capacitor-ios","تطوير التطبيقات النقالة","دمج Three.js مع Capacitor iOS","إنشاء تطبيقات تفاعلية","Vite","فلسفة النظامين الزمنيين","Animations والتحكم","مزامنة وتشغيل سير العمل الأصلي"]}},"owner":"chongdashu","repo":"threejs-capacitor-ios-game","repoPath":"chongdashu/threejs-capacitor-ios-game","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.586Z","topics":[],"category":"community","skillMd":{"name":"threejs-capacitor-ios","description":"Build and ship Three.js apps on Capacitor iOS with Vite and Swift Package Manager: GLTF loading, assets_index animation UI, OrbitControls mouse/touch mappings, and iOS sync/run troubleshooting.","bodyPreview":"# Three.js Capacitor iOS\n\nBuild interactive Three.js apps that run in browser and ship in an iOS native shell via Capacitor.\nThis skill focuses on the integration boundary where most breakage happens: web build output, animation contracts, controls, and native sync/run workflow.\n\n## Philosophy: Two Runtimes, One Contract\n\nTreat the project as two systems that must agree:\n- A web renderer runtime (Three.js + Vite)\n- A native runtime wrapper (Capacitor iOS)\n\nMost failures happen when their contrac","body":"# Three.js Capacitor iOS\n\nBuild interactive Three.js apps that run in browser and ship in an iOS native shell via Capacitor.\nThis skill focuses on the integration boundary where most breakage happens: web build output, animation contracts, controls, and native sync/run workflow.\n\n## Philosophy: Two Runtimes, One Contract\n\nTreat the project as two systems that must agree:\n- A web renderer runtime (Three.js + Vite)\n- A native runtime wrapper (Capacitor iOS)\n\nMost failures happen when their contract is implicit.\nMake file paths, animation names, build output, and iOS package manager choices explicit and testable.\n\n**Before implementing, ask:**\n- What is the exact web output directory (`dist` or `www`) and does Capacitor `webDir` match it?\n- Are animation names loaded from data (`assets_index.json`) instead of hardcoded strings?\n- Is iOS using SPM or CocoaPods, and are plugin dependencies compatible with that choice?\n- Are desktop and touch controls intentionally mapped, or left to defaults that may not match product UX?\n\n**Core principles:**\n1. Contract-first data flow: UI and animation playback should derive from JSON metadata, not ad-hoc clip names in code.\n2. SPM-first iOS setup: on modern Capacitor, default to Swift Package Manager unless a specific plugin forces CocoaPods.\n3. Symmetric controls: define mouse and touch mappings together so desktop and mobile behavior stay aligned.\n4. Build-sync discipline: every native run depends on fresh web assets and sync.\n5. Fast diagnosis: prefer small runtime checks for paths, clip names, and action resolution before deep debugging.\n\n## Quick Start Workflow\n\n1. Build the Three.js app with Vite (`npm run build`).\n2. Keep static assets under `public/` and load via absolute URLs (`/assets/...`).\n3. Configure Capacitor with `webDir: \"dist\"`.\n4. Add iOS platform with SPM (`npx cap add ios --packagemanager SPM`).\n5. Repeat day-to-day loop:\n   - `npm run build`\n   - `npx cap sync ios`\n   - `npx cap run ios` or `npx cap open ios`\n\nFor command-level details, see `references/capacitor-ios-spm-workflow.md`.\n\n## Implementation Guidelines\n\n### 1) Project Shape\n\nPrefer this shape for minimal ambiguity:\n- `index.html` and `src/*` for app code\n- `public/assets/...` for GLBs and JSON contracts\n- `capacitor.config.ts` with `webDir: \"dist\"`\n\nIf using Vite, keep all runtime fetches compatible with both browser and WKWebView:\n- Good: `fetch(''/assets/assets_index.json'')`\n- Avoid: filesystem paths or environment-specific base URLs unless intentionally configured.\n\n### 2) Animation Contract via `assets_index.json`\n\nUse one source of truth:\n- Character skeleton URL\n- Animation source URL\n- `animations[]` entries with:\n  - stable app id (`idle`, `walk`, `run`)\n  - `sourceClipName` (exact `AnimationClip.name`)\n  - loop mode and defaults\n\nRuntime pattern:\n1. Load index JSON\n2. Load skeleton GLB and animation GLB\n3. Resolve each UI button to a clip by `sourceClipName`\n4. Build `AnimationAction` map keyed by app id\n5. Play default action from index\n\nSee `references/threejs-animation-index-pattern.md`.\n\n### 3) Controls: Desktop and Touch\n\nUse `OrbitControls` and set mappings explicitly:\n- Mouse:\n  - left = rotate\n  - wheel = dolly/zoom\n  - right = pan\n- Touch:\n  - one-finger = rotate\n  - two-finger = dolly + pan\n\nIf product requires vertical-only pan, constrain target/camera translation after `controls.update()` each frame.\nDo not silently change rotate/zoom semantics when adding this constraint.\n\n### 4) Performance and Stability Guardrails\n\n- Cap pixel ratio: `Math.min(devicePixelRatio, 2)`.\n- Reuse mixer/actions; do not recreate per click.\n- On resize, always update camera aspect, projection, and renderer size.\n- Keep animation switching with fade transitions from metadata defaults.\n\n### 5) Capacitor iOS Integration\n\nUse SPM by default with Capacitor 8+.\nFor existing CocoaPods projects, migrate intentionally (assistant or recreate iOS platform).\n\nAfter native-side changes or plugin changes, run `npx cap sync ios` again.\n\n## Anti-Patterns to Avoid\n\n❌ **Hardcoding clip names in UI handlers**\nWhy bad: a renamed clip in GLB silently breaks buttons.\nBetter: map buttons from `assets_index.json` and resolve clip names once at startup.\n\n❌ **Mixing SPM and CocoaPods assumptions**\nWhy bad: dependency drift and broken Xcode project expectations.\nBetter: choose one package manager per project; for modern setups prefer SPM.\n\n❌ **Running iOS without rebuilding web assets**\nWhy bad: simulator shows stale JS/CSS and debugging becomes misleading.\nBetter: use scripts that always build before `cap sync`/`cap run`.\n\n❌ **Leaving control mappings implicit**\nWhy bad: desktop and mobile interaction diverge from UX requirements.\nBetter: set `mouseButtons` and `touches` explicitly in code.\n\n❌ **Debugging native first for web contract errors**\nWhy bad: wastes time in Xcode when issue is usually missing JSON keys, bad paths, or unresolved clips.\nBetter: add startup assertions/logs for index shape and clip resolution.\n\n## Variation Guidance\n\n**IMPORTANT**: Do not produce identical viewers by default.\nAdjust implementation to the product intent:\n- Character showcase: richer lighting, slower camera damping, emphasis on idle loop.\n- Gameplay prototype: fast transitions, state-driven animation switching, minimal UI chrome.\n- Asset QA tool: diagnostics overlay, clip length/track info, missing-clip warnings surfaced clearly.\n\nVary at least these dimensions intentionally:\n- Visual style (lighting/background/floor treatment)\n- Input tuning (damping/zoom/pan speeds)\n- Animation UX (buttons, keyboard shortcuts, auto-play strategy)\n\nAvoid converging on a single generic \"orbit + three buttons\" output when context calls for more.\n\n## Resource Map\n\n- `references/capacitor-ios-spm-workflow.md`\n  - canonical iOS setup, migration, and run commands\n- `references/threejs-animation-index-pattern.md`\n  - index contract and runtime loading pattern\n- `references/gotchas.md`\n  - high-frequency integration failures and fixes\n\n## Remember\n\nThree.js + Capacitor iOS succeeds when contracts are explicit and workflows are disciplined.\nBuild a clear metadata contract, map controls intentionally, prefer SPM on modern Capacitor, and keep build/sync/run deterministic.\n"},"lastSynced":"2026-03-08T02:11:57.626Z","agentAnalysis":{"suitability":{"en":"Perfect for Cross-Platform Agents needing interactive 3D app development with Three.js and Capacitor integration.","zh":"适用于需要交互式 3D 应用开发的跨平台代理，集成了 Three.js 和 Capacitor。","ja":"Three.js と Capacitor の統合を必要とするクロスプラットフォーム エージェントのインタラクティブ 3D アプリ開発に最適。","ko":"Three.js와 Capacitor를 통합하여 대화형 3D 앱 개발이 필요한 크로스 플랫폼 에이전트에 적합합니다.","es":"Perfecto para agentes de plataforma cruzada que necesitan desarrollo de aplicaciones interactivas 3D con Three.js y integración de Capacitor.","fr":"Parfait pour les agents de plateforme croisée nécessitant un développement d''applications interactives 3D avec Three.js et une intégration de Capacitor.","de":"Perfekt für Cross-Platform-Agents, die interaktive 3D-App-Entwicklung mit Three.js und Capacitor-Integration benötigen.","pt":"Perfeito para agentes Cross-Platform que necessitam de desenvolvimento de aplicativos 3D interativos com Three.js e integração com Capacitor.","ru":"Идеально для агентов Cross-Platform, которым необходим разработка интерактивных 3D-приложений с помощью Three.js и интеграции с Capacitor.","ar":"مثالي للوكلاء المتعددة المنصات الذين يحتاجون إلى تطوير تطبيقات 3D تفاعلية مع Three.js و Capacitor"},"recommendation":{"en":"Empowers agents to build interactive 3D apps that run seamlessly in the browser and on iOS devices via Capacitor, leveraging web build output, animation contracts, and native sync/run workflow with Three.js and Vite.","zh":"赋予代理构建可以在浏览器和 iOS 设备上无缝运行的交互式 3D 应用，利用 Web 构建输出、动画合同和 Three.js、Vite 的原生同步/运行工作流。","ja":"エージェントに、ブラウザと iOS デバイスでシームレスに実行されるインタラクティブ 3D アプリを構築する能力を提供します。Web ビルド出力、 애니메이션契約、Three.js と Vite のネイティブ同期/実行ワークフローを利用。","ko":"에이전트가 브라우저와 iOS 기기에서 무결점으로 실행되는 대화형 3D 앱을 구축할 수 있는 기능을 제공합니다. Three.js와 Vite의 웹 빌드 출력, 애니메이션 계약 및 네이티브 동기화/실행 워크플로를 활용합니다.","es":"Habilita a los agentes a crear aplicaciones interactivas 3D que se ejecutan de manera fluida en el navegador y en dispositivos iOS a través de Capacitor, aprovechando la salida de compilación web, los contratos de animación y el flujo de trabajo de sincronización/ejecución nativa con Three.js y Vite.","fr":"Permet aux agents de créer des applications interactives 3D qui s''exécutent sans problème dans le navigateur et sur les appareils iOS via Capacitor, en exploitant la sortie de build Web, les contrats d''animation et le workflow de synchronisation/exécution natif avec Three.js et Vite.","de":"Ermächtigt Agenten, interaktive 3D-Apps zu erstellen, die nahtlos im Browser und auf iOS-Geräten über Capacitor ausgeführt werden, indem sie die Web-Build-Ausgabe, Animationsverträge und den nativen Synchronisations-/Ausführungs-Workflow mit Three.js und Vite nutzen.","pt":"Habilita os agentes a construir aplicativos 3D interativos que executam de forma perfeita no navegador e em dispositivos iOS via Capacitor, aproveitando a saída de build da web, contratos de animação e fluxo de trabalho de sincronização/nativa com Three.js e Vite.","ru":"Наделяет агентов возможностью создавать интерактивные 3D-приложения, которые работают без проблем в браузере и на устройствах iOS через Capacitor, используя веб-выходные данные сборки, анимационные контракты и родной синхронизации/выполнения рабочий процесс с Three.js и Vite.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات 3D تفاعلية تعمل بسلاسة في المتصفح وأجهزة iOS من خلال Capacitor، مع الاستفادة من مخرجات بناء الويب، وعقود الرسوم المتحركة، وعمليات سير عمل التزام وتشغيل الأصلي مع Three.js و Vite"},"useCases":{"en":["Building interactive 3D simulations for iOS devices","Integrating Three.js animations with native iOS controls","Debugging web build output for Capacitor iOS projects"],"zh":["为 iOS 设备构建交互式 3D 模拟","将 Three.js 动画与原生 iOS 控件集成","调试 Capacitor iOS 项目的 Web 构建输出"],"ja":["iOS デバイス用のインタラクティブ 3D シミュレーションを構築","Three.js のアニメーションをネイティブの iOS コントロールと統合","Capacitor の iOS プロジェクトの Web ビルド出力をデバッグ"],"ko":["iOS 기기용 대화형 3D 시뮬레이션 구축","Three.js 애니메이션을 네이티브 iOS 컨트롤과 통합","Capacitor iOS 프로젝트의 웹 빌드 출력 디버깅"],"es":["Creación de simulaciones interactivas 3D para dispositivos iOS","Integración de animaciones de Three.js con controles nativos de iOS","Depuración de la salida de compilación web para proyectos de iOS de Capacitor"],"fr":["Création de simulations interactives 3D pour les appareils iOS","Intégration d''animations Three.js avec des contrôles natifs iOS","Débogage de la sortie de build Web pour les projets iOS de Capacitor"],"de":["Erstellung interaktiver 3D-Simulationen für iOS-Geräte","Integration von Three.js-Animationen mit nativen iOS-Steuerungselementen","Fehlersuche der Web-Build-Ausgabe für Capacitor-iOS-Projekte"],"pt":["Construir simulações 3D interativas para dispositivos iOS","Integrar animações Three.js com controles iOS nativos","Depurar saída de build da web para projetos iOS do Capacitor"],"ru":["Создание интерактивных 3D-симуляций для устройств iOS","Интеграция анимаций Three.js с родными элементами управления iOS","Отладка веб-выходных данных сборки для проектов iOS Capacitor"],"ar":["بناء محاكيات 3D تفاعلية لأجهزة iOS","دمج الرسوم المتحركة Three.js مع عناصر التحكم الأصلية في iOS","تصحيح أخطاء مخرجات بناء الويب لمشاريع iOS في Capacitor"]},"limitations":{"en":["Requires Capacitor and Three.js setup","Limited to iOS native shell deployment","Dependent on Vite for web build output"],"zh":["需要 Capacitor 和 Three.js 设置","仅限 iOS 原生 shell 部署","依赖 Vite 进行 Web 构建输出"],"ja":["Capacitor と Three.js の設定が必要","ネイティブ シェルのデプロイは iOS 限定","Web ビルド出力には Vite 依存"],"ko":["Capacitor와 Three.js 설정이 필요합니다","네이티브 셸 배포는 iOS 전용입니다","웹 빌드 출력에는 Vite가 필요합니다"],"es":["Requiere configuración de Capacitor y Three.js","Limitado a la implementación de shell nativa de iOS","Dependiente de Vite para la salida de compilación web"],"fr":["Nécessite une configuration de Capacitor et Three.js","Limité au déploiement de coquille native iOS","Dépendant de Vite pour la sortie de build Web"],"de":["Benötigt Capacitor- und Three.js-Setup","Begrenzt auf native iOS-Shell-Bereitstellung","Abhängig von Vite für die Web-Build-Ausgabe"],"pt":["Requer configuração do Capacitor e Three.js","Limitado à implantação de shell nativo do iOS","Dependente do Vite para saída de build da web"],"ru":["Требует настройки Capacitor и Three.js","Ограничен развертыванием родной оболочки iOS","Зависит от Vite для веб-выходных данных сборки"],"ar":["يتطلب إعداد Capacitor و Three.js","محدود بنشر حلقة الأصلية في iOS","يعتمد على Vite لمخرجات بناء الويب"]},"version":4},"contentHash":"9aa8326a0cd837637dfacca7c906e209c334bc1399a45b0108619f8f66a8feb6","qualityScore":35}');
DELETE FROM skills_fts WHERE id = 'chongdashu/threejs-capacitor-ios-game/threejs-capacitor-ios';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chongdashu/threejs-capacitor-ios-game/threejs-capacitor-ios', 'threejs-capacitor-ios', 'chongdashu', 'threejs-capacitor-ios-game', 'community', 'threejs-capacitor-ios chongdashu threejs-capacitor-ios-game community The threejs-capacitor-ios skill enables developers to build interactive 3D apps that run in the browser and on iOS devices via Capacitor. It focuses on the integration of web build output, animation contracts, and native sync/run workflow. Three.js Capacitor iOS是用于构建交互式Three.js应用的技能，实现web和native的无缝集成 Three.js Capacitor iOSは、インタラクティブなThree.jsアプリを構築するためのスキルで、webとnativeのシームレスな統合を実現 Three.js Capacitor iOS는 상호작용하는 Three.js 애플리케이션을 구축하기 위한 스킬로 웹과 네이티브의 무결한 통합을 제공 Three.js Capacitor iOS es una habilidad que permite crear aplicaciones web y nativas interactivas con renderizado y animaciones suaves. Se centra en la integración de la salida de la construcción web, los contratos de animación y los controles Three.js Capacitor iOS est une compétence qui permet de créer des applications web et natives interactives avec un rendu et des animations fluides. Elle se concentre sur l''intégration de la sortie de construction web, des contrats d''animation et des contrôles Three.js Capacitor iOS ist eine Fähigkeit, die die Erstellung interaktiver Web- und Native-Apps mit glatter Renderung und Animation ermöglicht. Sie konzentriert sich auf die Integration der Web-Build-Ausgabe, der Animationsverträge und der Steuerung O threejs-capacitor-ios permite a criação de aplicações interativas que funcionam em navegadores e dispositivos móveis, utilizando o Three.js e o Capacitor iOS ИИ Агенты: threejs-capacitor-ios позволяет создавать интерактивные приложения, работающие в браузерах и на мобильных устройствах, используя Three.js и Capacitor iOS ثلاثي الأبعاد مع threejs-capacitor-ios يتيح إنشاء تطبيقات تفاعلية تعمل على المتصفحات والأجهزة النقالة باستخدام Three.js و Capacitor iOS how to use threejs-capacitor-ios threejs-capacitor-ios alternative threejs-capacitor-ios install threejs-capacitor-ios setup guide what is threejs-capacitor-ios threejs-capacitor-ios vs react native Three.js Capacitor iOS web和native集成 交互式应用 AIエージェント 前端开发 Integrates Three.js with Capacitor for iOS native shell Supports web build output and animation contracts Enables native sync/run workflow for seamless app development Utilizes Vite for web renderer runtime Treats the project as two systems with a single contract: web and native threejs-capacitor-ios is a skill that integrates Three.js with Capacitor for iOS, allowing for the development of interactive 3D apps that run on both web and native platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DmitriyMuliak/z1mak-cv/qa-engineer', 'community', 'DmitriyMuliak', 'z1mak-cv', 'DmitriyMuliak/z1mak-cv', 'qa-engineer', 0, 0, 35, '2026-03-08T01:57:15.593Z', '2026-03-08T02:12:04.053Z', '6b797e1b5d41298425f904a906a4cc2e407ec74bced522d71d0623005262c544', '{"id":"DmitriyMuliak/z1mak-cv/qa-engineer","name":"qa-engineer","description":{"en":"The qa-engineer skill automates testing for the z1mak-cv project using Playwright and Vitest/React-testing-library. It benefits developers by validating changes and ensuring code quality.","zh":"作为一名 QA Engineer，您将使用 Playwright 和 Vitest 进行端到端和单元测试，以确保代码的质量和可靠性","ja":"QAエージェントとして、Playwright と Vitest を使用してエンドツーエンドとユニットテストを行い、コードの品質と信頼性を確保します","ko":"QA 엔지니어로서 Playwright와 Vitest를 사용하여 끝단부터 끝단까지 테스트와 단위 테스트를 수행하여 코드 품질과 신뢰성을 보장합니다","es":"El qa-engineer utiliza Playwright y Vitest para automatizar pruebas de software","fr":"Le qa-engineer utilise Playwright et Vitest pour automatiser les tests de logiciels","de":"Der qa-engineer verwendet Playwright und Vitest, um Softwaretests zu automatisieren","pt":"O QA Engineer é um especialista em automação de testes que utiliza Playwright e Vitest para garantir a qualidade do software","ru":"ИИ Агент QA Engineer - это специалист по автоматизации тестов, использующий Playwright и Vitest для обеспечения качества программного обеспечения","ar":"المهندسQA هو خبير في أتمتة الاختبارات الذي يستخدم Playwright وVitest لضمان جودة البرمجيات"},"seo":{"title":{"en":"qa-engineer: End-to-End Testing Setup Guide | AI Agent Skill","zh":"QA Engineer Setup Guide: Playwright 和 Vitest","ja":"QAエージェントのベストプラクティス: Playwright と Vitest","ko":"QA 엔지니어 설정 가이드: Playwright 및 Vitest","es":"Guía de configuración para qa-engineer con Playwright y V...","fr":"Mise en place de qa-engineer avec Playwright et Vitest","de":"Einrichtungsleitfaden für qa-engineer mit Playwright