INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DmitriyMuliak/z1mak-cv/qa-engineer', 'qa-engineer', 'DmitriyMuliak', 'z1mak-cv', 'community', 'qa-engineer DmitriyMuliak z1mak-cv community The qa-engineer skill automates testing for the z1mak-cv project using Playwright and Vitest/React-testing-library. It benefits developers by validating changes and ensuring code quality. 作为一名 QA Engineer，您将使用 Playwright 和 Vitest 进行端到端和单元测试，以确保代码的质量和可靠性 QAエージェントとして、Playwright と Vitest を使用してエンドツーエンドとユニットテストを行い、コードの品質と信頼性を確保します QA 엔지니어로서 Playwright와 Vitest를 사용하여 끝단부터 끝단까지 테스트와 단위 테스트를 수행하여 코드 품질과 신뢰성을 보장합니다 El qa-engineer utiliza Playwright y Vitest para automatizar pruebas de software Le qa-engineer utilise Playwright et Vitest pour automatiser les tests de logiciels Der qa-engineer verwendet Playwright und Vitest, um Softwaretests zu automatisieren O QA Engineer é um especialista em automação de testes que utiliza Playwright e Vitest para garantir a qualidade do software ИИ Агент QA Engineer - это специалист по автоматизации тестов, использующий Playwright и Vitest для обеспечения качества программного обеспечения المهندسQA هو خبير في أتمتة الاختبارات الذي يستخدم Playwright وVitest لضمان جودة البرمجيات how to use qa-engineer qa-engineer setup guide qa-engineer vs Cypress qa-engineer install what is qa-engineer qa-engineer alternative qa-engineer Playwright integration qa-engineer Vitest setup qa-engineer GitHub Actions pipeline QA Engineer Playwright Vitest 自动化测试 端到端测试 单元测试 CI/CD GitHub Actions playwrigh Utilizes Playwright for end-to-end testing in /tests/e2e/ directory Employs Vitest and React-testing-library for unit testing in colocated *.test.ts files Integrates with GitHub Actions for CI/CD pipeline automation Leverages Playwright commands for test execution Supports test validation using Vitest and React-testing-library assertions qa-engineer is a skill that automates end-to-end and unit testing using Playwright and Vitest/React-testing-library for the z1mak-cv project.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pegasus-isi/pegasus-workflow-toolkit/pegasus-wrapper', 'community', 'pegasus-isi', 'pegasus-workflow-toolkit', 'pegasus-isi/pegasus-workflow-toolkit', 'pegasus-wrapper', 0, 0, 35, '2026-03-08T01:57:15.616Z', '2026-03-08T02:13:22.445Z', 'a6bc044a5543161d2964c0fbaa156506eb58ea6e33008d55ae01db692e023f29', '{"id":"pegasus-isi/pegasus-workflow-toolkit/pegasus-wrapper","name":"pegasus-wrapper","description":{"en":"The pegasus-wrapper skill creates Pegasus WMS workflows with Claude Code, benefiting developers who need to automate pipeline steps. It generates wrapper scripts for seamless workflow integration.","zh":"Pegasus Wrapper 是一个可重用的工具包，用于创建 Pegasus WMS 工作流，支持 Claude Code","ja":"Pegasus Wrapper は、Claude Code をサポートする Pegasus WMS ワークフローを作成するための再利用可能なツールキットです","ko":"Pegasus Wrapper는 Claude Code를 지원하는 Pegasus WMS 워크플ロー 생성을 위한 재사용 가능한 툴킷입니다","es":"Pegasus Wrapper es una herramienta reutilizable para crear flujos de trabajo de Pegasus WMS con Claude Code. Ofrece plantillas para scripts de wrapper en Python y shell.","fr":"Pegasus Wrapper est un outil réutilisable pour créer des flux de travail Pegasus WMS avec Claude Code. Il propose des modèles pour les scripts de wrapper en Python et shell.","de":"Pegasus Wrapper ist ein wiederverwendbares Tool für die Erstellung von Pegasus WMS-Workflows mit Claude Code. Es bietet Vorlagen für Wrapper-Skripte in Python und Shell.","pt":"O Pegasus Wrapper é um toolkit reutilizável para criar fluxos de trabalho Pegasus WMS com Claude Code, permitindo a automação de pipelines.","ru":"Pegasus Wrapper - это многоразовый инструмент для создания рабочих потоков Pegasus WMS с помощью Claude Code, который позволяет автоматизировать пайплайны с ИИ Агентами","ar":"Pegasus Wrapper هو أداة قابلة لإعادة الاستخدام لإنشاء تدفقات عمل Pegasus WMS مع Claude Code، مما يسمحโดย تلقاء نفسه لخطوط الأنابيب مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"pegasus-wrapper: Pegasus WMS Workflow Setup Guide | AI Ag...","zh":"Pegasus Wrapper 设置指南 - AI工具","ja":"Pegasus Wrapper セットアップガイド - AIエージェント","ko":"Pegasus Wrapper 설정 가이드 - AI 도구","es":"Pegasus Wrapper: Guía de Configuración para Desarrolladores","fr":"Pegasus Wrapper: Guide de Mise en Place pour les Développ...","de":"Pegasus Wrapper: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Pegasus Wrapper para Fluxos de Tr...","ru":"Руководство по настройке Pegasus Wrapper для ИИ Агентов","ar":"دليل إعداد Pegasus Wrapper لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create reusable Pegasus WMS workflows with Claude Code using the pegasus-wrapper toolkit - get started now and streamline your workflow creation","zh":"使用 Pegasus Wrapper 创建 Pegasus WMS 工作流，了解 Claude Code 集成和 Shell Wrapper 脚本","ja":"Pegasus Wrapper を使用して Pegasus WMS ワークフローを作成し、Claude Code 統合と Shell Wrapper スクリプトについて学びます","ko":"Pegasus Wrapper를 사용하여 Pegasus WMS 워크플ロー 생성 및 Claude Code 통합, Shell Wrapper 스크립트","es":"Crea flujos de trabajo de Pegasus WMS con Claude Code usando pegasus-wrapper. Descubre cómo configurar y utilizar esta herramienta para desarrolladores.","fr":"Créez des flux de travail Pegasus WMS avec Claude Code en utilisant pegasus-wrapper. Découvrez comment configurer et utiliser cet outil pour les développeurs.","de":"Erstellen Sie Pegasus WMS-Workflows mit Claude Code mithilfe von pegasus-wrapper. Erfahren Sie, wie Sie dieses Tool für Entwickler konfigurieren und verwenden.","pt":"Aprenda a criar fluxos de trabalho Pegasus WMS com o toolkit reutilizável Claude Code e melhore a eficiência do seu pipeline","ru":"Узнайте, как создать рабочие потоки Pegasus WMS с помощью многоразового инструмента Claude Code и повысьте эффективность вашего пайплайна с ИИ Агентами","ar":"تعلم كيفية إنشاء تدفقات عمل Pegasus WMS باستخدام أداة Claude Code القابلة لإعادة الاستخدام وتحسين كفاءة خط أنابيبك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"pegasus-wrapper is a reusable toolkit for creating Pegasus WMS workflows with Claude Code, facilitating the automation of pipeline steps","zh":"Pegasus Wrapper 是一个用于创建 Pegasus WMS 工作流的工具包","ja":"Pegasus Wrapper は Pegasus WMS ワークフローを作成するためのツールキットです","ko":"Pegasus Wrapper는 Pegasus WMS 워크플ロー 생성을 위한 툴킷입니다","es":"Pegasus Wrapper es un toolkit para generar scripts de wrapper para pasos de canalización en Pegasus WMS.","fr":"Pegasus Wrapper est un kit d''outils pour générer des scripts de wrapper pour les étapes de canalisation dans Pegasus WMS.","de":"Pegasus Wrapper ist ein Toolkit zur Generierung von Wrapper-Skripten für Pipeline-Schritte in Pegasus WMS.","pt":"O Pegasus Wrapper é um toolkit que gera scripts de wrapper para fluxos de trabalho Pegasus WMS","ru":"Pegasus Wrapper - это инструмент, который генерирует оберточные скрипты для рабочих потоков Pegasus WMS","ar":"Pegasus Wrapper هو أداة لتوليد البرامج النصية المظلفة لتدفقات عمل Pegasus WMS"},"features":{"en":["Generates wrapper scripts for Pegasus WMS workflows using Claude Code","Reads reference materials from Pegasus.md and pegasus-templates","Supports creation of shell wrapper scripts using wrapper_template.sh","Utilizes wrapper_template.py for Python-based workflow automation","Gathers requirements for workflow creation through user interaction","Creates wrapper scripts for single pipeline steps using /pegasus-wrapper command"],"zh":["支持 Claude Code","提供 Shell Wrapper 脚本模板","集成 Pegasus WMS 工作流","支持 Python 脚本","提供 wrapper_template.py 和 wrapper_template.sh 模板"],"ja":["Claude Code をサポート","Shell Wrapper スクリプトテンプレートを提供","Pegasus WMS ワークフローを統合","Python スクリプトをサポート","wrapper_template.py と wrapper_template.sh テンプレートを提供"],"ko":["Claude Code 지원","Shell Wrapper 스크립트 템플릿 제공","Pegasus WMS 워크플ロー 통합","Python 스크립트 지원","wrapper_template.py 및 wrapper_template.sh 템플릿 제공"],"es":["Generación de scripts de wrapper para pasos de canalización","Plantillas para scripts de wrapper en Python y shell","Compatibilidad 