INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pegasus-isi/pegasus-workflow-toolkit/pegasus-wrapper', 'pegasus-wrapper', 'pegasus-isi', 'pegasus-workflow-toolkit', 'community', 'pegasus-wrapper pegasus-isi pegasus-workflow-toolkit community The pegasus-wrapper skill creates Pegasus WMS workflows with Claude Code, benefiting developers who need to automate pipeline steps. It generates wrapper scripts for seamless workflow integration. Pegasus Wrapper 是一个可重用的工具包，用于创建 Pegasus WMS 工作流，支持 Claude Code Pegasus Wrapper は、Claude Code をサポートする Pegasus WMS ワークフローを作成するための再利用可能なツールキットです Pegasus Wrapper는 Claude Code를 지원하는 Pegasus WMS 워크플ロー 생성을 위한 재사용 가능한 툴킷입니다 Pegasus Wrapper es una herramienta reutilizable para crear flujos de trabajo de Pegasus WMS con Claude Code. Ofrece plantillas para scripts de wrapper en Python y shell. Pegasus Wrapper est un outil réutilisable pour créer des flux de travail Pegasus WMS avec Claude Code. Il propose des modèles pour les scripts de wrapper en Python et shell. Pegasus Wrapper ist ein wiederverwendbares Tool für die Erstellung von Pegasus WMS-Workflows mit Claude Code. Es bietet Vorlagen für Wrapper-Skripte in Python und Shell. O Pegasus Wrapper é um toolkit reutilizável para criar fluxos de trabalho Pegasus WMS com Claude Code, permitindo a automação de pipelines. Pegasus Wrapper - это многоразовый инструмент для создания рабочих потоков Pegasus WMS с помощью Claude Code, который позволяет автоматизировать пайплайны с ИИ Агентами Pegasus Wrapper هو أداة قابلة لإعادة الاستخدام لإنشاء تدفقات عمل Pegasus WMS مع Claude Code، مما يسمحโดย تلقاء نفسه لخطوط الأنابيب مع أدوات الذكاء الاصطناعي how to use pegasus-wrapper pegasus-wrapper setup guide pegasus-wrapper alternative what is pegasus-wrapper pegasus-wrapper install pegasus-wrapper vs Claude Code Pegasus WMS workflow automation Claude Code workflow creation pegasus-wrapper tutorial automating pipeline steps with pegasus-wrapper Pegasus Wrapper AI工具 Claude Code Pegasus WMS Shell Wrapper 脚本 Python 脚本 工作流创建 AI开发工具 Generates wrapper scripts for Pegasus WMS workflows using Claude Code Reads reference materials from Pegasus.md and pegasus-templates Supports creation of shell wrapper scripts using wrapper_template.sh Utilizes wrapper_template.py for Python-based workflow automation Gathers requirements for workflow creation through user interaction Creates wrapper scripts for single pipeline steps using /pegasus-wrapper command pegasus-wrapper is a reusable toolkit for creating Pegasus WMS workflows with Claude Code, facilitating the automation of pipeline steps');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Henry229/antigravity-blog/detailed-implementation-plan', 'community', 'Henry229', 'antigravity-blog', 'Henry229/antigravity-blog', 'detailed-implementation-plan', 0, 0, 35, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:23.602Z', '6598293c1387a44cde7c90f88f8a32b642af04383935f046f92d9c17e9aa7f4b', '{"id":"Henry229/antigravity-blog/detailed-implementation-plan","name":"detailed-implementation-plan","description":{"en":"The detailed-implementation-plan skill transforms a single plan-based-page output file into an actionable implementation plan, designed for parallel session execution, benefiting developers and project managers.","zh":"详细实施计划是一种将单个计划页面输出文件转换为可行的实施计划的技术，支持并行会话执行","ja":"詳細実装計画は、単一の計画ページ出力ファイルを実行可能な実装計画に変換する技術で、並行セッションの実行をサポート","ko":"상세 구현 계획은 단일 계획 페이지 출력 파일을 실행 가능한 구현 계획으로 변환하는 기술로 병렬 세션 실행을 지원","es":"El plan de implementación detallado es una herramienta de AI Agent que transforma planes de página en acciones concretas para proyectos de desarrollo.","fr":"Le plan de mise en œuvre détaillé est un outil d''AI Agent qui transforme les plans de page en actions concrètes pour les projets de développement.","de":"Der detaillierte Implementierungsplan ist ein AI-Tool, das Seitenpläne in konkrete Aktionen für Entwicklungsprojekte umwandelt.","pt":"O skill de plano de implementação detalhado transforma um arquivo de plano em um plano de implementação executável em paralelo.","ru":"Навык детального плана реализации преобразует файл плана в детальный план реализации, выполненный в параллели.","ar":"مهارة خطة التنفيذ المفصلة تحول ملف الخطة إلى خطة تنفيذية قابلة للتنفيذ بالتوازي."},"seo":{"title":{"en":"Detailed-Implementation-Plan: Setup Guide for AI Agents","zh":"详细实施计划 Setup Guide - AI工具","ja":"詳細実装計画 Setup Guide - AIエージェント","ko":"상세 구현 계획 Setup Guide - AI 에이전트","es":"Guía de implementación detallada: Transformación de plane...","fr":"Plan de mise en œuvre détaillé: Transformer les plans de ...","de":"Detaillierter Implementierungsplan: Umwandlung von Seiten...","pt":"Guia de Configuração do Plano de Implementação Detalhado","ru":"Настройка детального плана реализации: ИИ Агенты","ar":"دليل إعداد الخطة التنفيذية المفصلة - أدوات الذكاء الاصطناعي"},"description":{"en":"Transform plan-based-page output files into actionable implementation plans with parallel session execution. Learn how to use detailed-implementation-plan to...","zh":"了解详细实施计划的技术细节，并发现如何将单个计划页面输出文件转换为可行的实施计划","ja":"詳細実装計画の技術的詳細を学び、単一の計画ページ出力ファイルを実行可能な実装計画に変換する方法を発見","ko":"상세 구현 계획의 기술적 세부 사항을 배우고 단일 계획 페이지 출력 파일을 실행 가능한 구현 계획으로 변환하는 방법을 발견","es":"Aprende a crear un plan de implementación detallado para proyectos de desarrollo con nuestra herramienta de AI Agent. Descubre cómo transformar planes de pág...","fr":"Découvrez comment créer un plan de mise en œuvre détaillé pour vos projets de développement avec notre outil d''AI Agent. Apprenez à transformer les plans de ...","de":"Erfahren Sie, wie Sie einen detaillierten Implementierungsplan für Ihre Entwicklungsprojekte mit unserem AI-Tool erstellen können. Lernen Sie, wie Sie Seiten...","pt":"Aprenda a transformar um arquivo de plano em um plano de implementação detalhado e executável em paralelo com o skill de plano de implementação detalhado","ru":"Изучите, как преобразовать файл плана в детальный план реализации с помощью навыка детального плана реализации и ИИ Агентов","ar":"تعرف على كيفية تحويل ملف خطة إلى خطة تنفيذية مفصلة وقابلة للتنفيذ بالتوازي باستخدام مهارة خطة التنفيذ المفصلة وأدوات الذكاء الاصطناعي"},"definition":{"en":"Detailed-implementation-plan is a skill that generates an actionable implementation plan from a plan-based-page output file, using fixed paths and supporting parallel session execution.","zh":"详细实施计划是一种技术，用于将计划页面输出文件转换为可行的实施计划","ja":"詳細実装計画は、計画ページ出力ファイルを実行可能な実装計画に変換する技術","ko":"상세 구현 계획은 계획 페이지 출력 파일을 실행 가능한 구현 계획으로 변환하는 기술","es":"Un plan de implementación detallado es una herramienta de AI que transforma planes de página en acciones concretas para proyectos de desarrollo.","fr":"Un plan de mise en œuvre détaillé est un outil d''IA qui transforme les plans de page en actions concrètes pour les projets de développement.","de":"Ein detaillierter Implementierungsplan ist ein AI-Tool, das Seitenpläne in konkrete Aktionen für Entwicklungsprojekte umwandelt.","pt":"Um plano de implementação detalhado é um arquivo que contém um plano de ação executável em paralelo","ru":"Детальный план реализации - это файл, содержащий план действий, выполненный в параллели","ar":"خطة التنفيذ المفصلة هي ملف يحتوي على خطة عمل قابلة للتنفيذ بالتوازي"},"features":{"en":["Transforms plan-based-page output files into actionable implementation plans","Supports parallel session execution","Uses fixed paths for input and output files, including .doc/plan/plans/ and implementation/","Accepts single file input in Markdown format, such as _shared-components.md and [page-name]-page.md","Designed for use with multiple sessions, including session 0 and session 1+"],"zh":["支持并行会话执行","将单个计划页面输出文件转换为可行的实施计划","使用固定路径.doc/plan/plans/和implementation/","支持多种文件类型，包括.md和.docx"],"ja":["並行セッションの実行をサポート","単一の計画ページ出力ファイルを実行可能な実装計画に変換","固定パス.doc/plan/plans/とimplementation/を使用","多くのファイルタイプをサポート，包括.mdと.docx"],"ko":["병렬 세션 실행을 지원","단일 계획 페이지 출력 파일을 실행 가능한 구현 계획으로 변환","고정 경로.doc/plan/plans/와 implementation/을 사용","여러 파일 유형을 지원, 포함.md와 .docx"],"es":["Transformación de planes de página en acciones concretas","Compatibilidad con ejecución de sesiones paralelas","Uso de rutas fijas para proyectos (.doc/plan/plans/ y implementation/)","Admite archivos de entrada de tipo .md","Permite la creación de planes de implementación detallados para proyectos de desarrollo"],"fr":["Transformation de plans de page en actions concrètes","Compatibilité avec l''exécution de sessions parallèles","Utilisation de chemins fixes pour les projets (.doc/plan/plans/ et implementation/)","Prise en charge de fichiers d''entrée de type .md","Permet la création de plans de mise en œuvre détaillés pour les projets de développement"],"de":["Umwandlung von Seitenplänen in konkrete Aktionen","Kompatibilität mit paralleler Sitzungsausführung","Verwendung von festen Pfaden für Projekte (.doc/plan/plans/ und implementation/)","Unterstützung von Eingabedateien vom Typ .md","Ermöglicht die Erstellung von detaillierten Implementierungsplänen für Entwicklungsprojekte"],"pt":["Transformação de arquivo de plano em plano de implementação detalhado","Execução em paralelo com fixação de caminhos","Suporte a arquivos de tipo .md","Compatibilidade com diretórios .doc/plan/plans/"],"ru":["Преобразование файла плана в детальный план реализации","Параллельная выполнение с фиксацией путей","Поддержка файлов типа .md","Совместимость с директориями .doc/plan/plans/"],"ar":["تحويل ملف الخطة إلى خطة تنفيذية مفصلة","التنفيذ بالتوازي مع تثبيت المسارات","دعم الملفات من نوع .md","التوافق مع الدلائل .doc/plan/plans/"]},"keywords":{"en":["how to use detailed-implementation-plan","what is detailed-implementation-plan","detailed-implementation-plan alternative","detailed-implementation-plan vs project management tools","detailed-implementation-plan install","detailed-implementation-plan setup guide","parallel session execution","plan-based-page output file"],"zh":["AI工具","详细实施计划","计划页面输出文件","并行会话执行","实施计划","技术细节","Setup Guide"],"ja":["AIエージェント","詳細実装計画","計画ページ出力ファイル","並行セッションの実行","実装計画","技術的詳細","Setup Guide"],"ko":["AI 에이전트","상세 구현 계획","계획 페이지 출력 파일","병렬 세션 실행","구현 계획","기술적 세부 사항","Setup Guide"],"es":["plan de implementación detallado","herramienta de AI Agent","transformación de planes de página","desarrollo de proyectos","ejecución de sesiones paralelas","rutas fijas para proyectos","archivos de entrada de tipo .md"],"fr":["plan de mise en œuvre détaillé","outil d''AI Agent","transformation de plans de page","développement de projets","exécution de sessions parallèles","chemins fixes pour les projets","fichiers d''entrée de type .md"],"de":["detaillierter Implementierungsplan","AI-Tool","Umwandlung von Seitenplänen","Entwicklung von Projekten","parallele Sitzungsausführung","feste Pfade für Projekte","Eingabedateien vom Typ .md"],"pt":["plano de implementação detalhado","execução em paralelo","transformação de arquivo de plano","fixação de caminhos","suporte a arquivos .md","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["детальный план реализации","параллельная выполнение","преобразование файла плана","фиксация путей","поддержка файлов .md","разработка программного обеспечения","инструменты разработки"],"ar":["خطة التنفيذ المفصلة","التنفيذ بالتوازي","تحويل ملف الخطة","تثبيت المسارات","دعم الملفات .md","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Henry229","repo":"antigravity-blog","repoPath":"Henry229/antigravity-blog","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"detailed-implementation-plan","description":"Generates detailed implementation plans from a SINGLE plan-based-page output file. Supports parallel execution - run multiple sessions simultaneously for different pages. Input is ONE file (either _shared-components.md or a specific page like landingpage-page.md). Use when you want to generate implementation plans in parallel across multiple sessions.","bodyPreview":"# Detailed Implementation Plan\nTransform a single plan-based-page output file into an actionable implementation plan. Designed for parallel session execution.\nFixed Paths\n모든 프로젝트에서 아래 고정 경로 사용:\n.doc/plan/\nplans/ ← plan-based-page 출력 (입력)\nimplementation/ ← 상세 구현 계획 (출력)\nInput Requirements\nSingle File Input - ONE of the following from .doc/plan/plans/ directory:\n파일 유형경로세션공통 컴포넌트.doc/plan/plans/\\_shared-components.md세션 0 (먼저 실행)페이지 계획.doc/plan/plans/[page-name]-page.md세션 1+ (병렬 가능)\nRequired Referen","body":"# Detailed Implementation Plan\nTransform a single plan-based-page output file into an actionable implementation plan. Designed for parallel session execution.\nFixed Paths\n모든 프로젝트에서 아래 고정 경로 사용:\n.doc/plan/\nplans/ ← plan-based-page 출력 (입력)\nimplementation/ ← 상세 구현 계획 (출력)\nInput Requirements\nSingle File Input - ONE of the following from .doc/plan/plans/ directory:\n파일 유형경로세션공통 컴포넌트.doc/plan/plans/\\_shared-components.md세션 0 (먼저 실행)페이지 계획.doc/plan/plans/[page-name]-page.md세션 1+ (병렬 가능)\nRequired References (세션 1+ 에서):\n\n.doc/plan/implementation/shared-components-impl.md - 공통 컴포넌트 상세 구현 참조\n\nOptional References:\n\n/ui-spec/[page].html - 상세 스타일 확인용\n\nSession-Based Parallel Workflow\n[순차 - 먼저 실행]\n세션 0: .doc/plan/plans/\\_shared-components.md\n↓\n출력: .doc/plan/implementation/shared-components-impl.md\n↓ (완료 후)\n\n[병렬 - 동시 실행 가능]\n세션 1: .doc/plan/plans/landingpage-page.md + 참조: shared-components-impl.md → .doc/plan/implementation/landingpage-impl.md\n세션 2: .doc/plan/plans/detailPage-page.md + 참조: shared-components-impl.md → .doc/plan/implementation/detailPage-impl.md\n세션 3: .doc/plan/plans/listPage-page.md + 참조: shared-components-impl.md → .doc/plan/implementation/listPage-impl.md\nHow to Use\n세션 0: 공통 컴포넌트 (먼저 실행)\n입력: .doc/plan/plans/\\_shared-components.md\n출력: .doc/plan/implementation/shared-components-impl.md\n세션 1+: 페이지별 (병렬 실행 가능, 세션 0 완료 후)\n입력: .doc/plan/plans/landingpage-page.md\n참조: .doc/plan/implementation/shared-components-impl.md (공통 컴포넌트 import 경로, props, 인터페이스 확인)\n출력: .doc/plan/implementation/landingpage-impl.md\nOutput Location\n모든 상세 구현 계획은 .doc/plan/implementation/ 디렉토리에 저장:\n.doc/plan/implementation/\nshared-components-impl.md # 세션 0\nlandingpage-impl.md # 세션 1\ndetailPage-impl.md # 세션 2\nlistPage-impl.md # 세션 3\nImportant Rules\n\n하나의 세션 = 하나의 파일 입력 = 하나의 출력\n공통 컴포넌트 먼저 - 페이지 세션 실행 전에 세션 0 완료 필수\n페이지는 병렬 가능 - 서로 의존성 없음 (세션 0 완료 후)\n공통 컴포넌트 impl 참조 - 페이지 세션에서 .doc/plan/implementation/shared-components-impl.md 참조하여 정확한 import 경로, props, 인터페이스 확인\n\nOutput Structure\nGenerate implementation plans in this exact format:\nFor 공통 컴포넌트 (Shared Components)\nmarkdown# 공통 컴포넌트 구현 계획\n\n## 개요\n\n공통으로 사용되는 UI 컴포넌트 구현\n\n- [Component 1]: [pages where used]\n- [Component 2]: [pages where used]\n\n---\n\n## 의존성 설치\n\n\\`\\`\\`bash\n\n# shadcn/ui\n\nnpx shadcn@latest add button input card form label\n\n# npm packages\n\nnpm install react-hook-form zod @hookform/resolvers lucide-react\n\\`\\`\\`\n\n---\n\n## Task List\n\n### 1. Header\n\n**상태:** - [ ] 미완료  \n**파일:** `components/layout/Header.tsx`\n**사용처:** Home, Create, Study (3/3 pages)\n\n**요구사항:**\n\n- [ ] 로고 (왼쪽)\n- [ ] 네비게이션 링크\n- [ ] 반응형 모바일 메뉴\n\n**스타일 (plan-based-page에서):**\n\n- Background: #FFFFFF\n- Height: 64px\n- Shadow: soft\n\n**기본 구조:**\n\\`\\`\\`typescript\nimport Link from \"next/link\"\n\nexport function Header() {\nreturn (\n<header className=\"h-16 border-b bg-white\">\n<nav className=\"container flex items-center justify-between\">\n{/_ Logo _/}\n{/_ Nav Links _/}\n</nav>\n</header>\n)\n}\n\\`\\`\\`\n\n**완료 조건:**\n\n- [ ] 모든 페이지에서 동일하게 렌더링\n- [ ] 반응형 동작 확인\n\n---\n\n### 2. Button\n\n...\nFor 페이지별 (Page-specific)\nmarkdown# [PageName] Page 구현 계획\n\n## 개요\n\n[Page description from plan-based-page]\n\n- User Flow Step: [step number and description]\n- 주요 기능: [key features]\n\n---\n\n## 페이지 구조 (plan-based-page에서)\n\n\\`\\`\\`\n\n- Header (공통)\n- Main\n  - [Section 1]\n  - [Section 2]\n- Footer (공통)\n  \\`\\`\\`\n\n---\n\n## Task List\n\n### 0. 페이지 라우트 생성\n\n- [ ] `app/[route]/page.tsx` 생성\n- [ ] 메타데이터 설정\n- [ ] 레이아웃 연결\n\n### 1. [PageSpecificComponent]\n\n**상태:** - [ ] 미완료  \n**파일:** `app/[route]/components/ComponentName.tsx`\n\n**요구사항:**\n\n- [ ] [Requirement from plan-based-page]\n- [ ] [UI requirement]\n\n**비즈니스 로직 (PRD에서):**\n\n- [ ] [Logic 1]\n- [ ] [Logic 2]\n\n**스타일:**\n\n- Primary: #4A90E2\n- Spacing: 16px\n- Border radius: 8px\n\n**기본 구조:**\n\\`\\`\\`typescript\n\"use client\"\n\nexport function ComponentName() {\nreturn (\n<section>\n{/_ Implementation _/}\n</section>\n)\n}\n\\`\\`\\`\n\n**완료 조건:**\n\n- [ ] 기능 동작 확인\n- [ ] 스타일 일치 확인\n\n---\n\n## 구현 순서\n\n1. 페이지 라우트 생성\n2. 공통 컴포넌트 import (Header, Footer)\n3. 페이지 전용 컴포넌트 구현\n4. 비즈니스 로직 연결\n5. 스타일 조정\n\n---\n\n## 검증 체크리스트\n\n- [ ] 페이지 렌더링 정상\n- [ ] User Flow 단계 완료 가능\n- [ ] 공통 컴포넌트 정상 표시\n- [ ] 반응형 동작\n- [ ] 에러 상태 처리\n      Analysis Process\n\nParse Page Plan: Extract selected section (공통 or specific page)\nGather Info: Components, styles, business logic from plan-based-page\nCheck HTML (Optional): If complex styling needed, reference original HTML\nDetermine Dependencies: shadcn/ui components, npm packages\nDefine File Paths: Next.js App Router conventions\nCreate Task Structure: Actionable tasks with checkboxes\nAdd Code Skeletons: TypeScript templates for each component\nAdd Verification Steps: Testing and validation checkpoints\nUpdate Page Plan File: Mark processed items as - [x]\n\nComponent Organization Patterns\nFile Path Conventions\napp/\ncomponents/\nauth/ - Authentication components\nadmin/ - Admin-specific components\nlearning/ - Learning-related components\nui/ - shadcn/ui components\nlayout/ - Layout components\nactions/ - Server actions\ncontexts/ - React contexts/providers\nlib/ - Utilities and helpers\n(routes)/ - Page routes\nComponent Types\nClient Components (\"use client\"):\n\nForms with user interaction\nComponents using hooks (useState, useEffect)\nEvent handlers (onClick, onChange)\nContexts that manage client state\n\nServer Components (default):\n\nData fetching components\nStatic layouts\nComponents without interactivity\n\nImplementation Details Template\nFor each component, provide:\n\n1. File Path\n   app/components/[category]/ComponentName.tsx\n2. Requirements Checklist\n\nSpecific feature 1\nSpecific feature 2\nUI/UX requirement (from image)\n\n3. Dependencies\n   List required packages:\n\nshadcn/ui components\nnpm packages\nCustom hooks\n\n4. Code Structure\n   Provide skeleton/template:\n   typescript\"use client\" // if needed\n\nimport statements\ntype definitions\ncomponent function\nreturn JSX 5. Implementation Details\n\nState management approach\nForm handling strategy\nAPI/Server action integration\nStyling approach\nError handling\n\nHTML Reference (Optional)\nWhen detailed styling verification is needed:\nWhen to Reference HTML\n\nComplex layouts not fully captured in plan-based-page\nExact pixel values for spacing\nSpecific CSS classes or patterns\nAnimation or transition details\n\nHow to Use\nmarkdown**HTML 참조:** `/ui-spec/home.html`\n\n스타일 확인 필요:\n\n- [ ] Hero section 정확한 padding 값\n- [ ] Button hover 상태\n- [ ] Grid gap 값\n      Extract from HTML\n\nExact spacing (padding: 24px 16px)\nColor values (#4A90E2, rgba(0,0,0,0.1))\nBorder radius (rounded-lg = 8px)\nShadow values\nResponsive breakpoints\n\nDependency Management\nshadcn/ui Components\nList required components to install:\nbashnpx shadcn@latest add button input card form\nnpm Packages\nList with installation commands:\nbashnpm install react-hook-form zod @hookform/resolvers\nCustom Dependencies\n\nCustom hooks to create\nUtility functions needed\nType definitions required\n\nImplementation Order Strategy\n\nInfrastructure First\n\nProviders/Contexts\nUtility functions\nType definitions\n\nBase Components\n\nUI components (shadcn/ui)\nLayout components\n\nFeature Components\n\nForms\nData display components\nInteractive features\n\nIntegration\n\nServer actions\nAPI routes\nPage routes\n\nTask Breakdown Pattern\nFor Forms\n\n- [ ] Install dependencies (react-hook-form, zod)\n- [ ] Create Zod validation schema\n- [ ] Implement form with react-hook-form\n- [ ] Add error handling and display\n- [ ] Add loading states\n- [ ] Connect to server action/API\n- [ ] Test validation\n- [ ] Test submission\n      For Display Components\n- [ ] Define TypeScript interface\n- [ ] Implement static UI\n- [ ] Add conditional rendering\n- [ ] Add loading skeleton\n- [ ] Add empty state\n- [ ] Add error state\n- [ ] Test with mock data\n- [ ] Test responsive design\n      For Contexts/Providers\n- [ ] Define context interface\n- [ ] Implement context provider\n- [ ] Add state management logic\n- [ ] Add mutation functions\n- [ ] Export custom hook\n- [ ] Wrap app with provider\n- [ ] Test context consumption\n      Verification Checklist Categories\n      Functionality\n\nComponent renders without errors\nAll features work as expected\nForms validate correctly\nData fetching works\n\nUI/UX\n\nMatches design mockup\nResponsive on mobile/tablet/desktop\nLoading states display properly\nError messages are clear\n\nCode Quality\n\nTypeScript types are correct\nNo console errors\nFollows Next.js 15 conventions\nProper use of server/client components\n\nIntegration\n\nServer actions work\nAPI calls succeed\nNavigation functions properly\nState persists correctly\n\nBest Practices\n\nUse Next.js 15 App Router conventions\nPrefer Server Components when possible\nUse Server Actions for mutations\nImplement proper error boundaries\nAdd loading states for async operations\nUse TypeScript strictly\nFollow shadcn/ui patterns\nKeep components focused and small\nExtract reusable logic to hooks\nAdd proper accessibility (ARIA labels)\n\nExample Output Format\nmarkdown# Home Page 구현 계획\n\n## 개요\n\nFlashLearn 앱의 랜딩 페이지 구현\n\n- User Flow Step 1: User lands on app\n- 주요 기능: 앱 소개, 새 덱 생성 CTA\n\n---\n\n## 페이지 구조 (plan-based-page에서)\n\n\\`\\`\\`\n\n- Header (공통)\n- Main\n  - HeroSection\n    - Logo (80px)\n    - Tagline\n  - CTAButton (공통 Button)\n- Footer (공통)\n  \\`\\`\\`\n\n---\n\n## 의존성\n\n이미 설치됨 (공통 컴포넌트에서):\n\n- shadcn/ui: button, card\n- lucide-react\n\n---\n\n## Task List\n\n### 0. 페이지 라우트 생성\n\n- [ ] `app/page.tsx` 생성\n- [ ] metadata 설정 (title, description)\n\n### 1. HeroSection 컴포넌트\n\n**상태:** - [ ] 미완료  \n**파일:** `app/(home)/components/HeroSection.tsx`\n\n**요구사항:**\n\n- [ ] 로고 이미지 (80px, 중앙 정렬)\n- [ ] 태그라인 텍스트\n- [ ] 반응형 레이아웃\n\n**스타일 (plan-based-page에서):**\n\n- Text: #1F2937\n- Background: #FFFFFF\n- Spacing: 48px (상하)\n\n**기본 구조:**\n\\`\\`\\`typescript\nimport Image from \"next/image\"\n\nexport function HeroSection() {\nreturn (\n<section className=\"py-12 text-center\">\n<Image \n        src=\"/logo.png\" \n        alt=\"FlashLearn\" \n        width={80} \n        height={80}\n        className=\"mx-auto\"\n      />\n<h1 className=\"mt-6 text-3xl font-bold text-gray-800\">\nLearn Smarter with Spaced Repetition\n</h1>\n</section>\n)\n}\n\\`\\`\\`\n\n**완료 조건:**\n\n- [ ] 로고 정상 표시\n- [ ] 반응형 텍스트 크기\n\n---\n\n### 2. Home Page 조립\n\n**상태:** - [ ] 미완료  \n**파일:** `app/page.tsx`\n\n**요구사항:**\n\n- [ ] Header 공통 컴포넌트 import\n- [ ] HeroSection 배치\n- [ ] CTA Button (\"Create New Deck\")\n- [ ] Footer 공통 컴포넌트 import\n\n**비즈니스 로직:**\n\n- [ ] CTA 클릭 → /create 페이지 이동\n- [ ] 기존 덱 있으면 덱 카드 표시 (localStorage 확인)\n\n**기본 구조:**\n\\`\\`\\`typescript\nimport { Header } from \"@/components/layout/Header\"\nimport { Footer } from \"@/components/layout/Footer\"\nimport { Button } from \"@/components/ui/button\"\nimport { HeroSection } from \"./(home)/components/HeroSection\"\nimport Link from \"next/link\"\n\nexport default function HomePage() {\nreturn (\n<>\n<Header />\n<main className=\"container py-8\">\n<HeroSection />\n<div className=\"mt-8 text-center\">\n<Button asChild size=\"lg\">\n<Link href=\"/create\">Create New Deck</Link>\n</Button>\n</div>\n</main>\n<Footer />\n</>\n)\n}\n\\`\\`\\`\n\n**완료 조건:**\n\n- [ ] 페이지 정상 렌더링\n- [ ] CTA 버튼 동작\n- [ ] 공통 컴포넌트 정상 표시\n\n---\n\n## 구현 순서\n\n1. `app/page.tsx` 파일 생성\n2. HeroSection 컴포넌트 구현\n3. 공통 컴포넌트 import (Header, Footer, Button)\n4. 페이지 조립 및 레이아웃 조정\n5. CTA 링크 연결\n6. 반응형 테스트\n\n---\n\n## 검증 체크리스트\n\n### HeroSection\n\n- [ ] 로고 이미지 표시\n- [ ] 태그라인 텍스트 표시\n- [ ] 모바일에서 정상 표시\n\n### Home Page\n\n- [ ] 전체 페이지 렌더링 정상\n- [ ] Header/Footer 공통 컴포넌트 표시\n- [ ] CTA 버튼 클릭 → /create 이동\n- [ ] 스타일이 plan-based-page와 일치\n\n---\n\n## HTML 참조 (필요시)\n\n**파일:** `/ui-spec/home.html`\n\n확인 필요 시:\n\n- [ ] HeroSection 정확한 padding 값\n- [ ] Button 정확한 스타일\n      Progressive Implementation\n      세션별 병렬 실행을 통한 빠른 개발:\n\n세션 0: 공통 컴포넌트 먼저 구현 (의존성 기반)\n세션 1~N: 페이지별 병렬 실행 (독립적)\n통합: 모든 세션 완료 후 통합 테스트\n\nParallel Execution Flow\n[Sequential - 먼저]\n세션 0: .doc/plan/plans/\\_shared-components.md → .doc/plan/implementation/shared-components-impl.md\n↓ (완료 대기)\n\n[Parallel - 동시 실행, shared-components-impl.md 참조]\n세션 1: .doc/plan/plans/landingpage-page.md + impl 참조 ──→ .doc/plan/implementation/landingpage-impl.md\n세션 2: .doc/plan/plans/detailPage-page.md + impl 참조 ───→ .doc/plan/implementation/detailPage-impl.md\n세션 3: .doc/plan/plans/listPage-page.md + impl 참조 ────→ .doc/plan/implementation/listPage-impl.md\n↓\n\n[After All Complete]\n통합 테스트 및 .doc/plan/plans/\\_overview.md 체크박스 업데이트\nSource File Update (Optional)\n세션 완료 후 원본 plan 파일의 체크박스 업데이트:\nmarkdown# Before\n\n- [ ] Header 구현\n- [ ] Button 구현\n\n# After\n\n- [x] Header 구현\n- [x] Button 구현\n      Session Examples\n      세션 0: 공통 컴포넌트\n      bash# 입력\n      .doc/plan/plans/\\_shared-components.md\n\n# 출력\n\n.doc/plan/implementation/shared-components-impl.md\n세션 1: Landing Page (병렬, 세션 0 완료 후)\nbash# 입력\n.doc/plan/plans/landingpage-page.md\n\n# 참조 (import 경로, props, 인터페이스 확인용)\n\n.doc/plan/implementation/shared-components-impl.md\n\n# 출력\n\n.doc/plan/implementation/landingpage-impl.md\n세션 2: Detail Page (병렬, 세션 0 완료 후)\nbash# 입력\n.doc/plan/plans/detailPage-page.md\n\n# 참조\n\n.doc/plan/implementation/shared-components-impl.md\n\n# 출력\n\n.doc/plan/implementation/detailPage-impl.md\nWorkflow Summary\n\n세션 0 실행: .doc/plan/plans/\\_shared-components.md → 공통 컴포넌트 상세 구현\n세션 0 완료 대기: .doc/plan/implementation/shared-components-impl.md 생성 완료 필수\n세션 1~N 병렬 실행: 각 페이지별 상세 구현 + shared-components-impl.md 참조\n모든 세션 완료: .doc/plan/plans/\\_overview.md 체크박스 업데이트\n구현 시작: .doc/plan/implementation/ 의 impl 파일들 기반으로 코딩\n"},"lastSynced":"2026-03-08T02:13:23.602Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing to transform plan-based-page output files into actionable implementation plans.","zh":"适合于需要将计划基于页面输出文件转换为可执行的实施计划的项目管理代理。","ja":"プロジェクト管理エージェントが計画ベースのページ出力ファイルを実行可能な実装計画に変換する必要がある場合に最適です。","ko":"계획 기반 페이지 출력 파일을 실행 가능한 구현 계획으로 변환해야 하는 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para agentes de gestión de proyectos que necesitan transformar archivos de salida de páginas basadas en planes en planes de implementación realizables.","fr":"Parfait pour les agents de gestion de projet ayant besoin de transformer les fichiers de sortie de page basée sur plan en plans d''implémentation réalisables.","de":"Perfekt für Projektmanagement-Agenten, die Plan-basierte Seite-Ausgabedateien in umsetzbare Implementierungspläne umwandeln müssen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que precisam transformar arquivos de saída de página baseada em plano em planos de implementação executáveis.","ru":"Идеально подходит для агентов управления проектами, которым необходимо преобразовывать файлы вывода страницы на основе плана в планы реализации.","ar":"مثالي لعمليات إدارة المشاريع التي تحتاج إلى تحويل ملفات الإخراج الخاصة bằng صفحة تعتمد على الخطة إلى خطط تنفيذ قابلة للتنفيذ."},"recommendation":{"en":"Empowers agents to generate detailed implementation plans from .md files, leveraging parallel session execution and benefiting developers and project managers through standardized directory structures like .doc/plan/plans/ and implementation/","zh":"赋予代理从 .md 文件生成详细的实施计划的能力，利用并行会话执行，并通过标准化的目录结构（如 .doc/plan/plans/ 和 implementation/）使开发人员和项目经理受益。","ja":".md ファイルから詳細な実装計画を生成するエージェントの能力を可能にし、並行セッションの実行を利用し、標準化されたディレクトリ構造（.doc/plan/plans/ や implementation/ など）を通じて開発者やプロジェクトマネージャーに利益をもたらします。","ko":"에이전트가 .md 파일에서 자세한 구현 계획을 생성할 수 있는 능력을 부여하며, 병렬 세션 실행을 활용하고 표준화된 디렉토리 구조(.doc/plan/plans/ 및 implementation/와 같은)를 통해 개발자와 프로젝트 관리자에게 이점을 제공합니다.","es":"Habilita a los agentes a generar planes de implementación detallados a partir de archivos .md, aprovechando la ejecución de sesiones paralelas y beneficiando a los desarrolladores y gestores de proyectos a través de estructuras de directorios estandarizadas como .doc/plan/plans/ e implementation/","fr":"Permet aux agents de générer des plans d''implémentation détaillés à partir de fichiers .md, en exploitant l''exécution de sessions parallèles et en bénéficiant aux développeurs et aux gestionnaires de projet grâce à des structures de répertoires standardisées comme .doc/plan/plans/ et implementation/","de":"Ermöglicht es den Agenten, detaillierte Implementierungspläne aus .md-Dateien zu generieren, indem sie die parallele Sitzungsausführung nutzen und Entwickler und Projektmanager durch standardisierte Verzeichnisstrukturen wie .doc/plan/plans/ und implementation/ unterstützen.","pt":"Habilita os agentes a gerar planos de implementação detalhados a partir de arquivos .md, aproveitando a execução de sessões paralelas e beneficiando os desenvolvedores e gerentes de projeto por meio de estruturas de diretório padronizadas como .doc/plan/plans/ e implementation/","ru":"Наделяет агентов возможностью генерировать подробные планы реализации из файлов .md, используя параллельное выполнение сессий и принося пользу разработчикам и менеджерам проектов через стандартизированные структуры каталогов, такие как .doc/plan/plans/ и implementation/","ar":"تمكّن الوكيل من توليد خطط تنفيذ مفصلة من ملفات .md، واستخدام تنفيذ الجلسات المتوازية، وتوفير فوائد للمطورين ومديري المشاريع من خلال هياكل دليل معيارية مثل .doc/plan/plans/ و implementation/"},"useCases":{"en":["Transforming plan-based-page output files into actionable implementation plans","Executing parallel sessions for efficient project management","Generating detailed implementation plans for shared components and page-specific plans"],"zh":["将计划基于页面输出文件转换为可执行的实施计划","执行并行会话以实现高效的项目管理","为共享组件和页面特定计划生成详细的实施计划"],"ja":["計画ベースのページ出力ファイルを実行可能な実装計画に変換する","並行セッションを実行して効率的なプロジェクト管理を行う","共有コンポーネントとページ固有の計画のための詳細な実装計画を生成する"],"ko":["계획 기반 페이지 출력 파일을 실행 가능한 구현 계획으로 변환하는 것","병렬 세션을 실행하여 효율적인 프로젝트 관리를 하는 것","공유 컴포넌트 및 페이지 특정 계획에 대한 자세한 구현 계획을 생성하는 것"],"es":["Transformar archivos de salida de páginas basadas en planes en planes de implementación realizables","Ejecutar sesiones paralelas para una gestión de proyectos eficiente","Generar planes de implementación detallados para componentes compartidos y planes específicos de página"],"fr":["Transformer les fichiers de sortie de page basée sur plan en plans d''implémentation réalisables","Exécuter des sessions parallèles pour une gestion de projet efficace","Générer des plans d''implémentation détaillés pour les composants partagés et les plans spécifiques de page"],"de":["Plan-basierte Seite-Ausgabedateien in umsetzbare Implementierungspläne umwandeln","Parallele Sitzungen für eine effiziente Projektverwaltung ausführen","Detaillierte Implementierungspläne für gemeinsam genutzte Komponenten und seiten-spezifische Pläne generieren"],"pt":["Transformar arquivos de saída de página baseada em plano em planos de implementação executáveis","Executar sessões paralelas para um gerenciamento de projeto eficiente","Gerar planos de implementação detalhados para componentes compartilhados e planos específicos de página"],"ru":["Преобразовывать файлы вывода страницы на основе плана в планы реализации","Выполнять параллельные сессии для эффективного управления проектом","Генерировать подробные планы реализации для общих компонентов и планов, специфичных для страницы"],"ar":["تحويل ملفات الإخراج الخاصة bằng صفحة تعتمد على الخطة إلى خطط تنفيذ قابلة للتنفيذ","تنفيذ الجلسات المتوازية لإدارة المشاريع الفعالة","توليد خطط تنفيذ مفصلة للمكونات المشتركة والخطط الخاصة بالصفحة"]},"limitations":{"en":["Requires single file input from .doc/plan/plans/ directory","Limited to .md file format","Fixed paths must be used (e.g., .doc/plan/, plans/, implementation/)"],"zh":["需要从 .doc/plan/plans/ 目录中输入单个文件","仅限 .md 文件格式","必须使用固定路径（例如 .doc/plan/、plans/、implementation/）"],"ja":[".doc/plan/plans/ ディレクトリから単一のファイル入力を必要とする",".md ファイル形式のみに限定される","固定パス（.doc/plan/、plans/、implementation/ など）を使用する必要がある"],"ko":[".doc/plan/plans/ 디렉토리에서 단일 파일 입력이 필요함",".md 파일 형식만으로 제한됨","고정 경로(.doc/plan/, plans/, implementation/ 등)를 사용해야 함"],"es":["Requiere una entrada de archivo único desde el directorio .doc/plan/plans/","Limitado al formato de archivo .md","Se deben utilizar rutas fijas (por ejemplo, .doc/plan/, planes/, implementation/)"],"fr":["Nécessite une entrée de fichier unique à partir du répertoire .doc/plan/plans/","Limité au format de fichier .md","Des chemins fixes doivent être utilisés (par exemple, .doc/plan/, plans/, implementation/)"],"de":["Erfordert eine einzelne Dateieingabe aus dem Verzeichnis .doc/plan/plans/","Begrenzt auf das Dateiformat .md","Feste Pfade müssen verwendet werden (z. B. .doc/plan/, plans/, implementation/)"],"pt":["Requer entrada de arquivo único do diretório .doc/plan/plans/","Limitado ao formato de arquivo .md","Caminhos fixos devem ser usados (por exemplo, .doc/plan/, plans/, implementation/)"],"ru":["Требует ввода одного файла из каталога .doc/plan/plans/","Ограничен форматом файла .md","Фиксированные пути должны быть использованы (например, .doc/plan/, plans/, implementation/)"],"ar":["يتطلب إدخال ملف واحد من دليل .doc/plan/plans/","محدود بنموذج ملف .md","يجب استخدام مسارات ثابتة (على سبيل المثال، .doc/plan/، plans/، implementation/)"]},"version":4},"contentHash":"6598293c1387a44cde7c90f88f8a32b642af04383935f046f92d9c17e9aa7f4b","qualityScore":35}');
