INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Henry229/antigravity-blog/detailed-implementation-plan', 'detailed-implementation-plan', 'Henry229', 'antigravity-blog', 'community', 'detailed-implementation-plan Henry229 antigravity-blog community The detailed-implementation-plan skill transforms a single plan-based-page output file into an actionable implementation plan, designed for parallel session execution, benefiting developers and project managers. 详细实施计划是一种将单个计划页面输出文件转换为可行的实施计划的技术，支持并行会话执行 詳細実装計画は、単一の計画ページ出力ファイルを実行可能な実装計画に変換する技術で、並行セッションの実行をサポート 상세 구현 계획은 단일 계획 페이지 출력 파일을 실행 가능한 구현 계획으로 변환하는 기술로 병렬 세션 실행을 지원 El plan de implementación detallado es una herramienta de AI Agent que transforma planes de página en acciones concretas para proyectos de desarrollo. Le plan de mise en œuvre détaillé est un outil d''AI Agent qui transforme les plans de page en actions concrètes pour les projets de développement. Der detaillierte Implementierungsplan ist ein AI-Tool, das Seitenpläne in konkrete Aktionen für Entwicklungsprojekte umwandelt. O skill de plano de implementação detalhado transforma um arquivo de plano em um plano de implementação executável em paralelo. Навык детального плана реализации преобразует файл плана в детальный план реализации, выполненный в параллели. مهارة خطة التنفيذ المفصلة تحول ملف الخطة إلى خطة تنفيذية قابلة للتنفيذ بالتوازي. how to use detailed-implementation-plan what is detailed-implementation-plan detailed-implementation-plan alternative detailed-implementation-plan vs project management tools detailed-implementation-plan install detailed-implementation-plan setup guide parallel session execution plan-based-page output file AI工具 详细实施计划 计划页面输出文件 并行会话执行 实施计划 技术细节 Setup Guide Transforms plan-based-page output files into actionable implementation plans Supports parallel session execution Uses fixed paths for input and output files, including .doc/plan/plans/ and implementation/ Accepts single file input in Markdown format, such as _shared-components.md and [page-name]-page.md Designed for use with multiple sessions, including session 0 and session 1+ Detailed-implementation-plan is a skill that generates an actionable implementation plan from a plan-based-page output file, using fixed paths and supporting parallel session execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TigerSillion/RenesasMcuMaster/pc-scope-qt', 'community', 'TigerSillion', 'RenesasMcuMaster', 'TigerSillion/RenesasMcuMaster', 'pc-scope-qt', 0, 0, 35, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:25.622Z', 'db08daee111fb857ba5cc41cf0283341043a2ef55e0540907d7301187de38d7b', '{"id":"TigerSillion/RenesasMcuMaster/pc-scope-qt","name":"pc-scope-qt","description":{"en":"pc-scope-qt is a legacy skill for minimal maintenance of historical Qt files in src/. It is used for deprecated Qt development and is not recommended for new features.","zh":"PC Scope Qt 是一个用于维护历史 Qt 文件的技能，主要用于 src/ 目录下的文件","ja":"PC Scope Qt はレガシー Qt ファイルのメンテナンスに使用されるスキルで、主に src/ ディレクトリ下的ファイルに使用される","ko":"PC Scope Qt는 역사적인 Qt 파일을 유지 보수하는 데 사용되는 기술로 주로 src/ 디렉토리의 파일에 사용됨","es":"pc-scope-qt es un skill legacy para el mantenimiento mínimo de archivos Qt históricos. Se utiliza para la configuración y mantenimiento de archivos en src/.","fr":"pc-scope-qt est un skill legacy pour la maintenance minimale des fichiers Qt historiques. Il est utilisé pour la configuration et la maintenance des fichiers dans src/.","de":"pc-scope-qt ist ein Legacy-Skill für die minimale Wartung historischer Qt-Dateien. Er wird für die Konfiguration und Wartung von Dateien in src/ verwendet.","pt":"O pc-scope-qt é uma habilidade legada para manutenção mínima de arquivos Qt históricos.","ru":"ИИ Агент pc-scope-qt - это устаревшая возможность для минимизации обслуживания исторических Qt-файлов.","ar":"وحدة pc-scope-qt هي مهارة معفاة لصيانة الملفات Qt التاريخية."},"seo":{"title":{"en":"pc-scope-qt: Legacy Qt Maintenance Guide | AI Agent Skill","zh":"PC Scope Qt Setup Guide - Legacy Qt 文件维护","ja":"PC Scope Qt セットアップガイド - Legacy Qt ファイルのメンテナンス","ko":"PC Scope Qt 설정 가이드 - 레거시 Qt 파일 유지 보수","es":"Guía de configuración de pc-scope-qt para desarrollo legacy","fr":"Guide de démarrage 