INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TigerSillion/RenesasMcuMaster/pc-scope-qt', 'pc-scope-qt', 'TigerSillion', 'RenesasMcuMaster', 'community', 'pc-scope-qt TigerSillion RenesasMcuMaster community pc-scope-qt is a legacy skill for minimal maintenance of historical Qt files in src/. It is used for deprecated Qt development and is not recommended for new features. PC Scope Qt 是一个用于维护历史 Qt 文件的技能，主要用于 src/ 目录下的文件 PC Scope Qt はレガシー Qt ファイルのメンテナンスに使用されるスキルで、主に src/ ディレクトリ下的ファイルに使用される PC Scope Qt는 역사적인 Qt 파일을 유지 보수하는 데 사용되는 기술로 주로 src/ 디렉토리의 파일에 사용됨 pc-scope-qt es un skill legacy para el mantenimiento mínimo de archivos Qt históricos. Se utiliza para la configuración y mantenimiento de archivos en src/. pc-scope-qt est un skill legacy pour la maintenance minimale des fichiers Qt historiques. Il est utilisé pour la configuration et la maintenance des fichiers dans src/. pc-scope-qt ist ein Legacy-Skill für die minimale Wartung historischer Qt-Dateien. Er wird für die Konfiguration und Wartung von Dateien in src/ verwendet. O pc-scope-qt é uma habilidade legada para manutenção mínima de arquivos Qt históricos. ИИ Агент pc-scope-qt - это устаревшая возможность для минимизации обслуживания исторических Qt-файлов. وحدة pc-scope-qt هي مهارة معفاة لصيانة الملفات Qt التاريخية. how to use pc-scope-qt pc-scope-qt alternative pc-scope-qt vs pc-scope-wpf pc-scope-qt install guide what is pc-scope-qt pc-scope-qt setup for legacy Qt pc-scope-qt maintenance for historical Qt files pc-scope-qt limitations pc-scope-qt deprecated features PC Scope Qt Legacy Qt 历史 Qt 文件 src/ 目录 最小维护 不支持新特性 AIエージェント Qt 技术 Maintains historical Qt files in src/ directory Supports minimal maintenance of legacy Qt code Redirects to pc-scope-wpf for active development Deprecated Qt path for new feature development Used for legacy Qt development only Not recommended for new feature implementation pc-scope-qt is a deprecated Qt skill used for maintaining historical Qt files in the src/ directory.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KatTate/Bmad-for-Replit/bmad-validate-prd', 'community', 'KatTate', 'Bmad-for-Replit', 'KatTate/Bmad-for-Replit', 'bmad-validate-prd', 0, 0, 35, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:26.040Z', '1cea6cd7265bac89d5b4015f1d39eda0943013094361bdb77234eaa3104385b1', '{"id":"KatTate/Bmad-for-Replit/bmad-validate-prd","name":"bmad-validate-prd","description":{"en":"The bmad-validate-prd skill activates a comprehensive PRD validation workflow, reviewing existing PRDs against BMAD standards through quality assessment. This skill benefits developers working with BMAD standards.","zh":"BMAD Validate PRD工作流通过综合性质评估审查现有的PRD，确保其符合BMAD标准","ja":"BMAD Validate PRDワークフローは、BMAD標準に従って既存のPRDを包括的な品質評価で検証します","ko":"BMAD Validate PRD 워크플로우는 종합적인 품질 평가를 통해 기존 PRD를 검토하여 BMAD 표준에 부합하는지 확인합니다","es":"bmad-validate-prd es un flujo de trabajo que valida PRD según los estándares de BMAD. Carga la configuración desde _bmad/bmm/config.yaml y utiliza arquitectura de paso de archivo","fr":"bmad-validate-prd est un flux de travail qui valide les PRD selon les normes de BMAD. Il charge la configuration à partir de _bmad/bmm/config.yaml et utilise une architecture de fichier de pas","de":"bmad-validate-prd ist ein Workflow, der PRD gemäß den BMAD-Standards validiert. Er lädt die Konfiguration aus _bmad/bmm/config.yaml und verwendet eine Datei-Schritt-Architektur","pt":"O bmad-validate-prd é um repositório para validar PRD com base em padrões BMAD. Ele utiliza arquitetura de steps e configuração em YAML.","ru":"Bmad-validate-prd - это репозиторий для валидации PRD на основе стандартов BMAD. Он использует шаговую архитектуру и конфигурацию в YAML.","ar":"bmad-validate-prd هو مستودع للتحقق من PRD بناءً على معايير BMAD. يستخدم هيكلاً متدرجاً وتكويناً في YAML."},"seo":{"title":{"en":"bmad-validate-prd: Comprehensive PRD Validation Workflow ...","zh":"BMAD Validate PRD 工作流设置指南","ja":"BMAD Validate PRD ワークフローのベストプラクティス - AIエージェント","ko":"BMAD Validate PRD 워크플ロー 설정 가이드 - 인공지능 툴","es":"Guía de configuración de bmad-validate-prd para flujos de...","fr":"Guide d''installation de bmad-validate-prd pour les flux d...","de":"Einrichtungsleitfaden für bmad-validate-prd-Workflows zur...","pt":"Guia de Configuração do bmad-validate-prd: Validação de P...","ru":"Настройка bmad-validate-prd: Руководство по валидации PRD...","ar":"دليل إعداد bmad-validate-prd: التحقق من PRD باستخدام أدوا..."},"description":{"en":"Discover how bmad-validate-prd streamlines PRD validation against BMAD standards. Learn how to trigger the workflow and improve your development process today!","zh":"了解BMAD Validate PRD工作流的激活和配置，通过综合性质评估审查现有的PRD","ja":"BMAD Validate PRDワークフローを活用するための設定方法と機能を紹介します - AIエージェント","ko":"BMAD Validate PRD 워크플로우의 활성화와 구성에 대해 알아보고, 종합적인 품질 평가를 통해 기존 PRD를 검토하세요","es":"Aprende a configurar bmad-validate-prd para validar PRD según los estándares de BMAD. Descubre cómo funciona el flujo de trabajo y cómo cargar la configuración","fr":"Découvrez comment configurer bmad-validate-prd pour valider les PRD selon les normes de BMAD. Apprenez à utiliser le flux de travail et à charger la configur...","de":"Erfahren Sie, wie Sie bmad-validate-prd für die Validierung von PRD gemäß den BMAD-Standards konfigurieren. Lernen Sie, wie der Workflow funktioniert und wie...","pt":"Aprenda a configurar o bmad-validate-prd para validar PRD com base em padrões BMAD e melhore a qualidade do seu projeto","ru":"Узнайте, как настроить bmad-validate-prd для валидации PRD на основе стандартов BMAD и улучшить качество вашего проекта с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد bmad-validate-prd للتحقق من PRD بناءً على معايير BMAD وتحسين جودة مشروعك باستخدام أدوات ذكاء الاصطناعي"},"definition":{"en":"bmad-validate-prd is a repository-based skill that activates the BMAD PRD Validation workflow, utilizing a step-file architecture and configuration loading from config.yaml","zh":"BMAD Validate PRD是激活BMAD PRD验证工作流的技能，用于审查现有的PRD","ja":"BMAD Validate PRDは、BMAD PRD検証ワークフローを活用するためのスキルです","ko":"BMAD Validate PRD는 BMAD PRD 검증 워크플로우를 활성화하는 스킬로, 기존 PRD를 검토하는 데 사용됩니다","es":"bmad-validate-prd es un agente de AI que valida PRD según los estándares de BMAD","fr":"bmad-validate-prd est un agent d''IA qui valide les PRD selon les normes de BMAD","de":"bmad-validate-prd ist ein KI-Agent, der PRD gemäß den BMAD-Standards validiert","pt":"O bmad-validate-prd é uma ferramenta de validação de PRD que utiliza padrões BMAD para garantir a qualidade do projeto","ru":"Bmad-validate-prd - это инструмент для валидации PRD, который использует стандарты BMAD для обеспечения качества проекта","ar":"bmad-validate-prd هو أداة للتحقق من PRD التي تستخدم معايير BMAD لضمان جودة المشروع"},"features":{"en":["Triggers the BMAD PRD Validation workflow through a step-file architecture","Loads configuration from _bmad/bmm/config.yaml","Utilizes steps in the steps-v/ directory for comprehensive quality assessment","Follows the workflow defined in _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Reviews existing PRDs against BMAD standards for improved validation"],"zh":["综合性质评估","BMAD标准审查","步骤文件架构","配置加载从_config.yaml","PRD文件检验"],"ja":["包括的な品質評価","BMAD標準の検証","ステップファイルアーキテクチャ","設定の読み込みから_config.yaml","PRDファイルの検証"],"ko":["종합적인 품질 평가","BMAD 표준 검증","ステップ 파일 아키텍처","구성 로딩 από _config.yaml","PRD 파일 검증"],"es":["Validación de PRD según los estándares de BMAD","Carga de configuración desde _bmad/bmm/config.yaml","Arquitectura de paso de archivo","Uso de la carpeta steps-v/ para los pasos del flujo de trabajo","Compatibilidad con el flujo de trabajo de creación de PRD"],"fr":["Validation des PRD selon les normes de BMAD","Chargement de la configuration à partir de _bmad/bmm/config.yaml","Architecture de fichier de pas","Utilisation du répertoire steps-v/ pour les étapes du flux de travail","Compatibilité avec le flux de travail de création de PRD"],"de":["Validierung von PRD gemäß den BMAD-Standards","Laden der Konfiguration aus _bmad/bmm/config.yaml","Datei-Schritt-Architektur","Verwendung des Verzeichnisses steps-v/ für die Schritte des Workflows","Kompatibilität mit dem Workflow zur Erstellung von PRD"],"pt":["Validação de PRD com base em padrões BMAD","Arquitetura de steps para fluxo de trabalho","Configuração em YAML","Integração com o repositório Replit","Suporte à criação de PRD"],"ru":["Валидация PRD на основе стандартов BMAD","Шаговая архитектура для рабочего процесса","Конфигурация в YAML","Интеграция с репозиторием Replit","Поддержка создания PRD"],"ar":["التحقق من PRD بناءً على معايير BMAD","هيكل متدرج للعمل","تكوين في YAML","التكامل مع مستودع Replit","دعم إنشاء PRD"]},"keywords":{"en":["how to use bmad-validate-prd","bmad-validate-prd setup guide","bmad-validate-prd alternative","bmad-validate-prd vs BMAD standards","what is bmad-validate-prd","bmad-validate-prd install","PRD validation workflow","BMAD standards compliance","comprehensive quality assessment"],"zh":["BMAD Validate PRD","AI工具","工作流设置","综合性质评估","BMAD标准","PRD检验","步骤文件架构","配置加载"],"ja":["BMAD Validate PRD","AIエージェント","ワークフローの設定","包括的な品質評価","BMAD標準","PRD検証","ステップファイルアーキテクチャ","設定の読み込み"],"ko":["BMAD Validate PRD","인공지능 툴","워크플ロー 설정","종합적인 품질 평가","BMAD 표준","PRD 검증","스테ップ 파일 아키텍처","구성 로딩"],"es":["bmad-validate-prd","validación de PRD","BMAD","flujo de trabajo","configuración","arquitectura de paso de archivo","Agentes de AI","Herramientas de AI"],"fr":["bmad-validate-prd","validation des PRD","BMAD","flux de travail","configuration","architecture de fichier de pas","Agents d''IA","Outils d''IA"],"de":["bmad-validate-prd","Validierung von PRD","BMAD","Workflow","Konfiguration","Datei-Schritt-Architektur","KI-Agents","KI-Tools"],"pt":["bmad-validate-prd","validação de PRD","padrões BMAD","ferramentas de IA","desenvolvimento de software","qualidade de projeto","configuração em YAML","repositório Replit"],"ru":["bmad-validate-prd","валидация PRD","стандарты BMAD","ИИ Агенты","разработка программного обеспечения","качество проекта","конфигурация в YAML","репозиторий Replit"],"ar":["bmad-validate-prd","التحقق من PRD","معايير BMAD","أدوات ذكاء الاصطناعي","تطوير البرمجيات","جودة المشروع","تكوين في YAML","مستودع Replit"]}},"owner":"KatTate","repo":"Bmad-for-Replit","repoPath":"KatTate/Bmad-for-Replit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"bmad-validate-prd","description":">","bodyPreview":"# BMAD Validate PRD Workflow\n\nThis skill activates the BMAD PRD Validation workflow. It reviews an existing\nPRD against BMAD standards through comprehensive quality assessment.\n\n## Activation\n\nWhen this skill is triggered, load and follow the workflow directly:\n\nRead fully and follow: `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md`\n\nThe workflow uses step-file architecture with steps in `steps-v/` directory.\n- Configuration loading from `_bmad/bmm/config.yaml`\n- PRD fi","body":"# BMAD Validate PRD Workflow\n\nThis skill activates the BMAD PRD Validation workflow. It reviews an existing\nPRD against BMAD standards through comprehensive quality assessment.\n\n## Activation\n\nWhen this skill is triggered, load and follow the workflow directly:\n\nRead fully and follow: `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md`\n\nThe workflow uses step-file architecture with steps in `steps-v/` directory.\n- Configuration loading from `_bmad/bmm/config.yaml`\n- PRD file discovery and loading\n- Output: validation report\n\n## Workflow Steps (13 Steps + 1 Conditional Branch)\n\n1. **step-v-01-discovery** — Discover and load the PRD to validate, detect format\n2. **step-v-02-format-detection** — Format classification and structure analysis\n   - ↳ **step-v-02b-parity-check** — Parity check handler (conditional: auto-loaded for variant/legacy formats)\n3. **step-v-03-density-validation** — Information density validation (wordiness, filler, conciseness)\n4. **step-v-04-brief-coverage-validation** — Product brief coverage validation\n5. **step-v-05-measurability-validation** — Measurability validation (quantified success criteria)\n6. **step-v-06-traceability-validation** — Traceability validation (requirements linkage)\n7. **step-v-07-implementation-leakage-validation** — Implementation leakage detection (technology in requirements)\n8. **step-v-08-domain-compliance-validation** — Domain compliance validation\n9. **step-v-09-project-type-validation** — Project-type compliance validation\n10. **step-v-10-smart-validation** — SMART requirements validation\n11. **step-v-11-holistic-quality-validation** — Holistic quality assessment and rating\n12. **step-v-12-completeness-validation** — Completeness validation\n13. **step-v-13-report-complete** — Final report compilation, summary, and next steps\n\n## Commonly Missed Steps\n\n- ⚠️ **step-v-07-implementation-leakage** — Agents may skip leakage detection since it requires checking FRs/NFRs for technology-specific language. This is a critical quality gate.\n- ⚠️ **step-v-11-holistic-quality** — The holistic assessment provides the overall quality rating. Skipping it means no overall score.\n- ⚠️ **step-v-13-report-complete** — Final report step that compiles all findings and presents actionable options (edit, review, fix). Must not be skipped.\n- ⚠️ **Each validation step must be executed sequentially** — agents may try to batch multiple validations together. Each step must complete fully before the next begins.\n\n## Replit Task List Integration\n\n**MANDATORY on activation:** Before beginning Step 1, create a Replit task list using the `write_task_list` tool with one task per workflow step listed above (13 sequential steps; if step-v-02b parity check is triggered, add it as a task dynamically). Each task should include the step number and name (e.g., \"Step 1: Discovery — Discover and load the PRD to validate\"). Mark the first task as `in_progress`. As you complete each step, immediately mark its task as `completed` (architect_reviewed: \"not_applicable\", reason: \"BMAD workflow step — planning/facilitation, not code\") and mark the next task as `in_progress`. This gives the user visible progress tracking throughout the workflow.\n\n## Critical Rules\n\n- NEVER skip steps or optimize the sequence\n- NEVER auto-proceed past WAIT points — stop and wait for user input\n- ALWAYS read each step file completely before taking action\n- ALWAYS follow step-file architecture: load one step at a time, never look ahead\n- ALWAYS halt at menus and wait for user selection\n- Recommend using a different high-quality LLM for validation if available\n- Each validation step must produce findings independently — do not batch\n\n## What''s Next\n\nAfter validating a PRD, the typical next steps are:\n- If issues found: **Edit PRD (EP)** — fix the identified problems\n- If passed: **Create Architecture (CA)** or **Create UX (CU)**\n"},"lastSynced":"2026-03-08T02:13:26.040Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents working with BMAD standards, needing comprehensive PRD validation and quality assessment capabilities.","zh":"非常适合使用BMAD标准的开发代理，需要全面PRD验证和质量评估能力。","ja":"BMAD規格を使用する開発エージェントに最適で、包括的なPRD検証および品質評価機能が必要です。","ko":"BMAD 표준을 사용하는 개발 에이전트에게 적합하며, 포괄적인 PRD 검증 및 품질 평가 기능이 필요합니다.","es":"Perfecto para Agentes de Desarrollo que trabajan con estándares BMAD, que necesitan capacidades de validación y evaluación de calidad de PRD exhaustivas.","fr":"Parfait pour les agents de développement travaillant avec les normes BMAD, ayant besoin d''une validation et d''une évaluation de la qualité de PRD complètes.","de":"Perfekt für Entwicklungsmittel, die mit BMAD-Standards arbeiten und umfassende PRD-Validierungs- und Qualitätsbewertungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que trabalham com padrões BMAD, necessitando de capacidades de validação e avaliação de qualidade de PRD abrangentes.","ru":"Идеально подходит для агентов разработки, работающих со стандартами BMAD, которым необходимы всесторонние возможности проверки и оценки качества PRD.","ar":"مثالي لعميل التطوير الذين يعملون مع معايير BMAD ، وهم بحاجة إلى إمكانيات شاملة لتحقق و تقييم جودة PRD."},"recommendation":{"en":"Empowers agents to review existing PRDs against BMAD standards through step-file architecture and configuration loading from config.yaml, ensuring adherence to quality standards and best practices, utilizing MD file workflows for validation.","zh":"赋予代理人通过步骤文件架构和从config.yaml加载配置来查看现有PRD与BMAD标准的能力，确保遵守质量标准和最佳实践，利用MD文件工作流进行验证。","ja":"ステップファイルアーキテクチャとconfig.yamlからの設定読み込みを通じて、エージェントがBMAD規格に従った既存のPRDを確認する機能を与え、品質規格とベストプラクティスへの従属を確保し、MDファイルワークフローを使用して検証します。","ko":"에이전트가 스텝 파일 아키텍처와 config.yaml에서 설정을 불러오는 것을 통해 기존 PRD를 BMAD 표준에 따라 검토할 수 있는 기능을 부여하여 품질 표준과 최고의 실践을 준수하고 MD 파일 워크플ロー를 사용하여 검증합니다.","es":"Habilita a los agentes a revisar los PRD existentes frente a los estándares BMAD a través de la arquitectura de archivo de paso y la carga de configuración desde config.yaml, garantizando el cumplimiento de los estándares de calidad y las mejores prácticas, utilizando flujos de trabajo de archivos MD para la validación.","fr":"Permet aux agents de revoir les PRD existants par rapport aux normes BMAD via l''architecture de fichier de passe et le chargement de la configuration à partir de config.yaml, en garantissant le respect des normes de qualité et des meilleures pratiques, en utilisant les flux de travail de fichiers MD pour la validation.","de":"Ermächtigt die Mittel, bestehende PRDs gegen BMAD-Standards zu überprüfen, indem sie die Datei-Schritt-Architektur und die Konfigurationsladung aus config.yaml nutzen, wodurch die Einhaltung der Qualitätsstandards und der besten Praktiken sichergestellt wird, unter Verwendung von MD-Datei-Workflows für die Validierung.","pt":"Habilita os agentes a revisar PRDs existentes contra os padrões BMAD por meio da arquitetura de arquivo de etapas e carregamento de configuração a partir do config.yaml, garantindo a adesão aos padrões de qualidade e às melhores práticas, utilizando fluxos de trabalho de arquivo MD para validação.","ru":"Наделяет агентов возможностью просматривать существующие PRD против стандартов BMAD посредством архитектуры файла шагов и загрузки конфигурации из config.yaml, обеспечивая соблюдение стандартов качества и лучших практик, используя рабочие процессы файла MD для проверки.","ar":"يمنح الوكلاء khảية مراجعة PRDs الحالية ضد معايير BMAD من خلال هندسة ملف الخطوات وتحميل التكوين من config.yaml ، مما يضمن الالتزام بمعايير الجودة وأفضل الممارسات ، باستخدام تدفقات العمل لملف MD للتحقق."},"useCases":{"en":["Validating PRDs against BMAD standards","Automating quality assessment for development projects","Reviewing workflow configurations in config.yaml"],"zh":["对PRD进行BMAD标准验证","自动化开发项目的质量评估","在config.yaml中查看工作流配置"],"ja":["PRDをBMAD規格に従って検証する","開発プロジェクトの品質評価を自動化する","config.yaml内のワークフローコンフィギュレーションを確認する"],"ko":["PRD를 BMAD 표준에 따라 검증한다","개발 프로젝트의 품질 평가를 자동화한다","config.yaml의 워크플ロー 구성 확인"],"es":["Validar PRD frente a los estándares BMAD","Automatizar la evaluación de la calidad para proyectos de desarrollo","Revisar configuraciones de flujo de trabajo en config.yaml"],"fr":["Valider les PRD par rapport aux normes BMAD","Automatiser l''évaluation de la qualité pour les projets de développement","Réviser les configurations de flux de travail dans config.yaml"],"de":["PRD gegen BMAD-Standards validieren","Qualitätsbewertung für Entwicklungsvorhaben automatisieren","Workflow-Konfigurationen in config.yaml überprüfen"],"pt":["Validar PRDs contra os padrões BMAD","Automatizar a avaliação de qualidade para projetos de desenvolvimento","Revisar configurações de fluxo de trabalho em config.yaml"],"ru":["Проверка PRD против стандартов BMAD","Автоматизация оценки качества для проектов разработки","Просмотр конфигураций рабочего процесса в config.yaml"],"ar":["التحقق من PRD ضد معايير BMAD","تأتمتة تقييم الجودة لمشاريع التطوير","مراجعة إعدادات سير العمل في config.yaml"]},"limitations":{"en":["Requires access to _bmad/bmm/workflows and config.yaml files","Limited to BMAD standards and workflow validation"],"zh":["需要访问_bmad/bmm/workflows和config.yaml文件","仅限BMAD标准和工作流验证"],"ja":["_bmad/bmm/workflowsおよびconfig.yamlファイルへのアクセスが必要","BMAD規格およびワークフローの検証のみ"],"ko":["_bmad/bmm/workflows 및 config.yaml 파일에 대한 액세스가 필요함","BMAD 표준 및 워크플로 검증만"],"es":["Requiere acceso a los archivos _bmad/bmm/workflows y config.yaml","Limitado a los estándares BMAD y la validación de flujo de trabajo"],"fr":["Nécessite l''accès aux fichiers _bmad/bmm/workflows et config.yaml","Limité aux normes BMAD et à la validation du flux de travail"],"de":["Erfordert den Zugriff auf die Dateien _bmad/bmm/workflows und config.yaml","Begrenzt auf BMAD-Standards und Workflow-Validierung"],"pt":["Requer acesso aos arquivos _bmad/bmm/workflows e config.yaml","Limitado aos padrões BMAD e validação de fluxo de trabalho"],"ru":["Требует доступа к файлам _bmad/bmm/workflows и config.yaml","Ограничен стандартами BMAD и проверкой рабочего процесса"],"ar":["يتطلب الوصول إلى الملفات _bmad/bmm/workflows و config.yaml","محدود بمعايير BMAD و التحقق من سير العمل"]},"version":4},"contentHash":"1cea6cd7265bac89d5b4015f1d39eda0943013094361bdb77234eaa3104385b1","qualityScore":35}');
