INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KatTate/Bmad-for-Replit/bmad-validate-prd', 'bmad-validate-prd', 'KatTate', 'Bmad-for-Replit', 'community', 'bmad-validate-prd KatTate Bmad-for-Replit community The bmad-validate-prd skill activates a comprehensive PRD validation workflow, reviewing existing PRDs against BMAD standards through quality assessment. This skill benefits developers working with BMAD standards. BMAD Validate PRD工作流通过综合性质评估审查现有的PRD，确保其符合BMAD标准 BMAD Validate PRDワークフローは、BMAD標準に従って既存のPRDを包括的な品質評価で検証します BMAD Validate PRD 워크플로우는 종합적인 품질 평가를 통해 기존 PRD를 검토하여 BMAD 표준에 부합하는지 확인합니다 bmad-validate-prd es un flujo de trabajo que valida PRD según los estándares de BMAD. Carga la configuración desde _bmad/bmm/config.yaml y utiliza arquitectura de paso de archivo bmad-validate-prd est un flux de travail qui valide les PRD selon les normes de BMAD. Il charge la configuration à partir de _bmad/bmm/config.yaml et utilise une architecture de fichier de pas bmad-validate-prd ist ein Workflow, der PRD gemäß den BMAD-Standards validiert. Er lädt die Konfiguration aus _bmad/bmm/config.yaml und verwendet eine Datei-Schritt-Architektur O bmad-validate-prd é um repositório para validar PRD com base em padrões BMAD. Ele utiliza arquitetura de steps e configuração em YAML. Bmad-validate-prd - это репозиторий для валидации PRD на основе стандартов BMAD. Он использует шаговую архитектуру и конфигурацию в YAML. bmad-validate-prd هو مستودع للتحقق من PRD بناءً على معايير BMAD. يستخدم هيكلاً متدرجاً وتكويناً في YAML. how to use bmad-validate-prd bmad-validate-prd setup guide bmad-validate-prd alternative bmad-validate-prd vs BMAD standards what is bmad-validate-prd bmad-validate-prd install PRD validation workflow BMAD standards compliance comprehensive quality assessment BMAD Validate PRD AI工具 工作流设置 综合性质评估 BMAD标准 PRD检验 步骤文件架构 配置加载 Triggers the BMAD PRD Validation workflow through a step-file architecture Loads configuration from _bmad/bmm/config.yaml Utilizes steps in the steps-v/ directory for comprehensive quality assessment Follows the workflow defined in _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md Reviews existing PRDs against BMAD standards for improved validation bmad-validate-prd is a repository-based skill that activates the BMAD PRD Validation workflow, utilizing a step-file architecture and configuration loading from config.yaml');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Piece-Puzzly/Piece-iOS/merge', 'community', 'Piece-Puzzly', 'Piece-iOS', 'Piece-Puzzly/Piece-iOS', 'merge', 0, 0, 35, '2026-03-08T01:57:15.635Z', '2026-03-08T02:13:37.195Z', '658862681efd1e1d682d72f207c9f814631607427b0008376cbf3d0f785e141c', '{"id":"Piece-Puzzly/Piece-iOS/merge","name":"merge","description":{"en":"The merge skill automates squash merging of feature branches into main, supporting Git worktree environments and detecting develop or main branches as merge targets.","zh":"合并技能用于将当前特性分支合并到主分支，支持工作树环境","ja":"マージスキルは現在の機能ブランチをメインブランチにマージし、ワークツリー環境をサポートします","ko":"머지 스킬은 현재 피처 브랜치를 메인 브랜치에 머지하고 워크트리 환경을 지원합니다","es":"La función merge combina la rama actual con la rama principal en Git, incluso en entornos de worktree","fr":"La fonctionnalité merge combine la branche actuelle avec la branche principale Git, même dans les environnements de worktree","de":"Die Merge-Funktion kombiniert den aktuellen Zweig mit dem Hauptzweig in Git, auch in Worktree-Umgebungen","pt":"O merge é uma habilidade que executa squash merge do branch de recurso atual para o branch principal, funcionando em ambientes de trabalho","ru":"Слияние - это навык, который выполняет squash merge текущей функциональной ветки в основную ветку, работает в рабочих средах для ИИ Агентов","ar":"الدمج هو مهارة تقوم بدمج Squash للفرع الحالي إلى الفرع الرئيسي، يعمل في بيئات العمل"},"seo":{"title":{"en":"Merge: Squash Merge Setup Guide for AI Agents","zh":"合并技能设置指南 - Squash Merge 功能","ja":"マージスキルの設定方法 - スクワッシュマージのベストプラクティス","ko":"머지 스킬 설정 가이드 - 스쿼시 머지 기능","es":"Guía de configuración de merge para desarrolladores","fr":"Guide de mise en place de la fonctionnalité merge","de":"Merge-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Merge: Squash Merge em Ambientes ...","ru":"Настройка Слияния: Руководство по Squash Merge для ИИ Аге...","ar":"دليل إعداد الدمج: دمج Squash في بيئات العمل"},"description":{"en":"Discover how to squash merge feature branches into main using Git worktree detection and automation - get started with our expert guide","zh":"了解合并技能的设置和使用方法，实现 squash merge 功能，提升开发效率","ja":"マージスキルの設定と使用方法を学び、スクワッシュマージ機能を実現して開発効率を向上させる","ko":"머지 스킬의 설정과 사용 방법을 알아보고 스쿼시 머지 기능을 구현하여 개발 효율을 향상시키세요","es":"Aprende a utilizar la función merge para combinar ramas en Git de manera efectiva","fr":"Découvrez comment utiliser la fonctionnalité merge pour combiner des branches Git avec succès","de":"Erfahren Sie, wie Sie die Merge-Funktion für die Kombination von Git-Zweigen verwenden","pt":"Aprenda a configurar o merge com squash merge em ambientes de trabalho, incluindo detecção de workspace e direcionamento para o repositório principal","ru":"Узнайте, как настроить слияние с squash merge в рабочих средах, включая обнаружение рабочего пространства и направление в основной репозиторий для ИИ Агентов","ar":"تعرف على كيفية إعداد الدمج مع دمج Squash في بيئات العمل، بما في ذلك كشف workspace وتوجيه إلى المستودع الرئيسي"},"definition":{"en":"Merge is a Git-based skill that performs squash merges of feature branches into main, utilizing worktree detection and automation.","zh":"合并技能是指将代码更改合并到主分支的功能","ja":"マージスキルはコードの変更をメインブランチにマージする機能です","ko":"머지 스킬은 코드 변경을 메인 브랜치에 머지하는 기능입니다","es":"La función merge es una operación Git que combina dos ramas en una sola","fr":"La fonctionnalité merge est une opération Git qui combine deux branches en une seule","de":"Die Merge-Funktion ist eine Git-Operation, die zwei Zweige in einem kombiniert","pt":"O que é merge? É uma habilidade que permite unir branches de código com squash merge","ru":"Что такое слияние? Это навык, который позволяет объединять ветки кода с помощью squash merge для ИИ Агентов","ar":"ما هو الدمج؟ هو مهارة تسمح بدمج فروع الكود باستخدام دمج Squash"},"features":{"en":["Performs squash merge of feature branches into main using Git","Detects Git worktree environments and adjusts merge behavior","Automatically identifies develop or main branches as merge targets","Utilizes bash scripting for environment detection and merge automation","Supports merge operations in both worktree and non-worktree environments"],"zh":["支持工作树环境","实现 squash merge 功能","自动检测工作树","使用 Git 命令行接口","支持多个分支合并","提高开发效率"],"ja":["ワークツリー環境をサポート","スクワッシュマージ機能を実現","ワークツリーを自動検出","Git コマンドラインインターフェースを使用","複数のブランチをマージ","開発効率を向上"],"ko":["워크트리 환경을 지원","스쿼시 머지 기능을 구현","워크트리를 자동 감지","Git 명령행 인터페이스를 사용","여러 브랜치를 머지","개발 효율을 향상"],"es":["Combina la rama actual con la rama principal en Git","Funciona en entornos de worktree","Detecta automáticamente la rama de destino","Utiliza Git CLI para la combinación de ramas","Soporta la combinación de ramas en proyectos con múltiples worktrees","Permite la configuración personalizada de la combinación de ramas"],"fr":["Combinez la branche actuelle avec la branche principale Git","Fonctionne dans les environnements de worktree","Détecte automatiquement la branche cible","Utilise Git CLI pour la combinaison de branches","Prend en charge la combinaison de branches dans les projets avec plusieurs worktrees","Permet la configuration personnalisée de la combinaison de branches"],"de":["Kombiniert den aktuellen Zweig mit dem Hauptzweig in Git","Funktioniert in Worktree-Umgebungen","Erkennet automatisch den Zielzweig","Verwendet Git CLI für die Kombination von Zweigen","Unterstützt die Kombination von Zweigen in Projekten mit mehreren Worktrees","Ermöglicht die individuelle Konfiguration der Zweigkombination"],"pt":["Detecção de workspace para direcionar o merge correto","Squash merge do branch de recurso para o branch principal","Funcionamento em ambientes de trabalho com repositório principal","Uso de git worktree list para detecção de workspace","Suporte a branches de desenvolvimento e principal"],"ru":["Обнаружение рабочего пространства для направления правильного слияния","Squash merge функциональной ветки в основную ветку","Работа в рабочих средах с основным репозиторием для ИИ Агентов","Использование git worktree list для обнаружения рабочего пространства","Поддержка dévelopмент и основной веток"],"ar":["كشف workspace لتوجيه الدمج الصحيح","دمج Squash للفرع الحالي إلى الفرع الرئيسي","العمل في بيئات العمل مع المستودع الرئيسي","استخدام git worktree list لكشف workspace","دعم فروع التطوير والرئيسية"]},"keywords":{"en":["how to use merge in Git","merge vs rebase","merge setup guide for AI agents","Git worktree merge","squash merge best practices","merge install for developers","what is merge in Git","merge alternative for Git workflows"],"zh":["合并技能","squash merge","工作树环境","Git 命令行接口","代码合并","开发效率","AI 工具","代码管理"],"ja":["マージスキル","スクワッシュマージ","ワークツリー環境","Git コマンドラインインターフェース","コードマージ","開発効率","AI エージェント","コード管理"],"ko":["머지 스킬","스쿼시 머지","워크트리 환경","Git 명령행 인터페이스","코드 머지","개발 효율","AI 에이전트","코드 관리"],"es":["merge git","combinar ramas git","worktree git","git cli","configuración de merge","herramientas de desarrollo","desarrollo de software","control de versiones","git para desarrolladores"],"fr":["merge git","combiner des branches git","worktree git","git cli","configuration de merge","outils de développement","développement de logiciels","contrôle de version","git pour les développeurs"],"de":["merge git","zweige kombinieren git","worktree git","git cli","konfiguration von merge","entwicklungstools","softwareentwicklung","versionskontrolle","git für entwickler"],"pt":["merge","squash merge","git worktree","ambiente de trabalho","repositório principal","desenvolvimento de software","ferramentas de desenvolvimento","ÍI Aprendizado de Máquina"],"ru":["слияние","squash merge","git worktree","рабочая среда","основной репозиторий","разработка программного обеспечения","инструменты разработки","ИИ Агенты","ИИ Инструменты"],"ar":["الدمج","دمج Squash","git worktree","بيئة العمل","المستودع الرئيسي","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي","الدمج التلقائي"]}},"owner":"Piece-Puzzly","repo":"Piece-iOS","repoPath":"Piece-Puzzly/Piece-iOS","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.635Z","topics":[],"category":"community","skillMd":{"name":"merge","description":"feature 브랜치를 main에 squash merge (워크트리 지원)","version":"3.2.0","bodyPreview":"# Merge 스킬\n\n현재 feature 브랜치를 main 브랜치에 squash merge합니다.\n워크트리 환경에서도 메인 레포를 통해 정상 동작합니다.\n\n> **참고**: develop 브랜치가 존재하면 develop을, 없으면 main을 머지 타겟으로 사용합니다.\n\n## 실행 단계\n\n### 1. 환경 감지\n\n```bash\n# 워크트리 여부 확인\nWORKTREE_COUNT=$(git worktree list | wc -l)\nPROJECT_ROOT=$(git worktree list --porcelain | head -1 | cut -d'' '' -f2)\nCURRENT_DIR=$(pwd)\n\n# 워크트리인지 판별\nif [ \"$WORKTREE_COUNT\" -gt 1 ] && [ \"$PROJECT_ROOT\" != \"$CURRENT_DIR\" ]; then\n  IS_WORKTREE=true\nelse\n  IS_WORKTREE=false\nfi\n```\n\n**워크트리 감지 시**:\n→ 메인 레포 경로(","body":"# Merge 스킬\n\n현재 feature 브랜치를 main 브랜치에 squash merge합니다.\n워크트리 환경에서도 메인 레포를 통해 정상 동작합니다.\n\n> **참고**: develop 브랜치가 존재하면 develop을, 없으면 main을 머지 타겟으로 사용합니다.\n\n## 실행 단계\n\n### 1. 환경 감지\n\n```bash\n# 워크트리 여부 확인\nWORKTREE_COUNT=$(git worktree list | wc -l)\nPROJECT_ROOT=$(git worktree list --porcelain | head -1 | cut -d'' '' -f2)\nCURRENT_DIR=$(pwd)\n\n# 워크트리인지 판별\nif [ \"$WORKTREE_COUNT\" -gt 1 ] && [ \"$PROJECT_ROOT\" != \"$CURRENT_DIR\" ]; then\n  IS_WORKTREE=true\nelse\n  IS_WORKTREE=false\nfi\n```\n\n**워크트리 감지 시**:\n→ 메인 레포 경로(`PROJECT_ROOT`)를 사용하여 `git -C \"$PROJECT_ROOT\"` 형태로 명령 실행\n\n### 2. 사전 확인\n\n```bash\n# 현재 브랜치 확인\ngit branch --show-current\n\n# 변경사항 확인 (커밋되지 않은 변경사항 체크)\ngit status --short\n```\n\n**체크리스트**:\n- [ ] 현재 브랜치가 feature/* 또는 fix/* 등 작업 브랜치인가?\n- [ ] 커밋되지 않은 변경사항이 없는가?\n\n**분기 처리**:\n- **IF** 현재 브랜치가 `main` 또는 `develop`:\n  → \"feature 브랜치에서 실행해주세요. 현재 브랜치: {브랜치명}\" 안내 후 종료\n\n- **IF** 커밋되지 않은 변경사항 존재:\n  → \"먼저 `/commit` 스킬을 실행하여 변경사항을 커밋해주세요.\" 안내 후 종료\n\n### 3. 브랜치 정보 분석\n\n**Step 1: 현재 브랜치명 확인**\n\n```bash\nBRANCH=$(git branch --show-current)\n# 예: feat/grt-42/button-disabled\n```\n\n**Step 2: 브랜치명에서 정보 추출**\n\n```bash\n# 예: feat/button-disabled\nTYPE=$(echo \"$BRANCH\" | cut -d''/'' -f1)\nDESCRIPTION=$(echo \"$BRANCH\" | cut -d''/'' -f2-)\n```\n\n**추출 정보**:\n- 타입: 브랜치 prefix에서 추출 (`feat`, `fix`, `refactor`, `chore`, `docs`, `build`)\n- 설명: 브랜치명의 두 번째 세그먼트 (예: `button-disabled`)\n\n**타입 매핑** (병합 커밋용 대문자):\n| 브랜치 prefix | 커밋 prefix |\n|--------------|-------------|\n| `feat/`      | `FEAT`      |\n| `fix/`       | `FIX`       |\n| `refactor/`  | `REFACTOR`  |\n| `chore/`     | `CHORE`     |\n| `docs/`      | `DOCS`      |\n| `build/`     | `BUILD`     |\n\n### 4. 병합 커밋 메시지 생성\n\n**머지 타겟 결정**:\n```bash\n# develop 브랜치가 있으면 develop, 없으면 main\nif git show-ref --verify --quiet refs/heads/develop; then\n  TARGET=\"develop\"\nelse\n  TARGET=\"main\"\nfi\n```\n\n**커밋 로그 분석**:\n```bash\n# 타겟 브랜치와의 차이 확인\ngit log $TARGET..HEAD --oneline\n```\n\n**커밋 메시지 형식**:\n\n```\n[TYPE] 기능 요약\n```\n\n**예시**:\n- `[FEAT] Button disabled 상태 추가`\n- `[FIX] 로그인 유효성 검증 버그 수정`\n- `[REFACTOR] 네트워크 레이어 구조 개선`\n\n**기능 요약 생성 방법**:\n1. 커밋 로그에서 주요 변경사항 파악\n2. 50자 이내 한글로 요약\n\n### 5. Squash Merge 실행\n\n#### 일반 환경 (워크트리가 아닌 경우)\n\n```bash\n# 현재 브랜치명 저장\nFEATURE_BRANCH=$(git branch --show-current)\n\n# 타겟 브랜치로 전환\ngit checkout $TARGET\n\n# 타겟 브랜치를 최신 상태로 동기화\ngit pull origin $TARGET\n\n# feature 브랜치를 squash merge\ngit merge --squash $FEATURE_BRANCH\n\n# 병합 커밋 생성\ngit commit -m \"[TYPE] 기능 요약\"\n\n# feature 브랜치 삭제\ngit branch -d $FEATURE_BRANCH\n```\n\n#### 워크트리 환경\n\n```bash\n# 현재 브랜치명 저장\nFEATURE_BRANCH=$(git branch --show-current)\n\n# 메인 레포에서 타겟 브랜치 최신화\ngit -C \"$PROJECT_ROOT\" fetch origin\ngit -C \"$PROJECT_ROOT\" checkout $TARGET\ngit -C \"$PROJECT_ROOT\" pull origin $TARGET\n\n# 메인 레포에서 squash merge 실행\ngit -C \"$PROJECT_ROOT\" merge --squash $FEATURE_BRANCH\n\n# 충돌 발생 시: 메인 레포에서 충돌 해결 후 스테이징\n# git -C \"$PROJECT_ROOT\" add <충돌파일>\n\n# 메인 레포에서 병합 커밋 생성\ngit -C \"$PROJECT_ROOT\" commit -m \"[TYPE] 기능 요약\"\n\n# feature 브랜치 삭제는 워크트리 제거 후 수동으로\n# (워크트리에서 사용 중인 브랜치는 삭제 불가)\n```\n\n**체크리스트**:\n- [ ] 타겟 브랜치 최신화 성공\n- [ ] Squash merge 성공\n- [ ] 병합 커밋 생성 성공\n- [ ] Feature 브랜치 삭제 성공 (워크트리 환경에서는 보류)\n\n**IF** 타겟 브랜치 pull 중 충돌:\n→ 오류 메시지 출력 후 안내:\n```\n타겟 브랜치 동기화 중 충돌이 발생했습니다.\n\n해결 방법:\n1. git checkout {feature-branch}\n2. git rebase {target-branch}\n3. 충돌 해결 후 다시 /merge 실행\n\n또는 수동으로 병합을 진행해주세요.\n```\n\n### 6. Push 여부 확인\n\n**사용자에게 질문**:\n```\n병합이 완료되었습니다.\n\n타겟 브랜치를 원격에 push할까요?\n\n1. 예, push합니다\n2. 아니오, 나중에 수동으로 push합니다\n\n선택:\n```\n\n**IF** \"예\" 선택:\n\n일반 환경:\n```bash\ngit push origin $TARGET\n```\n\n워크트리 환경:\n```bash\ngit -C \"$PROJECT_ROOT\" push origin $TARGET\n```\n\n### 7. 최종 확인 및 요약\n\n**사용자에게 보고**:\n\n```\n병합 완료!\n\n병합 정보:\n- 브랜치: {feature-branch} → {target-branch}\n- 커밋: [TYPE] 기능 요약\n- Push: {완료/미완료}\n- 환경: {일반/워크트리}\n\n다음 단계:\n- 새 작업을 시작하려면 `/start-branch`를 실행하세요\n- 워크트리 환경: 워크트리 제거 후 브랜치 삭제 필요\n```\n\n## 엣지 케이스 처리\n\n### Case 1: main 또는 develop 브랜치에서 실행\n→ \"feature 브랜치에서 실행해주세요\" 안내 후 종료\n\n### Case 2: 커밋되지 않은 변경사항이 있을 때\n→ \"/commit 스킬을 먼저 실행하세요\" 안내 후 종료\n\n### Case 3: 타겟 브랜치와 충돌 발생\n→ 메인 레포에서 충돌 해결 후 스테이징, 커밋 진행\n\n### Case 4: feature 브랜치 삭제 실패 (워크트리)\n→ 안내 출력:\n```\n워크트리에서 사용 중인 브랜치는 삭제할 수 없습니다.\n워크트리 제거 후 삭제하세요:\n  git worktree remove <worktree-path>\n  git branch -d {branch-name}\n```\n\n### Case 5: 워크트리에서 메인 레포 작업 디렉토리가 dirty\n→ 경고 출력:\n```\n메인 레포에 커밋되지 않은 변경사항이 있습니다.\n메인 레포에서 변경사항을 정리한 후 다시 시도하세요.\n경로: {PROJECT_ROOT}\n```\n\n## 사용자 상호작용 포인트\n\n### 필수 확인 사항:\n1. **Push 여부** - 병합 후 develop을 원격에 push할지\n\n### 자동화 가능:\n- 워크트리 환경 감지\n- 브랜치명 분석\n- 타입 매핑\n- Squash merge 실행 (메인 레포 경유)\n- 커밋 메시지 생성\n"},"lastSynced":"2026-03-08T02:13:37.195Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents requiring automated squash merging of feature branches into main or develop branches.","zh":"适用于需要自动将功能分支合并到主分支或开发分支的 Git 基础 AI 代理。","ja":"Git ベースの AI エージェントが機能ブランチをメインブランチまたは開発ブランチに自動で squash マージする必要がある場合に適しています。","ko":"기능 브랜치를 메인 브랜치 또는 개발 브랜치로 자동으로 squash merge 해야 하는 Git 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en Git que requieren una fusión automática de squash de ramas de características en ramas principales o de desarrollo.","fr":"Idéal pour les agents d''IA basés sur Git nécessitant une fusion automatique de squash des branches de fonctionnalités dans les branches principales ou de développement.","de":"Ideal für Git-basierte KI-Agents, die eine automatisierte Squash-Zusammenführung von Feature-Branches in Haupt- oder Entwicklungszweige erfordern.","pt":"Ideal para Agentes de IA baseados em Git que requerem mesclagem de squash automatizada de branches de recursos para branches principais ou de desenvolvimento.","ru":"Идеально для агентов ИИ, основанных на Git, требующих автоматического сжатия слияния веток функций в основные или ветки разработки.","ar":"مثالي للوكلاء الذكية القائمة على Git التي تتطلب دمج سكويش آلي لفرع الميزات في الفرع الرئيسي أو التطوير."},"recommendation":{"en":"Empowers agents to automate squash merging of feature branches into main or develop branches, supporting Git worktree environments and detecting merge targets, utilizing Git commands and worktree list functionality.","zh":"使代理能够自动将功能分支合并到主分支或开发分支，支持 Git worktree 环境，检测合并目标，利用 Git 命令和 worktree 列表功能。","ja":"エージェントが機能ブランチをメインブランチまたは開発ブランチに自動で squash マージできるようにし、Git worktree 環境をサポートし、merge ターゲットを検出して Git コマンドと worktree リスト機能を利用します。","ko":"에이전트가 기능 브랜치를 메인 브랜치 또는 개발 브랜치로 자동으로 squash merge 할 수 있도록 해주며, Git worktree 환경을 지원하고 merge 대상에 대한 감지를 지원하며 Git 명령어 및 worktree 목록 기능을 활용합니다.","es":"Permite a los agentes automatizar la fusión de squash de ramas de características en ramas principales o de desarrollo, admitiendo entornos de Git worktree y detectando objetivos de fusión, utilizando comandos de Git y funcionalidad de lista de worktree.","fr":"Permet aux agents d''automatiser la fusion de squash des branches de fonctionnalités dans les branches principales ou de développement, en prenant en charge les environnements Git worktree et en détectant les cibles de fusion, en utilisant des commandes Git et des fonctionnalités de liste de worktree.","de":"Ermöglicht es Agents, die Squash-Zusammenführung von Feature-Branches in Haupt- oder Entwicklungszweige zu automatisieren, indem sie Git worktree-Umgebungen und Merge-Ziele erkennen, Git-Befehle und Worktree-Listenfunktionen nutzen.","pt":"Habilita os agentes a automatizar a mesclagem de squash de branches de recursos para branches principais ou de desenvolvimento, suportando ambientes de trabalho Git e detectando alvos de mesclagem, utilizando comandos Git e funcionalidade de lista de trabalho.","ru":"Наделяет агентов возможностью автоматизировать сжатие слияния веток функций в основные или ветки разработки, поддерживая среды рабочего дерева Git и обнаруживая цели слияния, используя команды Git и функциональность списка рабочего дерева.","ar":"يمكّن الوكلاء من توفير دمج سكويش آلي لفرع الميزات في الفرع الرئيسي أو التطوير، ودعم بيئات شجرة العمل Git واكتشاف أهداف الدمج، باستخدام أوامر Git ووظائف قائمة الشجرة العاملة."},"useCases":{"en":["Automating squash merging of feature branches","Detecting and merging into develop or main branches","Supporting Git worktree environments for seamless repository management"],"zh":["自动将功能分支合并到主分支或开发分支","检测并合并到开发或主分支","支持 Git worktree 环境以实现无缝的仓库管理"],"ja":["機能ブランチをメインブランチまたは開発ブランチに自動でマージする","開発ブランチまたはメインブランチにマージするための検出とマージ","Git worktree 環境をサポートしてリポジトリの管理を円滑に行う"],"ko":["기능 브랜치를 메인 브랜치 또는 개발 브랜치로 자동으로 squash merge 하는 것","개발 또는 메인 브랜치로의 감지 및 머지","리포지토리 관리를 원활하게 하기 위한 Git worktree 환경 지원"],"es":["Automatización de la fusión de squash de ramas de características","Detección y fusión en ramas de desarrollo o principales","Soporte de entornos de Git worktree para una gestión de repositorios sin problemas"],"fr":["Automatisation de la fusion de squash des branches de fonctionnalités","Détection et fusion dans les branches de développement ou principales","Prise en charge des environnements Git worktree pour une gestion de référentiels sans problème"],"de":["Automatisierung der Squash-Zusammenführung von Feature-Branches","Erkennung und Zusammenführung in Entwicklungszweige oder Hauptzweige","Unterstützung von Git worktree-Umgebungen für eine reibungslose Repository-Verwaltung"],"pt":["Automatizar a mesclagem de squash de branches de recursos","Detectar e mesclar em branches de desenvolvimento ou principais","Suportar ambientes de trabalho Git para gerenciamento de repositório sem interrupções"],"ru":["Автоматизировать сжатие слияния веток функций","Обнаруживать и сливать в ветки разработки или основные","Поддерживать среды рабочего дерева Git для бесперебойного управления репозиторием"],"ar":["توفير دمج سكويش آلي لفرع الميزات","اكتشاف ودمج في فروع التطوير أو الرئيسية","دعم بيئات شجرة العمل Git لإدارة المستودع بدون انقطاع"]},"limitations":{"en":["Requires Git installation and configuration","Limited to Git worktree environments and squash merge strategy"],"zh":["需要 Git 安装和配置","仅限 Git worktree 环境和 squash merge 策略"],"ja":["Git のインストールと設定が必要","Git worktree 環境と squash マージ戦略のみに限定される"],"ko":["Git 설치 및 구성이 필요함","Git worktree 환경 및 squash merge 전략으로 제한됨"],"es":["Requiere instalación y configuración de Git","Limitado a entornos de Git worktree y estrategia de fusión de squash"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux environnements Git worktree et à la stratégie de fusion de squash"],"de":["Erfordert Git-Installation und -Konfiguration","Begrenzt auf Git worktree-Umgebungen und Squash-Zusammenführungsstrategie"],"pt":["Exige instalação e configuração do Git","Limitado a ambientes de trabalho Git e estratégia de mesclagem de squash"],"ru":["Требует установки и настройки Git","Ограничен средами рабочего дерева Git и стратегией сжатия слияния"],"ar":["يتطلب تثبيت وتكوين Git","محدود ببيئات شجرة العمل Git و استراتيجية دمج السكويش"]},"version":4},"contentHash":"658862681efd1e1d682d72f207c9f814631607427b0008376cbf3d0f785e141c","qualityScore":35}');
